  var C=window.YLT_CFG||{};var books=C.books||(window.GAME_CONFIG&&window.GAME_CONFIG.books)||[];var byId={};for(var i=0;i<books.length;i++)byId[books[i].id]=books[i];
  function acc(id,chs){var b=byId[id];if(!b)return;b.chapters=(b.chapters||[]).concat(chs);}
  acc("b_bencao",[{"n": 11, "text": "卷十一\n\n石。取一两研末，熟猪肝作丸梧子大。空腹，量人加减。水牛肝更佳。如素食人，以蒸饼为 \n丸。或云白矾中青黑者，名巴石。（刘禹锡《传信方》）冷劳泄痢食少，诸药不效∶白矾三两 \n（烧），羊肝一具（去脂），酽醋三升煮烂，擂泥和丸梧子大。每服二十丸，米饮下，早夜各 \n一 \n服。（《普济方》）泄泻下痢∶白龙丹∶用明矾枯过为末，飞罗面醋打糊丸梧子大。每服二、 \n三十丸，白痢姜汤下；赤痢甘草汤下；泄泻米汤下。（《经验方》）疟疾寒热∶即上方，用东 \n南桃心七个，煎汤下。反胃呕吐∶白矾、硫黄各二两，铫内烧过，入朱砂一分，为末，面糊 \n丸小豆大。每姜汤下十五丸。又方∶白矾（枯）三两，蒸饼丸梧子大。每空心米饮服十五丸。 \n（《普济方》）化痰治嗽∶明矾二两，生参末一两，苦醋二升。熬为膏子，以油纸包收，旋丸 \n豌豆大。每用一丸，放舌下，其嗽立止，痰即消。《定西侯方》∶只用明矾末，醋糊丸梧子大。 \n每睡时茶下二、三十丸。《摘要》∶用明矾（半生半烧）、山栀子（炒黑）等分。为末，姜汁 \n糊为 \n丸。如上服。《杂兴方》∶用白明矾、建茶等分为末，糊丸服。诸心气痛∶《儒门事亲》方∶ \n生矾一皂子大，醋一盏，煎七分服，立止。邵真人方∶用明矾一两（烧），朱砂一钱，金箔 \n三个，为末。每服一钱半，空心白汤下。 \n中诸蛊毒∶晋矾、建茶等分。为末。新汲水调下二钱，泻吐即效。未吐再服。（《济生 \n方》）蛇虫诸毒∶毒蛇、射工、沙虱等伤人，口噤目黑，手足直，毒瓦斯入腹。白矾、甘草等 \n分。为末。冷水服二钱。（《瑞竹堂方》）驴马汗毒所伤疮痛∶白矾（飞过）、黄丹（炒紫）等 \n分。 \n贴之。（王氏《博济方》）虎犬伤人∶矾末，纳入裹之，止痛尤妙。（《肘后方》）蛇咬蝎螫∶ \n烧刀矛头令赤，置白矾于上，汁出热滴之，立瘥。此神验之方也。真元十三年，有两僧流南 \n方，到邓州，俱为蛇啮，令用此法便瘥，更无他苦。（刘禹锡《传信方》）壁镜毒人必死∶白 \n矾涂之。（《太平广记》）刀斧金疮∶白矾、黄丹等分为末。敷之最妙。（《救急方》）折伤止 \n痛∶白矾末一匙，泡汤一碗，帕蘸乘热熨伤处。少时痛止，然后排整筋骨，点药。（《灵苑 \n方》）漆疮作痒∶白矾汤拭之。（《千金方》）牛皮癣疮∶石榴皮蘸明矾末，抹之。切勿用醋， \n即虫沉下。（《直指方》）小儿风疹作痒∶白矾（烧），投热酒中，马尾 酒涂之。（《子母秘 \n录》）小儿脐肿，出汁不止∶白矾烧灰敷之。（《圣惠方》）干湿头疮∶白矾（半生半 ），酒 \n调涂上。（《生生编》）身面瘊子∶白矾、地肤子等分，煎水。频洗之。（《多能鄙事》）腋下 \n狐臭∶矾石绢袋盛之，常粉腋下，甚妙。（许尧臣方）鱼口疮毒∶白矾（枯）研，寒食面糊 \n调敷 \n上，即消。（《救急良方》）阴疮作臼∶取高昌白矾、麻仁等分。研末，猪脂和膏。先以槐白 \n皮煎汤洗过，涂之。外以楸叶粘贴。不过三度愈。（葛洪《肘后方》）足疮生虫∶南方地卑湿， \n人多患足疮，岁久生虫如蛭，乃风毒攻注而然。用牛或羊或猪肚，去粪不洗，研如泥，看疮 \n大小，入 过泥矾半两。以上研匀，涂帛上贴之。须臾痒入心，徐徐连帛取下，火上炙之。 \n虫出，丝发马尾千万，或青白赤黑，以汤洗之。三日一作，不过数次，虫尽疮愈。（南宫从 \n《岣嵝神书》）嵌甲作疮∶足趾甲入肉作疮，不可履靴。矾石烧灰敷之。蚀恶肉，生好肉。 \n细细割去甲角，旬日取愈，此方神效。（《肘后方》）鸡眼肉刺∶枯矾、黄丹、朴硝等分。为 \n末，搽之。次日浴二、三次，即愈。（《多能鄙事》）冷疮成漏∶明矾（半生半飞，飞者生肉， \n生者追脓）、五灵脂（水飞）各半钱为末。以皮纸裁条，唾和末作小捻子，香油捏湿，于末 \n拖 \n过，剪作大小捻，安入漏，早安午换。候脓出尽后，有些小血出，方得干水住药，自然生肉 \n痊好。（《普济方》）鱼睛疔疮∶枯矾末，寒食面糊调贴。消肿无脓。（崔氏方）疔疮肿毒∶雪 \n白矾末五钱，葱白煨熟，捣和丸梧子大。每服二钱五分，以酒送下，未效再服。久病、孕妇 \n不可服。（《卫生宝鉴》）痈疽肿毒∶方见前发明下。阴汗湿痒∶枯矾扑之。又泡汤沃洗。（《御 \n药院方》）交接劳复∶卵肿或缩入，腹痛欲绝。矾石一分，硝三分。大麦粥清服方寸匕，日 \n三服，热毒从二便出也。（《肘后方》）女人阴痛∶矾石三分（炒），甘草末半分。绵裹导之， \n取瘥。（《肘后百一方》）疔肿恶疮∶二仙散∶用生矾、黄丹临时等分。以三棱针刺血，待尽 \n敷之。不过三上，决愈。乃太医李管勾方。（《卫生宝鉴》）虫蛇兽毒及蛊毒∶生明矾、明雄 \n黄等分，于端午日研末，黄蜡和丸梧子大。每服七丸，念药王菩萨七遍，熟水送下。（东坡 \n《良》）方 \n\n\n\n<目录>石部第十一卷\\金石之五\n\n<篇名>绿矾\n\n内容：（《日华》） \n【释名】皂矾（《纲目》）、青矾， 赤者名绛矾（《唐本》）、矾红。时珍曰∶绿矾可以 \n染皂色，故谓之皂矾。又黑矾亦名皂矾，不堪服食，惟疮家用之。 赤者俗名矾红，以别朱 \n红。 \n【集解】颂曰∶绿矾出隰州温泉县、池州铜陵县，并煎矾处生焉。初生皆石也，煎炼乃 \n成。其形似朴硝而绿色，取置铁板上，聚炭烧之，矾沸流出，色赤如金汁者，是真也。沸定 \n时，汁尽，则色如黄丹。又有皂荚矾，或云即绿矾也。 \n恭曰∶绿矾新出窟未见风者，正如琉璃色，人以为石胆。烧之赤色，故名绛矾。出瓜州 \n者良。 \n时珍曰∶绿矾晋地、河内、西安、沙州皆出之，状如焰硝。其中拣出深青莹净者，即为 \n青矾； 过变赤，则为绛矾。入圬墁及漆匠家多用之，然货者亦杂以沙土为块。昔人往往以 \n青矾为石胆，误矣。 \n【气味】酸，凉，无毒。 \n【主治】疳及诸疮（苏恭）。喉痹虫牙口疮，恶疮疥癣。酿鲫鱼烧灰服，疗肠风泻血（大 \n明）。消积滞，燥脾湿，化痰涎，除胀满黄肿疟利，风眼口齿诸病（时珍）。 \n【发明】时珍曰∶绿矾酸涌涩收，燥湿解毒化涎之功与白矾同，而力差缓。按《张三丰 \n仙传方》载伐木丸云∶此方乃上清金蓬头祖师所传。治脾土衰弱，肝木气盛，木来克土，病 \n心腹中满，或黄肿如土色，服此能助土益元。用苍术二斤（米泔水浸二宿，同黄酒面曲四两 \n炒赤色），皂矾一斤（醋拌晒干，入瓶火 ），为末，醋糊丸梧子大。每服三、四十丸，好酒、 \n米汤任下，日二、三服。时珍常以此方加平胃散，治一贱役中满腹胀，果有效验。盖此矾色 \n绿味酸，烧之则赤，既能入血分伐木，又能燥湿化涎，利小便，消食积，故胀满黄肿疟痢疳 \n疾方往往用之，其源则自张仲景用矾石硝石治女劳黄胆方中变化而来。 \n颂曰∶刘禹锡《传信方》治喉痹，用皂荚矾，入好米醋同研含之，咽汁立瘥。此方出于 \n李谟，甚奇妙。皂荚矾，即绿矾也。 \n【附方】旧一，新三十四。 \n重舌木舌∶皂矾二钱，铁上烧红，研，掺之。（陆氏《积德堂方》） \n喉风肿闭∶皂矾一斤，米醋三斤拌，晒干末，吹之。痰涎出尽，用良姜末少许，入茶内 \n漱口，咽之即愈。（孙氏《集效方》）眼暴赤烂∶红枣五斤，入绿矾在内，火煨熟，以河水、 \n井水各一碗，桃、柳心各七个，煎稠。每点少许入 上。（《摘玄方》）烂弦风眼∶青矾火 \n出毒，细研。泡汤澄清，点洗。（《永类方》）倒睫拳毛∶方同上。 \n疟疾寒热∶矾红、独蒜头（煨）等分。捣丸芡子大。每白汤嚼下一丸，端午日合之。（《普 \n济方》）少阴疟疾呕吐∶绿矾一钱，干姜（泡）、半夏（姜制），各半两。为末。每服半钱， \n发 \n日早以醋汤下。（《圣济录》）翻胃吐食∶白面二斤半，蒸作大馒头一个，头上开口，剜空， \n将皂矾填满，以新瓦围住，盐泥封固，挖土窑安放。文武火烧一日夜，取出研末，枣肉为丸 \n梧子大。每服二十丸，空心酒、汤任下。忌酒色。（《医方摘要》）大便不通∶皂矾一钱，巴 \n霜二个，同研，入鸡子内搅匀，封头，湿纸裹，煨熟食之，酒下，即通。（《集玄方》） \n肠风下血∶积年不止，虚弱甚者，一服取效。绿矾四两，入砂锅内，新瓦盖定，盐泥固 \n济， \n赤取出，入青盐、生硫黄各一两、研匀。再入锅中固济， 赤取出，去火毒，研。入熟附 \n子末一两，粟米粥糊丸梧子大。每空心米饮、温酒任下三十丸。（《永类方》）妇人血崩∶青 \n矾二两，轻粉一钱，为末，水丸梧子大。每服二、三十丸，新汲水下。（《摘玄方》）血证黄 \n肿∶绿矾四两，百草霜一升，炒面半升，为末，沙糖和丸梧子大。每服三、四十丸，食后姜 \n汤下。郑时举所传。又方∶小麦淘净一斤，皂矾半斤，同炒黄为末，黑枣肉半斤捣匀，米醋 \n打糊丸梧子大。每姜汤下八、九十丸，一日三服。（《简便方》）脾病黄肿∶青矾四两（ 成 \n赤珠子），当归四两（酒 浸七日，焙），百草霜三两。为末，以浸药酒打糊丸梧子大。每服 \n五丸至七丸，温水下。一月后黄去立效，此方祖传七世。又方∶绿矾四两，百草霜、五倍子 \n各一两，木香一钱。为末，酒煎，飞面丸梧子大。每空心酒下五丸。又方∶平胃散四两、青 \n矾二两。为末，醋糊丸，米饮下。或加乌沉汤四两，酒糊丸亦可。（洁古《活法机要》）酒黄 \n水肿∶黄肿积病。青矾半斤（醋一大盏，和匀，瓦盆内 干为度）、平胃散、乌药顺气散各 \n半 \n两。为末，醋煮糊丸梧子大。每酒或姜汤下二、三十丸。不忌口，加锅灰。（赵原杨真人《济 \n急方》）食劳黄病，身目俱黄∶青矾锅内安，炭 赤，米醋拌为末，枣肉和丸梧子大。每服 \n二、三十丸，食后姜汤下。（《救急方》）腹中食积∶绿矾二两，研，米醋一大碗，瓷器煎之， \n柳条搅成膏，入赤脚乌一两（研），丸绿豆大。每空心温酒下五丸。（《圣惠方》）疳虫食土及 \n生物∶研绿矾末，猪胆汁丸绿豆大。每米饮下五、七丸。（《保幼大全》）小儿疳气不可疗者∶ \n绿矾 赤、醋淬三次，为末，枣肉和丸绿豆大。每服十丸，温水下，日三。（《集验方》） \n走马疳疮∶绿矾入锅内，炭火 红，以醋拌匀，如此三次，为末，入麝香少许。温浆水漱净， \n掺之。（谈野翁《试效方》）白秃头疮∶皂矾、楝树子，烧研，搽之。（《普济方》）小儿头疮∶ \n绛矾一两，淡豉一两（炒黑），腻粉二钱。研匀。以桑灰汤洗净，掺之良。小儿甜疮∶大枣 \n去 \n核，填入绿矾，烧存性研，贴之。（《拔萃方》）耳生烂疮∶枣子去核，包青矾 研，香油调 \n敷之。（《摘玄方》）蚰蜒入耳∶水调绿矾，灌之。（《普济方》）蛆入耳中∶绿矾掺之，即化 \n为水。（《摘玄方》）疮中生蛆∶绿矾末掺贴，即化为水。（《摘玄方》）汤火伤灼∶皂矾和凉 \n水浇之。其疼即止，肿亦消。（杨诚《经验方》）癣疮作痒∶螺蛳十四个，槿树皮末一两，入 \n碗内蒸熟，入矾红三钱捣匀，搽之。（孙氏《集效方》）甲疽延烂∶崔氏方∶治甲疽，或因割 \n甲伤肌，或因甲长侵肉，遂成疮肿，黄水浸淫相染，五指俱烂，渐上脚趺，泡浆四边起，如 \n火烧疮，日夜倍增，医不能疗。绿矾石五两，烧至汁尽，研末，色如黄丹，收之。每以盐汤 \n洗拭，用末浓敷之，以软帛缠裹，当日即汁断疮干。每日一遍，盐汤洗濯，有脓处使净敷， \n其痂干处不须近。但有急痛，即涂酥少许令润。五日即觉上痂起，依前洗敷。十日痂渐剥尽， \n软处或更生白脓泡，即擦破敷之，自然瘥也。张侍郎病此，卧经六十日，京医并处方无效， \n得此法如神。（王焘《外台秘要》）妇人甲疽∶妇人趾甲内生疮，恶肉突出，久不愈，名臭田 \n螺。用皂矾日晒夜露。每以一两，煎汤浸洗。仍以矾末一两，加雄黄二钱，硫黄一钱，乳香、 \n没药各一钱。研匀，搽之。（《医方摘要》）涂染白发∶绿矾、薄荷、乌头等分为末，以铁浆 \n水浸。日染之。（《相感志》）腋下狐气∶绿矾（半生半 ）为末，入少轻粉。以半钱，浴后 \n姜汁调搽，候十分热痛乃止。（《仁斋直指方》） \n\n\n\n<目录>石部第十一卷\\金石之五\n\n<篇名>黄矾\n\n内容：（《纲目》） \n【集解】恭曰∶黄矾，丹灶家所须，亦入染皮用。 \n时珍曰∶黄矾，出陕西瓜州、沙州及舶上来者为上，黄色，状如胡桐泪。人于绿矾中拣 \n出黄色者充之，非真也。波斯出者，打破中有金丝纹，谓之金线矾，磨刀剑显花纹。《丹房 \n镜源》云∶五色山脂，吴黄矾也。 \n【气味】酸、涩、咸，有毒。 \n【主治】疗疮生肉（苏恭）。野鸡 痔，恶疮疥癣（李 ）。治阳明风热牙疼（李杲）。 \n【附方】新五。 \n耳出汁∶黄矾二两烧枯，绵裹二钱塞之。（《圣惠方》） \n妇人颊疮，每年频发∶水银一两半，以猪脂揉擦，令消尽。入黄矾石末二两，胡粉一两， \n再加猪脂和令如泥。洗疮净，涂之。别以胡粉涂膏上。此甘家秘方也。（《肘后方》）身上瘢 \n痕∶黄矾石（烧令汁尽）、胡粉（炒令黄）各八分。细研，以腊月猪脂和研如泥。以生布揩 \n令痛，乃涂药五度。取鹰粪、白燕窠中草（烧灰）等分，和人乳涂之。其瘢自灭，肉平如故。 \n（崔元 \n亮《海上集验方》）急疳蚀齿∶黄矾、青矾半钱，白矾（烧）一钱，麝香一分，为末。敷之， \n吐涎。（《圣惠方》）妒精阴疮∶黄矾、青矾、麝香等分。为末，敷之，不过三度。（《千金 \n方》） \n\n\n\n<目录>石部第十一卷\\金石之五\n\n<篇名>汤瓶内碱\n\n内容：（《纲目》） \n【集解】时珍曰∶此煎汤瓶内，澄结成水碱，如细砂者也。 \n【主治】止消渴，以一两为末，粟米烧饭丸梧子大，每人参汤下二十丸。又小儿口疮， \n卧时以醋调末书十字两足心，验（时珍）。 \n【附方】新二。 \n消渴引饮∶汤瓶内碱、葛根、水萍（焙）等分。每服五钱，水煎服。又方∶汤瓶内碱、 \n菝根（炒）各一两，乌梅（连核）二两（焙）。为散。每服二钱，水一盏，石器煎七分， \n温呷，日一服。（《圣济录》） \n\n\n\n<目录>石部第十一卷\\金石之五\n\n<篇名>附录诸石二十七种\n\n内容：时珍曰∶《别录》有名未用诸石，及诸家所列而不详，难以类附者，通附于此云。石脾 《别 \n录》有名未用曰∶味甘，无毒。主胃中寒热，益气，令人有子。一名胃石，一名膏石，一名 \n硝石。生隐蕃山谷石间，黑如大豆，有赤纹，色微黄，而轻薄如棋子，采无时。 \n弘景曰∶皇甫士安言∶硝石，取石脾与硝石以水煮之，一斛得三斗，正白如雪，以水投 \n中即消，故名消石。按此说，是取硝石合煮成为真硝石，不知石脾是何物？本草有石脾、石 \n肺，人无识者。 \n藏器曰∶石脾生西戎卤地，碱水结成者。 \n时珍曰∶石脾乃生成者，陶氏所说是造成者。按《九鼎神丹经》云∶石脾乃阴阳结气， \n五盐之精，因矾而成，峨嵋山多有之。俗无识者，故古人作成代用。其法用白矾、戎盐各一 \n斤为末，取苦参水二升，铛中煮五沸，下二物煎减半，去滓熬干，色白如雪，此为石脾也。 \n用石脾、朴硝、芒硝各一斤为末，苦参水二斗，铜铛煎十沸，入三物煮减半，去滓煎，着器 \n中，冷水渍一夜，即成硝石。可化诸石为水，此与焰硝之硝石不同，皆非真也。石肺 《别 \n录》曰∶味辛，无毒。主疠咳寒久痿，益气明目。生水中，状如覆肺，黑泽有赤纹，出水即 \n干。 \n弘景曰∶今浮石亦疗咳，似肺而不黑泽，非此也。 \n石肝 《别录》曰∶味酸，无毒。主身痒，令人色美。生常山，色如肝。 \n石肾 《别录》曰∶味咸，无毒。主泄痢，色白如珠。 \n紫石华 《别录》曰∶味甘，平，无毒。主渴，去小肠热。一名茈石华。生中牟山阴， \n采无时。 \n白石华 《别录》曰∶味辛，无毒。主瘅消渴，膀胱热。生腋北乡北邑山，采无时。 \n黄石华 《别录》曰∶味甘，无毒。主阴痿消渴，膈中热，去百毒。生腋北山，黄色， \n采无时。 \n黑石华 《别录》曰∶味甘，无毒。主阴痿消渴，去热，疗月水不利。生弗其劳山阴石 \n间，采无时。 \n陵石 《别录》曰∶味甘，无毒。主益气耐寒，轻身长年。生华山，其形薄泽。 \n时珍曰∶按《圣济录》云∶汗后耳聋。用陵石，有窍如银眼者，为末。每服一钱，冷水 \n下。 \n终石 《别录》曰∶味辛，无毒。主阴痿痹，小便难，益精气。生陵阴，采无时。 \n封石 《别录》曰∶味甘，无毒。主消渴热中，女子疽蚀。生常山及少室，采无时。 \n时珍曰∶虎尾之山、游戏之山、婴侯之山、丰山、服山，多封石，即此。 \n遂石 《别录》曰∶味甘，无毒。主消渴伤中，益气。生泰山阴，采无时。 \n五羽石 《别录》曰∶主轻身长年。一名金黄，生海水中蓬葭山中，黄如金。 \n紫佳石 《别录》曰∶味酸，无毒。主痹血气。一名赤英，一名石血。生邯郸，石如 \n爵茈，二月采。 \n弘景曰∶《三十六水方》呼为紫贺石。 \n火药（《纲目》） 时珍曰∶味辛、酸，有小毒。主疮癣，杀虫，避湿气温疫。乃焰硝、 \n硫黄、杉木炭所合，以为烽燧铳机诸药者。 \n石 《别录》曰∶味甘，无毒。主咳逆气。生石间，色赤如铁脂，四月采。 \n马肝石（《纲目》） 时珍曰∶按郭宪《洞冥记》云∶郅支国进马肝石百片，青黑如马肝， \n以金函盛水银养之。用拭白发，应手皆黑。云和九转丹吞一粒，弥年不饥。亦可作砚。 \n猪牙石（《纲目》） 时珍曰∶明目去翳。出西番，纹理如象牙，枣红色。 \n碧霞石（《纲目》） 时珍曰∶明目、去翳障。 \n龙涎石（《纲目》） 时珍曰∶主大风疠疮。出齐州。一名龙仙石。 \n铅光石（《纲目》） 时珍曰∶主哽骨。 \n太阳石（《纲目》）时珍曰∶刘守真《宣明方》∶治远年近日一切目疾方∶用太阳石、太 \n阴石、碧霞石、猪牙石、河洛石、寒水石、紫石英、代赭石、菩萨石、金精石、银精石、禹 \n余石、矾矿石、云母石、炉甘石、井泉石、阳起石、滑石、乌贼骨、青盐、铜青各一两， \n砂半两，密陀僧一两，鹏砂三钱，乳香二钱，麝香、脑子一钱，轻粉一钱半，黄丹四两，各 \n为末，熊胆一斤，白砂蜜二斤，井华水九碗，同熬至四碗，点水内不散为度，滤净收点。此 \n方所用太阳石、太阴石等，多无考证，姑附于此。朵梯牙（《纲目》） 时珍曰∶周定王《普 \n济方》∶眼科去翳，用水飞朵梯牙、火 大海螺、碗糖霜，为末，日点。又方∶用可铁刺一 \n钱，阿飞勇一钱，李子树胶四钱，白雪粉八钱，为末，鸡子白调作锭，每以乳女儿汁磨点之。 \n又方∶安咱芦（出回回地面）、黑丁香（即蜡粪）、海螵蛸，各为末，日点。所谓朵梯牙、碗 \n糖 \n霜、安咱芦、可铁刺、阿飞勇，皆不知何物也？附录于此以俟。白狮子石（《拾遗》） 藏器 \n曰∶主白虎病，江东人呼为历节风是也。置此于病者前自愈，亦厌伏之意也。白虎，粪神名， \n状如猫。扫粪置门下，令人病此。疗法∶以鸡子揩病患痛处，咒愿，送于粪堆之头上，勿反 \n顾。镇宅大石（《拾遗》） 藏器曰∶主灾异不起。《荆楚岁时记》∶十二月暮日，掘宅四角， \n各埋一大石为镇宅。又《鸿宝万毕术》云∶埋丸石于宅四隅，捶桃核七枚，则鬼无能殃也。 \n神丹（《拾遗》） 藏器曰∶味辛，温，有小毒。主万病，有寒温。飞金石及诸药合成，服之 \n长生神仙。烟药（《拾遗》） 藏器曰∶味辛，温，有毒。主瘰 五痔 瘿瘤，疮根恶肿。乃 \n石黄、空青、桂心并四两，干姜一两。为末，置铁片上烧之。以猪脂涂碗覆之，待药飞上， \n如此五度。随疮大小，以鼠屎大纳孔中，面封之，三度根出也。无孔，针破纳之。 \n\n\n\n<目录>\n\n<篇名>草部第十二卷\n\n内容：李时珍曰∶天造地化而草木生焉。刚交于柔而成根 ，柔交于刚而成枝干。叶萼属阳， \n华实属阴。由是草中有木，木中有草。得气之粹者为良，得气之戾者为毒。故有五形焉（金 \n、木、水、火、土），五气焉（香、臭、臊、腥、膻），五色焉（青、赤、黄、白、黑），五 \n味焉（酸、苦、甘、辛、咸），五性焉（寒、热、温、凉、平），五用焉（升、降、浮、沉、 \n中） \n。炎农尝而辨之，轩岐述而着之，汉、魏、唐、宋明贤良医代有增益。但三品虽存，淄渑交 \n混，诸条重出，泾渭不分。苟不察其精微，审其善恶，其何以权七方、衡十剂而寄死生耶？ \n于是剪繁去复，绳缪补遗，析族区类，振纲分目。除谷、菜外，凡得草属之可供医药者六百 \n一十一种，分为十类∶曰山，曰芳，曰隰，曰毒，曰蔓，曰水，曰石，曰苔，曰杂，曰有名 \n未用。（旧本草部上、中、下三品，共四百四十七种。今并入三十一种，移二十三种入菜部， \n三种入谷部，四种入果部，二种入木部。自木部移并一十四种，蔓草二十九种，菜部移并一 \n十三种，果部移并四种，外类有名未用共二百四十七种） \n《神农本草经》一百六十二种（梁陶弘景注） \n《名医别录》一百三十一种（陶弘景注。七十八种有名未用） \n《李氏药录》一种（魏李当之） \n《吴氏本草》一种（魏吴普） \n《唐本草》三十三种（唐苏恭） \n《本草拾遗》六十八种（唐陈藏器） \n《食疗本草》二种（唐孟诜） \n《海药本草》六种（唐李 ） \n《四声本草》一种（唐萧炳） \n《开宝本草》三十八种（宋马志） \n《嘉 本草》一十七种（宋掌禹锡） \n《图经本草》五十四种（宋苏颂） \n《日华本草》七种（宋人大明） \n《用药法象》一种（元李杲） \n《本草补遗》一种（元朱震亨） \n《救荒本草》一种（明定王） \n《本草会编》一种（明汪机） \n《本草纲目》八十六种（明李时珍） \n【附注】宋雷 《炮炙论》 北齐徐之才《药对》 唐杨损之《删繁》 唐孙思邈《千 \n金》 蜀韩保升《重注》 南唐陈士良《食性》 宋寇宗 《衍义》 唐慎微《证类》 陈 \n承《别说》 金张元素《珍珠囊》 元王好古《汤液》 吴瑞《日用》 明汪颖《食物》 王 \n纶《集要》 陈嘉谟《蒙筌》 定王《救荒》宁原《食鉴》 \n\n\n\n<目录>草部第十二卷\n\n<篇名>草之一\n\n内容：\\x山草类三十一种\\x \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>甘草\n\n内容：（《本经》上品） \n【释名】蜜甘（《别录》）、蜜草（《别录》）、美草（《别录》）、 草（《别录》）、灵通 \n（《记事珠》）、国老（《别录》）。 \n弘景曰∶此草最为众药之主，经方少有不用者，犹如香中有沉香也。国老即帝师之称， \n虽非君而为君所宗，是以能安和草石而解诸毒也。 \n甄权曰∶诸药中甘草为君，治七十二种乳石毒，解一千二百般草木毒，调和众药有功 \n故有国老之号。 \n【集解】《别录》曰∶甘草生河西川谷积沙山及上郡。二月、八月除日采根，曝干，十 \n日成。 \n陶弘景曰∶河西上郡，今不复通市。今出蜀汉中，悉从汶山诸地中来。赤皮断理，看之 \n坚实者，是抱罕草，最佳。抱罕乃西羌地名。亦有火炙干者，理多虚疏。又有如鲤鱼肠者， \n被刀破，不复好。青州间有而不如。又有紫甘草，细而实，乏时亦可用。 \n苏颂曰∶今陕西、河东州郡皆有之。春生青苗，高一、二尺，叶如槐叶，七月开紫花似 \n柰冬，结实作角子如毕豆。根长者，三、四尺，粗细不定，皮赤色，上有横梁，梁下皆细根 \n也。采得去芦头及赤皮，阴干用。今甘草有数种，以坚实断理者为佳。其轻虚纵理及细韧者， \n不堪，惟货汤家用之。谨按∶《尔雅》云∶ ，大苦。郭璞∶ ，似地黄。又《诗·唐风》 \n云∶采苓采苓，首阳之巅，是也。 ，与苓通用。首阳之山在河东蒲 县，乃今甘草所生处 \n相近，而先儒所说苗叶与今全别，岂种类有不同者乎？ \n李时珍曰∶按∶沈括《笔谈》云∶《本草注》引《尔雅》 大苦之注，为甘草者，非矣。 \n郭璞之注，乃黄药也，其味极苦，故谓之大苦，非甘草也。甘草枝叶悉如槐，高五、六尺， \n但叶端微尖而糙涩，似有白毛，结角如相思角，作一本生，至熟时角拆，子扁如小豆，极坚， \n齿啮不破，今出河东西界。寇氏《衍义》亦取此说，而不言大苦非甘草也。以理度之，郭说 \n形状殊不相类，沈说近之。今人惟以大径寸而结紧断纹者，为佳，谓之粉草；其轻虚细小者， \n皆不及之。刘绩《霏雪录》，言安南甘草大者如柱，土人以架屋，不识果然否也？ \n\\x根\\x \n【修治】雷 曰∶凡使须去头尾尖处，其头、尾吐人。每用切长三寸，擘作六七片， \n入瓷器中盛，用酒浸蒸，从巳至午，取出曝干，锉细用。一法∶每斤用酥七两涂炙，酥尽为 \n度。又法∶先炮令内外赤黄用。 \n时珍曰∶方书炙甘草皆用长流水蘸湿炙之，至熟刮去赤皮，或用浆水炙熟，未有酥炙、 \n酒蒸者。大抵补中宜炙用；泻火宜生用。 \n【气味】甘，平，无毒。寇宗 曰∶生则微凉，味不佳；炙则温。 \n王好古曰∶气薄味浓，升而浮，阳也。入足太阴厥阴经。时珍曰∶通入手足十二经。 \n徐之才曰∶术、苦参、干漆为之使，恶远志，反大戟、芫花、甘遂、海藻。 \n权曰∶忌猪肉。 \n时珍曰∶甘草与藻、戟、遂、芫四物相反，而胡洽居士治痰 ，以十枣汤加甘草、大黄， \n乃是痰在膈上，欲令通泄，以拔去病根也。东垣李杲治项下结核，消肿溃坚汤加海藻。丹溪 \n朱震亨治劳瘵，莲心饮用芫花。二方俱有甘草，皆本胡居士之意也。故陶弘景言古方亦有相 \n恶相反者，乃不为害。非妙达精微者，不知此理。 \n【主治】五脏六腑寒热邪气，坚筋骨，长肌肉，倍气力，金疮 ，解毒。久服轻身延年 \n（《本经》。 ，音时勇切，肿也）。温中下气，烦满短气，伤脏咳嗽，止渴，通经脉，利血 \n气，解百药毒，为九土之精，安和七十二种石，一千二百种草（《别录》）。主腹中冷痛，治 \n惊痫，除腹胀满，补益五脏，养肾气内伤，令人阴不痿，主妇人血沥腰痛，凡虚而多热者， \n加用之（甄权）。安魂定魄，补五劳七伤，一切虚损，惊悸烦闷健忘，通九窍，利百脉，益 \n精 \n养气，壮筋骨（大明）。生用泻火热；熟用散表寒，去咽痛，除邪热，缓正气，养阴血，补 \n脾 \n胃，润肺（李杲）。吐肺痿之脓血，消五发之疮疽（好古）。解小儿胎毒惊痫，降火止痛（时 \n珍）。 \n\\x稍\\x 【主治】生用治胸中积热，去茎中痛，加酒煮玄胡索、苦楝子尤妙（元素）。 \n\\x头\\x 【主治】生用能行足厥阴、阳明二经污浊之血，消肿导毒（震亨）。主痈肿， \n宜入吐药（时珍）。 \n【发明】震亨曰∶甘草味甘，大缓诸火，黄中通理，浓德载物之君子也。欲达下焦，须 \n用梢子。杲曰∶甘草气薄味浓，可升可降，阴中阳也。阳不足者，补之以甘。甘温能除大热， \n故生用则气平，补脾胃不足而大泻心火；炙之则气温，补三焦元气而散表寒，除邪热，去咽 \n痛，缓正气，养阴血。凡心火乘脾，腹中急痛，腹皮急缩者，宜倍用之。其性能缓急，而又 \n协和诸药，使之不争。故热药得之缓其热；寒药得之缓其寒；寒热相杂者用之得其平。好古 \n曰∶五味之用，苦泄辛散，酸收咸敛，甘上行而发，而本草言甘草下气何也？盖甘味主中， \n有升降浮沉，可上可下，可外可内，有和有缓，有补有泄，居中之道尽矣。张仲景附子理中 \n汤用甘草，恐其僭上也；调胃承气汤用甘草，恐其速下也，皆缓之之意。小柴胡汤有柴胡、 \n黄芩之寒，人参、半夏之温，而用甘草者，则有调和之意。建中汤用甘草，以补中而缓脾急 \n也；凤髓丹用甘草，以缓肾急而生元气也，乃甘补之意。又曰∶甘者令人中满；中满者勿食 \n甘，甘缓而壅气，非中满所宜也。凡不满而用炙甘草为之补；若中满而用生甘草为之泻， \n能引诸药直至满所，甘味入脾，归其所喜，此升降、浮沉之理也。《经》云∶以甘补之，以 \n甘泻之，以甘缓之，是矣。 \n时珍曰∶甘草外赤中黄，色兼坤离；味浓气薄，资全土德。协和群品，有元老之功；普 \n治百邪，得王道之化。赞帝力而人不知，敛神功而己不与，可谓药中之良相也。然中满、呕 \n吐、酒客之病，不喜其甘；而大戟、芫花、甘遂、海藻，与之相反。是亦迂缓不可以救昏昧， \n而君子尝见嫉于宵人之意欤？ \n颂曰∶按∶孙思邈《千金方》论云∶甘草解百药毒，如汤沃雪。有中乌头、巴豆毒，甘 \n草入腹即定，验如反掌。方称大豆汁解百药毒，予每试之不效，加入甘草为甘豆汤，其验乃 \n奇也。又葛洪《肘后备急方》云∶席辩刺史尝言∶岭南俚人解蛊毒药，并是常用之物，畏人 \n得其法，乃言三百头牛药，或言三百两银药。久与亲狎，乃得其详。凡饮食时，先取炙熟甘 \n草一寸，嚼之咽汁，若中毒。随即吐出。仍以炙甘草三两，生姜四两，水六升，煮二升，日 \n三服。或用都淋藤、黄藤二物，酒煎温常服，则毒随大。小溲出。又常带甘草数寸，随身备 \n急。若经含甘草而食物不吐者，非毒物也。三百头牛药，即土常山也；三百两银药，即马兜 \n铃藤也，详见各条。 \n【附方】旧十五，新二十二。 \n伤寒心悸，脉结代者∶甘草二两。水三升，煮一半，服七合。日一服。（《伤寒类要》） \n伤寒咽痛∶少阴证，甘草汤主之。用甘草二两（蜜水炙），水二升，煮一升半，服五合， \n日二服。（张仲景《伤寒论》） \n肺热喉痛有痰热者。甘草（炒）二两，桔梗（米泔浸一夜）一两。每服五钱，水一钟半， \n入阿胶半片，煎服。（钱乙《直诀》） \n肺痿多涎∶肺痿吐涎沫，头眩，小便数而不咳者，肺中冷也，甘草干姜汤温之。甘草（炙） \n四两，干姜（炮）二两。水三升，煮一升五合，分服。（张仲景《金匮要略》）肺痿久嗽涕唾 \n多，骨节烦闷，寒热。以甘草三两（炙），捣为末。每日取小便三合，调甘草末一钱，服之。 \n（《广利方》） \n小儿热嗽∶甘草二两，猪胆汁浸五宿，炙，研末，蜜丸绿豆大。食后薄荷汤下十丸。名 \n凉膈丸。（《圣惠方》） \n初生解毒∶小儿初生，未可便与朱砂、蜜。只以甘草一指节长，炙碎，以水二合，煮取 \n一合，以绵染点儿口中，可为一蚬壳，当吐出胸中恶汁。此后待儿饥渴，更与之。令儿智慧， \n无病，出痘稀少。（王 《选方》） \n初生便闭∶甘草、枳壳（煨）各一钱。水半盏，煎服。（《全幼心鉴》） \n小儿撮口发噤∶用生甘草二钱半，水一盏，煎六分，温服。令吐痰涎，后以乳汁点儿口 \n中。（《金匮玉函》） \n婴儿目涩∶月内目闭不开，或肿羞明，或出血者，名慢肝风。用甘草一截，以猪胆汁炙， \n为末。每用米泔调少许，灌之。（《幼幼新书》） \n小儿遗尿∶大甘草头，煎汤，夜夜服之。（危氏《得效方》） \n小儿尿血∶甘草一两二钱，水六合，煎二合，一岁儿一日服尽。（姚和众《至宝方》） \n小儿羸瘦∶甘草三两，炙焦为末，蜜丸绿豆大。每温水下五丸，日二服。（《金匮玉函》） \n大人羸瘦∶甘草三两（炙）。每旦以小便煮三、四沸，顿服之。良。（《外台秘要》） \n赤白痢下∶崔宣州衍所传方∶用甘草一尺，炙，劈破，以淡浆水蘸，三二度，又以慢火 \n炙之，后用生姜去皮半两，二味以浆水一升半，煎取八合，服之立效。《梅师方》∶用甘 \n草一两（炙），肉豆蔻七个（煨）锉。以水三升，煎一升，分服。舌肿塞口，不治杀人∶甘 \n草，煎浓汤，热漱频吐。（《圣济总录》） \n太阴口疮∶甘草二寸，白矾一粟大，同嚼，咽汁。（《保命集》） \n发背痈疽∶崔元亮《海上集验方》云∶李北海言，此方乃神授，极奇秘。用甘草三大两 \n（生捣筛末），大麦面九两，和匀，取好酥少许入内，下沸水搜如饼状，方圆大于疮一分， \n热 \n敷肿上，以绸片及故纸隔，令通风，冷则换之。已成者脓水自出；未成者肿便内消，仍当吃 \n黄粥为妙。又一法∶甘草一大两，水炙，捣碎，水一大升浸之，器上横一小刀子，露一宿， \n平明以物搅，令沫出，去沫服之。但是疮肿发背，皆甚效。（苏颂《图经》） \n诸般痈疽∶甘草三两，微炙，切，以酒一斗，同浸瓶中，用黑铅一片溶成汁，投酒中取 \n出，如此九度。令病者饮酒至醉，寝后即愈也。（《经验方》）一切痈疽诸发，预期服之，能 \n消肿逐毒，使毒不内攻，功效不可具述。用大横纹粉草二斤捶碎，河水浸一宿，揉取浓汁， \n再以密绢过，银石器内慢火熬成膏，以瓷罐收之。每服一、二匙，无灰酒或白汤下。曾服丹 \n药者，亦解之，或微利无妨，名国老膏。（《外科精要方》） \n痈疽秘塞∶生甘草二钱半，井水煎服，能疏导下恶物。（《直指方》） \n乳痈初起∶炙甘草二钱，新水煎服，仍令人咂之。（《直指方》） \n些小痈疖∶发热时，即用粉草节，晒干为末，热酒服一、二钱，连进数服，痛热皆止。 \n（《外科精要方》） \n痘疮烦渴∶粉甘草（炙）、栝蒌根等分，水煎服之。甘草能通血脉，发疮痘也。（《直指 \n方》） \n阴下悬痈∶生于谷道前后，初发如松子大，渐如莲子，数十日后，赤肿如桃李，成脓即 \n破，破则难愈也。用横纹甘草一两，四寸截断，以溪涧长流水一碗，河水、井水不用，以文 \n武火慢慢蘸水炙之，自早至午，令水尽为度，劈开视之，中心水润乃止。细锉，用无灰好酒 \n二小碗，煎至一碗，温服，次日再服，便可保无虞。此药不能急消，过二十日，方得消尽。 \n兴化守康朝病已破，众医拱手，服此两剂即合口，乃韶州刘从周方也。（李迅《痈疽方》） \n阴头生疮∶蜜煎甘草末，频频涂之，神效。（《千金方》） \n阴下湿痒∶甘草，煎汤，日洗三、五度。（《古今录验》） \n代指肿痛∶甘草，煎汤渍之。（《千金方》） \n冻疮发裂∶甘草，煎汤洗之。次以黄连、黄柏、黄芩末，入轻粉、麻油调敷。（《谈野 \n翁方》） \n汤火灼疮∶甘草，煎蜜涂。（李楼《奇方》） \n蛊毒药毒∶甘草节，以真麻油浸之，年久愈妙。每用嚼咽，或水煎服，神妙。（《直指 \n方》） \n小儿中蛊欲死者∶甘草半两，水一盏，煎五分，服。当吐出。（《金匮玉函》） \n牛马肉毒∶甘草，煮浓汁，饮一、二升，或煎酒服，取吐或下。如渴，不可饮水，饮之 \n即死。（《千金方》）饮馔中毒，未审何物，猝急无药。只煎甘草荠 汤，入口便活。（《金 \n匮玉函方》） \n水莨菪毒∶菜中有水莨菪，叶圆而光，有毒，误食令人狂乱，状若中风，或作吐。以甘 \n草煮汁服之，即解。（《金匮玉函妙方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>黄耆\n\n内容：（《本经》上品） \n【释名】黄 （《纲目》）、戴糁（《本经》）、戴椹（《别录》，又名独椹）、芰草（《别录》， \n又名蜀脂）、百本（《别录》）、王孙（《药性论》）。 \n时珍曰∶耆，长也。黄耆色黄，为补药之长，故名。今俗通作黄 。或作蓍者，非矣。 \n蓍，乃蓍龟之蓍，音尸。王孙与牡蒙同名异物。 \n【集解】《别录》曰∶黄 ，生蜀郡山谷、白水、汉中。二月、十月采，阴干。 \n弘景曰∶第一出陇西洮阳，色黄白，甜美，今亦难得。次用黑水宕昌者，色白，肌理粗， \n新者亦甘而温补。又有蚕陵白水者，色理胜蜀中者而冷补。又有赤色者，可作膏贴。俗方多 \n用，道家不须。 \n恭曰∶今出原州及华原者，最良，蜀汉不复采用。宜州、宁州者，亦佳。 \n颂曰∶今河东、陕西州郡多有之。根长二、三尺以来。独茎，或作丛生，枝干去地二、 \n三寸。其叶扶疏作羊齿状，又如蒺藜苗。七月中开黄紫花。其实作荚子，长寸许。八月中采 \n根用。其皮折之如绵，谓之绵黄 。然有数种，有白水 、赤水 、木 ，功用并同，而力 \n不及白水 。木 ，短而理横。今人多以苜蓿根假作黄 ，折皮亦似绵，颇能乱真。但苜蓿 \n根坚而脆，黄 至柔韧，皮微黄褐色，肉中白色，此为异耳。 \n承曰∶黄 本出绵上者为良，故名绵黄 ，非谓其柔韧如绵也。今《图经》所绘宪州者， \n地与绵上相邻也。 \n好古曰∶绵上，即出西沁州；白水，在陕西同州。黄 味甘，柔软如绵，能令人肥；苜 \n蓿根，味苦而坚脆，俗呼为土黄 ，能令人瘦。用者宜审。 \n嘉谟曰∶绵上，沁州乡名，今有巡检司；白水、赤水二乡，俱属陇西。 \n时珍曰∶黄 ，叶似槐叶而微尖小，又似蒺藜叶而微阔大，青白色。开黄紫花，大如槐 \n花。结小尖角，长寸许。根长二、三尺，以紧实如箭竿者为良。嫩苗亦可 淘茹食。其子收 \n之，十月下种，如种菜法亦可。 \n【修治】 曰∶凡使勿用木 草，真相似，只是生时叶短并根横也。须去头上皱皮，蒸 \n半日，擘细，于槐砧上锉用。 \n时珍曰∶今人但捶扁，以蜜水涂炙数次，以熟为度。亦有以盐汤润透，器盛，于汤瓶蒸 \n熟切用者。 \n\\x根\\x \n【气味】甘，微温，无毒（《本经》）。白水者冷，补（《别录》）。 \n元素曰∶味甘，气温、平。气薄味浓，可升可降，阴中阳也。入手足太阴气分，又入手 \n少阳、足少阴命门。 \n之才曰∶茯苓为之使，恶龟甲、白藓皮。 \n【主治】痈痈久败疮，排脓止痛，大风癞疾，五痔鼠 ，补虚，小儿百病（《本经》）。 \n妇人子脏风邪气，逐五脏间恶血，补丈夫虚损，五劳羸瘦，止渴，腹痛泄痢，益气，利阴气 \n（《别录》）。主虚喘，肾衰耳聋，疗寒热，治发背，内补（甄权）。助气壮筋骨，长肉补血， \n破症癖，瘰 瘿赘，肠风血崩，带下赤白痢，产前后一切病，月候不匀，痰嗽，头风热毒赤 \n目（《日华》）。治虚劳自汗，补肺气，泻肺火、心火，实皮毛，益胃气，去肌热及诸经之痛 \n（元素）。主太阴疟疾，阳维为病，苦寒热；督脉为病，逆气里急（好古）。 \n【发明】 \n弘景曰∶出陇西者，温补；出白水者，冷补。又有赤色者，可作膏，用消痈肿。 \n藏器曰∶虚而客热，用白水黄 ；虚而客冷，用陇西黄 。 \n大明曰∶黄 ，药中补益，呼为羊肉；白水 ，凉，无毒，排脓治血，及烦闷热毒骨蒸 \n劳；赤水 ，凉，无毒，治血退热毒，余功并同；木 ，凉，无毒，治烦排脓之力，微于黄 \n，遇阙即倍用之。 \n元素曰∶黄 甘温纯阳，其用有五∶补诸虚不足，一也；益元气，二也；壮脾胃，三也； \n去肌热，四也；排脓止痛，活血生血，内托阴疽，为疮家圣药，五也。又曰∶补五脏诸虚， \n治脉弦自汗，泻阴火，去虚热，无汗，则发之；有汗，则止之。 \n好古曰∶黄 ，治气虚盗汗，并自汗及肤痛，是皮表之药；治咯血，柔脾胃，是中州之 \n药；治伤寒尺脉不至，补肾脏元气，是里药。乃上、中、下、内、外、三焦之药也。 \n杲曰∶《灵枢》云∶卫气者，所以温分肉而充皮肤，肥腠理而司开阖。黄 既补三焦， \n实卫气，与桂同功；特比桂甘平，不辛热为异耳。但桂则通血脉，能破血而实卫气， 则益 \n气也。又黄 与人参、甘草三味，为除躁热肌热之圣药。脾胃一虚，肺气先绝，必用黄 温 \n分肉，益皮毛，实腠理，不令汗出，以益元气而补三焦。 \n震亨曰∶黄 补元气，肥白而多汗者，为宜；若面黑形实而瘦者，服之，令人胸满，宜 \n以三拗汤泻之。 \n宗 曰∶防风、黄 ，世多相须而用。唐许胤宗初仕陈为新蔡王外兵参军时，柳太后病 \n风不能言，脉沉而口噤。胤宗曰∶既不能下药，宜汤气蒸之，药入腠理，周时可瘥。乃造黄 \n防风汤数斛，置于床下，气如烟雾，其夕便得语也。 \n杲曰∶防风能制黄 ，黄 得防风其功愈大，乃相畏而相使也。 \n震亨曰∶人之口通乎地，鼻通乎天。口以养阴，鼻以养阳。天主清，故鼻不受有形而受 \n无形；地主浊，故口受有形而兼乎无形。柳太后之病不言，若以有形之汤，缓不及事；今投 \n以二物，汤气满室，则口鼻俱受。非智者通神，不可回生也。 \n杲曰∶小儿外物惊，宜用黄连安神丸镇心药。若脾胃寒湿，呕吐腹痛，泻痢青白，宜用 \n益黄散药。如脾胃伏火，劳役不足之证，及服巴豆之类，胃虚而成慢惊者，用益黄、理中之 \n药，必伤人命。当于心经中，以甘温补土之源，更于脾土中，以甘寒泻火，以酸凉补金，使 \n金旺火衰，风木自平矣。今立黄 汤泻火补金益土，为神治之法。用炙黄 二钱，人参一钱， \n炙甘草五分，白芍药五分，水一大盏，煎半盏，温服。 \n机曰∶萧山魏直着《博爱心鉴》三卷，言小儿痘疮，惟有顺、逆、险三证。顺者为吉， \n不用药。逆者为凶，不必用药。惟险乃悔吝之象，当以药转危为安，宜用保元汤加减主之。 \n此方原出东垣，治慢惊土衰火旺之法。今借而治痘，以其内固营血，外护卫气，滋助阴阳， \n作为脓血，其证虽异，其理则同。去白芍药，加生姜，改名曰保元汤。炙黄 三钱，人参二 \n钱，炙甘草一钱，生姜一片，水煎服之。险证者，初出圆晕干红少润也，浆长光泽，顶陷不 \n起也；既出虽起惨色不明也，浆行色灰不荣也，浆定光润不消也，浆老湿润不敛也，结痂而 \n胃弱内虚也，痂落而口渴不食也，痂后生痈肿也，痈肿溃而敛迟也。凡有诸症，并宜此汤。 \n或加芎 ，加官桂，加糯米以助之。详见本书。 \n嘉谟曰∶人参补中，黄 实表。凡内伤脾胃，发热恶寒，吐泄怠卧，胀满痞塞，神短脉 \n微者，当以人参为君，黄 为臣；若表虚自汗亡阳，溃疡痘疹阴疮者，当以黄 为君，人参 \n为臣，不可执一也。 \n【附方】旧五，新九。 \n小便不通∶绵黄 二钱，水二盏，煎一盏，温服。小儿减半。（《总微论》） \n酒疸黄疾∶心下懊痛，足胫满，小便黄，饮酒发赤黑黄斑，由大醉当风，入水所致。黄 \n二两，木兰一两，为末。酒服方寸匕，日三服。（《肘后方》） \n气虚白浊∶黄 （盐炒）半两，茯苓一两。为末。每服一钱，白汤下。（《经验良方》） \n治渴补虚∶男子妇人诸虚不足，烦悸焦渴，面色萎黄，不能饮食，或先渴而后发疮疖， \n或先痈疽而后发渴，并宜常服此药，平补气血，安和脏腑，终身可免痈疽之疾。用绵黄 （箭 \n杆者，去芦）六两（一半生焙，一半以盐水润湿，饭上蒸三次，焙，锉），粉甘草一两（一 \n半生用，一半炙黄为末）。每服二钱，白汤点服，早晨、日午各一服，亦可煎服，名黄 六 \n一汤。（《外科精要》） \n老人秘塞∶绵黄 、陈皮（去白）各半两。为末。每服三钱，用大麻子一合，研烂，以 \n水 \n滤浆，煎至乳起，入白蜜一匙，再煎沸，调药空心服，甚者不过二服。此药不冷不热，常服 \n无秘塞之患，其效如神。（《和剂局方》） \n肠风泻血∶黄 、黄连等分，为末。面糊丸绿豆大。每服三十丸，米饮下。（孙用和《秘 \n宝方》）尿血沙淋，痛不可忍∶黄 、人参等分。为末，以大萝卜一个，切一指浓大，四、 \n五片，蜜二两，淹炙令尽，不令焦，点末，食无时，以盐汤下。（《永类方》） \n吐血不止∶黄 二钱半，紫背浮萍五钱。为末。每服一钱，姜、蜜水下。（《圣济总录》） \n咳嗽脓血咽干，乃虚中有热，不可服凉药。以好黄 四两，甘草一两。为末。每服二钱，点 \n汤服。（席延赏方） \n肺痈得吐∶黄 二两。为末。每服二钱，水一中盏，煎至六分，温服，日三、四服。（《圣 \n惠方》） \n甲疽疮脓∶生足趾甲边，赤肉突出，时常举发者。黄 二两， 茹一两。醋浸一宿，以 \n猪脂五合，微火上煎取二合，绞去滓，以封疮口上，日三度，其肉自消。（《外台秘要》） \n胎动不安腹痛，下黄汁。黄 、川芎 各一两，糯米一合。水一升，煎半升，分服。（《妇 \n人良方》） \n阴汗湿痒∶绵黄 ，酒炒为末，以熟猪心点吃妙。（赵真人《济急方》） \n痈疽内固∶黄 、人参各一两。为末，入真龙脑一钱，用生藕汁和丸绿豆大。每服二十， \n温水下，日三服。（《本事方》） \n\\x茎叶\\x \n【主治】疗渴及筋挛，痈肿疽疮（《别录》）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>人参\n\n内容：（《本经》上品） \n【释名】人 （音参。或省作 ）、黄参（《吴普》）、血参（《别录》）、人衔（《本经》）、 \n鬼盖（《本经》）、神草（《别录》）、土精（《别录》）、地精（《广雅》）、海腴、皱面还丹 \n（《广雅》）。 \n时珍曰∶人KT 年深，浸渐长成者，根如人形，有神，故谓之人 、神草。 字，从 \n，亦浸渐之义。 ，即浸字，后世因字文繁，遂以参星之字代之，从简便尔。然承误日久， \n亦不能变矣，惟张仲景《伤寒论》尚作KT 字。《别录》一名人衔衔乃 字之讹也。其成有 \n阶级，故曰人衔。其草背阳向阴，故曰鬼盖。其在五参，色黄属土，而补脾胃，生阴血，故 \n有黄参、血参之名。得地之精灵，故有土精、地精之名。《广五行记》云∶隋文帝时，上党 \n有人宅后每夜闻人呼声，求之不得。去宅一里许，见人参枝叶异常，掘之入地五尺，得人参， \n一如人体，四肢毕备，呼声遂绝。观此，则土精之名，尤可证也。《礼斗威仪》云∶下有人 \n参，上有紫气。《春秋运斗枢》云∶摇光星散而为人参。人君废山渎之利，则摇光不明，人 \n参不生。观此，则神草之名，又可证矣。 \n【集解】《别录》曰∶人参生上党山谷及辽东，二月、四月、八月上旬采根，竹刀刮， \n曝干，无令见风。根如人形者，有神。 \n普曰∶或生邯郸，三月生叶小锐，枝黑茎有毛。三月、九月采根。根有手足、面目如人 \n者神。 \n弘景曰∶上党在冀州西南，今来者形长而黄，状如防风，多润实而甘。俗乃重百济者， \n形细而坚白，气味薄于上党者。次用高丽者，高丽地近辽东，形大而虚软，不及百济，并不 \n及上党者。其草一茎直上，四、五叶相对生，花紫色。高丽人作《人参赞》云∶三桠五叶， \n背阳向阴。欲来求我， 树相寻。 ，音贾，树似桐，甚大，附广则多生，采作甚有法。今 \n近山亦有，但作之不好。 \n恭曰∶人参见用多是高丽、百济者，潞州太行紫团山所出者，谓之紫团参。 \n保升曰∶今沁州、辽州、泽州、箕州、平州、易州、檀州、幽州、妫州、并州并出人参， \n盖其山皆与太行连亘相接故也。 \n曰∶新罗国所产者，有手足，状如人形，长尺余，以杉木夹定，红丝缠饰之。又沙州 \n参，短小，不堪用。 \n颂曰∶今河东诸州及泰山皆有之，又有河北榷场及闽中来者，名新罗人参，俱不及上党 \n者佳。春生苗，多于深山背阴，近 漆下湿润处。初生小者三、四寸许，一桠五叶；四、五 \n年后生两桠五叶，未有花茎；至十年后生三桠；年深者生四桠，各五叶。中心生一茎，俗名 \n百尺杵。三月、四月有花，细小如粟，蕊如丝，紫白色。秋后结子，或七、八枚，如大豆， \n生青熟红，自落。根如人形者，神。泰山出者，叶干青，根白，殊别。江淮间出一种土人参， \n苗长一、二尺，叶如匙而小，与桔梗相似，相对生，生五、七节。根亦如桔梗而柔，味极甘 \n美。秋生紫花，又带青色。春秋采根，土人或用之。相传欲试上党参，但使二人同走，一含 \n人参，一空口，度走三、五里许，其不含人参者，必大喘；含者气息自如，其人参乃真也。 \n宗 曰∶上党者，根颇纤长，根下垂，有及一尺余者，或十歧者，其价与银等，稍为难 \n得。土人得一窠，则置板上，以新彩绒饰之。 \n嘉谟曰∶紫团参，紫大稍扁；百济参，白坚且圆，名白条参，俗名羊角参；辽东参，黄 \n润纤长有须，俗名黄参，独胜；高丽参，近紫体虚；新罗参，亚黄味薄。肖人形者神；其类 \n鸡腿者，力洪。 \n时珍曰∶上党，今潞州也。民以人参为地方害，不复采取。今所用者皆是辽参。其高丽、 \n百济、新罗三国，今皆属于朝鲜矣。其参犹来中国互市。亦可收子，于十月下种，如种菜法。 \n秋冬采者，坚实；春夏采者，虚软，非地产有虚实也。辽参，连皮者，黄润色如防风；去皮 \n者，坚白如粉；伪者，皆以沙参、荠 、桔梗采根造作乱之。沙参，体虚无心而味淡；荠 ， \n体虚无心；桔梗，体坚有心而味苦；人参，体实有心而味甘，微带苦，自有余味，俗名金井 \n玉阑也。其似人形者，谓之孩儿参，尤多赝伪。宋苏颂《图经本草》所绘潞州者，三桠五叶 \n，真人参也；其滁州者，乃沙参之苗叶；沁州、兖州者，皆荠 之苗叶。其所云江淮土人参 \n者，亦荠 也。并失之详审。今潞州者尚不可得，则他处者尤不足信矣。近又有薄夫以人参 \n先浸取汁自啜，乃晒干复售，谓之汤参，全不任用，不可不察。考月池翁讳言闻，字子郁， \n衔太医吏目。尝着《人参传》上、下卷甚详，不能备录，亦略节要语于下条云耳。 \n【修治】弘景曰∶人参易蛀 ，唯纳新器中密封，可经年不坏。 \n炳曰∶人参频见风日则易蛀，惟用盛过麻油瓦罐，泡净焙干。入华阴细辛与参相间收之， \n密封，可留经年。一法∶用淋过灶灰，晒干罐收亦可。李言闻曰∶人参生时背阳，故不喜见 \n风日。凡生用宜 咀；熟用，宜隔纸焙之，或醇酒润透 咀、焙熟用，并忌铁器。 \n\\x根\\x \n【气味】甘，微寒，无毒。《别录》曰∶微温。普曰∶神农∶小寒；桐君、雷公∶苦； \n黄帝、岐伯∶甘，无毒。 \n元素曰∶性温，味甘、微苦，气味俱薄，浮而升，阳中之阳也。又曰∶阳中微阴。 \n之才曰∶茯苓、马蔺为之使，恶溲疏、卤碱，反藜芦。一云∶畏五灵脂，恶皂荚、黑豆， \n动紫石英。 \n元素曰∶人参得升麻引用，补上焦之元气，泻肺中之火；得茯苓引用，补下焦之元气， \n泻肾中之火。得麦门冬则生脉；得干姜，则补气。 \n杲曰∶得黄 、甘草，乃甘温除大热，泻阴火，补元气，又为疮家圣药。 \n震亨曰∶人参入手太阴。与藜芦相反，服参一两，入黎芦一钱，其功尽废也。 \n言闻曰∶东垣李氏理脾胃，泻阴火，交泰丸内用人参、皂荚，是恶而不恶也。古方疗月 \n闭四物汤加人参、五灵脂，是畏而不畏也。又疗痰在胸膈，以人参、黎芦同用而取涌越，是 \n激其怒性也。此皆精微妙奥，非达权衡者不能知。 \n【主治】补五脏，安精神，定魂魄，止惊悸，除邪气，明目开心益智。久服轻身延年（《本 \n经》）。疗肠胃中冷，心腹鼓痛，胸胁逆满，霍乱吐逆，调中，止消渴，通血脉，破坚积， \n令人不忘（《别录》）。主五劳七伤，虚损痰弱，止呕哕，补五脏六腑，保中守神。消胸中痰， \n治肺痿及痫疾，冷气逆上，伤寒不下食，凡虚而多梦纷纭者加之（甄权）。止烦躁，变酸水 \n（李 \n）。消食开胃，调中治气，杀金石药毒（大明）。治肺胃阳气不足，肺气虚促，短气少气， \n补中缓中，泻心、肺、脾、胃中火邪，止渴生津液（元素）。治男妇一切虚证，发热自汗， \n眩晕头痛，反胃吐食， 疟，滑泻久痢，小便频数淋沥，劳倦内伤，中风中暑，痿痹，吐血 \n、嗽血、下血，血淋、血崩，胎前、产后诸病（时珍）。 \n【发明】弘景曰∶人参为药切要，与甘草同功。 \n杲曰∶人参甘温，能补肺中元气，肺气旺则四脏之气皆旺，精自生而形自盛，肺主诸气 \n故也。张仲景云∶病患汗后身热、亡血、脉沉迟者，下痢身凉、脉微、血虚者，并加人参。 \n古人血脱者益气，盖血不自生，须得生阳气之药乃生，阳生则阴长，血乃旺也。若单用补血 \n药，血无由而生矣。《素问》言∶无阳则阴无以生，无阴则阳无以化。故补气须用人参，血 \n虚者亦须用之。本草十剂云∶补可去弱，人参、羊肉之属是也。盖人参补气，羊肉补形，形 \n气者，有无之象也。 \n好古曰∶洁古老人言∶以沙参代人参，取其味甘也。然人参补五脏之阳，沙参补五脏之 \n阴，安得无异？虽云补五脏，亦须各用本脏药相佐使引之。 \n言闻曰∶人参生用气凉，熟用气温；味甘补阳，微苦补阴。气主生物，本呼天；味主成 \n物，本呼地。气味生成，阴阳之造化也。凉者，高秋清肃之气，天之阴也，其性降；温者， \n阳春生发之气，天之阳也，其性升。甘者，湿土化成之味，地之阳也，其性浮；微苦者，火 \n土相生之味，地之阴也，其性沉。人参气味俱薄。气之薄者，生降熟升；味之薄者，生升熟 \n降。如土虚火旺之病，则宜生参，凉薄之气，以泻火而补土，是纯用其气也；脾虚肺怯之病， \n则宜熟参，甘温之味，以补土而生金，是纯用其味也。东垣以相火乘脾，身热而烦，气高而 \n喘，头痛而渴，脉洪而大者，用黄柏佐人参。孙真人治夏月热伤元气，人汗大泄，欲成痿厥， \n用生脉散，以泻热火而救金水。君以人参之甘寒，泻火而补元气；臣以麦门冬之苦甘寒，清 \n金而滋水源，佐以五味子之酸温，生肾精而收耗气。此皆补天元之真气，非补热火也。白飞 \n霞云∶人参炼膏服，回元气于无何有之乡。凡病后气虚及肺虚嗽者，并宜之。若气虚有火者， \n合天门冬膏对服之。 \n【正误】 曰∶夏月少使人参，发心 之患。 \n好古曰∶人参甘温，补肺之阳，泄肺之阴。肺受寒邪，宜此补之；肺受火邪，则反伤肺， \n宜以沙参代之。 \n王纶曰∶凡酒色过度，损伤肺肾真阴，阴虚火动，劳嗽吐血、咳血等证，勿用之。盖人 \n参入手太阴能补火，故肺受火邪者忌之。若误服参、 甘温之剂，则病日增；服之过多，则 \n死不可治。盖甘温助气，气属阳，阳旺则阴愈消；惟宜苦甘寒之药，生血降火。世人不识， \n往往服参、 为补，而死者多矣。 \n言闻曰∶孙真人云∶夏月服生脉散、肾沥汤三剂，则百病不生。李东垣亦言生脉散、清 \n暑益气汤，乃三伏泻火益金之圣药，而雷 反谓发心 之患非矣。 乃脐旁积气，非心病也。 \n人参能养正破坚积，岂有发 之理？观张仲景治腹中寒气上冲，有头足，上下痛不可触近， \n呕不能食者，用大建中汤，可知矣。又海藏王好古言人参补阳泄阴，肺寒宜用，肺热不宜用。 \n节斋王纶因而和之，谓参、 能补肺火，阴虚火动失血诸病，多服必死。二家之说皆偏矣。 \n夫人参能补元阳，生阴血，而泻阴火，东垣李氏之说也明矣。仲景张氏言∶亡血血虚者，并 \n加人参；又言∶肺寒者，去人参，加干姜，无令气壅。丹溪朱氏亦言虚火可补，参、 之属； \n实火可泻，芩、连之属。二家不察三氏之精微，而谓人参补火，谬哉。夫火与元气不两立， \n元气胜则邪火退。人参既补元气而又补邪火，是反复之小人矣，何以与甘草、苓、术谓之四 \n君子耶？虽然，三家之言不可尽废也。惟其语有滞，故守之者，泥而执一，遂视人参加蛇蝎， \n则不可也。凡人面白、面黄、面青黧悴者，皆脾、肺、肾气不足，可用也；面赤、面黑者， \n气壮神强，不可用也。脉之浮而芤、濡、虚、大、迟缓无力，沉而迟、涩、弱、细、结、代 \n无力者，皆虚而不足，可用也；若弦长紧实、滑数有力者，皆火郁内实，不可用也。洁古谓 \n喘嗽勿用者，痰实气壅之喘也；若肾虚气短喘促者，必用也。仲景谓肺寒而咳勿用者，寒束 \n热邪壅郁在肺之咳也；若自汗恶寒而咳者，必用也。东垣谓久病郁热在肺勿用者，乃火郁于 \n内宜发不宜补也；若肺虚火旺，气短自汗者，必用也。丹溪言诸痛不可骤用者，乃邪气方锐， \n宜散不宜补也；若里虚吐利及久病胃弱虚痛喜按者，必用也。节斋谓阴虚火旺勿用者，乃血 \n虚火亢能食，脉弦而数，凉之则伤胃，温之则伤肺，不受补者也。若自汗气短，肢寒脉虚者， \n必用也。如此详审，则人参之可用不可用，思过半矣。机曰∶节斋、王纶之说，本于海藏王 \n好古，但纶又过于矫激。丹溪言虚火可补，须用参、 。又云阴虚潮热，喘嗽吐血，盗汗等 \n证，四物加人参、黄柏、知母。又云好色之人，肺肾受伤，咳嗽不愈，琼玉膏主之。又云肺 \n肾虚极者，独参膏主之。是知阴虚劳瘵之证，未尝不用人参也。节斋，私淑丹溪者也，而乃 \n相反如此。斯言一出，印定后人眼目。凡遇前证，不问病之宜用不宜，辄举以借口。致使良 \n工掣肘，惟求免夫病家之怨。病家亦以此说横之胸中，甘受苦寒，虽至上呕下泄，去死不远， \n亦不悟也。古今治劳莫过于葛可久，其独参汤、保真汤，何尝废人参而不用耶？节斋之说， \n诚未之深思也。杨起曰∶人参功载本草，人所共知。近因病者吝财薄医，医复算本惜费，不 \n肯用参疗病，以致轻者至重，重者至危。然有肺寒、肺热、中满、血虚四证，只宜散寒、消 \n热、消胀、补营，不用人参，其说近是；殊不知各加人参在内，护持元气，力助群药，其功 \n更捷。若曰气无补法，则谬矣。古方治肺寒以温肺汤，肺热以清肺汤，中满以分消汤，血虚 \n以养营汤，皆有人参在焉。所谓邪之所辏，其气必虚。又曰养正邪自除，阳旺则生阴血，贵 \n在配合得宜尔。庸医每谓人参不可轻用，诚哉庸也。好生君子，不可轻命薄医，医亦不可计 \n利不用。书此奉勉，幸勿曰迂。 \n【附方】旧七，新六十。 \n人参膏∶用人参十两细切，以活水二十盏浸透，入银石器内，桑柴火缓缓煎取十盏，滤 \n汁，再以水十盏，煎取五盏，与前汁合煎成膏，瓶收，随病作汤使。丹溪云∶多欲之人，肾 \n气衰惫，咳嗽不止，用生姜、橘皮煎汤，化膏服之。浦江郑兄，五月患痢，又犯房室，忽发 \n昏晕，不知人事，手撒目暗，自汗如雨，喉中痰鸣如曳锯声，小便遗失，脉大无伦，此阴亏 \n阳绝之证也。予令急煎大料人参膏，仍与灸气海十八壮，右手能动，再三壮，唇口微动， \n遂与膏服一盏，半夜后服三盏，眼能动，尽三斤，方能言而索粥，尽五斤而痢止，至十斤而 \n全安，若作风治则误矣。一人背疽，服内托十宣药已多，脓出作呕，发热，六脉沉数有力， \n此溃疡所忌也。遂与大料人参膏，入竹沥饮之，参尽一十六斤，竹伐百余竿，而安。后经旬 \n余，值大风拔木，疮起有脓，中有红线一道，过肩胛，抵右肋。予曰∶急作参膏，以芎、归、 \n橘皮作汤，入竹沥、姜汁饮之。尽三斤而疮溃，调理乃安。若痈疽溃后，气血俱虚，呕逆不 \n食，变证不一者，以参、 、归、术等分，煎膏服之，最妙。 \n治中汤∶颂曰∶张仲景治胸痹，心中痞坚，留气结胸，胸满，胁下逆气抢心，治中汤主 \n之。即理中汤，人参、术、干姜、甘草各三两。四味以水八升，煮三升，每服一升，日三服， \n随证加减。此方自晋宋以后至唐名医，治心腹病者，无不用之，或作汤，或蜜丸，或为散， \n皆有奇效。胡洽居士治霍乱，谓之温中汤。陶隐居《百一方》云∶霍乱余药乃或难求，而治 \n中方、四顺汤、浓朴汤不可暂缺，常须预合自随也。唐石泉公王方庆云∶数方不惟霍乱可医， \n诸病皆疗也。四顺汤，用人参、甘草、干姜、附子（炮）各二两，水六升，煎二升半，分四 \n服。 \n四君子汤∶治脾胃气虚，不思饮食，诸病气虚者，以此为主。人参一钱，白术二钱，白 \n茯苓一钱，炙甘草五分，姜三片，枣一枚。水二钟，煎一钟，食前温服。随证加减。（《和 \n剂局方》）开胃化痰∶不思饮食，不拘大人小儿。人参（焙）二两，半夏（姜汁浸，焙）五 \n钱。 \n为末，飞罗面作糊，丸绿豆大。食后姜汤下三、五十丸，日三服。《圣惠方》∶加陈橘皮五钱。 \n（《经验后方》）胃寒气满不能传化，易饥不能食。人参（末）二钱，生附子（末）半钱，生 \n姜二 \n钱。水七合，煎二合，鸡子清一枚，打转空心服之。（《圣济总录》）脾胃虚弱，不思饮食∶ \n生姜半斤（取汁），白蜜十两，人参（末）四两。银锅煎成膏。每米饮调服一匙。（《普济方》） \n胃虚恶心，或呕吐有痰∶人参一两。水二盏，煎一盏，入竹沥一杯，姜汁三匙，食远温服， \n以知为度，老人尤宜。（《简便方》）胃寒呕恶不能腐熟水谷，食即呕吐∶人参、丁香、藿香 \n各二钱半，橘皮五钱，生姜三片，水二盏，煎一盏，温服。（《拔萃方》）反胃呕吐 饮食入 \n口即吐，困弱无力，垂死者。上党人参三大两（拍破）。水一大升，煮取四合，热服，日再。 \n兼以人参汁，入粟米、鸡子白、薤白，煮粥与啖。李直方司勋，于汉南患此，两月余， \n诸方不瘥。遂与此方，当时便定。后十余日，遂入京师。绛每与名医论此药，难可为俦也。 \n（李绛《兵部手集方》）食入即吐 人参半夏汤∶用人参一两，半夏一两五钱，生姜十片。 \n水 \n一斗，以杓扬二百四十遍，取三升，入白蜜三合，煮一升半，分服。（张仲景《金匮方》） \n霍乱呕恶∶人参二两，水一盏半，煎汁一盏，入鸡子白一枚，再煎温服。一加丁香。（《卫 \n生家宝方》）霍乱烦闷∶人参五钱，桂心半钱。水二盏，煎服。（《圣惠方》）霍乱吐泻、烦 \n躁不止∶人参二两，橘皮三两，生姜一两。水六升，煮三升，分三服。（《圣济总录》）妊娠 \n吐水，酸心腹痛，不能饮食∶人参、干姜（炮）等分，为末，以生地黄汁和丸梧子大。每服 \n五 \n十丸，米汤下。（《和剂局方》）阳虚气喘∶自汗盗汗，气短头晕。人参五钱，熟附子一两。 \n分作四帖，每帖以生姜十片，流水二盏，煎一盏，食远温服。（《济生方》）喘急欲绝，上气 \n鸣息者∶人参末，汤服方寸匕，日五、六服效。（《肘后方》）产后发喘 乃血入肺窍，危症 \n也∶人参（末）一两，苏木二两。水二碗，煮汁一碗，调参末服，神效。（《圣惠方》）产后 \n血 \n晕∶人参一两，紫苏半两以童尿、酒、水三合，煎服。（《医方摘要》）产后不语∶人参、石 \n菖蒲、石莲肉等分，每服五钱，水煎服。（《妇人良方》）产后诸虚，发热自汗∶人参、当归 \n等分。为末，用猪腰子一个，去膜，切小片，以水三升，糯米半合，葱白二茎，煮米熟，取 \n汁一盏，入药煎至八分，食前温服。（《永类方》） 产后秘塞出血多∶以人参、麻子仁、枳 \n壳（麸炒）。为末，炼蜜丸梧子大。每服五十丸，米饮下。（《济生方》）横生倒产∶人参（末）、 \n乳香（末）各一钱，丹砂（末）五分。研匀，鸡子白一枚，入生姜自然汁三匙，搅匀，冷服， \n即 \n母子俱安，神效，此施汉卿方也。（《妇人良方》）开心益智∶人参（末）一两，炼成 猪肥 \n肪 \n十两。以淳酒和匀。每服一杯，日再服。服至百日，耳目聪明，骨髓充盈，肌肤润泽，日记 \n千言，兼去风热痰病。（《千金方》）闻雷即昏∶一小儿七岁，闻雷即昏倒，不知人事，此气 \n怯也。以人参、当归、麦门冬各二两，五味子五钱。水一斗，煎汁五升；再以水五升，煎滓 \n取汁二升，合煎成膏。每服三匙，白汤化下。服尽一斤，自后闻雷自若矣。（杨起《简便方》） \n忽喘闷绝∶方见大黄下。离魂异疾∶有人卧则觉身外有身，一样无别，但不语。盖人卧则魂 \n归于肝，此由肝虚邪袭，魂不归舍，病名曰离魂。用人参、龙齿、赤茯苓各一钱。水一盏， \n煎半盏，调飞过朱砂末一钱，睡时服。一夜一服，三夜后，真者气爽，假者即化矣。（夏子 \n益《怪证奇疾方》）怔忡自汗∶心气不足也。人参半两，当归半两，用 猪腰子二个，以 \n水二碗，煮至一碗半，取腰子细切，人参、当归同煎至八分，空心吃腰子，以汁送下。其滓 \n焙干为末，以山药末作糊丸绿豆大。每服五十丸，食远枣汤下，不过两服即愈。此昆山神 \n济大师方也，一加乳香二钱。（王 《百一选方》）心下结气∶凡心下硬，按之则无，常觉膨 \n满，多食则吐，气引前后，噫呃不除，由思虑过多，气不以时而行则结滞，谓之结气。人参 \n一两，橘皮（去白）四两。为末，炼蜜丸梧子大，每米饮下五六十丸。（《圣惠方》）房后困 \n倦∶ \n人参七钱，陈皮一钱，水一盏半，煎八分，食前温服，日再服，千金不传。（赵永庵方）虚 \n劳 \n发热∶愚鲁汤∶用上党人参、银州柴胡各三钱，大枣一枚，生姜三片。水一钟半，煎七分， \n食远温服，日再服，以愈为度。（《奇效良方》）肺热声哑∶人参二两，诃子一两，为末噙咽。 \n（《丹溪摘玄》）肺虚久咳∶人参（末）二两，鹿角胶（炙，研）一两。每服三钱，用薄荷、 \n豉汤 \n一盏，葱少许，入铫子煎一、二沸，倾入盏内。遇咳时，温呷三、五口，甚佳。（《食疗本 \n草》）止嗽化痰∶人参（末）一两，明矾二两。以酽醋二升，熬矾成膏，入参末、炼蜜和收。 \n每以豌豆大一丸，放舌下，其嗽即止，痰自消。（《简便方》）小儿喘咳∶发热自汗吐红，脉 \n虚无力者。人参、天花粉等分。每服半钱，蜜水调下，以瘥为度。（《经济方》）喘咳嗽血∶ \n咳喘上气，喘急，嗽血吐血，脉无力者。人参末每服三钱，鸡子清调之，五更初服便睡，去 \n枕仰卧，只一服愈。年深者，再服。咯血者，服尽一两甚好。一方以乌鸡子水磨千遍，自然 \n化作水，调药尤妙。忌醋、咸、腥、酱，面酢、醉饱，将息乃佳。（沈存中《灵苑方》）咳嗽 \n吐血∶人参、黄 、飞罗面各一两，百合五钱。为末，水丸梧子大。每服五十丸，食前茅根 \n汤下。《朱氏集验方》∶用人参、乳香、辰砂等分。为末，乌梅肉和丸弹子大。每白汤化下一 \n丸，日一服。虚劳吐血甚者，先以十灰散止之，其人必困倦，法当补阳生阴，独参汤主之。 \n好人参一两，肥枣五枚。水二钟，煎一钟服，熟睡一觉，即减五、六，继服调理药。（葛可 \n久《十药神书》）吐血下血∶因七情所感，酒色内伤，气血妄行，口鼻俱出，心肺脉破，血 \n如涌泉，须臾不救。用人参（焙）、侧柏叶（蒸，焙）、荆芥穗（烧存性）各五钱。为末。用 \n二钱， \n入飞罗面二钱，以新汲水调如稀糊服，少倾再啜，一服立止。（华佗《中藏经》）衄血不止∶ \n人参、柳枝（寒食采者）等分，为末。每服一钱，东流水服，日三服。无柳枝，用莲子心。 \n（《圣 \n济总录》）齿缝出血∶人参、赤茯苓、麦门冬各二钱。水一钟，煎七分，食前温服，日再。 \n苏东坡得此，自谓神奇。后生小子多患此病，予累试之，累如所言。（《谈野翁试验方》） \n阴虚尿血∶人参（焙）、黄 （盐水炙）等分。为末。用红皮大萝卜一枚，切作四片，以蜜 \n二两 \n，将萝卜逐片蘸炙，令干再炙，勿令焦，以蜜尽为度。每用一片，蘸药食之，仍以盐汤送下 \n以瘥为度。（《三因方》）沙淋石淋∶方同上。消渴引饮∶人参为末，鸡子清调服一钱，日三、 \n四服。《集验》∶用人参、栝蒌根等分。生研为末，炼蜜丸梧子大。每服百丸，食前麦门冬汤 \n下，日二服，以愈为度。名玉壶丸。忌酒面炙爆。《郑氏家传》消渴方∶人参一两，粉草二 \n两。以雄猪胆汁浸炙，脑子半钱。为末，蜜丸芡子大。每嚼一丸，冷水下。《圣济总录》∶用 \n人参一两，葛粉二两。为末。发时以 猪汤一升，入药三钱，蜜二两，慢火熬至三合， \n状如黑饧，以瓶收之，每夜以一匙含咽，不过三服，取效也。虚疟寒热∶人参二钱二分， \n雄黄五钱。为末，端午日用粽尖捣丸梧子大。发日侵晨，井华水吞下七丸，发前再服。忌诸 \n般热物，立效。一方∶加神曲等分。（《丹溪纂要》）冷痢厥逆、六脉沉细∶人参、大附子各 \n一两半。每服半两，生姜十片，丁香十五粒，粳米一撮。水二盏，煎七分，空心温服。（《经 \n验方》）下痢噤口∶人参、莲肉各三钱。以井华水二盏，煎一盏，细细呷之。或加姜汁炒黄 \n连三钱。（《经验良方》）老人虚痢不止，不能饮食∶上党人参一两，鹿角（去皮，炒研）五 \n钱。 \n为末。每服方寸匕，米汤调下，日三服。（《十便良方》）伤寒坏证∶凡伤寒时疫，不问阴阳， \n老幼妊妇，误服药饵，困重垂死，脉沉伏，不省人事，七日以后，皆可服之，百不失一。此 \n名夺命散，又名复脉汤。人参一两，水二钟，紧火煎一钟，以井水浸冷服之，少顷鼻梁有汗 \n出，脉复立瘥。苏韬光侍郎云∶用此救数十人。予作清流宰，县 申屠行辅之子妇患时疫三 \n十余日，已成壤病，令服此药而安。（王 《百一选方》）伤寒厥逆∶身有微热，烦躁，六脉 \n沉细微弱，此阴极发躁也。无忧散∶用人参半两。水一钟，煎七分，调牛胆南星末二钱，热 \n服，立苏。（《三因方》）夹阴伤寒∶先因欲事，后感寒邪，阳衰阴盛，六脉沉伏，小腹绞痛， \n四肢逆冷，呕吐清水，不假此药，无以回阳。人参、干姜（炮）各一两，生附子一枚（破作 \n八 \n片）。水四升半，煎一升，顿服。脉出身温，即愈。（吴绶《伤寒蕴要》）筋骨风痛∶人参四 \n两（酒浸三日，晒干），土茯苓一斤，山慈菇一两。为末，炼蜜丸梧子大。每服一百丸，食 \n前 \n米汤下。（《经验方》）小儿风痫螈 ∶用人参、蛤粉、辰砂等分。为末，以 猪心血和丸绿 \n豆大。每服五十丸，金银汤下，一日二服，大有神效。（《卫生宝鉴》）脾虚慢惊∶黄 汤， \n见黄 发明下。痘疹险证∶保元汤，见黄 发明下。惊后瞳斜∶小儿惊后瞳人不正者。人参、 \n阿胶（糯米炒成珠）各一钱。水一盏，煎七分，温服，日再服。愈乃止，效。（《直指方》） \n小儿脾风多困∶人参、冬瓜仁各半两，南星一两。浆水煮过，为末。每用一钱，水半盏，煎 \n二、三分，温服。（《本事方》）酒毒目盲∶一人形实，好饮热酒，忽病目盲而脉涩，此热酒 \n所伤，胃气污浊，血死其中而然。以苏木煎汤，调人参末一钱服。次日鼻及两掌皆紫黑，此 \n滞血行矣。再以四物汤，加苏木、桃仁、红花、陈皮，调人参末服，数日而愈。（《丹溪纂 \n要》）酒毒生疽∶一妇嗜酒，胸生一疽，脉紧而涩。用酒炒人参、酒炒大黄，等分为末，姜 \n汤服一钱，得睡汗出而愈。效。（《丹溪医案》）狗咬风伤肿痛∶人参置桑柴炭上烧存性，以 \n碗覆定，少顷为末，掺之，立瘥。（《经验后方》）蜈蚣咬伤∶嚼人参涂之。（《医学集成》） \n蜂虿螫伤∶人参末敷之。（《证治要诀》）胁破肠出∶急以油抹入，煎人参、枸杞汁淋之， \n内吃羊肾粥，十日愈。（危氏《得效方》）气奔怪疾∶方见虎杖。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>芦\n\n内容：【气味】苦，温，无毒。 \n【主治】吐虚劳痰饮（时珍）。 \n【发明】吴绶曰∶人弱者，以人参芦代瓜蒂。 \n震亨曰∶人参入手太阴，补阳中之阴；芦，则反能泻太阴之阳。亦如麻黄，苗，能发汗； \n根，则止汗。谷属金而糠之性热，麦属阳而麸之性凉。先儒谓物物具一太极，学人可不触类 \n而长之乎？一女子性躁味浓，暑月因怒而病呃，每作则举身跳动，昏冒不知人。其形气俱实， \n乃痰因怒郁，气不得降，非吐不可。遂以人参芦半两，逆流水一盏半，煎一大碗饮之，大吐 \n顽痰数碗，大汗昏睡一日而安。又一人作劳发疟，服疟药变为热病，舌短痰嗽，六脉洪数而 \n滑，此痰蓄胸中，非吐不愈。以参芦汤加竹沥二服，涌出胶痰三块，次与人参、黄 、当归 \n煎服，半月乃安。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>沙参\n\n内容：（《本经》上品） \n【校正】并入《别录》有名未用部羊乳。 \n【释名】白参（《吴普》）、知母（《别录》）、羊乳（《别录》）、羊婆奶（《纲目》）、 \n铃儿草（《别录》）、虎须（《别录》）、苦心（《别录》，又名文希，一名识美，一名志取。） \n弘景曰∶此与人参、玄参、丹参、苦参是为五参，其形不尽相类，而主疗颇同，故皆有 \n参名。又有紫参，乃牡蒙也。 \n时珍曰∶沙参白色，宜于沙地，故名。其根多白汁，俚人呼为羊婆奶。《别录》有名未 \n用，羊乳即此也。此物无心味淡，而《别录》一名苦心，又与知母同名，不知所谓也。铃儿 \n草，象花形也。 \n【集解】《别录》曰∶沙参，生河内川谷及冤句般阳续山，二月、八月采根，曝干。又 \n名∶羊乳，一名地黄，三月采，立夏后母死。 \n恭曰∶出华山者，为善。普曰∶二月生苗，如葵，叶青色，根白，实如芥，根大如芜菁， \n三月采。 \n弘景曰∶今出近道，丛生，叶似枸杞，根白实者佳。 \n保升曰∶其根若葵根，其花白色。 \n颂曰∶今淄、齐、潞、随、江、淮、荆、湖州郡皆有之。苗长一、二尺以来，丛生崖壁 \n间，叶似枸杞而有叉丫，七月开紫花，根如葵根，大如指许，赤黄色，中正白实者佳。二月、 \n八月采根。南土生者叶有细有大，花白，瓣上仍有白粘，此为小异。 \n藏器曰∶羊乳根加荠 而圆，大小如拳，上有角节，折之有白汁，人取根当荠 。苗作 \n蔓，折之有白汁。 \n时珍曰∶沙参处处山原有之。二月生苗，叶如初生小葵叶，而团扁不光。八、九月抽茎， \n高一、二尺。茎上之叶，则尖长如枸杞叶，而小有细齿。秋月叶间开小紫花，长二、三分， \n状如铃铎，五出，白蕊，亦有白花者。并结实，大如冬青实，中有细子。霜后苗枯。其根生 \n沙地者，长尺余，大一虎口；黄土地者则短而小。根茎皆有白汁。八、九月采者，白而实； \n春月采者，微黄而虚。小人亦往往絷蒸压实以乱人参，但体轻松，味淡而短耳。 \n\\x根\\x \n【气味】苦，微寒，无毒。《别录》曰∶羊乳，温，无毒。 \n普曰∶沙参，岐伯∶咸；神农、黄帝、扁鹊∶无毒。李当之∶大寒。好古曰∶甘、微苦。 \n之才曰∶恶防己，反藜芦。 \n【主治】血积惊气，除寒热，补中，益肺气（《本经》）。 \n疗胃痹心腹痛，结热邪气头痛，皮间邪热，安五脏。久服利人。又云∶羊乳，主头眩痛， \n益气，长肌肉（《别录》）。去皮肌浮风，疝气下坠，治常欲眠，养肝气，宣五脏风气（甄权）。 \n补虚，止惊烦，益心肺，并一切恶疮疥癣及身痒，排脓，消肿毒（大明）。清肺火，治久咳 \n肺痿（时珍）。 \n【发明】元素曰∶肺寒者，用人参；肺热者，用沙参代之，取其味甘也。好古曰∶沙参 \n味甘微苦，厥阴本经之药，又为脾经气分药。微苦补阴，甘则补阳，故洁古取沙参代人参。 \n盖人参性温，补五脏之阳；沙参性寒，补五脏之阴。虽云补五脏，亦须各用本脏药相佐， \n使随所引而相辅之可也。 \n时珍曰∶人参甘苦温，其体重实，专补脾胃元气，因而益肺与肾，故内伤元气者宜之。 \n沙参甘淡而寒，其体轻虚，专补肺气，因而益脾与肾，故金能受火克者宜之。一补阳而生阴， \n一补阴而制阳，不可不辨之也。 \n【附方】旧一，新二。 \n肺热咳嗽∶沙参半两。水煎服之。（《卫生易简方》）猝得疝气∶小腹及阴中相引痛如绞， \n自汗出，欲死者。沙参，捣筛为末，酒服方寸匕，立瘥。（《肘后方》）妇人白带∶多因七情 \n内伤或下元虚冷所致。沙参为末，每服二钱，米饮调下。《证治要诀》 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>荠\n\n内容：（音齐尼，并上声。《别录》中品） \n【校正】并入《图经》杏参。 \n【释名】杏参（《图经》）、杏叶沙参（《救荒》）、 （ ，音底。《尔雅》）、甜桔梗（《纲 \n目》）、白面根（《救荒》），苗名隐忍。 \n时珍曰∶荠 多汁，有济 之状，故以名之。济 ，浓露也。其根如沙参而叶如杏， \n故河南人呼为杏叶沙参。苏颂《图经》杏参，即此也。俗谓之甜桔梗。《尔雅》云∶ ， \n也。郭璞云∶即荠 也。隐忍，说见下文。 \n【集解】弘景曰∶荠 根茎都似人参，而叶小异，根味甜绝，能杀毒。以其与毒药共处， \n毒皆自然歇，不正入方家用也。又曰∶魏文帝言荠 乱人参，即此也。 \n荠 叶甚似桔梗，但叶下光明滑泽无毛为异，又不如人参相对耳。 \n恭曰∶人参苗似五加而阔短，茎圆有三、四桠，桠头有五叶，陶引荠 乱人参，误矣。 \n且荠 、桔梗又有叶差互者，亦有叶三、四对者，皆一茎直上，叶既相乱，惟以根有心 \n为别尔。 \n颂曰∶今川蜀、江浙皆有之。春生苗茎，都似人参，而叶小异，根似桔梗，但无心为异。 \n润州、陕州尤多，人家收以为果，或作脯啖，味甚甘美，兼可寄远。二月、八月采根，曝干。 \n承曰∶今人多以蒸过压扁乱人参，但味淡尔。 \n宗 曰∶陶以根言，故云荠 乱人参；苏以苗言，故以陶为误也。 \n机曰∶荠 苗茎与桔梗相似，其根与人参相乱。今言苗茎都似人参，近于误也。当以人 \n参、荠 、桔梗三注参看自明矣。 \n时珍曰∶荠 苗似桔梗，根似沙参，故奸商往往以沙参、荠 通乱人参。苏颂《图经》 \n所谓杏参，周定王《救荒本草》所谓杏叶沙参，皆此荠 也。《图经》云∶杏参生淄州 \n田野，根如小菜根。土人五月采苗叶，治咳嗽上气。《救荒本草》云∶杏叶沙参，一名白面 \n根。苗高一、二尺，茎色青白。叶似杏叶而小，微尖而背白，边有叉牙。杪间开五瓣白碗子 \n花。根形如野胡萝卜，颇肥，皮色灰黝，中间白色，味甜微寒。亦有开碧花者。嫩苗炸熟水 \n淘，油盐拌食。根换水煮，亦可食。人以蜜煎充果。又陶弘景注桔梗，言其叶名隐忍，可煮 \n食之，治蛊毒。谨按《尔雅》云∶蒡，隐忍也。郭璞注云∶似苏，有毛。江东人藏以为菹， \n亦可瀹食。葛洪《肘后方》云∶隐忍草，苗似桔梗，人皆食之。捣汁饮，治蛊毒。据此则隐 \n忍非桔梗，乃荠 苗也。荠 苗甘，可食；桔梗苗苦，不可食，尤为可证。《神农本经》无 \n荠，只有桔梗一名荠 ，至《别录》始出荠 。盖荠 、桔梗乃一类，有甜、苦二种，则 \n其苗亦可呼为隐忍也。 \n\\x根\\x \n【气味】甘，寒，无毒。 \n【主治】解百药毒（《别录》）。 \n杀蛊毒，治蛇虫咬，热狂温疾， 毒箭（大明）。利肺气，和中明目止痛，蒸切作羹粥 \n食，或作齑菹食（昝殷）。食之，压丹石发动（孟诜）。主咳嗽消渴强中，疮毒疔肿，辟沙虱 \n短狐毒（时珍）。 \n【发明】时珍曰∶ \n荠 寒而利肺，甘而解毒，乃良品也，而世不知用，惜哉。按葛洪《肘后方》云∶一药 \n而兼解众毒者，惟荠 汁浓饮二升，或煮嚼之，亦可作散服。此药在诸药中，毒皆自解也。 \n又张 《朝野佥载》云∶各医言虎中药箭，食清泥而解；野猪中药箭， 荠 而食。物犹 \n知解毒，何况人乎？又孙思邈《千金方》，治强中为病，茎长兴盛，不交精出，消渴之后， \n发为痈疽，有荠 丸、猪肾荠 汤方，此皆本草所未及者。然亦取其解热解毒之功尔，无他 \n义。 \n【附方】旧四，新三。强中消渴∶猪肾荠 汤∶治强中之病，茎长兴盛，不交精液自出， \n消渴之后，即发痈疽。皆由恣意色欲，或饵金石所致，宜此以制肾中热也。用猪肾一具，荠 \n、石膏各三两，人参、茯苓、磁石、知母、葛根、黄芩、栝蒌根、甘草各二两，黑大豆一 \n升，水一斗半，先煮猪肾、大豆，取汁一斗，去滓下药，再煮三升，分三服。后人名为石子 \n荠汤。又荠 丸∶用荠 、大豆、茯神、磁石、栝蒌根、熟地黄、地骨皮、玄参、石斛、 \n鹿茸各一两，人参、沉香各半两。为末，以猪肚治净煮烂，杵和丸梧子大。每服七十丸，空 \n心盐汤下。（并《千金方》） \n疔疮肿毒∶生荠 根捣汁，服一合，以滓敷之，不过三度。（《千金翼》） \n面上 ∶荠 、肉桂各一两。为末。每用方寸匕，酢浆服之，日一服。又灭瘢痣。（《圣 \n济总录》） \n解诸蛊毒∶荠 根捣末，饮服方寸匕，立瘥。（陈延之《短剧方》） \n解钩吻毒∶钩吻叶与芹叶相似，误食之杀人。惟以荠 八两，水六升，煮取三升，每服 \n五合，日五服。（仲景《金匮玉函》） \n解五石毒∶荠 生捣汁，多服之，立瘥。（苏颂《图经》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>隐忍叶\n\n内容：【气味】甘、苦，寒，无毒。 \n【主治】蛊毒腹痛，面目青黄，林露骨立，煮汁一二升饮（时珍）。主腹脏风壅，咳嗽 \n上气（苏颂）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>桔梗\n\n内容：（《本经》下品） \n【释名】白药（《别录》）、梗草（《别录》）、荠 （《本经》）。 \n时珍曰∶此草之根结实而梗直，故名。《吴普本草》一名利如，一名符扈，一名房图， \n方书并无见，盖亦瘦辞尔。桔梗、荠 乃一类，有甜、苦二种，故《本经》桔梗一名荠 ， \n而今俗呼荠 为甜桔梗也。至《别录》始出荠 条，分为二物，然其性味功用皆不同，当以 \n《别录》为是。 \n【集解】《别录》曰∶桔梗，生嵩高山谷及冤句。二、八月采根，曝干。 \n普曰∶叶如荠 ，茎如笔管，紫赤色，二月生苗。 \n弘景曰∶近道处处有，二、三月生苗，可煮食之。桔梗疗蛊毒，甚验。俗方用此，乃名 \n荠。今别有荠 ，能解药毒，可乱人参，叶甚相似。但荠 叶下光明滑泽无毛为异，叶生 \n又不如人参相对耳。 \n恭曰∶荠 、桔梗，叶有差互者，亦有叶三、四对者，皆一茎直上，叶既相乱，惟以根 \n有心为别耳。 \n颂曰∶今在处有之。根如小指大，黄白色。春生苗，茎高尺余。叶似杏叶而长椭，四叶 \n相对而生，嫩时亦可煮食。夏开小花紫碧色，颇似牵牛花，秋后结子。八月采根，其根有心， \n若无心者为荠 。关中所出桔梗，根黄皮，似蜀葵根。茎细，青色。叶小，青色，似菊叶也。 \n\\x根\\x \n【修治】 曰∶凡使勿用木梗，真似桔梗，只是咬之腥涩不堪。凡用桔梗，须去 \n头上尖硬二、三分以来，并两畔附枝。于槐砧上细锉，用生百合捣膏，投水中浸一伏时滤 \n出，缓火熬令干用。每桔梗四两，用百合二两五钱。 \n时珍曰∶今但刮去浮皮，米泔水浸一夜，切片微炒用。 \n【气味】辛，微温，有小毒。普曰∶神农、医和∶苦，无毒；黄帝、扁鹊∶辛、咸；岐 \n伯、雷公∶甘，无毒。李当之∶大寒。权曰∶苦、辛。时珍曰∶当以苦、辛、平为是。 \n之才曰∶节皮为之使。畏白芨、龙眼、龙胆草忌猪肉。得牡蛎、远志，疗恚怒；得硝石 \n石膏，疗伤寒。白粥解其 毒。 \n时珍曰∶伏砒。徐之才所云节皮，不知何物也。 \n【主治】胸胁痛如刀刺，腹满肠鸣幽幽，惊恐悸气（《本经》）。 \n利五脏肠胃，补血气，除寒热风痹，温中消谷，疗喉咽痛，下蛊毒（《别录》）。治下痢 \n，破血去积气，消积聚痰涎，去肺热气促嗽逆，除腹中冷痛，主中恶及小儿惊痫（甄权）。 \n下一切气，止霍乱转筋，心腹胀痛，补五劳，养气，除邪辟温，破症瘕肺痈，养血排脓，补 \n内漏及喉痹（大明）。利窍，除肺部风热，清利头目咽嗌，胸膈滞气及痛，除鼻塞（元素）。 \n治寒呕（李杲）。主口舌生疮，赤目肿痛（时珍）。 \n【发明】好古曰∶桔梗气微温，味苦辛，味浓气轻，阳中之阴，升也。入手太阴肺经气 \n分及足少阴经。 \n元素曰∶桔梗清肺气，利咽喉，其色白，故为肺部引经。 \n与甘草同行，为舟楫之剂。如大黄苦泄峻下之药，欲引至胸中至高之分成功，须用辛甘 \n之剂升之。譬如铁石入江，非舟楫不载。所以诸药有此一味，不能下沉也。 \n时珍曰∶朱肱《活人书》治胸中痞满不痛，用桔梗、枳壳，取其通肺利膈下气也。张仲 \n景《伤寒论》治寒实结胸，用桔梗、贝母、巴豆，取其温中消谷破积也。又治肺痈唾脓，用 \n桔梗、甘草，取其苦辛清肺，甘温泻火，又能排脓血、补内漏也。其治少阴证二、三日咽痛， \n亦用桔梗、甘草，取其苦辛散寒，甘平除热，合而用之，能调寒热也。后人易名甘桔汤，通 \n治咽喉口舌诸病。宋仁宗加荆芥、防风、连翘，遂名如圣汤，极言其验也。按∶王好古《医 \n垒元戎》载之颇详，云失音，加诃子；声不出，加半夏；上气，加陈皮；涎嗽，加知母、贝 \n母；咳渴，加五味子；酒毒，加葛根；少气，加人参；呕，加半夏、生姜；唾脓血，加紫菀； \n肺痿，加阿胶；胸膈不利，加枳壳；心胸痞满，加枳实；目赤，加栀子、大黄；面肿，加茯 \n苓；肤痛，加黄 ；发斑，加防风、荆芥；疫毒，加鼠粘子、大黄；不得眠，加栀子。震亨 \n曰∶干咳嗽，乃痰火之邪郁在肺中，宜苦梗以开之；痢疾腹痛，乃肺金之气郁在大肠，亦宜 \n苦梗开之，后用痢药。此药能开提气血，故气药中宜用之。 \n【附方】旧十，新八。胸满不痛∶桔梗、枳壳等分。水二钟，煎一钟，温服。（《南阳 \n活人书》）伤寒腹胀∶阴阳不和也，桔梗半夏汤主之。桔梗、半夏、陈皮各三钱，姜五片。 \n水二钟，煎一钟服。（《南阳活人书》） \n痰嗽喘急∶桔梗一两半。为末。用童子小便半升，煎四合，去滓，温服。（《简要济众 \n方》）肺痈咳嗽∶胸满振寒，脉数咽干，不渴，时出浊唾腥臭，久久吐脓如粳米粥者，桔梗 \n汤主之。桔梗一两，甘草二两。水三升，煮一升，分温再服。朝暮吐脓血则瘥。（张仲景《金 \n匮玉函方》）喉痹毒瓦斯∶桔梗二两。水三升，煎一升，顿服。（《千金方》）少阴咽痛∶少阴 \n证，二、三日，咽痛者，可与甘草汤；不瘥者，与桔梗汤主之。桔梗一两，甘草二两。水三 \n升，煮一升，分服。（张仲景《伤寒论》）口舌生疮∶方同上。齿 肿痛∶桔梗、薏苡仁等分。 \n为末服。（《永类方》）骨槽风痛，牙根肿痛∶桔梗为末，枣瓤和丸皂子大。绵裹咬之。仍以 \n荆芥汤漱之。（《经验后方》）牙疳臭烂∶桔梗、茴香等分。烧研，敷之。（《卫生易简方》） \n肝风眼黑∶目睛痛，肝风盛也，桔梗丸主之。桔梗一斤，黑牵牛（头末）三两，为末，蜜丸 \n梧 \n子大。每服四十丸，温水下，日二服。（《保命集》）鼻出衄血∶桔梗为末，水服方寸匕，日 \n四服。一加生犀角屑。（《普济方》）吐血下血∶方同上。打击瘀血在肠内，久不消，时发动 \n者。桔梗为末，米汤下一刀圭。（《肘后要方》）中蛊下血如鸡肝，昼夜出血石余，四脏皆损， \n惟心未毁，或鼻破将死者。苦桔梗为末，以酒服方寸匕，日三服。不能下药，以物拗口灌之。 \n心中当烦，须臾自定，七日止。当食猪肝 以补之。神良。一方加犀角等分。（《古今录验》） \n妊娠中恶，心腹疼痛∶桔梗一两（锉）。水一钟，生姜三片，煎六分，温服。（《圣惠方》） \n小儿客忤，死不能言∶桔梗（烧研）三钱，米汤服之。仍吞麝香少许。（张文仲《备急方》） \n\\x芦头\\x \n【主治】吐上膈风热痰实，生研末，白汤调服一二钱，探吐（时珍）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>长松\n\n内容：（《拾遗》） \n【释名】仙茆。 \n时珍曰∶其叶如松，服之长年，功如松脂及仙茆，故有二名。 \n【集解】藏器曰∶长松生关内山谷中，叶似松，叶上有脂，山人服之。 \n时珍曰∶长松生古松下，根色如荠 ，长三、五寸。味甘微苦，类人参，清香可爱。 \n按∶《张天觉文集》云∶僧普明居五台山，患大风，眉发俱堕，哀苦不堪。忽遇异人， \n教服长松，示其形状。明采服之，旬余毛发俱生，颜色如故。今并代间土人，多以长松杂甘 \n草、山药为汤煎，甚佳。然本草及方书皆不载，独释慧祥《清凉传》始叙其详如此。韩 《医 \n通》云∶长松产太行西北诸山，根似独活而香。 \n\\x根\\x \n【气味】甘，温，无毒。【主治】风血冷气宿疾，温中去风（藏器）。治大风恶疾， \n眉发堕落，百骸腐溃。每以一两，入甘草少许，水煎服，旬日即愈。又解诸虫毒，补益长年 \n（时珍）。 \n【附方】新一。长松酒∶滋补一切风虚，乃庐山休休子所传。长松一两五钱（状似独 \n活而香，乃酒中圣药也）。熟地黄八钱，生地黄、黄 （蜜炙）、陈皮各七钱，当归、浓朴、 \n黄柏各五钱，白芍药（煨）、人参、枳壳各四钱，苍术（米泔制）、半夏（制）、天门冬、麦 \n门冬、 \n砂仁、黄连各三钱，木香、蜀椒、胡桃仁各二钱，小红枣肉八个，老米一撮，灯心（五寸长） \n一百二十根。一料分十剂，绢袋盛之。凡米五升，造酒一尊，煮一袋，窨久乃饮。（《韩氏 \n医通》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>黄精\n\n内容：（《别录》上品） \n【校正】并入《拾遗》救荒草。 \n【释名】黄芝（《瑞草经》）、戊己芝（《五符经》）、菟竹（《别录》）、鹿竹（《别录》）、 \n仙人余粮（弘景）、救穷草（《别录》）、米铺（《蒙筌》）、野生姜（《蒙筌》）、重楼（《别录》）、 \n鸡格（《别录》）、龙衔（《广雅》）、垂珠。 \n颂曰∶隋时羊公服黄精法云∶黄精是芝草之精也，一名葳蕤，一名白芨，一名仙人余粮， \n一名苟格，一名马箭，一名垂珠，一名菟竹。 \n时珍曰∶黄精为服食要药，故《别录》列于草部之首，仙家以为芝草之类，以其得坤土 \n之精粹，故谓之黄精。《五符经》云∶黄精获天地之淳精，故名为戊己芝，是此义也。余粮、 \n救穷，以功名也；鹿竹、菟竹，因叶似竹，而鹿兔食之也。垂珠，以子形也。陈氏《拾遗》 \n救荒草即此也，今并为一。嘉谟曰∶根如嫩姜，俗名野生姜。九蒸九曝，可以代粮，又名米 \n。 \n【集解】《别录》曰∶黄精生山谷。二月采根，阴干。 \n弘景曰∶今处处有之。二月始生，一枝多叶，叶状似竹而短。根似葳蕤。葳蕤根如荻根 \n及菖蒲，概节而平直；黄精根如鬼臼、黄连，大节而不平。虽燥，并柔软有脂润。俗方无用 \n此，而为《仙经》所贵。根、叶、花、实，皆可饵服，酒散随宜，具在断谷方中。其叶乃与 \n钩吻相似，惟茎不紫、花不黄为异，而人多惑之。其类乃殊，遂致死、生之反，亦为奇事。 \n曰∶钩吻真似黄精，只是叶头尖有毛钩子二个，若误服之，害人。黄精叶似竹也。 \n恭曰∶黄精，肥地生者，即大如拳；薄地生者，犹如拇指。葳蕤肥根，颇类其小者，肌 \n理形色，大都相似。今以鬼臼、黄连为比，殊无仿佛。黄精叶似柳及龙胆、徐长卿辈而坚。 \n其钩吻蔓生，叶如柿叶，殊非比类。 \n藏器曰∶黄精叶偏生不对者，名偏精，功用不如正精。正精叶对生。钩吻乃野葛之别名， \n二物殊不相似，不知陶公凭何说此？ \n保升曰∶钩吻，一名野葛，陶说叶似黄精者当是。苏说叶似柿者，当别是一物。 \n颂曰∶黄精南北皆有，以嵩山、茅山者为佳。三月生苗，高一、二尺以来。叶如竹叶而 \n短，两两相对。茎梗柔脆，颇似桃枝，本黄末赤。四月开细青白花，状如小豆花。结子白如 \n黍粒，亦有无子者。根如嫩生姜而黄色，二月采根，蒸过曝干用。今遇八月采，山中人九蒸 \n九曝作果卖，黄黑色而甚甘美。其苗初生时，人多采为菜茹，谓之笔菜，味极美。江南人说 \n黄精苗叶稍类钩吻，但钩吻叶头极尖而根细，而苏恭言钩吻蔓生，恐南北所产之异耳。 \n时珍曰∶黄精野生山中，亦可劈根长二寸，稀种之，一年后极稠，子亦可种。其叶似竹 \n而不尖，或两叶、三叶、四、五叶，俱对节而生。其根横行，状如葳蕤，俗采其苗爆熟，淘 \n去苦味食之，名笔管菜。《陈藏器本草》言青粘是葳蕤，见葳蕤发明下。又黄精、钩吻之说， \n陶弘景、雷 、韩保升皆言二物相似。苏恭、陈藏器皆言不相似。苏颂复设两可之辞。今考 \n《神农本草》、《吴普本草》，并言钩吻是野葛，蔓生，其茎如箭，与苏恭之说相合。张华《博 \n物志》云∶昔黄帝问天老曰∶天地所生，有食之令人不死者乎？天老曰∶太阳之草名黄精， \n食之可以长生；太阴之草名钩吻，不可食之，入口立死。人信钩吻杀人，不信黄精之益寿， \n不亦惑乎？按∶此但以黄精、钩吻相对待而言，不言其相似也。陶氏因此遂谓二物相似，与 \n神农所说钩吻不合。恐当以苏恭所说为是，而陶、雷所说别一毒物，非钩吻也。历代本草惟 \n陈藏器辨物最精审，尤当信之。余见钩吻条。 \n\\x根\\x \n【修治】 曰∶凡采得以溪水洗净蒸之，从巳至子，薄切，曝干用。 \n颂曰∶羊公服黄精法∶二月、三月采根，入地八九寸为上。细切一石，以水二石五斗， \n煮去苦味，漉出，囊中压取汁，澄清再煎，如膏乃止。以炒黑黄豆末，相和得所，捏作饼子， \n如钱大。初服二枚，日益之。亦可焙干筛末，水服。 \n诜曰∶饵黄精法∶取瓮子去底，釜内安置得所，入黄精令满，密盖，蒸至气溜，即曝之。 \n如此九蒸九曝。若生则刺人咽喉。若服生者，初时只可一寸半，渐渐增之，十日不食， \n服止三尺五寸。三百日后，尽见鬼神，久必升天。根、叶、花、实皆可食之。但以相对者是 \n正，不对者名偏精也。 \n【气味】甘，平，无毒。权曰∶寒。 \n时珍曰∶忌梅实，花、叶、子并同。 \n【主治】补中益气，除风湿，安五脏。久服轻身延年不饥（《别录》）。 \n补五劳七伤，助筋骨，耐寒暑，益脾胃，润心肺。单服九蒸九曝食之，驻颜断谷（大明）。 \n补诸虚，止寒热，填精髓，下三尸虫（时珍）。 \n【发明】时珍曰∶黄精受戊己之淳气，故为补黄宫之胜品。土者万物之母，母得其养， \n则水火既济，木金交合，而诸邪自去，百病不生矣。《神仙芝草经》云∶黄精宽中益气，使 \n五脏调良，肌肉充盛，骨髓坚强，其力增倍，多年不老，颜色鲜明，发白更黑，齿落更生。 \n又能先下三尸虫∶上尸名彭质，好宝货，百日下；中尸，名彭矫，好五味，六十日下；下尸 \n名彭居，好五色，三十日下，皆烂出也。根为精气，花实为飞英，皆可服食。又按∶雷氏《炮 \n炙论》序云∶驻色延年，精蒸神锦。注云∶以黄精自然汁拌研细神锦，于柳木甑中蒸七日， \n以木蜜丸服之。木蜜，枳 也。神锦不知是何物，或云朱砂也。 \n禹锡曰∶按《抱朴子》云∶黄精服其花胜其实服其实胜其根。但花难得，得其生花十斛， \n干之，才可得五、六斗尔，非大有力者不能办也。日服三合，服之十年，乃得其益。其断谷 \n不及术。术饵令人肥健，可以负重涉险；但不及黄精甘美易食，凶年可与老少代粮，谓之米 \n脯也。 \n慎微曰∶徐铉《稽神录》云∶临川士家一婢，逃入深山中，久之，见野草枝叶可爱，取 \n根食之，久久不饥。夜息大树下，闻草中动，以为虎攫，上树避之。及晓下地，其身 然凌 \n空而去，若飞鸟焉。数岁家人采薪见之，捕之不得，临绝壁下网围之，俄而腾上山顶。或云 \n此婢安有仙骨，不过灵药服食尔。遂以酒饵置往来之路，果来，食讫，遂不能去，擒之，具 \n述其故。指所食之草，即是黄精也。 \n【附方】旧一，新四。 \n服食法∶《圣惠方》∶用黄精根茎不限多少，细锉阴干捣末。每日水调末服，任多少。一 \n年内变老为少，久久成地仙。 仙《神隐书》∶以黄精细切一石，用水二石五斗煮之，自旦 \n至夕，候冷，以手 碎，布袋榨取汁煎之。渣焙干为末，同入釜中，煎至可丸，丸如鸡头子 \n大。每服一丸，日三服。绝粮轻身，除百病。渴则饮水。 \n补肝明目∶黄精二斤，蔓菁子一斤（淘），同和，九蒸九晒，为末。空心每米饮下二钱， \n日二服，延年益寿。（《圣惠方》） \n大风癞疮∶营气不清，久风入脉，因而成癞，鼻坏色败、皮肤痒溃。用黄精根（去皮， \n洗净）二斤，日中曝令软，纳粟米饭甑中，同蒸至二斗米熟，时时食之。（《圣济总录》） \n补虚精气∶黄精、枸杞子等分。捣作饼，日干为末，炼蜜丸梧子大。每汤下五十丸。（《奇 \n效良方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>葳蕤\n\n内容：（音威 。《本经》上品） \n【释名】女萎（《本经》）、葳蕤（《吴普》）、萎 （音威移）、委萎（《尔雅》）、萎香（《纲 \n目》）、荧（《尔雅》，音行）、玉竹（《别录》）、地节（《别录》）。 \n时珍曰∶按∶黄公绍《古今韵会》云∶葳蕤，草木叶垂之貌。此草根长多须，如冠缨下 \n垂之 而有威仪，故以名之。凡羽盖旌旗之缨 ，皆象葳蕤，是矣。张氏《瑞应图》云∶王 \n者礼备，则葳蕤生于殿前。一名萎香。则威仪之义，于此可见。《别录》作葳蕤，省文也。 \n《说文》作萎 ，音相近也。《尔雅》作委萎，字相近也。其叶光莹而象竹，其根多节，故 \n有荧及玉竹、地节诸名。《吴普本草》又有乌女、虫蝉之名。宋本一名马熏，即乌萎之讹者 \n也。 \n【正误】弘景曰∶《本经》有女萎无葳蕤，《别录》无女萎有葳蕤，而功用正同，疑女萎 \n即葳蕤，惟名异尔。 \n恭曰∶女萎功用及苗蔓与萎蕤全别。今《本经》朱书是女萎功效，故《别录》墨书乃葳 \n蕤功效也。 \n藏器曰∶本草女萎、葳蕤同传。陶云是一物，苏云二物不同，于中品别出女萎一条。然 \n其主霍乱泄痢肠鸣，正与上品女萎相合，则是更非二物矣。 \n颂曰∶观古方书所用，胡洽治时气洞下有女萎丸；治伤寒冷下结肠丸中用女萎；治虚劳 \n下痢小黄 酒中加女萎，详此数方所用，乃似中品女萎，缘其性温主霍乱泄痢故也。又治贼 \n风手足枯痹四肢拘挛茵蓣酒中用女萎；古今录验治身体 疡斑驳，有女萎膏，乃似上品《本 \n经》朱书女萎，缘其主中风不能动摇及去 好色故也。又治伤寒七、八日不解续命鳖甲汤； \n及治脚弱，鳖甲汤，并用葳蕤；及《延年方》，治风热项急痛，四肢骨肉烦热，有葳蕤饮； \n又主虚风热发即头热，有葳蕤丸，乃似上品《别录》墨书葳蕤，缘其主虚热湿毒腰痛故也。 \n三者既别，则非一物明矣。且葳蕤甘平，女萎辛温，安得为一物？ \n时珍曰∶《本经》女萎，乃《尔雅》委萎二字，即《别录》葳蕤也，上古钞写讹为女萎 \n尔。古方治伤寒风虚用女萎者，即葳蕤也，皆承本草之讹而称之。诸家不察，因中品有女萎 \n名字相同，遂致费辩如此。今正其误，只依《别录》书葳蕤为纲，以便寻检。其治泄痢女萎， \n乃蔓草也，见本条。 \n【集解】《别录》云∶葳蕤生泰山山谷及丘陵，立春后采，阴干。 \n普曰∶叶青黄色，相值如姜叶，二月、七月采。 \n弘景曰∶今处处有之。根似黄精，小异。服食家亦用之。 \n颂曰∶今滁州、舒州及汉中、均州皆有之。茎干强直，似竹箭杆，有节。叶狭而长，表 \n白里青，亦类黄精。根黄而多须，大如指，长一、二尺。或云可啖。三月开青花，结圆实。 \n时珍曰∶处处山中有之。其根横生似黄精，差小，黄白色，性柔多须，最难燥。其叶如 \n竹，两两相值。亦可采根种之，极易繁也。嫩叶及根，并可煮淘食茹。 \n\\x根\\x \n【修治】 曰∶凡使勿用黄精并钩吻，二物相似。葳蕤节上有须毛，茎斑，叶尖处 \n有小黄点，为不同。采得以竹刀刮去节皮，洗净，以蜜水浸一宿，蒸了焙干用。 \n【气味】甘，平，无毒。普曰∶神农∶苦；桐君、雷公、扁鹊∶甘，无毒；黄帝∶辛。 \n之才曰∶畏卤碱。 \n【主治】女萎∶主中风暴热，不能动摇，跌筋结肉，诸不足。久服，去面黑 ，好颜色 \n润泽，轻身不老（《本经》）。葳蕤∶主心腹结气，虚热湿毒腰痛，茎中寒，及目痛 烂泪出 \n（《别录》）。时疾寒热，内补不足，去虚劳客热。头痛不安，加而用之，良（甄权）。补中 \n益气（萧炳）。除烦闷，止消渴，润心肺，补五劳七伤虚损，腰脚疼痛。天行热狂，服食无 \n忌 \n（大明）。服诸石人不调和者，煮汁饮之（弘景）。主风温自汗灼热，及劳疟寒热，脾胃虚乏， \n男子小便频数，失精，一切虚损（时珍）。 \n【发明】杲曰∶葳蕤能升能降，阳中阴也。其用有四∶主风淫四末，两目泪烂，男子湿 \n注腰痛，女子面生黑 。 \n时珍曰∶葳蕤性平味甘，柔润可食。故朱肱《南阳活人书》，治风温自汗身重，语言难 \n出，用葳蕤汤，以之为君药。予每用治虚劳寒热 疟，及一切不足之证，用代参、 ，不寒 \n不燥，大有殊功，不只于去风热湿毒而已，此昔人所未阐者也。 \n藏器曰∶陈寿《魏志·樊阿传》云∶青粘，一名黄芝，一名地节。此即葳蕤，极似偏精。 \n本功外，主聪明，调血气，令人强壮。和漆叶为散服，主五脏益精，去三虫，轻身不老，变 \n白，润肌肤，暖腰脚惟有热不可服。晋嵇绍有胸中寒疾，每酒后苦唾，服之得愈。草似竹， \n取根花叶阴干用。 \n昔华佗入山见仙人所服，以告樊阿，服之寿百岁也。 \n颂曰∶陈藏器以青粘即葳蕤。世无识者，未敢以为信然。 \n时珍曰∶苏颂注黄精，疑青粘是黄精，与此说不同。今考黄精、葳蕤性味功用大抵相近， \n而葳蕤之功更胜。故青粘，一名黄芝，与黄精同名；一名地节，与葳蕤同名，则二物虽通用 \n亦可。 \n【附方】旧一，新六。 \n服食法∶二月、九月采葳蕤根，切碎一石，以水二石煮之，从旦至夕，以手 烂，布囊 \n榨取汁，熬稠。其渣晒为末，同熬至可丸，丸如鸡头子大。每服一丸，白汤下，日三服。导 \n气脉，强筋骨，治中风湿毒，去面皱颜色，久服延年。（ 仙《神隐书》）赤眼涩痛∶葳蕤、 \n赤芍药、当归、黄连等分。煎汤，薰洗。（《卫生家宝方》）眼见黑花，赤痛昏暗∶甘露汤∶ \n用葳蕤（焙）四两。每服二钱，水一盏，入薄荷二叶，生姜一片，蜜少许，同煎七分，卧时 \n温 \n服，日一服。（《圣济总录》）小便猝淋∶葳蕤一两，芭蕉根四两。水二大碗，煎一碗半 \n，入滑石二钱，分三服。（《太平圣惠方》）发热口干，小便涩∶用葳蕤五两，煎汁饮之。（《外 \n台秘要》）乳石发热∶葳蕤三两，炙甘草二两，生犀角一两。水四升，煮一升半，分三服。（《圣 \n惠方》）痫后虚肿∶小儿痫病瘥后，血气上虚，热在皮肤，身面俱肿。葳蕤、葵子、龙胆、 \n茯苓、前胡等分，为末。每服一钱，水煎服。（《圣济总录》） \n【附录】鹿药（《开宝》） 志曰∶鹿药甘，温，无毒。主风血，去诸冷，益老起阳，浸 \n酒服之。生姑藏已西，苗根并似黄精，鹿好食其根。 \n时珍曰∶胡洽居士言∶鹿食九种解毒之草，此其一也。或云即是萎蕤，理亦近之。姑附 \n以俟考访。委蛇（音威贻） 《别录》曰∶味甘，平，无毒。主消渴少气，令人耐寒。生人 \n家园中，大枝长须，多叶而两两相值，子如芥子。 \n时珍曰∶此亦似是葳蕤，并俟考访。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>知母\n\n内容：（《本经》中品） \n【释名】 母（《本经》音迟。《说文》作 ）、连母（《本经》）、 母（ 音匙，又音 \n提，或作 ）、货母（《本经》）、地参（《本经》）、水参（又名水须、水浚）、 （《尔雅》， \n音覃）、 藩（音沉烦）、苦心（《别录》）、儿草（《别录》，又名儿踵草、女雷、女理、鹿列、 \n韭逢、东根、野蓼、昌支）时珍曰∶宿根之旁，初生子根，状如 虻之状，故谓之 母，讹 \n为知母、 母也。余多未详。 \n【集解】《别录》曰∶知母，生河内川谷。二月、八月采根，曝干。 \n弘景曰∶今出彭城。形似菖蒲而柔润，叶至难死，掘出随生，须枯燥乃止。 \n禹锡曰∶按∶《范子》云∶提母出三辅，黄白者善。郭璞释《尔雅》云∶ ， 母也。 \n生山上，叶如韭。 \n颂曰∶今濒河怀、卫、彰、德诸郡及解州、滁州亦有之。四月开青花如韭花，八月结实。 \n\\x根\\x \n【修治】 曰∶凡使，先于槐砧上锉细，焙干，木臼杵捣，勿犯铁器。 \n时珍曰∶凡用，拣肥润里白者，去毛，切。引经上行则用酒浸焙干；下行，则用盐水 \n润焙。 \n【气味】苦，寒，无毒。大明曰∶苦、甘。权曰∶平。 \n元素曰∶气寒，味大辛、苦。气味俱浓，沉而降，阴也。又云∶阴中微阳，肾经本药， \n入足阳明、手太阴经气分。 \n时珍曰∶得黄柏及酒良，能伏盐及硼砂。 \n【主治】消渴热中，除邪气，肢体浮肿，下水，补不足，益气（《本经》）。 \n疗伤寒久疟烦热，胁下邪气，膈中恶，及风汗内疸。多服令人泄（《别录》）。心烦躁闷 \n，骨热劳往来，产后蓐劳，肾气劳，憎寒虚烦（甄权）。热劳传尸疰痛，通小肠，消痰止嗽， \n润心肺，安心，止惊悸（大明）。凉心去热，治阳明火热，泻膀胱、肾经火，热厥头痛，下 \n痢 \n腰痛，喉中腥臭（元素）。泻肺火，滋肾水，治命门相火有余（好古）。安胎，止子烦，辟射 \n工、 \n溪毒（时珍）。 \n【发明】权曰∶知母治诸热劳，患人虚而口干者，加用之。 \n杲曰∶知母入足阳明、手太阴。其用有四∶泻无根之肾火，疗有汗之骨蒸，止虚劳之热， \n滋化源之阴。仲景用此入白虎汤治不得眠者，烦躁也。烦出于肺，躁出于肾。君以石膏，佐 \n以知母之苦寒，以清肾之源；缓以甘草、粳米，使不速下也。又凡病小便 塞而渴者，热在 \n上焦气分，肺中伏热不能生水，膀胱绝其化源，宜用气薄、味薄、淡渗之药，以泻肺火、清 \n肺金而滋水之化源。若热在下焦血分而不渴者，乃真水不足，膀胱干涸，乃无阴则阳无以化， \n法当用黄柏、知母大苦寒之药，以补肾与膀胱，使阴气行而阳自化，小便自通。方法详载木 \n部黄柏下。 \n时珍曰∶肾苦燥，宜食辛以润之。肺苦逆，宜食苦以泻之。知母之辛苦寒凉，下则润肾 \n燥而滋阴，上则清肺金而泻火，乃二经气分药也。黄柏则是肾经血分药。故二药必相须而行 \n，昔人譬之虾与水母，必相依附。补阴之说，详黄柏条。 \n【附方】旧二，新六。 \n久近痰嗽 自胸膈下塞停饮，至于脏腑。用知母、贝母各一两（为末），巴豆三十枚（去 \n油，研匀）。每服一字，用姜三片，二面蘸药，细嚼咽下，便睡，次早必泻一行，其嗽立止。 \n壮人乃用之。一方不用巴豆。（《医学集成》）久嗽气急 知母（去毛，切）五钱（隔纸炒）， \n杏 \n仁（姜水泡，去皮尖，焙）五钱。以水一钟半，煎一钟，食远温服。次以萝卜子、杏仁等分。 \n为末，米糊丸。服五十丸，姜汤下，以绝病根。（邓笔峰《杂兴方》）妊娠子烦 因服药致胎 \n气不安，烦不得卧者。知母一两（洗焙）。为末，枣肉丸弹子大。每服一丸，人参汤下。医 \n者 \n不识此病，作虚烦治，反损胎气。产科郑宗文得此方于陈藏器《本草拾遗》中，用之良验。 \n（杨归浓《产乳集验方》）妊娠腹痛 月未足，如欲产之状。用知母二两为末，蜜丸梧子大。 \n每粥饮下二十丸。（《圣惠方》）溪毒射工 凡中溪毒。知母（连根叶）捣作散服，亦可投水 \n捣 \n绞汁饮一二升。夏月出行，多取其屑自随。欲入水，先取少许投水上流，便无畏。兼辟射工。 \n亦可煮汤浴之，甚佳。（《肘后良方》）紫癜风疾 醋磨知母擦之，日三次。（《卫生易简方 \n》）嵌甲肿痛 知母（烧存性）研，掺之。（《多能方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>肉苁蓉\n\n内容：（《本经》上品） \n【释名】肉松容（《吴普》）、黑司命（《吴普》）。 \n时珍曰∶此物补而不峻，故有从容之号。从容，和缓之貌。 \n【集解】《别录》曰∶肉苁蓉，生河西山谷及代郡雁门，五月五日采，阴干。 \n普曰∶生河西山阴地，丛生，二月至八月采。 \n弘景曰∶代郡雁门属并州，多马处便有之，言是野马精落地所生。生时似肉，以作羊肉 \n羹补虚乏极佳，亦可生啖。芮芮河南间至多。今第一出陇西，形扁广，柔润多花而味甘。次 \n出北地者，形短而少花。巴东建平间亦有，而不嘉也。 \n恭曰∶此乃论草苁蓉也，陶未见肉者。今人所用亦草苁蓉刮去花，代肉苁蓉，功力稍劣。 \n保升曰∶出肃州福禄县沙中。三月、四月掘根，长尺余，切取中央好者三四寸，绳穿阴 \n干，八月始好，皮有松子鳞甲。其草苁蓉，四月中旬采，长五、六寸至一尺以来，茎圆紫色。 \n大明曰∶生 落树下，并土堑上，此即非马交之处，陶说误尔。又有花苁蓉，即暮春抽苗者， \n力较微尔。 \n颂曰∶今陕西州郡多有之，然不及西羌界中来者，肉浓而力紧。旧说是野马遗沥所生， \n今西人云大木间及土堑垣中多生，乃知自有种类尔。或疑其初生于马沥，后乃滋殖，如茜根 \n生于人血之类是也。五月采取，恐老不堪，故多三月采之。 \n震亨曰∶河西混一之后，今方识其真形，何尝有所谓鳞甲者？盖苁蓉罕得，人多以金莲 \n根用盐盆制而为之，又以草苁蓉充之，用者宜审。 \n嘉谟曰∶今人以嫩松梢盐润伪之。 \n【修治】 曰∶凡使先须清酒浸一宿，至明以棕刷去沙土浮甲，劈破中心，去白膜一重 \n，如竹丝草样。有此，能隔人心前气不散，令人上气也。以甑蒸之，从午至酉取出，又用酥 \n炙得所。 \n【气味】甘，微温，无毒。《别录》曰∶酸、咸。普曰∶神农、黄帝∶咸；雷公∶酸； \n李当之∶小温。 \n【主治】五劳七伤，补中，除茎中寒热痛，养五腑，强阴，益精气，多子，妇人症瘕。 \n久服轻身（《本经》）。除膀胱邪气腰痛，止痢（《别录》）。益髓，悦颜色，延年，大补壮阳， \n日御过倍，治女人血崩（甄权）。男子绝阳不兴，女子绝阴不产，润五脏，长肌肉，暖腰膝， \n男子泄精尿血遗沥，女子带下阴痛（大明）。 \n【发明】好古曰∶命门相火不足者，以此补之，乃肾经血分药也。凡服苁蓉以治肾，必 \n妨心。 \n震亨曰∶峻补精血，骤用，反动大便滑也。 \n藏器曰∶强筋健髓，以苁蓉、鳝鱼二味为末，黄精汁丸服之，力可十倍。此说出《干宁 \n记》。 \n颂曰∶西人多用作食。只刮去鳞甲，以酒浸洗去黑汁，薄切，合山芋、羊肉作羹，极美 \n好，益人，胜服补药。 \n宗 曰∶洗去黑汁，气味皆尽矣。然嫩者，方可作羹；老者，味苦。入药，少则不效。 \n【附方】旧一，新四。 \n补益劳伤，精败面黑∶用苁蓉四两，水煮令烂，薄切细研精羊肉，分为四度，下五味， \n以米煮粥空心食。（《药性论》）肾虚白浊∶肉苁蓉、鹿茸、山药、白茯苓等分，为末，米糊 \n丸梧子大，每枣汤下三十丸。（《圣济总录》）汗多便秘，老人虚人皆可用。肉苁蓉（酒浸， \n焙）二两，研沉香末一两。为末，麻子仁汁打糊，丸梧子大。每服七十丸，白汤下。（《济生 \n方》）消中易饥∶肉苁蓉、山茱萸、五味子为末。蜜丸梧子大。每盐酒下二十丸。（《医学指 \n南》）破伤风病，口噤身强∶肉苁蓉切片晒干，用一小盏，底上穿定，烧烟于疮上熏之，累 \n效。（《卫生总微》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>列当\n\n内容：（宋《开宝》） \n【释名】栗当（《开宝》）、草苁蓉（《开宝》）、花苁蓉（《日华》）。 \n【集解】志曰∶列当生山南岩石上，如藕根，初生掘取阴干。 \n保升曰∶原州、秦州、渭州、灵州皆有之。暮春抽苗，四月中旬采取，长五、六寸至一 \n尺以来，茎圆紫色，采取压扁，日干。 \n颂曰∶草苁蓉根与肉苁蓉极相类，刮去花，压扁以代肉者，功力殊劣。即列当也。 \n\\x根\\x \n【气味】甘，温，无毒。 \n【主治】男子五劳七伤，补腰肾，令人有子，去风血，煮酒、浸酒服之（《开宝》）。 \n【附方】旧一。 \n阳事不兴∶栗当（好者）二斤（即列当）。捣筛毕，以好酒一斗浸之经宿，随性日饮之。 \n（昝殷《食医心镜》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>锁阳\n\n内容：（《补遗》） \n【集解】时珍曰∶锁阳出肃州。按∶陶九成《辍耕录》云∶锁阳，生鞑靼田地，野马或 \n与蛟龙遗精入地，久之发起如笋，上丰下俭，鳞甲栉比，筋脉联系，绝类男阳，即肉苁蓉之 \n类。或谓里之淫妇，就而合之，一得阴气，勃然怒长。土人掘取洗涤，去皮薄切晒干，以充 \n药货，功力百倍于苁蓉也。时珍疑此自有种类，如肉苁蓉、列当，亦未必尽是遗精所生也。 \n【气味】甘，温，无毒。 \n【主治】大补阴气，益精血，利大便。虚人大便燥结者，啖之可代苁蓉，煮粥弥佳。不 \n燥结者勿用（震亨）。润燥养筋，治痿弱（时珍）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>天麻\n\n内容：（宋《开宝》） \n【校正】天麻，系宋本重出，今并为一。 \n【释名】赤箭芝（《药性》）、独摇芝（《抱朴子》）、定风草（《药性》）、离母（《本经 \n》）、合离草（《抱朴子》）、神草（《吴普》）、鬼督邮（《本经》）。 \n弘景曰∶赤箭，亦是芝类。其茎如箭杆，赤色，叶生其端。根如人足，又云如芋，有十 \n二子为卫。有风不动，无风自摇。如此，亦非俗所见。而徐长卿亦名鬼督邮。又有鬼箭，茎 \n有羽，其主疗并相似，而益大乖异，并非此赤箭也。 \n颂曰∶按∶《抱朴子》云∶仙方有合离草，一名独摇芝，一名离母。所以谓之合离、离 \n母者，此草下根如芋魁，有游子十二枚周环之，以仿十二辰也。去大魁数尺，皆有细根如白 \n发，虽相须而实不相连，但以气相属尔。如菟丝之草，下有伏菟之根，无此则丝不得上， \n亦不相属也。然则赤箭之异，陶隐居已云非俗所见，菟丝之下有伏菟，亦不闻有见者，殆其 \n种类，时有神异者而如此尔。 \n时珍曰∶赤箭，以状而名；独摇、定风，以性异而名；离母、合离，以根异而名；神草 \n、鬼督邮，以功而名。天麻即赤箭之根，《开宝本草》重出一条，详后集解下。 \n【集解】《别录》曰∶赤箭生陈仓川谷、雍州及太山少室。三月、四月、八月采根，曝 \n干。 \n弘景曰∶陈仓，今属雍州扶风郡。 \n志曰∶天麻，生郓州、利州、太山、崂山诸处，五月采根曝干。叶如芍药而小，当中抽 \n一茎，直上如箭杆。茎端结实，状若续随子。至叶枯时，子黄熟。其根连一、二十枚，犹如 \n天门冬之类。形如黄瓜，亦如芦菔，大小不定。彼人多生啖，或蒸煮食之。今多用郓州者佳。 \n恭曰∶赤箭，是芝类。茎似箭杆，赤色。端有花，叶赤色，远看如箭有羽。四月开花， \n结实似苦楝子，核作五、六棱，中有肉如面，日曝则枯萎。其根皮肉汁，大类天门冬，惟 \n无心脉尔。去根五、六寸，有十余子卫之，似芋，可生啖之，无干服之法。颂曰∶赤箭，今 \n江湖间亦有之，然不中药用。其苗如苏恭所说，但《本经》云三月、四月、八月采根，不言 \n用苗。而今方家乃三月、四月采苗，七月、八月、九月采根，与《本经》参差不同，难以兼 \n着，故但从今法。又曰∶天麻，今汴京东西、湖南、淮南州郡皆有之。春生苗，初出若芍药 \n，独抽一茎直上，高三、四尺，如箭杆状，青赤色，故名赤箭芝。茎中空，依半以上，贴茎 \n微有尖小叶。梢头生成穗，开花结子，如豆粒大。其子至夏不落，却透虚入茎中，潜生土内 \n。其根形如黄瓜，连生一、二十枚，大者至重半斤，或五、六两。其皮黄白色，名曰龙皮。 \n肉名天麻，二月、三月、五月、八月内采。初得乘润刮去皮，沸汤略煮过，曝干收之。嵩山 \n、衡山人，或取生者，蜜煎作果食，甚珍之。宗 曰∶赤箭，天麻苗也。与天麻治疗不同， \n故后人分为二条。承曰∶今医家见用天麻，即是赤箭根。《开宝本草》又于中品出天麻一条 \n，云出郓州。今之赤箭根苗，皆自齐、郓而来者为上。苏颂《图经》所载天麻之状，即赤箭 \n苗之未长大者也。赤箭用苗，有自表入里之功；天麻用根，有自内达外之理；根则抽苗径直 \n而上，苗则结子成熟而落，返从杆中而下，至土而生，此粗可识其外内主治之理。今翰林沈 \n括最为博识，尝云∶古方用天麻不用赤箭，用赤箭不用天麻，则天麻、赤箭本为一物明矣。 \n机曰∶赤箭、天麻，一物也，经分为二，以根与苗主治不同也。产不同地者，各有所宜 \n也。时珍曰∶《本经》止有赤箭，后人称为天麻。甄权《药性论》云∶赤箭芝一名天麻，本 \n自明白。宋人马志《重修本草》，重出天麻，遂致分辩如此。沈括《笔谈》云∶《神农本草 \n》明言赤箭采根，后人谓其根如箭，疑当用茎，盖不然也。譬如鸢尾、牛膝，皆因茎叶相似 \n，则用其根，何足疑哉？上品五芝之外，补益上药，赤箭为第一。世人惑于天麻之说，遂止 \n用之治风，良可惜哉。沈公此说虽是，但根、茎并皆可用。天麻子从茎中落下，俗名还筒子 \n。其根曝干，肉色坚白，如羊角色，呼羊角天麻；蒸过黄皱如干瓜者，俗呼酱瓜天麻，皆可 \n用者。一种形尖而空，薄如玄参状者，不堪用。《抱朴子》云∶独摇芝，生高山深谷之处， \n所生左右无草。其茎大如手指，赤如丹素。叶似小苋。根有大魁如斗，细者如鸡子十二枚绕 \n之。人得大者，服之延年。按∶此乃天麻中一种神异者，如人参中之神参也。 曰∶凡使天 \n麻，勿用御风草，二物相似，只是叶、茎不同。御风草根茎斑，叶背白有青点。使御风草， \n即勿使天麻。若同用，令人有肠结之患。 \n【正误】藏器曰∶天麻，生平泽，似马鞭草，节节生紫花。花中有子，如青葙子。子性 \n寒，作饮去热气。茎叶捣敷痈肿。承曰∶藏器所说，与赤箭不相干，乃别一物也。时珍曰∶ \n陈氏所说，乃一种天麻草，是益母草之类是也。《嘉 本草》误引入天麻下耳。今正其误。 \n【修治】 曰∶修事天麻十两，锉，安于瓶中。用蒺藜子一镒，缓火熬焦，盖于天麻上， \n以三重纸封系，从巳至未取出，蒺藜炒过，盖系如前，凡七遍。用布拭上气汗，刀劈焙干， \n单捣用。若用御风草，亦同此法。时珍曰∶此乃治风痹药，故如此修事也。若治肝经风虚， \n惟洗净，以湿纸包，于糠火中煨熟，取出切片，酒浸一宿，焙干用。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>赤箭\n\n内容：（《本经》上品） \n【气味】辛，温，无毒。志曰∶天麻，辛、平，无毒。大明曰∶甘，暖。权曰∶赤箭 \n芝，一名天麻。味甘，平，无毒。好古曰∶苦，平，阴中之阳也。 \n【主治】杀鬼精物，蛊毒恶气。久服益气力，长阴肥健，轻身增年（《本经》）。消痈肿， \n下支满，寒疝下血（《别录 \n强筋力。久服益气，轻身长年（《开宝》）。治冷气 痹，摊缓不随，语多恍惚，善惊失志 \n（甄权）。助阳气，补五劳七伤，鬼疰，通血脉，开窍。服食无忌。（大明）治风虚眩运头痛 \n（元素）。 \n【发明】杲曰∶肝虚不足者，宜天麻、芎 以补之。其用有四∶疗大人风热头痛， \n小儿风痫惊悸，诸风麻痹不仁，风热语言不遂。时珍曰∶天麻，乃肝经气分之药。《素问》 \n云∶诸风掉眩，皆属于肝。故天麻入厥阴之经而治诸病。按∶罗天益云∶眼黑头旋，风虚内 \n作，非天麻不能治。天麻乃定风草，故为治风之神药。今有久服天麻药，遍身发出红丹者， \n是其祛风之验也。宗 曰∶天麻，须别药相佐使，然后见其功，仍须加而用之。人或蜜渍为 \n果，或蒸煮食，当深思则得矣。 \n【附方】新二。 \n天麻丸∶消风化痰，清利头目，宽胸利膈。治心忪烦闷，头晕欲倒，项急，肩背拘倦， \n神 \n二两。为末，炼蜜丸如芡子大。每食后嚼一丸，茶、酒任下。（《普济方》）腰脚疼痛∶天麻 \n、半夏、细辛各二两。绢袋二个，各盛药令匀，蒸热，交互熨痛处。汗出则愈。数日再熨。 \n（《卫生易简方》）还筒子 \n【主治】定风补虚，功同天麻（时珍）。 \n【附方】新一。 \n益气固精∶补血，黑发，益寿，有奇效。还筒子半两，芡实半两，金银花二两，破故纸 \n（酒浸，春三、夏一、秋二，冬五日，焙，研末）二两。各研末，蜜糊丸梧子大。每服五十 \n丸，空心盐汤 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>术\n\n内容：（直律切。《本经》上品） \n【释名】山蓟（《本经》）、杨桴（音孚）、桴蓟（《尔雅》）、马蓟（《纲目》）、山姜（《别 \n录》）、山连（《别录》）、吃力伽（《日华》）。时珍曰∶按《六书本义》，术字篆文，象其根 \n干枝叶之形。《吴普本草》一名山芥，一名天蓟。因其叶似蓟，而味似姜、芥也。西域谓之 \n吃力伽，故《外台秘要》有吃力伽散。扬州之域多种白术，其状如桴，故有杨桴及桴蓟之名 \n，今人谓之吴术是也。桴乃鼓槌之名。古方二术通用。后人始有苍、白之分，详见下。 \n【集解】《别录》曰∶术，生郑山山谷、汉中、南郑。二月、三月、八月、九月采根， \n曝干。 \n弘景曰∶郑山，即南郑也。今处处有，以蒋山、白山、茅山者为胜。十一月、十二月采 \n者好，多脂膏而甘。其苗可作饮，甚香美。术有两种∶白术，叶大有毛而作桠，根甜而少膏 \n，可作丸、散用；赤术，叶细无桠，根小苦而多膏，可作煎用。东境术大而无气烈，不任用 \n。今市人卖者，皆以米粉涂令白，非自然矣，用时宜刮去之。 \n颂曰∶术，今处处有之，以茅山、嵩山者为佳。春生苗，青色无桠。茎作蒿干状，青赤 \n色，长三、二尺以来。夏开花，紫碧色，亦似刺蓟花，或有黄白色者。入伏后结子，至秋而 \n苗枯。根似姜而旁有细根，皮黑，心黄白色，中有膏液紫色。其根干湿并通用。陶隐居言术 \n有二种，则《尔雅》所谓桴蓟，即白术也。今白术生杭、越、舒、宣州高山岗上，叶叶相对 \n，上有毛，方茎，茎端生花，淡紫碧红数色，根作桠生。二月、三月、八月、九月采，曝干 \n用，以大块紫花为胜。古方所用术者，皆白术也。 \n宗 曰∶苍术，长如大拇指，肥实，皮色褐，其气味辛烈，须米泔浸洗，去皮用。白术 \n粗促，色微褐，其气亦微辛苦而不烈。古方及《本经》止言术，不分苍、白二种，亦宜两审 \n时珍曰∶苍术，山蓟也，处处山中有之。苗高二、三尺，其叶抱茎而生，梢间叶似棠梨 \n叶，其脚下叶有三、五叉，皆有锯齿小刺。根如老姜之状，苍黑色，肉白有油膏。白术，桴 \n蓟也，吴越有之。人多取根栽莳，一年即稠。嫩苗可茹，叶稍大而有毛。根如指大，状如鼓 \n槌，亦有大如拳者。彼人剖开曝干，谓之削术，亦曰片术。陈自良言∶白而肥者，是浙术； \n瘦而黄者，是幕阜山所出，其力劣。昔人用术不分赤、白。自宋以来，始言苍术苦辛气烈， \n白术苦甘气和，各自施用，亦颇有理。并以秋采者，佳；春采者，虚软易坏。嵇含《南方草 \n木状》云∶药有吃力伽，即术也。濒海所产，一根有至数斤者，采饵尤良。嘉谟曰∶浙术， \n俗名云头术，种平壤，颇肥大，由粪力也，易润油。歙术，俗名狗头术，虽瘦小，得土气充 \n也，甚燥白，胜于浙术。宁国、昌化、池州者，并同歙术，境相邻也。 \n\\x术\\x（白术也） \n【气味】甘，温，无毒。《别录》曰∶甘。权曰∶甘，辛。 \n杲曰∶味苦而甘，性温，味浓气薄，阳中阴也，可升可降。 \n好古曰∶入手太阳、少阴，足太阴、阳明，少阴、厥阴六经。 \n之才曰∶防风、地榆为之使。 \n权曰∶忌桃、李、菘菜、雀肉、青鱼。 \n嘉谟曰∶咀后人乳汁润之，制其性也。脾病，以陈壁土炒过，窃土气以助脾也。 \n【主治】风寒湿痹，死肌痉疸，止汗除热消食。作煎饵，久服，轻身延年不饥（《本经》） \n。主大风在身面，风眩头痛，目泪出，消痰水，逐皮间风水结肿，除心下急满，霍乱吐下不 \n止，利腰脐间血，益津液，暖胃消谷嗜食（《别录》）。治心腹胀满，腹中冷痛，胃虚下利， \n多年气痢，除寒热，止呕逆（甄权）。止反胃，利小便，主五劳七伤，补腰膝，长肌肉，治 \n冷气， 癖气块，妇人冷症瘕（大明）。除湿益气，和中补阳，消痰逐水，生津止渴，止泻 \n痢，消足胫湿肿，除胃中热、肌热。得枳实，消痞满气分；佐黄芩，安胎清热（元素）。理 \n胃益脾，补肝风虚，主舌本强，食则呕，胃脘痛，身体重，心下急痛，心下水痞。冲脉为病， \n逆气里急，脐腹痛（好古）。 \n【发明】好古曰∶本草无苍、白术之名。近世多用白术，治皮间风，止汗消痞，补胃和 \n发，有汗则止，与黄 同功。 \n元素曰∶白术除湿益燥，和中补气。其用有九∶温中，一也；去脾胃中湿，二也；除胃 \n中热，三也；强脾胃，进饮食，四也；和胃生津液，五也；止肌热，六也；四肢困倦，嗜卧 \n，目不能开，不思饮食，七也；止渴，八也；安胎，九也。凡中焦不受湿不能下利，必须白 \n术以逐水益脾。非白术不能去湿，非枳实不能消痞，故枳术丸以之为君。 \n机曰∶脾恶湿，湿胜则气不得施化，津何由生？故曰∶膀胱者津液之府，气化则能出焉 \n。用白术以除其湿，则气得周流而津液生矣。 \n【附方】旧七，新二十四。 \n枳术丸∶消痞强胃，久服令人食自不停也。白术一两（黄壁土炒过，去土），枳实（麸 \n炒，去麸）一两。为末，荷叶包饭烧熟，捣和丸梧子大。每服五十丸，白汤下。气滞，加橘 \n皮一两；有火，加黄连一两；有痰，加半夏一两；有寒，加干姜五钱，木香三钱；有食，加 \n神曲、麦 各五钱。（《洁古家珍》） \n枳术汤∶心下坚大如盘，边如旋杯，水饮所作。寒气不足，则手足厥逆，腹满胁鸣相逐 \n。阳气不通即身冷，阴气不通即骨疼。阳前通则恶寒，阴前通则痹不仁。阴阳相得，其气乃 \n行；大气一转，其气乃散。实则失气，虚则遗尿。名曰气分，宜此主之。白术一两，枳实七 \n个。水五升，煮三升，分三服。腹中软，即散。（仲景《金匮玉函》） \n白术膏∶服食滋补，止久泄痢。上好白术十斤，切片，入瓦锅内，水淹过二寸，文武火 \n煎至一半，倾汁入器内，以渣再煎，如此三次，乃取前后汁同熬成膏，入器中一夜，倾去上 \n面清水，收之。每服二、三匙，蜜汤调下。（《千金良方》）参术膏∶治一切脾胃虚损，益元 \n气。白术一斤，人参四两。切片，以流水十五碗浸一夜，桑柴文武火煎取浓汁，熬膏，入炼 \n蜜收之。每以白汤点服。（《集简方》）胸膈烦闷∶白术末，水服方寸匕。（《千金方》）心下 \n有水∶白术三两，泽泻五两。水三升，煎一升半，分三服。（《梅师方》）五饮酒癖∶一、 \n留饮，水停心下；二、癖饮，水在两胁下；三、痰饮，水在胃中；四、溢饮，水在五脏间； \n五、流饮，水在肠间。皆因饮食冒寒，或饮茶过多致此。倍术丸∶用白术一斤，干姜（炮）、 \n桂心各半斤。为末，蜜丸梧子大。每温水服二、三十丸。（《惠民和剂局方》）四肢肿满∶白 \n术三两。 咀。每服半两，水一盏半，大枣三枚，煎九分，温服，日三、四服，不拘时候。 \n（ \n产后中寒，遍身冷直，口噤，不识人∶白术四两，泽泻一两，生姜五钱。水一升，煎服 \n。（《产宝》）头忽眩运，经久不瘥，四体渐羸，饮食无味，好食黄土∶用术三斤，曲三斤。 \n捣筛，酒和 \n湿气作痛∶白术切片，煎汁熬膏，白汤点服。（《集简方》） \n中湿骨痛∶术一两，酒三盏，煎一盏，顿服。不饮酒，以水煎之。（《三因良方》） \n妇人肌热，血虚者。吃力伽散∶用白术、白茯苓、白芍药各一两，甘草半两。为散。姜、 \n枣煎服。（王焘《外台秘要》） \n风瘙瘾疹∶白术为末，酒服方寸匕，日二服。（《千金方》） \n面多 雀卵色∶苦酒渍术，日日拭之。极效。（《肘后方》） \n自汗不止∶白术末，饮服方寸匕，日二服。（《千金方》） \n脾虚盗汗∶白术四两，切片，以一两同黄 炒，一两同牡蛎炒，一两同石斛炒，一两同 \n麦麸炒，拣术为末。每服三钱，食远粟米汤下，日三服。（丹溪方）老小虚汗 白术五钱， \n小麦一撮。水煮干，去麦为末，用黄 汤下一钱。（《全幼心鉴》）产后呕逆，别无他疾者∶ \n白术一两二钱，生姜一两五钱。酒、水各二升，煎一升，分三服。（《妇人良方》）脾虚胀满， \n脾气不和，冷气客于中，壅遏不通，是为胀满。宽中丸∶用白术二两，橘皮四两。为末，酒 \n糊丸梧子大。每食前木香汤送下三十丸，效。（《指迷方》） \n脾虚泄泻∶白术五钱，白芍药一两，冬月用肉豆蔻（煨）。为末，米饭丸梧子大。每米 \n饮下 \n湿泻暑泻∶白术、车前子等分。炒为末，白汤下二、三钱。（《简便方》） \n久泻滑肠∶白术（炒）、茯苓各一两，糯米（炒）二两。为末，枣肉拌食，或丸服之。（《简 \n便方》） \n老小滑泻∶白术半斤（黄土炒过），山药四两（炒）。为末，饭丸。量人大小，米汤服。 \n或加人参三钱。（《濒湖集简方》） \n老人常泻∶白术二两（黄土拌蒸，焙干去土），苍术五钱（泔浸炒），茯苓一两。为末， \n米糊丸梧子大，每米汤下七、八十丸。（《简便方》） \n小儿久泻∶脾虚，米谷不化，不进饮食。温白丸∶用白术（炒）二钱半，半夏曲二钱半， \n丁 \n泻血萎黄∶肠风痔漏，脱肛泻血，面色萎黄，积年不瘥者。白术一斤（黄土炒过，研末），"}, {"n": 12, "text": "卷十二\n\n干地黄半斤。饭上蒸熟，捣和，干则入少酒，丸梧子大。每服十五丸，米饮下，日三服。（ \n《普济方》） \n孕妇束胎∶白术、枳壳（麸炒）等分。为末，烧饭丸梧子大。入月一日，每食前温水下 \n三十丸。胎瘦，则易产也。（《保命集》）牙齿日长，渐至难食，名髓溢病。白术煎汤，漱服 \n取效，即愈也。（张锐《鸡峰备急方》） \n\\x苍术\\x \n【释名】赤术（《别录》）、山精（《抱朴》）、仙术（《纲目》）、山蓟。 \n时珍曰∶《异术》言∶术者山之精也，服之令人长生辟谷，致神仙，故有山精、仙术之 \n号。术有赤、白二种，主治虽近，而性味止发不同。本草不分苍、白，亦未可据。今将《本 \n经》并《别录》、甄权、大明四家所说功用，参考分别，各自附方，庶用户有所依凭。 \n【修治】大明曰∶用术以米泔浸一宿，入药。 \n宗 曰∶苍术辛烈，须米泔浸洗，再换泔浸二日，去上粗皮用。 \n时珍曰∶苍术性燥，故以糯米泔浸去其油，切片，焙干用。亦有用脂麻同炒，以制其 \n燥者。 \n【气味】苦，温，无毒。《别录》曰∶甘。权曰∶甘、辛。 \n时珍曰∶白术，甘而微苦，性温而和；赤术，甘而辛烈，性温而燥，阴中阳也，可升可 \n降，入足太阴、阳明、手太阴、阳明、太阳之经。忌同白术。 \n【主治】风寒湿痹，死肌痉疸。作煎饵久服，轻身延年不饥（《本经》）。主头痛，消痰 \n水，逐皮间风水结肿，除心下急满及霍乱吐下不止，暖胃消谷嗜食（《别录》）。除恶气，弭 \n灾（弘景）。主大风 痹，心腹胀痛，水肿胀满，除寒热，止呕逆下泄冷痢（甄权）。治筋 \n骨软弱， 癖气块，妇人冷气症瘕，山岚瘴气温疾（大明）。明目，暖水脏（刘完素）。除湿 \n发汗，健胃安脾，治痿要药（李杲）。散风益气，总解诸郁（震亨）。治湿痰留饮，或挟瘀血 \n成窠囊，及脾湿下流，浊沥带下，滑泻肠风（时珍）。 \n【发明】宗 曰∶苍术，气味辛烈；白术，微辛苦而不烈。古方及《本经》止言术，未 \n分苍、白。只缘陶隐居言术有两种，自此人多贵白者，往往将苍术置而不用。如古方平胃散 \n之类，苍术为最要药，功效尤速。殊不详本草原无白术之名。嵇康曰∶闻道人遗言，饵术、 \n黄精，令人久寿。亦无白字，用宜两审。 \n杲曰∶本草但言术，不分苍、白。而苍术别有雄壮上行之气，能除湿，下安太阴，使邪 \n气不传入脾也。以其经泔浸、火炒，故能出汗，与白术止汗特异，用者不可以此代彼。盖有 \n止、发之殊，其余主治则同。 \n元素曰∶苍术与白术主治同，但比白术气重而体沉。若除上湿发汗，功最大；若补中焦 \n，除脾胃湿，力少不如白术。腹中窄狭者，须用之。 \n震亨曰∶苍术治湿，上、中、下皆有可用。又能总解诸郁。痰、火、湿、食、气、血六 \n郁，皆因传化失常，不得升降。病在中焦，故药必兼升降。将欲升之，必先降之；将欲降之 \n，必先升之。故苍术为足阳明经药，气味辛烈，强胃强脾，发谷之气，能径入诸经，疏泄阳 \n明之湿，通行敛涩。香附乃阴中快气之药，下气最速。一升一降，故郁散而平。杨士瀛曰∶ \n脾精不禁，小便漏浊淋不止，腰背酸疼，宜用苍术以敛脾精，精生于谷故也。弘景曰∶白术 \n少膏，可作丸散；赤术多膏，可作煎用。昔刘涓子 取其精而丸之，名守中金丸，可以长生 \n。颂曰∶服食多单饵术，或合白茯苓，或合石菖蒲，并捣末。旦日水服，晚再进，久久弥 \n佳。 取生术，去土水浸，再三煎如饴糖，酒调饮之，更善。今茅山所造术煎，是此法也。 \n陶隐居言取其精丸之，今乃是膏煎，恐非真也。慎微曰∶梁庾肩吾答陶隐居 术煎启云∶绿 \n叶抽条，紫花标色。百邪外御，六腑内充。山精见书，华神在录。木荣火谢，尽采撷之难； \n启旦移申，穷淋漉之剂。又谢术蒸启云∶味重金浆，芳逾玉液。足使坐致延生，伏深铭感。 \n又葛洪《抱朴子·内篇》云∶南阳文氏，汉末逃难壶山中，饥困欲死。有人教之食术，遂不 \n饥。数十年乃还乡里，颜色更少，气力转胜。故术一名山精，《神农药经》所谓必欲长生， \n常服山精，是也。 \n时珍曰∶按∶《吐纳经》云∶紫微夫人术序云∶吾察草木之胜速益于己者，并不及术之 \n多验也。可以长生久视，远而更灵。山林隐逸，得服术者，五岳比肩。又《神仙传》云∶陈 \n子皇得饵术要方，其妻姜氏得疲病，服之自愈，颜色气力如二十时也。时珍谨按∶以上诸说 \n，皆似苍术，不独白术。今服食家亦呼苍术为仙术，故皆列于苍术之后。又张仲景辟一切恶 \n气，用赤术同猪蹄甲烧烟。陶隐居亦言术能除恶气，弭灾 。故今病疫及岁旦，人家往往烧 \n苍术以辟邪气。《类编》载越民高氏妻，病恍惚谵语，亡夫之鬼凭之。其家烧苍术烟，鬼遽 \n求去。《夷坚志》载江西一士人，为女妖所染。其鬼将别曰∶君为阴气所浸，必当暴泄，但 \n多服平胃散为良。中有苍术能去邪也。许叔微《本事方》云∶微患饮癖三十年。始因少年夜 \n坐写文，左向伏几，是以饮食多坠左边。中夜必饮酒数杯，又向左卧。壮时不觉，三、五年 \n后，觉酒止从左下有声，胁痛食减嘈杂，饮酒半杯即止。十数日，必呕酸水数升。暑月止右 \n边有汗，左边绝无。遍访名医及海上方，间或中病，止得月余复作。其补，如天雄、附子、 \n矾石辈；利，如牵牛、甘遂、大戟，备尝之矣。自揣必有癖囊，如潦水之有科臼，不盈科不 \n行。但清者可行，而浊者停滞，无路以决之，故积至五、七日必呕而去。脾土恶湿，而水则 \n流湿，莫若燥脾以去湿，崇土以填科臼。乃悉屏诸药，只以苍术一斤（去皮，切片，为末）， \n生油麻（半两）（水二盏，研，滤汁），大枣（五十枚）（煮，去皮核）。捣和丸梧子大。每日 \n空腹温服五十丸，增至一、二百丸。忌桃、李、雀肉。服三月而疾除。自此常服，不呕不痛， \n胸膈宽利，饮啖如故，暑月汗亦周身，灯下能书细字，皆术之力也。初服时必觉微燥，以山 \n栀子末，沸汤点服解之，久服亦自不燥矣。 \n【附方】旧二，新三十二。 \n服术法∶乌髭发，驻颜色，壮筋骨，明耳目，除风气，润肌肤，久服令人轻健。苍术不 \n计多少，米泔水浸三日，逐日换水，取出刮去黑皮，切片曝干，慢火炒黄，细捣为末。每一 \n斤，用蒸过白茯苓末半斤，炼蜜和丸梧子大，空心卧时热水下十五丸。别用术末六两，甘草 \n末一两，拌和作汤点之，吞丸尤妙。忌桃、李、雀、蛤，及三白、诸血。（《经验方》） \n苍术膏∶邓才笔峰《杂兴方》∶除风湿，健脾胃，变白驻颜，补虚损，大有功效。苍术 \n新者，刮去皮，薄切，米泔水浸二日，一日一换，取出，以井华水浸过二寸，春、秋五日， \n夏三日，冬七日，漉出，以生绢袋盛之，放在一半原水中，揉洗津液出，纽干。将渣又捣烂 \n，袋盛于一半原水中，揉至汁尽为度。将汁入大砂锅中，慢火熬成膏。每一斤，入白蜜四两 \n，熬二炷香。每膏一斤，入水澄白茯苓末半斤，搅匀瓶收。每服三匙，清早、临卧各一服， \n以温酒送下。忌醋及酸物、桃、李、雀、蛤、菘菜、首鱼等物。吴球《活人心统》苍术膏∶ \n治脾经湿气，少食，足肿无力，伤食，酒色过度，劳逸有伤，骨热。用鲜白苍术二十斤，浸 \n，刮去粗皮，晒切，以米泔浸一宿，取出，同溪水一石，大砂锅慢火煎半干，去渣。再入石 \n楠叶三斤（刷去红衣），楮实子一斤，川当归半斤，甘草四两，切，同煎黄色，滤去滓，再 \n煎 \n苍术丸∶萨谦斋《瑞 \n竹堂方》云∶清上实下，兼治内外障，服。茅山苍术（洗刮净）一斤，分作四分，用酒、醋、 \n糯泔、童尿各浸三日，一日一换；取出，洗捣晒焙，以黑脂麻同炒香，共为末，酒煮面糊丸 \n梧子大。每空心白汤下五十丸。李仲南《永类方》八制苍术丸∶疏风顺气养肾，治腰脚湿气 \n痹痛。苍术一斤（洗刮净），分作四分，用酒、醋、米泔、盐水各浸三日，晒干。又分作四 \n分，用川椒红、茴香、补骨脂、黑牵牛各一两，同炒香，拣去不用，只取术研末，醋糊丸梧 \n子大。每服五十丸，空心盐酒送下。五十岁后，加沉香末一两。 \n苍术散∶治风湿，常服 \n壮筋骨，明目。苍术一斤，粟米泔浸过，竹刀刮去皮。半斤以无灰酒浸，半斤以童子小便浸， \n春五、夏三、秋七、冬十日，取出。净地上掘一坑，炭火 赤，去炭，将浸药酒，小便倾入 \n坑内，却放术在中，以瓦器盖定，泥封一宿，取出为末。每服一钱，空心温酒或盐汤下。万 \n表《积善堂方》∶六制苍术散∶治下元虚损，偏坠茎痛。茅山苍术（净刮）六斤，分作六分∶ \n一斤，仓米泔浸二日，炒；一斤，酒浸二日，炒；一斤，青盐半斤炒黄，去盐；一斤，小茴 \n香四两炒黄，去茴；一斤，大茴香四两炒黄，去茴；一斤，用桑椹子汁浸二日，炒。取术为 \n末。每服三钱，空心温酒下。 \n固真丹∶《瑞竹堂方》固真丹∶燥湿养脾，助胃固真。茅山苍术（刮净）一斤，分作四 \n分 \n一两炒。并拣术研末，酒煮面，糊丸梧子大。每空心米饮下五十丸。《乾坤生意》平补固真 \n丹∶治元脏久虚，遗精白浊，妇人赤白带下崩漏。金州苍术（刮净）一斤，分作四分∶一分， \n川椒一两炒；一分，破故纸一两炒；一分，茴香、食盐各一两炒；一分，川楝肉一两炒。取 \n净术为末，入白茯苓末二两，酒洗当归末二两，酒煮，面糊丸梧子大。每空心盐酒下五十丸。 \n固元丹∶治元脏久虚，遗精白浊五淋，及小肠膀胱疝气，妇人赤白带下，血崩便血等疾， \n以小便频数为效。好苍术（刮净）一斤，分作四分∶一分，小茴香、食盐各一两，同炒；一 \n分，川椒、补骨脂各一两，同炒；一分，川乌头、川楝子肉各一两，同炒；一分，用醇醋、 \n老酒各半斤，同煮干焙，连同炒药通为末，用酒煮糊丸梧子大。每服五十丸，男以温酒，女 \n以醋汤，空心下。此高司法方也。（王 《百一选方》） \n少阳丹∶苍术（米泔浸半日，刮皮，晒干为末）一斤，地骨皮（温水洗净，去心晒研） \n一斤，熟桑椹二十斤（入瓷盆揉烂，绢袋压汁）。和末如糊，倾入盘内，日晒夜露，采日精 \n月华，待干，研末，炼蜜和丸赤小豆大。每服二十丸，无灰酒下，日三服。一年辫发返黑， \n三年面如童子。（刘松石《保寿堂方》） \n交感丹∶补虚损，固精气，乌髭发。此铁瓮城申先生方也，久服令人有子。茅山苍术（刮 \n净）一斤（分作四分，用酒、醋、米泔、盐汤各浸七日，晒研），川椒红、小茴香各四两（炒 \n研 \n交加丸∶升水降火，除百病。苍术（刮净）一斤（分作四分∶一分，米泔浸炒；一分， \n盐水浸炒；一分，川椒炒；一分，破故纸炒），黄柏皮（刮净）一斤（分作四分∶一分，酒 \n炒；一分，童尿浸炒；一分，小茴香炒；一分，生用）。拣去各药，只取术、柏为末，炼蜜 \n丸梧子大。每服六十丸，空心盐汤下。（邓才笔峰《杂兴方》） \n坎离丸∶滋阴降火，开胃进食，强筋骨，去湿热。白苍术（刮净）一斤（分作四分∶一 \n分，川椒一两炒；一分，破故纸一两炒；一分，五味子一两炒；一分，川芎 一两炒，只取 \n术研末），川柏皮四斤（分作四分∶一斤，酥炙；一斤，人乳汁炙；一斤，童尿炙；一斤， \n米泔炙，各十二次，研末）。和匀，炼蜜丸梧子大。每服三十丸，早用酒，午用茶，晚用白 \n汤下。（《积善堂方》）不老丹∶补脾益肾，服之，七十亦无白发。茅山苍术（刮净，米泔浸 \n软，切片）四斤（一斤，酒浸焙；一斤，醋浸焙；一斤，盐四两炒；一斤，椒四两炒），赤、 \n白何首乌各二斤（泔浸，竹刀刮切，以黑豆、红枣各五升，同蒸至豆烂，曝干），地骨皮（去 \n骨）一斤。各取净末，以桑椹汁和成剂，铺盆内，汁高三指，日晒夜露，取日月精华，待干， \n以石臼捣末，炼蜜和丸梧子大。每空心酒服一百丸。此皇甫敬之方也。（王海藏《医垒元戎》） \n灵芝丸∶治脾肾气虚，添补精髓，通利耳目。苍术一斤。米泔水浸，春、夏五日，秋、冬七 \n日，逐日换水，竹刀刮皮切晒，石臼为末，枣肉蒸，和丸梧子大。每服三、五十丸，枣汤空 \n心服。（《奇效良方》）补脾滋肾、生精强骨，真仙方也。苍术（去皮）五斤（为末，米泔水 \n漂，澄取底用），脂麻二升半（去壳研烂，绢袋滤去渣）。澄浆拌术，曝干。每服三钱，米汤 \n或酒空心调服。（《孙氏 \n面黄食少∶男妇面无血色，食少嗜卧。苍术一斤，熟地黄半斤，干姜（炮）冬一两（春、 \n秋 \n小儿癖疾∶苍术四两，为末。羊肝一具，竹刀批开，撒术末，线缚，入砂锅煮熟，捣作 \n丸服。（《生生编》） \n好食生米∶男子、妇人因食生熟物留滞肠胃，遂至生虫，久则好食生米，否则终日不乐， \n至憔悴萎黄，不思饮食，以害其生。用苍术米泔水浸一夜，锉焙为末，蒸饼丸梧子大。每服 \n五十丸，食前米饮下，日三服。益昌伶人刘清啸，一娼名曰花翠，年逾笄病此。惠民局监赵 \n尹，以此治之，两旬而愈。盖生米留滞，肠胃受湿，则谷不磨而成此疾，苍术能去湿暖胃消 \n谷也。（杨氏《家藏经验方》）腹中虚冷，不能饮食，食辄不消，羸弱生病。术二斤，曲一斤。 \n炒为末，蜜丸梧子大。每服三十丸，米汤下，日三服。大冷，加干姜三两；腹痛，加当归三 \n两；羸弱，加甘草二两。（《肘后方》）脾湿水泻注下，困弱无力，水谷不化，腹痛甚者。苍 \n术二两，白芍药一两，黄芩半两，淡桂二钱。每服一两，水一盏半，煎一盏，温服。脉弦头 \n微痛，去芍药，加防风二两。（《保命集》）暑月暴泻∶壮脾温胃，及疗饮食所伤。曲术丸∶ \n用神曲（炒）、苍术（米泔浸一夜，焙）等分为末，糊丸梧子大。每服三、五十丸，米饮下。 \n（《和剂局方》） \n飧泻久痢∶椒术丸∶用苍术二两，川椒一两。为末，醋糊丸梧子大。每服二十丸，食前 \n温水下。恶痢久者，加桂。（《保命集》）脾湿下血∶苍术二两，地榆一两。分作二服，水二 \n盏，煎一盏，食前温服。久痢虚滑，以此下桃花丸。（《保命集》）。 \n肠风下血∶苍术不拘多少，以皂角 浓汁浸一宿，煮干，焙研为末，面糊丸如梧子大。 \n每服五十丸，空心米饮下，日三服。（《妇人良方》） \n湿气身痛∶苍术泔浸切，水煎，取浓汁熬膏，白汤点服。（《简便方》）补虚明目、健骨 \n和血。苍术（泔浸）四两，熟地黄（焙）二两。为末，酒糊丸梧子大。每温酒下三、五十丸， \n日三服。（《普济方》） \n青盲雀目∶《圣惠方》∶用苍术四两，泔浸一夜，切焙研末。每服三钱，猪肝三两，劈开 \n掺药在内，扎定，入粟米一合，水一碗，砂锅煮熟，熏眼，临卧食肝饮汁，不拘大人、小儿 \n皆治。又方∶不计时月久近。用苍术二两，泔浸，焙捣为末。每服一钱，以好羊子肝一斤， \n竹刀切破，掺药在内，麻扎，以粟米泔煮熟，待冷食之，以愈为度。 \n眼目昏涩∶苍术半斤（泔浸七日，去皮切焙），木贼各二两。为末。每服一钱，茶、酒 \n任下。（《圣惠方》）婴儿目涩不开，或出血。苍术二钱，入猪胆中扎煮。将药气熏眼后，更 \n嚼取汁与服。妙。（《幼幼新书》） \n风牙肿痛∶苍术盐水浸过，烧存性，研末揩牙。去风热。（《普济方》）脐虫怪病∶腹中 \n如铁石，脐中水出，旋变作虫行，绕身匝痒难忍，拨扫不尽。用苍术浓煎汤浴之。仍以苍术 \n末 \n\\x苗\\x \n【主治】作饮甚香，去水（弘景）。亦止自汗。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>狗脊\n\n内容：（《本经》中品） \n【释名】强膂（《别录》）、扶筋（《别录》）、百枝（《本经》）、狗青（《吴普》）。 \n恭曰∶此药苗似贯众，根长多歧，状如狗之脊骨，而肉作青绿色，故以名之。 \n时珍曰∶强膂、扶筋，以功名也。《别录》又名扶盖，乃扶筋之误。《本经》狗脊一名 \n百枝，《别录》萆 一名赤节，而《吴普本草》谓百枝为萆 ，赤节为狗脊，皆似误也。 \n【集解】《别录》曰∶狗脊，生常山川谷。二月、八月采根，曝干。普曰∶狗脊如萆 ， \n茎节如竹有刺，叶圆赤，根黄白，亦如竹根，毛有刺。《岐伯经》云∶茎无节，叶端圆青赤， \n皮白有赤脉。弘景曰∶今山野处处有之，与菝 相似而小异。其茎叶小肥，其节疏，其茎大 \n直，上有刺，叶圆有赤脉，根凸凹 KT 如羊角强细者是。颂曰∶今太行山、淄、温、眉 \n州 \n亦有之。苗尖细碎青色，高一尺以来，无花。其茎叶似贯众而细。其根黑色，长三、四寸， \n多歧，似狗之脊骨，大有两指许。其肉青绿色。春秋采根，曝干。今方亦有用金毛者。陶氏 \n所说乃有刺萆 ，非狗脊也，今江左俗犹用之。 曰∶凡使狗脊，勿用透山藤根，形状一般， \n只是入顶苦，不可饵也。 \n时珍曰∶狗脊有二种∶一种根黑色，如狗脊骨，一种有金黄毛，如狗形，皆可入药。其 \n茎细而叶、花两两对生，正似大叶蕨，比贯众叶有齿，面背皆光。其根大如拇指，有硬黑须 \n簇之。吴普、陶弘景所说根苗，皆是菝 ；苏恭、苏颂所说，即真狗脊也。按张揖《广雅》 \n云∶菝 ，狗脊也。张华《博物志》云∶菝 ，与萆 相乱，一名狗脊。观此则昔人以菝 \n为狗脊，相承之误久矣。然菝 、萆 、狗脊三者，形状虽殊，而功用亦不甚相远。 \n\\x根\\x \n【修治】 曰∶凡修事，火燎去须，细锉了，酒浸一夜，蒸之，从巳至申，取出晒干用。 \n时珍曰∶今人惟锉炒，去毛须用。 \n【气味】苦，平，无毒。《别录》曰∶甘，微温。普曰∶神农∶苦；桐君、黄帝、岐伯、 \n雷公、扁鹊∶甘，无毒；李当之∶小温。权曰∶苦、辛、微热。之才曰∶萆 为之使，恶败 \n酱、莎草。 \n【主治】腰背强，关机缓急，周痹寒湿膝痛，颇利老人（《本经》）。疗失溺不节，男子 \n脚弱腰痛，风邪淋露，少气目暗，坚脊利俯仰，女子伤中关节重（《别录》）。男子女人毒风 \n软脚，肾气虚弱，续筋骨，补益男子（甄权）。强肝肾，健骨，治风虚（时珍）。 \n【附方】新四。 \n男子诸风∶四宝丹∶用金毛狗脊（盐泥固济， 红去毛）、苏木、萆 、川乌头（生用） \n等分。为末，米醋和丸梧子大。每服二十丸，温酒、盐汤下。（《普济方》）室女白带，冲任 \n虚寒。鹿茸丸∶用金毛狗脊（燎去毛）、白蔹各一两，鹿茸（酒蒸，焙）二两。为末，用艾 \n煎醋汁打糯米糊丸梧子大。每服五十丸，空心温酒下。（《济生方》） \n固精强骨∶金毛狗脊、远志肉、白茯神、当归身等分。为末，炼蜜丸梧子大。每酒服五 \n十丸。（《集简方》）病后足肿，但节食以养胃气。外用狗脊，煎汤渍洗。（吴绶《蕴要》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>贯众\n\n内容：（《本经》下品） \n【释名】贯节（《本经》）、贯渠（《本经》）、百头（《本经》、又名虎卷、扁苻）、草鸱 \n头（《别录》）、黑狗脊（《纲目》）、凤尾草（《图经》）。 \n时珍曰∶此草叶茎如凤尾，其根一本而众枝贯之，故草名凤尾，根名贯众、贯节、贯渠 \n。渠者，魁也。《吴普本草》作贯中，俗名贯仲、管仲者，皆谬称也。《尔雅》云∶泺（ \n音灼），贯众，即此也。《别录》一名伯萍，一名药藻，皆字讹也。金星草一名凤尾草，与此 \n同名，宜互考之。 \n弘景曰∶近道皆有之。叶如大蕨。其根形色毛芒，全似老鸱头，故呼为草鸱头。 \n【集解】《别录》曰∶贯众生玄山山谷及冤句少室山。二月、八月采根，阴干。 \n普曰∶叶青黄色，两两相对，茎有黑毛，丛生，冬夏不死。四月花白，七月实黑，聚相 \n连卷旁生。三月、八月采根，五月采叶。 \n保升曰∶苗似狗脊，状如雉尾，根直多枝，皮黑肉赤，曲者名草鸱头，所在山谷阴处则 \n有之。 \n颂曰∶今陕西、河东州郡及荆、襄间多有之，而少有花者。春生苗，赤。叶大如蕨。茎 \n干三棱。叶绿色似鸡翎，又名凤尾草。其根紫黑色，形如犬爪，下有黑须毛，又似老鸱。郭 \n璞注《尔雅》云∶叶圆锐，茎毛黑，布地，冬不死，《广雅》谓之贯节是矣。 \n时珍曰∶多生山阴近水处。数根丛生，一根数茎，茎大如箸，其涎滑。其叶两两对生， \n如狗脊之叶而无锯齿，青黄色，面深背浅。其根曲而有尖嘴，黑须丛簇，亦似狗脊根而大， \n状如伏鸱。 \n\\x根\\x \n【气味】苦，微寒，有毒。 \n之才曰∶ 菌、赤小豆为之使，伏石钟乳。 \n【主治】腹中邪热气，诸毒，杀三虫（《本经》）。去寸白，破症瘕，除头风，止金疮（《别 \n录》）。为末，水服一钱，止鼻血有效（苏颂）。治下血崩中带下，产后血气胀痛，斑疹毒， \n漆毒，骨哽。解猪病（时珍）。 \n【发明】时珍曰∶贯众大治妇人血气，根汁能制三黄，化五金，伏钟乳，结砂制汞，且 \n能解毒软坚。王海藏治夏月痘出不快，快斑散用之。云贯众有毒，而能解腹中邪热之毒。病 \n因内感而发之于外者多效，非古法之分经也。又黄山谷《煮豆帖》，言荒年以黑豆一升 净 \n，入贯众一斤，锉如骰子大，同以水煮，文火斟酌至豆熟，取出日干，覆令展尽余汁，簸去 \n贯众。每日空心 豆五、七粒，能食百草木枝叶有味可饱。又王 《百一选方》，言滁州蒋 \n教授，因食鲤鱼玉蝉羹，为肋肉所哽，凡药皆不效。或令以贯众浓煎汁一盏半，分三服，连 \n进至夜，一咯而出。亦可为末，水服一钱。观此可知其软坚之功，不但治血、治疮而已也。 \n【附方】新一十五。 \n鼻衄不止∶贯众根末，水服一钱。（《普济方》） \n诸般下血∶肠风酒痢，血痔鼠痔下血。黑狗脊，黄者不用，须内肉赤色者，即本草贯众 \n也。去皮毛，锉焙为末。每服二钱，空心米饮下。或醋糊丸梧子大，每米饮下三、四十丸。 \n或烧存性，出火毒为末，入麝香少许，米饮服二钱。（《普济方》） \n女人血崩∶贯众半两，煎酒服之，立止。（《集简方》） \n产后亡血∶过多，心腹彻痛者。用贯众状如刺 者一个，全用不锉，只揉去毛及花萼， \n以 \n赤白带下∶年深，诸药不能疗者，用上方治之亦验，名独圣汤。方同上。年深咳嗽出脓 \n血。贯众、苏方木等分，每服三钱，水一盏，生姜三片，煎服，日二服。久咳，渐成劳瘵。 \n凤尾草为末，用鱼 蘸食之。（《圣惠方》）痘疮不快∶快斑散∶用贯众、赤芍药各一钱，升 \n麻、甘草各五分。入淡竹叶三片，水一盏半，煎七分，温服。（王海藏方） \n头疮白秃∶贯众、白芷为末，油调涂之。又方∶贯众烧末，油调涂。（《圣惠方》） \n漆疮作痒∶油调贯众末，涂之。（《千金方》） \n鸡鱼骨哽∶贯众、缩砂、甘草等分。为粗末，绵包少许，含之咽汁，久则随痰自出。（《普 \n济方》）解轻粉毒∶齿缝出血，臭肿。贯众、黄连各半两。煎水，入冰片少许，时时漱之。（ \n陆氏《积德堂方》） \n血痢不止∶凤尾草根（即贯众）五钱，煎酒服。陈解元吉言所传。（《集简方》） \n便毒肿痛∶贯众，酒服二钱，良。（《多能鄙事》） \n\\x花\\x \n【主治】恶疮，令人泄（《别录》）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>巴戟天\n\n内容：（《本经》上品） \n【释名】不凋草（《日华》）、三蔓草。 \n时珍曰∶名义殊不可晓。 \n【集解】《别录》曰∶巴戟天生巴郡及下邳山谷。二月、八月采根，阴干。 \n弘景曰∶今亦用建平、宜都者，根状如牡丹而细，外赤内黑，用之打去心。 \n恭曰∶其苗俗名三蔓草。叶似茗，经冬不枯。根如连珠，宿根青色，嫩根白紫，用之亦 \n同，以连珠多肉浓者为胜。 \n大明曰∶紫色如小念珠，有小孔子，坚硬难捣。 \n宗 曰∶巴戟天本有心，干缩时偶自落，或抽去，故中心或空，非自有小孔也。今人欲 \n要中间紫色，则多伪以大豆汁沃之，不可不察。 \n颂曰∶今江淮、河东州郡亦有，但不及蜀川者佳。多生竹林内。内地生者，叶似麦门 \n冬而浓大，至秋结实。今方家多以紫色为良。蜀人云∶都无紫色者。采时或用黑豆同煮，欲 \n其色紫，殊失气味，尤宜辨之。又有一种山 根，正似巴戟，但色白。土人采得，以醋水煮 \n之，乃以杂巴戟，莫能辨也。但击破视之，中紫而鲜洁者，伪也；其中虽紫，又有微白，糁 \n有粉色，而理小暗者，真也。真巴戟嫩时亦白，干时亦煮治使紫，力劣弱耳。 \n\\x根\\x \n【修治】 曰∶凡使须用枸杞子汤浸一宿，待稍软漉出，再酒浸一伏时，漉出，同 \n菊花熬焦黄，去菊花，以布拭干用。 \n时珍曰∶今法∶惟以酒浸一宿，锉焙入药。若急用，只以温水浸软去心也。 \n【气味】辛、甘，微温，无毒。大明曰∶苦。 \n之才曰∶覆盆子为之使，恶雷丸、丹参、朝生。 \n【主治】大风邪气，阴痿不起，强筋骨，安五脏，补中增志益气（《本经》）。疗头面游 \n风，小腹及阴中相引痛，补五劳，益精，利男子（《别录》）。治男子夜梦鬼交精泄，强阴下 \n气，治风癞（甄权）。治一切风，疗水胀（《日华》）。治香港脚，去风疾，补血海（时珍，出《 \n仙经》）。 \n【发明】好古曰∶巴戟天，肾经血分药也。 \n权曰∶病患虚损，加而用之。 \n宗 曰∶有人嗜酒，日须五、七杯，后患香港脚甚危。或教以巴戟半两（糯米同炒，米微 \n转色，去米不用），大黄一两（锉，炒）。同为末，熟蜜丸。温水服五、七十丸。仍禁酒，遂 \n愈。 \n【附录】巴棘 《别录》曰∶味苦，有毒。主恶疥疮出虫。生高地，叶白有刺，根连数 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>远志\n\n内容：（《本经》上品） \n【释名】苗名小草（《本经》）、细草（《本经》）、棘菀（《本经》）、 绕（《本经》）。 \n时珍曰∶此草服之能益智强志，故有远志之称。《世说》载郝隆讥谢安云∶处则为远志， \n出则为小草。《记事珠》谓之醒心杖。 \n【集解】《别录》曰∶远志，生太山及冤句川谷。四月采根、叶，阴干。 \n弘景曰∶冤句，属兖州济阴郡。今此药犹从彭城北兰陵来。用之去心取皮，一斤止得三 \n两尔。亦入仙方用。小草，状似麻黄而青。 \n志曰∶茎叶似大青而小。比之麻黄，陶不识也。 \n禹锡曰∶按∶《尔雅》云∶ 绕，棘菀。郭璞注云∶今远志也。似麻黄，赤华，叶锐而 \n黄。其上谓之小草。 \n颂曰∶今河、陕、洛西州郡亦有之。根形如蒿根，黄色。苗似麻黄而青，又如毕豆。叶 \n亦有似大青而小者。三月开白花。根长及一尺。泗州出者，花红，根叶俱大于他处。商州出 \n者，根乃黑色。俗传夷门出者最佳。四月采根，晒干。古方通用远志、小草。今医但用远志 \n，稀用小草。 \n时珍曰∶远志有大叶、小叶二种，陶弘景所说者，小叶也；马志所说者，大叶也。大叶 \n者，花红。 \n\\x根\\x \n【修治】 曰∶凡使，须去心，否则令人烦闷。仍用甘草汤浸一宿，曝干或焙干用。 \n【气味】苦，温，无毒。之才曰∶远志、小草，得茯苓、冬葵子、龙骨良。畏珍珠、藜 \n芦、蜚蠊、齐蛤。弘景曰∶药无齐蛤，恐是百合也。权曰∶是蛴螬也。恭曰∶《药录》下卷 \n有齐蛤，陶说∶非也。 \n【主治】咳逆伤中，补不足，除邪气，利九窍，益智慧，耳目聪明，不忘，强志倍力。 \n久服轻身不老（《本经》）。利丈夫，定心气，止惊悸，益精，去心下膈气，皮肤中热，面目 \n黄（《别录》）。杀天雄、附子、乌头毒，煎汁饮之（之才）。治健忘，安魂魄，令人不迷，坚 \n壮阳道（甄权）。长肌肉，助筋骨，妇人血噤失音，小儿客忤（《日华》）。肾积奔豚（好古）。 \n治一切痈疽（时珍）。 \n\\x叶\\x \n【主治】益精补阴气，止虚损梦泄（《别录》）。 \n【发明】好古曰∶远志，肾经气分药也。 \n时珍曰∶远志，入足少阴肾经，非心经药也。其功专于强志益精，治善忘。盖精与志， \n皆肾经之所藏也。肾经不足，则志气衰，不能上通于心，故迷惑善忘。《灵枢经》云∶肾藏 \n精，精合志。肾盛怒而不止则伤志，志伤则喜忘其前言，腰脊不可以俯仰屈伸，毛悴色夭。 \n又云∶人之善忘者，上气不足，下气有余，肠胃实而心肺虚，虚则营卫留于下，久之不 \n以时上，故善忘也。陈言《三因方》远志酒，治痈疽，云有奇功，盖亦补肾之力尔。葛洪《抱 \n朴 \n【附方】旧三，新四。 \n心孔昏塞∶多忘善误。丁酉日密自至市买远志，着巾角中，还为末服之，勿令人知。（《 \n肘后方》） \n胸痹心痛∶逆气，膈中饮不下。小草丸∶用小草、桂心、干姜、细辛、蜀椒（出汗）各 \n三分，附子二分（炮）。六物下筛，蜜和丸梧子大。先食米汁下三丸，日三服，不知稍增， \n以知为度。忌猪肉、冷水、生葱、生菜。（《范汪东阳方》）喉痹作痛∶远志肉为末，吹之。 \n涎出为度。（《直指方》）脑风头痛∶不可忍。远志末 鼻。（《宣明方》）吹乳肿痛∶远志焙研， \n酒服二钱，以滓敷之。（《袖珍方》） \n一切痈疽∶远志酒∶治一切痈疽、发背、疖毒，恶候侵大。有死血，阴毒在中则不痛， \n敷之即痛。有忧怒等气积而怒攻则痛不可忍，敷之即不痛。或蕴热在内，热逼人手不可近， \n敷之即清凉。或气虚血冷，溃而不敛，敷之即敛。此本韩大夫宅用以救人方，极验。若七情 \n内郁，不问虚实寒热，治之皆愈。用远志不以多少，米泔浸洗，捶去心，为末。每服三钱， \n温酒一盏调，澄少顷饮其清，以滓敷患处。（《三因方》）小便赤浊 远志（甘草水煮）半斤， \n茯神、益智仁各二两。为末，酒糊丸梧子大。每空心枣 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>百脉根\n\n内容：（《唐本》） \n【集解】恭曰∶出肃州、巴西。叶似苜蓿，花黄，根如远志。二月、三月采根，晒干。 \n时珍曰∶按∶《唐书》作柏脉根，肃州岁贡之。《千金》、《外台》大方中亦时用之。今不 \n复闻此，或者名称又不同也。 \n\\x根\\x \n【气味】甘，苦，微寒，无毒。 \n【主治】下气止渴去热，除虚劳，补不足。酒浸或水煮，丸散兼用。（《唐本》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>淫羊藿\n\n内容：（《本经》中品） \n【释名】仙灵脾（《唐本》）、放杖草（《日华》）、弃杖草（《日华》）、千两金（《日华 \n》）、干鸡筋（《日华》）、黄连祖（《日华》）、三枝九叶草（《图经》）、刚前（《本经》）。 \n弘景曰∶服之使人好为阴阳。西川北部有淫羊，一日百遍合，盖食此藿所致，故名淫羊 \n时珍曰∶豆叶曰藿，此叶似之，故亦名藿。仙灵脾、千两金、放杖、刚前，皆言其功力 \n也。鸡筋、黄连祖，皆因其根形也。柳子浓文作仙灵毗，入脐曰毗，此物补下，于理尤通。 \n【集解】《别录》曰∶淫羊藿生上郡阳山山谷。 \n恭曰∶所在皆有。叶形似小豆而圆薄，茎细亦坚，俗名仙灵脾是也。 \n颂曰∶江东、陕西、泰山、汉中、湖湘间皆有之。茎如粟秆。叶青似杏，叶上有刺。根 \n紫色有须。四月开白花，亦有紫花者，碎小，独头子。五月采叶，晒干。湖湘出者，叶如小 \n豆，枝茎紧细，经冬不凋，根似黄连。关中呼为三枝九叶草，苗高一、二尺许，根叶俱堪用 \n。《蜀本草》言生处不闻水声者，良。 \n时珍曰∶生大山中。一根数茎，茎粗如线，高一、二尺。一茎三桠，一桠三叶。叶长二 \n、三寸，如杏叶及豆藿，面光背淡，甚薄而细齿，有微刺。 \n\\x根叶\\x \n【修治】 曰∶凡使时呼仙灵脾，以夹刀夹去叶四畔花枝，每一斤用羊脂四两拌 \n炒，待脂尽为度。 \n【气味】辛，寒，无毒。普曰∶神农、雷公∶辛；李当之∶小寒。权曰∶甘，平。可单 \n用。保升曰∶性温。 \n时珍曰∶甘、香、微辛，温。 \n之才曰∶薯蓣、紫芝为之使，得酒良。 \n【主治】阴痿绝伤，茎中痛，利小便，益气力，强志（《本经》）。坚筋骨，消瘰 赤痈， \n下部有疮，洗出虫。丈夫久服，令人无子（《别录》。机曰∶无子字误，当作有子。）丈夫绝 \n阳无子，女人绝阴无子，老人昏耄，中年健忘，一切冷风劳气，筋骨挛急，四肢不仁，补腰 \n膝，强心力（大明）。 \n【发明】时珍曰∶淫羊藿，味甘气香，性温不寒，能益精气，乃手足阳明、三焦、命门 \n药也。真阳不足者，宜之。 \n【附方】旧三，新五。 \n仙灵脾酒∶益丈夫兴阳，理腰膝冷。用淫羊藿一斤，酒一斗，浸三日，逐时饮之。（《食 \n医心镜》）偏风不遂、皮肤不仁，宜服。仙灵脾酒∶仙灵脾一斤，细锉，生绢袋盛，于不津 \n器中，用无灰酒二斗浸之，重封，春、夏三日、秋、冬五日后，每日暖饮，常令醺然，不得 \n大醉，酒尽再合，无不效验。合时，切忌鸡、犬、见。（《圣惠方》）三焦咳嗽，腹满不饮食， \n气不顺。仙灵脾、覆盆子、五味子（炒）各一两，为末，炼蜜丸梧子大。每姜茶下二十丸。 \n（《圣济录》） \n目昏生翳∶仙灵脾，生王瓜（即小栝蒌红色者）等分，为末。每服一钱，茶下，日二服。 \n（《圣济总录》）病后青盲，日近者可治。仙灵脾一两，淡豆豉一百粒。水一碗半，煎一碗， \n顿服即瘳。（ \n小儿雀目∶仙灵脾根、晚蚕蛾各半两，炙甘草、射干各二钱半，为末。用羊子肝一枚， \n切 \n痘疹入目∶仙灵脾、威灵仙等分，为末。每服五分，米汤下。（《痘疹便览》）牙齿虚痛∶ \n仙 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>仙茅\n\n内容：（《开宝》） \n【释名】独茅（《开宝》）、茅爪子（《开宝》）、婆罗门参。 \n曰∶其叶似茅，久服轻身，故名仙茅。梵音呼为阿输干陀。 \n颂曰∶其根独生。始因西域婆罗门僧献方于唐玄宗，故今江南呼为婆罗门参，言其功补 \n如人参也。 \n【集解】 曰∶仙茅生西域。叶似茅。其根粗细有筋，或如笔管，有节纹理。其花黄色 \n多涎。自武城来，蜀中诸州亦皆有之。 \n颂曰∶今大庾岭、蜀川、江湖、两浙诸州亦有之。叶青如茅而软，且略阔，面有纵纹。 \n又似初生棕榈秧，高尺许。至冬尽枯，春初乃生。三月有花如栀子花，黄色，不结实。其根 \n独茎而直，大如小指，下有短细肉根相附，外皮稍粗褐色，内肉黄白色。二月、八月采根， \n曝干用。衡山出者，花碧，五月结黑子。 \n时珍曰∶苏颂所说详尽得之。但四、五月中抽茎四、五寸，开小花深黄色六出。不似栀 \n子，处处大山中有之。人惟取梅岭者用，而《会典》成都岁贡仙茅二十一斤。 \n\\x根\\x \n【修治】 曰∶采得，以清水洗，刮去皮，于槐砧上用铜刀切豆许大，以生稀布袋 \n盛，于乌豆水中浸一宿，取出，用酒拌湿蒸之，从巳至亥，取出曝干。勿犯铁器及牛乳，斑 \n人鬓须。大明曰∶彭祖单服法∶以竹刀刮切，糯米泔浸去赤汁出毒，后无妨损。 \n【气味】辛，温，有毒。 曰∶甘，微温，有小毒。又曰∶辛，平，宣而复补，无大毒 \n，有小热、小毒。 \n【主治】心腹冷气不能食，腰脚风冷挛痹不能行，丈夫虚劳，老人失溺无子，益阳道。 \n久服通神强记，助筋骨，益肌肤，长精神，明目（《开宝》）。治一切风气，补暖腰脚，清安 \n五脏。久服轻身，益颜色。丈夫五劳七伤，明耳目，填骨髓（李 ）。开胃消食下气，益房 \n事 \n【发明】颂曰∶五代伪唐筠州刺史王颜着《续传信方》，因国书编录西域婆罗门僧服仙 \n茅方，当时盛行。云五劳七伤，明目益筋力，宣而复补。云十斤乳石，不及一斤仙茅，表其 \n功力也。本西域道人所传。开元元年婆罗门僧进此药，明皇服之有效，当时禁方不传。天宝 \n之乱，方书流散，上都僧不空三藏始得此方，传与司徒李勉、尚书路嗣恭、给事齐杭、仆射 \n张建封服之，皆得力。路公久服金石无效，得此药，其益百倍。齐给事守缙云日，少气力， \n风疹继作，服之遂愈。八、九月采得，竹刀刮去黑皮，切如豆粒，米泔浸两宿，阴干捣筛， \n熟蜜丸梧子大。每旦空心酒饮任便下二十丸。忌铁器，禁食牛乳及黑牛肉，大减药力。机曰∶ \n五台山有仙茅，患大风者，服之多瘥。 \n时珍曰∶按∶《许真君书》云∶仙茅久服长生。其味甘能养肉，辛能养肺，苦能养气， \n咸能养骨，滑能养肤，酸能养筋，宜和苦酒服之，必效也。又范成《大虞衡志》云∶广西英 \n州多仙茅，其羊食之，举体悉化为筋，不复有血肉，食之补人，名乳羊。沈括《笔谈》云∶ \n夏文庄公禀赋异于人，但睡则身冷如逝者，既觉须令人温之，良久乃能动。常服仙茅、钟乳 \n、硫黄，莫知纪极。观此则仙茅盖亦性热，补三焦命门之药也。惟阳弱精寒，禀赋素怯者宜 \n之。若体壮相火炽盛者服之，反能动火。按∶张杲《医说》云∶一人中仙茅毒，舌胀退场门， \n渐大与肩齐。因以小刀 之，随破随合， 至百数，始有血一点出，曰可救矣。煮大黄、 \n朴硝与服，以药掺之，应时消缩。此皆火盛性淫之人过服之害也。弘治间东海张弼梅岭仙茅 \n诗，“有使君昨日才持去，今日人来乞墓铭”之句。皆不知服食之理，惟借药纵恣以速其生 \n者，于仙茅何尤？ \n【附方】新二。 \n仙茅丸∶壮筋骨，益精神，明目，黑髭须。仙茅二斤（糯米泔浸五日，去赤水，夏月浸 \n三 \n车前子十二两，白茯苓（去皮）、茴香（炒）、柏子仁（去壳）各八两，生地黄（焙）、熟地 \n黄（焙）各四两。为末，酒煮糊丸如梧子大。每服五十丸，食前温酒下，日二服。（《圣济总 \n录》）定喘下气，补心肾。神秘散∶用白仙茅半两（米泔浸三宿，晒炒），团参二钱半，阿 \n胶一两半（炒），鸡 一两（烧）。为末。每服二钱，糯米饮空心下，日二服。（《三因方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>玄参\n\n内容：（《本经》中品） \n【释名】黑参（《纲目》）、玄台（《吴普》）、重台（《本经》）、鹿肠（《吴普》）、正马 \n（《别录》）、逐马（《药性》）、馥草（《开宝》）、野脂麻（《纲目》）、鬼藏（《吴普》）。时 \n珍曰∶玄，黑色也。《别录》一名端，一名咸，多未详。 \n弘景曰∶其茎微似人参，故得参名。志曰∶合香家用之，故俗呼馥草。 \n【集解】《别录》曰∶玄参，生河间川谷及冤句，三月、四月采根，曝干。 \n普曰∶生冤句山阳。三月生苗。其叶有毛，四四相值，似芍药。黑茎，茎方，高四、五 \n尺。叶亦生枝间。四月实黑。 \n弘景曰∶今出近道，处处有之。茎似人参而长大。根甚黑，亦微香，道家时用，亦以 \n合香。 \n恭曰∶玄参根苗并臭，茎亦不似人参，未见合香。 \n志曰∶其茎方大，高四、五尺，紫赤色而有细毛。叶如掌大而尖长。根生青白，干即紫 \n黑，新者润腻。陶云茎似人参，苏言根苗并臭，似未深识。 \n颂曰∶二月生苗。叶似脂麻对生，又如槐柳而尖长有锯齿。细茎青紫色。七月开花青碧 \n色。八月结子黑色。又有白花者，茎方大，紫赤色而有细毛；有节若竹者，高五、六尺，其 \n根一根五、七枚。三月、八月采，曝干。或云蒸过曝干。 \n时珍曰∶今用玄参，正如苏颂所说。其根有腥气，故苏恭以为臭也。宿根多地蚕食之， \n故其中空。花有紫、白二种。 \n\\x根\\x \n【修治】 曰∶凡采得后，须用蒲草重重相隔，入甑蒸两伏时，晒干用。勿犯铜器 \n，饵之噎人喉，丧人目。 \n【气味】苦，微寒，无毒。《别录》曰∶咸。普曰∶神农、桐君、黄帝、雷公∶苦，无 \n毒；岐伯∶寒。 \n元素曰∶足少阴肾经君药也，治本经须用。 \n之才曰∶恶黄 、干姜、大枣、山茱萸，反藜芦。 \n【主治】腹中寒热积聚，女子产乳余疾，补肾气，令人目明（《本经》）。主暴中风伤寒 \n，身热支满，狂邪忽忽不知人，温疟洒洒，血瘕，下寒血，除胸中气，下水止烦渴，散颈下 \n核，痈肿，心腹痛，坚症，定五脏。久服补虚明目，强阴益精（《别录》）。热风头痛，伤寒 \n劳复，治暴结热，散瘤 瘰 （甄权）。治游风，补劳损，心惊烦躁，骨蒸传尸邪气，止健 \n忘 \n【发明】元素曰∶玄参乃枢机之剂，管领诸气上下，清肃而不浊，风药中多用之。故《活 \n人书》治伤寒阳毒，汗下后毒不散，及心下懊 ，烦不得眠，心神颠倒欲绝者，俱用玄参。 \n以此论之，治胸中氤氲之气，无根之火，当以玄参为圣剂也。时珍曰∶肾水受伤，真阴失守， \n孤阳无根，发为火病。法宜壮水以制火，故玄参与地黄同功。其消瘰 亦是散火，刘守真言 \n∶结核是火病。 \n【附方】旧二，新七。 \n诸毒鼠 ∶玄参渍酒，日日饮之。（《开宝本草》） \n年久瘰 ∶生玄参，捣敷上，日二易之。（《广利方》） \n赤脉贯瞳∶玄参为末，以米泔煮猪肝，日日蘸食之。（《济急仙方》） \n发斑咽痛∶玄参升麻汤∶用玄参、升麻、甘草各半两。水三盏，煎一盏半，温服。（《南 \n阳活人书》） \n急喉痹风∶不拘大人小儿。玄参、鼠粘子（半生半炒）各一两，为末。新水服一盏，立 \n瘥。（《圣惠方》） \n鼻中生疮∶玄参末涂之，或以水浸软，塞之。（《卫生易简方》） \n三焦积热∶玄参、黄连、大黄各一两。为末，炼蜜丸梧子大。每服三、四十丸，白汤下。 \n小儿，丸粟米大。（丹溪方）小肠疝气∶黑参 咀，炒，为丸。每服一钱半，空心酒服，出 \n汗即效。（孙天仁《集效方》） \n\\x烧香治痨\\x \n《经验方》∶用玄参一斤，甘松六两。为末，炼蜜一斤和匀，入瓶中封闭，地中埋 十 \n日取出。更用炭末六两，炼蜜六两，同和入瓶，更 五日取出。烧之，常令闻香，疾自愈。 \n颂曰∶初入瓶中封固，煮一伏时，破瓶取捣入蜜，别以瓶盛，埋地中 过用。亦可熏衣。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>地榆\n\n内容：（《本经》中品） \n【校正】并入《别录》有名未用酸赭。 \n【释名】玉豉、酸赭。 \n弘景曰∶其叶似榆而长，初生布地，故名。其花子紫黑色如豉，故又名玉豉。时珍曰∶ \n按∶外丹方言∶地榆一名酸赭，其味酸、其色赭故也。今蕲州俚人呼地榆为酸赭，又讹赭为 \n枣，则地榆、酸赭为一物甚明，其主治之功亦同，因并《别录》有名未用酸赭为一云。 \n【集解】《别录》曰∶地榆，生桐柏及冤句山谷。二月、八月采根曝干。又曰∶酸赭生 \n昌阳山。采无时。颂曰∶今处处平原川泽皆有之。宿根三月内生苗，初生布地，独茎直上， \n高三、四尺，对分出叶。叶似榆叶而稍狭，细长作锯齿状，青色。七月开花如椹子，紫黑色。 \n根 \n山人乏茗时，采作饮亦好，又可炸茹。 \n\\x根\\x \n【气味】苦，微寒，无毒。《别录》曰∶甘、酸。权曰∶苦，平。元素曰∶气微寒，味 \n微苦，气味俱薄，其体沉而降，阴中阳也，专主下焦血。杲曰∶味苦、酸，性微寒，沉也， \n阴也。之才曰∶得发良，恶麦门冬，伏丹砂、雄黄、硫黄。 \n【主治】妇人乳产， 痛七伤，带下五漏，止痛止汗，除恶肉，疗金疮（《本经》）。止 \n脓血，诸 恶疮热疮，补绝伤，产后内塞，可作金疮膏，消酒，除渴，明目（《别录》）。止 \n冷热痢疳痢，极效（《开宝》）。止吐血鼻衄肠风，月经不止，血崩，产前后诸血疾，并水泻 \n（大明）。治胆气不足（李杲）。汁酿酒治风痹，补脑。捣汁涂虎犬蛇虫伤（时珍）。酸赭∶ \n味酸。主内漏，止血不足（《别录》）。 \n【发明】颂曰∶古者断下多用之。炳曰∶同樗皮治赤白痢。 \n宗 曰∶其性沉寒，入下焦。若热血痢则可用。若虚寒人及水泻白痢，即未可轻使。 \n时珍曰∶地榆除下焦热，治大小便血证。止血取上截切片炒用。其梢则能行血，不可不 \n知。杨士瀛云∶诸疮，痛者，加地榆；痒者，加黄芩。 \n【附方】旧八，新七。 \n男女吐血∶地榆三两。米醋一升，煮十余沸，去滓，食前稍热服一合。（《圣惠方》）妇 \n人漏下，赤白不止，令人黄瘦。方同上。 \n血痢不止∶地榆晒研。每服二钱，掺在羊血上，炙熟食之，以捻头煎汤送下。一方∶以 \n地榆煮汁作饮，每服三合。（《圣济》）赤白下痢，骨立者。地榆一斤。水三升，煮一升半， \n去滓，再煎如稠饧，绞滤，空腹服三合，日再服。（崔元亮《海上方》）久病肠风∶痛痒不止。 \n地榆五钱，苍术一两。水二钟，煎一钟，空心服，日一服。（《活法机要》）下血不止二十年 \n者。取地榆、鼠尾草各二两。水二升，煮一升，顿服。若不断，以水渍屋尘饮一小杯投之。 \n（《肘后方》）结阴下血∶腹痛不已。地榆四两，炙甘草三两。每服五钱，水三盏，入缩砂仁 \n七枚，煎一盏半，分二服。（《宣明方》）小儿疳痢∶地榆煮汁，熬如饴糖，与服便已。（《肘 \n后方》）毒蛇螫人∶新地榆根捣汁饮，兼以渍疮。（《肘后方》） \n虎犬咬伤∶地榆煮汁饮，并为末敷之。亦可为末，白汤服，日三。忌酒。（《梅师方》） \n代指肿痛∶地榆煮汁渍之，半日愈。（《千金翼》） \n小儿湿疮∶地榆煮浓汁，日洗二次。（《千金方》） \n小儿面疮， 赤肿痛。地榆八两。水一斗，煎五升，温洗之。（《卫生总微方》） \n煮白石法∶七月七日取地榆根，不拘多少阴干，百日烧为灰。复取生者，与灰合捣万下 \n。灰三分，生末一分，合之。若石二、三斗，以水浸过三寸，以药入水搅之，煮至石烂可食 \n乃已。（ 仙《神隐书》） \n\\x叶\\x \n【主治】作饮代茶，甚解热（苏恭）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>丹参\n\n内容：（《本经》上品） \n【释名】赤参（《别录》）、山参（《日华》）、 蝉草（《本经》）、木羊乳（《吴普》）、 \n逐马（弘景）、奔马草。 \n时珍曰∶五参五色配五脏。故人参入脾，曰黄参；沙参入肺，曰白参；玄参入肾，曰黑 \n参；牡蒙入肝，曰紫参；丹参入心，曰赤参。其苦参，则右肾命门之药也。古人舍紫参而称 \n苦参，未达此义尔。炳曰∶丹参治风软脚，可逐奔马，故名奔马草。曾用，实有效。 \n【集解】《别录》曰∶丹参，生桐柏山川谷及太山。五月采根，曝干。 \n弘景曰∶此桐柏山在义阳，是淮水发源之山，非江东临海之桐柏也。今近道处处有之。 \n茎方有毛，紫花，时人呼为逐马。 \n普曰∶茎叶小房如荏有毛，根赤色，四月开紫花。二月、五月采根，阴干。 \n颂曰∶今陕西、河东州郡及随州皆有之。二月生苗，高一尺许。茎方有棱，青色。叶相 \n对，如薄荷而有毛。三月至九月开花成穗，红紫色，似苏花。根赤色，大者如指，长尺余， \n一苗数根。 \n恭曰∶冬采者，良；夏采者，虚恶。时珍曰∶处处山中有之。一枝五叶，叶如野苏而尖， \n青 \n\\x根\\x \n【气味】苦，微寒，无毒。 \n普曰∶神农、桐君、黄帝、雷公∶苦，无毒；岐伯∶咸。李当之∶大寒。 \n弘景曰∶久服多眼赤，故应性热，今云∶微寒，恐谬也。 \n权曰∶平。 \n之才曰∶畏咸水，反藜芦。 \n【主治】心腹邪气，肠鸣幽幽如走水，寒热积聚，破症除瘕，止烦满，益气（《本经》） \n。养血，去心腹痼疾结气，腰脊强脚痹，除风邪留热。久服利人（《别录》）。渍酒饮，疗风 \n痹足软（弘景）。主中恶及百邪鬼魅，腹痛气作，声音鸣吼，能定精（甄权）。养神定志，通 \n利 \n落死胎，止血崩带下，调妇人经脉不匀，血邪心烦，恶疮疥癣，瘿赘肿毒丹毒，排脓止痛， \n生肌长肉。（大明）活血，通心包络，治疝痛（时珍）。 \n【发明】时珍曰∶丹参色赤味苦，气平而降，阴中之阳也。入手少阴、厥阴之经，心与 \n包络血分药也。按∶《妇人明理论》云∶四物汤治妇人病，不问产前、产后，经水多少，皆 \n可通用。唯一味丹参散，主治与之相同。盖丹参能破宿血，补新血，安生胎，落死胎，止崩 \n中带下，调经脉，其功大类当归、地黄、芎 、芍药故也。 \n【附方】旧三，新四。 \n丹参散∶治妇人经脉不调，或前或后，或多或少，产前胎不安，产后恶血不下，兼治冷 \n热 \n落胎下血∶丹参十二两，酒五升，煮取三升，温服一升，一日三服。亦可水煮。（《千 \n金方》）寒疝腹痛∶小腹阴中相引痛，白汗出，欲死。以丹参一两为末。每服二钱，热酒调 \n下。（《圣惠方》）小儿身热，汗出拘急，因中风起。丹参半两，鼠屎（炒）三十枚。为末。 \n每服 \n惊痫发热∶丹参摩膏∶用丹参、雷丸各半两，猪膏二两。同煎七上七下，滤去滓盛之。 \n每 \n妇人乳痈∶丹参、白芷、芍药各二两。 咀，以醋腌一夜，猪脂半斤，微火煎成膏，去 \n滓敷之。（孟诜《必效方》）热油火灼，除痛生肌。丹参八两锉，以水微调，取羊脂二斤，煎 \n三上三下，以涂疮上。（《肘后方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>紫参\n\n内容：（《本经》中品） \n【释名】牡蒙（《本经》）、童肠（《别录》）、马行（《别录》）、众戎（《别录》）、五鸟 \n花（《纲目》）。 \n时珍曰∶紫参、王孙，并有牡蒙之名。古方所用牡蒙，多是紫参也。按∶《钱起诗集》 \n云∶紫参，幽芳也。五葩连萼，状如飞禽羽举。故俗名五鸟花。 \n【集解】《别录》曰∶紫参，生河西及冤句山谷。三月采根，火炙使紫色。 \n普曰∶紫参一名牡蒙，生河西或商山。圆聚生根，黄赤有纹，皮黑中紫，五月花紫赤， \n实黑大如豆。 \n弘景曰∶今方家皆呼为牡蒙，用之亦少。 \n恭曰∶紫参叶似羊蹄，紫花青穗。其根皮紫黑，肉红白，肉浅皮深。所在有之。长安见 \n用者，出蒲州。牡蒙乃王孙也，叶似及己而大，根长尺余，皮肉亦紫色，根苗不相似。 \n颂曰∶今河中、晋、解、齐及淮、蜀州郡皆有之。苗长一、二尺，茎青而细。其叶青 \n似槐叶，亦有似羊蹄者。五月开花白色，似葱花，亦有红紫而似水荭者。根淡紫，根皮紫黑 \n色，如地黄状，肉红白色，肉浅而皮深。三月采根，火炙紫色。又云∶六月采，晒干用。 \n时珍曰∶紫参根干紫黑色，肉带红白，状如小紫草。《范子计然》云∶紫参出三辅，有 \n三色，以青赤色为善。 \n\\x根\\x \n【气味】苦，辛，寒，无毒。《别录》曰∶微寒。普曰∶牡蒙∶神农、黄帝∶苦。李当 \n之∶小寒。之才曰∶畏辛夷。 \n【主治】心腹积聚，寒热邪气，通九窍，利大小便（《本经》）。疗肠胃大热，唾血衄血 \n，肠中聚血，痈肿诸疮，止渴益精（《别录》）。治心腹坚胀，散瘀血，治妇人血闭不通（甄 \n权）。主狂疟瘟疟，鼽血汗出（好古）。治血痢（好古）。牡蒙∶治金疮，破血，生肌肉，止 \n痛，赤白痢，补虚益气，除脚肿，发阴疡（苏恭）。 \n【发明】时珍曰∶紫参色紫黑，气味俱浓，阴也，沉也。入足厥阴之经，肝脏血分药也 \n。故治诸血病，及寒热疟痢、痈肿积块之属厥阴者。古方治妇人肠覃病乌啄丸，所用牡蒙， \n即此物也。唐苏恭注王孙，引陈延之《短剧方》牡蒙所主之证，正是紫参；若王孙则止治风 \n湿痹证，不治血病。故今移附于此。 \n【附方】旧一，新三。 \n紫参汤∶治痢下。紫参半斤。水五升，煎二升，入甘草二两，煎取半升，分三服。（张 \n仲景《金匮玉函》） \n吐血不止∶紫参、人参、阿胶（炒）等分。为末。乌梅汤服一钱。一方去人参，加甘草， \n以 \n面上酒刺∶五参丸∶用紫参、丹参、人参、苦参、沙参各一两。为末，胡桃仁杵和丸， \n梧 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>王孙\n\n内容：（《本经》中品） \n【校正】并入《拾遗》旱藕。 \n【释名】牡蒙（弘景）、黄孙（《别录》）、黄昏（《别录》）、旱藕。普曰∶楚名王孙。齐 \n名长孙，又名海孙。吴名白功章，又名蔓延。时珍曰∶紫参一名牡蒙，木部合欢一名黄昏， \n皆与此名同物异。 \n【集解】《别录》曰∶王孙，生海西川谷，及汝南城郭垣下。普曰∶蔓延赤文，茎叶相 \n当。 \n弘景曰∶今方家皆呼为黄昏，云牡蒙，市人少识者。恭曰∶按∶陈延之《短剧方》，述 \n本草牡蒙一名王孙。徐之才《药对》有牡蒙，无王孙。此则一物明矣。牡蒙叶似及己而大， \n根长尺余，皮肉皆紫色。藏器曰∶旱藕生太行山中，状如藕。时珍曰∶王孙叶生颠顶，似紫 \n河车叶。按神农及《吴普本草》，紫参一名牡蒙。陶弘景亦曰，今方家呼紫参为牡蒙。其王 \n孙并无牡蒙之名，而陶氏于王孙下乃云∶又名牡蒙，且无形状。唐苏恭始以紫参、牡蒙为二 \n物，谓紫参叶似羊蹄，王孙叶似及己。但古方所用牡蒙，皆为紫参；后人所用牡蒙，乃王孙 \n非紫参也。不可不辨。唐玄宗时隐民姜抚上言∶终南山有旱藕，饵之延年，状类葛粉。帝取 \n作汤饼，赐大臣。右骁骑将军甘守诚曰∶旱藕者，牡蒙也，方家久不用，抚易名以神之尔。 \n据此牡蒙乃王孙也。盖紫参止治血证积聚疟痢；而王孙主五脏邪气痹痛，疗百病之文，自 \n可推也。苏恭引《短剧方》牡蒙所主之证，乃紫参，非王孙，故今移附紫参之下。 \n\\x根\\x \n【气味】苦，平，无毒。普曰∶神农、雷公∶苦，无毒；黄帝∶甘。藏器曰∶旱藕 \n∶甘，平，无毒。 \n【主治】五脏邪气，寒湿痹，四肢疼酸，膝冷痛（《本经》）。疗百病，益气（《别录》） \n。旱藕∶主长生不饥，黑毛发（藏器）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>紫草\n\n内容：（《本经》中品） \n【释名】紫丹（《别录》）、紫 （音袄）、茈 （《广雅》，音紫戾）、藐（《尔雅》，音邈）、 \n地血（《吴普》）、鸦衔草。 \n时珍曰∶此草花紫根紫，可以染紫，故名。《尔雅》作茈草。瑶、侗人呼为鸦衔草。 \n【集解】《别录》曰∶紫草，生砀山山谷及楚地。三月采根，阴干。 \n弘景曰∶今出襄阳，多从南阳新野来，彼人种之，即是今染紫者，方药都不复用。《博 \n物志》云∶平氏阳山，紫草特好。魏国者，染色殊黑。比年东山亦种之，色小浅于北者。 \n恭曰∶所在皆有，人家或种之。苗似兰香，茎赤节青。二月开花紫白色。结实白色，秋 \n月熟。 \n时珍曰∶种紫草，三月逐垄下子，九月子熟时刈草，春社前后采根阴干，其根头有白 \n毛如茸。未花时采，则根色鲜明；花过时采，则根色黯恶。采时，以石压扁，曝干；收时， \n忌人溺及驴马粪并烟气，皆令草黄色。 \n\\x根\\x \n【修治】 曰∶凡使，每一斤，用蜡三两溶水，拌蒸之，待水干，取去头并两畔髭 \n，细锉用。 \n【气味】苦，寒，无毒。权曰∶甘，平。完素曰∶苦，温。 \n时珍曰∶甘、咸，寒。入手、足厥阴经。 \n【主治】心腹邪气，五疸，补中益气，利九窍，通水道（《本经》）。疗腹肿胀满痛。以 \n合膏，疗小儿疮，及面 （《别录》）。治恶疮 癣（甄权）。治斑疹痘毒，活血凉血，利大肠 \n（时珍）。 \n【发明】颂曰∶紫草古方稀用。今医家多用治伤寒时疾发疮疹不出者，以此作药，使其 \n发出。《韦宙独行方》治豌豆疮，煮紫草汤饮，后人相承用之，其效尤速。时珍曰∶紫草味 \n甘咸而气寒，入心包络及肝经血分。其功长于凉血活血，利大小肠。故痘疹欲出未出，血热 \n毒盛，大便闭涩者，宜用之。已出而紫黑便闭者，亦可用。若已出而红活，及白陷大便利者， \n切 \n尤为有益。又曾世荣《活幼心书》云∶紫草性寒，小儿脾气实者犹可用；脾气虚者反能 \n作泻。古方惟用茸，取其初得阳气，以类触类，所以用发痘疮。今人不达此理，一概用之， \n非矣。 \n【附方】旧三，新六。消解痘毒∶紫草一钱，陈皮五分，葱白三寸。新汲水煎服。（《直 \n指 \n封勿泄气，待温时服半合，则疮虽出亦轻。大便利者，勿用。煎服亦可。（《经验后方》） \n痘毒黑疔∶紫草三钱，雄黄一钱。为末，以胭脂汁调，银簪挑破，点之极妙。（《集简 \n方》） \n痈疽便闭∶紫草、栝蒌实等分，新水煎服。（《直指方》） \n小儿白秃∶紫草煎汁涂之。（《圣惠方》） \n小便卒淋∶紫草一两，为散，每食前用井华水服二钱。（《圣惠方》） \n产后淋沥∶方同上。（《产宝》） \n恶虫咬人∶紫草煎油涂之。（《圣惠方》）火黄身热、午后却凉，身有赤点，如生黑点者， \n不可治。宜烙手足心、背心、百会、下廉。 \n内服紫草汤∶紫草、吴蓝各一两，木香、黄连各半两。粗捣筛，每服五钱匕，水煎服。 \n（《三十六黄方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>白头翁\n\n内容：（《本经》下品） \n【释名】野丈人（《本经》）、胡王使者（《本经）》）、奈何草（《别录》）。 \n弘景曰∶处处有之。近根处有白茸，状似白头老翁，故以为名。 \n时珍曰∶丈人、胡使、奈何，皆状老翁之意。 \n【集解】《别录》曰∶白头翁，生高山山谷及田野。四月采。 \n恭曰∶其叶似芍药而大，抽一茎。茎头一花，紫色，似木槿花。实大者如鸡子，白毛寸 \n余，皆披下，似纛头，正似白头老翁，故名焉。陶言近根有白茸，似不识也。太常所贮蔓生 \n者，乃是女葳。其白头翁根，似续断而扁。 \n保升曰∶所在有之。有细毛，不滑泽，花蕊黄。二月采花，四月采实，八月采根，皆晒 \n干。 \n颂曰∶处处有之。正月生苗，作丛生，状似白薇而柔细稍长。叶生茎头，如杏叶，上有 \n细白毛而不滑泽。近根有白茸。根紫色，深如蔓菁。其苗有风则静，无风而摇，与赤箭、独 \n活同也。陶注未述茎叶，苏注言叶似芍药，实如鸡子，白毛寸余者，皆误矣。 \n宗 曰∶白头翁生河南洛阳界，其新安山野中屡尝见之，正如苏恭所说。至今本处山中 \n人卖白头翁丸，言服之寿考，又失古人命名之义。陶氏所说，失于不审，宜其排叱也。 \n机曰∶寇宗 以苏恭为是，苏颂以陶说为是。大抵此物用根，命名取象，当准苏颂《图 \n经》，而恭说恐别是一物也。 \n\\x根\\x \n【气味】苦，温，无毒。《别录》曰∶有毒。吴绶曰∶苦、辛，寒。权曰∶甘、苦， \n有小毒。豚实为之使。大明曰∶得酒良。花、子、茎、叶同。 \n【主治】温疟狂 ，寒热，症瘕积聚瘿气，逐血，止痛，疗金疮（《本经》）。鼻衄（《 \n别录》）。止毒痢（弘景）。赤痢腹痛，齿痛，百骨节痛，项下瘤 。（甄权）。一切风气，暖 \n腰膝，明目消赘（大明）。 \n【发明】颂曰∶俗医合补下药，甚验，亦冲人。 \n杲曰∶气浓味薄，可升可降，阴中阳也。张仲景治热痢下重，用白头翁汤主之。盖肾欲 \n坚，急食苦以坚之。痢则下焦虚，故以纯苦之剂坚之。男子阴疝偏坠，小儿头秃膻腥，鼻 \n衄无此不效，毒痢有此获功。 \n吴绶曰∶热毒下痢紫血鲜血者，宜之。 \n【附方】旧二，新三。白头翁汤∶治热痢下重。用白头翁二两，黄连、黄柏、秦皮各三 \n两。水七升，煮二升，每服一升，不愈更服。妇人产后痢虚极者，加甘草、阿胶各二两。（仲 \n景《金匮玉函方》）下痢咽痛∶春夏病此，宜用白头翁、黄连各一两，木香二两。水五升， \n煎一升半，分三服。（《圣惠方》）阴 偏肿∶白头翁根生者，不限多少，捣敷肿处。一宿当 \n作疮，二十日愈。（《外台秘要》）外痔肿痛∶白头翁草，一名野丈人，以根捣涂之，逐血止 \n痛。（《卫生易简方》）小儿秃疮∶白头翁根捣敷，一宿作疮，半月愈。（《肘后方》） \n\\x花\\x \n【主治】疟疾寒热，白秃头疮（时珍）。 \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>白芨\n\n内容：（《本经》下品） \n【校正】并入《别录》白给。 \n【释名】连及草（《本经》）、甘根（《本经》）、白给。 \n时珍曰∶其根白色，连及而生，故曰白芨。其味苦，而曰甘根，反言也。《吴普》作白 \n根，其根有白，亦通。《金光明经》谓之罔达罗喝悉多。又《别录》有名未用白给，即白芨 \n也，性味功用皆同，系重出，今并为一。 \n【集解】《别录》曰∶白芨，生北山川谷及冤句及越山。又曰∶白给生山谷，叶如藜芦 \n，根白相连，九月采。普曰∶茎叶如生姜、藜芦。十月花，直上，紫赤色。根白连。二月、 \n八月、九月采。弘景曰∶近道处处有之。叶似杜若，形根似菱米，节间有毛。方用亦稀，可 \n以作糊。保升曰∶今出申州。叶似初生棕苗叶及藜芦。三、四月抽出一苔，开紫花。七月实 \n熟，黄黑色。冬凋。根似菱，有三角，白色，角头生芽。八月采根用。颂曰∶今江淮、河、 \n陕、汉、黔诸州皆有之，生石山上。春生苗，长一尺许。叶似棕榈，两指大，青色。夏开紫 \n花。二月、七月采根。 \n时珍曰∶韩保升所说形状正是，但一科止抽一茎。开花长寸许，红紫色，中心如舌。其 \n根如菱米，有脐，如凫茈之脐，又如扁扁螺旋纹。性难干。 \n\\x根\\x \n【气味】苦，平，无毒。《别录》曰∶辛，微寒。白给∶辛，平，无毒。普曰∶神农∶ \n苦；黄帝∶辛；李当之∶大寒；雷公∶辛，无毒。大明曰∶甘、辛。杲曰∶苦、甘，微寒， \n性涩，阳中之阴也。 \n之才曰∶ \n【主治】痈肿恶疮败疽，伤阴死肌，胃中邪气，贼风鬼击，痱缓不收（《本经》）。除白 \n癣疥虫（《别录》）。结热不消，阴下痿，面上 ，令人肌滑（甄权）。止惊邪血邪血痢，痫 \n疾风痹，赤眼症结，温热疟疾，发背瘰 ，肠风痔 ，扑损，刀箭疮，汤火疮，生肌止痛（ \n大明）。止肺血（李杲）。 \n白给∶主伏虫白癣肿痛（《别录》）。 \n【发明】恭曰∶山野人患手足皲拆者，嚼以涂之，有效。为其性粘也。 \n颂曰∶今医家治金疮不瘥及痈疽方，多用之。 \n震亨曰∶凡吐血不止，宜加白芨。 \n时珍曰∶白芨性涩而收，得秋金之令，故能入肺止血，生肌治疮也。按洪迈《夷坚志》 \n云∶台州狱吏悯一大囚。囚感之，因言∶吾七次犯死罪，遭讯拷，肺皆损伤，至于呕血。 \n人传一方∶只用白芨为末，米饮日服，其效如神。后其囚凌迟，刽者剖其胸，见肺间窍穴数 \n十处，皆白芨填补，色犹不变也。洪贯之闻其说，赴任洋州，一卒忽苦咯血，甚危，用此救 \n之，一日即止也。《摘玄》云∶试血法∶吐在水碗内，浮者，肺血也；沉者，肝血也；半浮 \n半沉者，心血也。各随所见，以羊肺、羊肝、羊心煮熟，蘸白芨末，日日服之。 \n【附方】旧一，新八。鼻衄不止∶津调白芨末，涂山根上，仍以水服一钱，立止。（《经 \n验 \n生编》）重舌鹅口∶白芨末，乳汁调涂足心。（《圣惠方》） \n妇人阴脱∶白芨、川乌头等分。为末，绢裹一钱，纳阴中，入三寸，腹内热即止，日用 \n一次。（《广济方》）疔疮肿毒∶白芨末半钱，以水澄之，去水，摊于浓纸上贴之。（《袖珍 \n方》）打跌骨折∶酒调白芨末二钱服，其功不减自然铜、古铢钱也。（《永类方》）刀斧伤损∶ \n白芨、石膏（ ）等分。为末。掺之，亦可收口。（《济急方》）手足皲裂∶白芨末水调塞之。 \n勿犯水。（《济急方》）汤火伤灼∶白芨末，油调敷之。（《赵真人方》） \n\n\n\n<目录>草部第十二卷\\草之一\n\n<篇名>三七\n\n内容：（《纲目》） \n【释名】山漆（《纲目》）、金不换。 \n时珍曰∶彼人言其叶左三右四，故名三七，盖恐不然。或云本名山漆，谓其能合金疮， \n如漆粘物也，此说近之。金不换，贵重之称也。 \n【集解】时珍曰∶生广西、南丹诸州番峒深山中，采根曝干，黄黑色。团结者，状略似 \n白芨；长者，如老干地黄，有节。味微甘而苦，颇似人参之味。或云∶试法，以末糁猪血中 \n，血化为水者乃真。近传一种草，春生苗，夏高三、四尺。叶似菊艾而劲浓，有歧尖。茎有 \n赤棱。夏秋开黄花，蕊如金丝，盘纽可爱，而气不香。花干则吐絮如苦 絮。根叶味甘。治 \n金疮折伤出血，及上下血病，甚效。云是三七，而根大如牛蒡根，与南中来者不类，恐是刘 \n寄奴之属，甚易繁衍。 \n\\x根\\x \n【气味】甘、微苦，温，无毒。 \n【主治】止血散血定痛，金刃箭伤、跌扑杖疮、血出不止者，嚼烂涂，或为末掺之，其 \n血即止。亦主吐血衄血，下血血痢，崩中经水不止，产后恶血不下，血运血痛，赤目痈肿， \n虎咬蛇伤诸病（时珍）。 \n【发明】时珍曰∶此药近时始出，南人军中用为金疮要药，云有奇功。又云∶凡杖扑伤 \n损，瘀血淋漓者，随即嚼烂，罨之即止；青肿者，即消散。若受杖时，先服一、二钱，则血 \n不冲心；杖后，尤宜服之。产后服，亦良。大抵此药气温、味甘微苦，乃阳明、厥阴血分之 \n药，故能治一切血病，与骐 竭、紫矿相同。 \n【附方】新八。 \n吐血衄血∶山漆一钱，自嚼，米汤送下。或以五分，加入八核汤。（《濒湖集简方》） \n赤痢血痢∶三七三钱，研末，米泔水调服。即愈。（同上）大肠下血∶三七研末，同淡 \n白酒调一、二钱服，三服可愈。加五分入四物汤，亦可。（同上）妇人血崩∶方同上。产后 \n血多∶山漆研末，米汤服一钱。（同上）男妇赤眼，十分重者∶以山漆根磨汁，涂四围。甚 \n妙。（同上） \n虎咬蛇伤∶山漆研末，米饮服三钱，仍嚼涂之。（并同上） \n\\x叶\\x \n【主治】折伤跌扑出血，敷之即止；青肿，经夜即散，余功同根（时珍）。 \n\n\n\n<目录>草部第十三卷\n\n<篇名>草之二\n\n内容：\\x山草类下三十九种\\x \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>黄连\n\n内容：（《本经》上品） \n【释名】王连（《本经》）、支连（《药性》）。 \n时珍曰∶其根连珠而色黄，故名。 \n【集解】《别录》曰∶黄连，生巫阳川谷及蜀郡太山之阳。二月、八月采根。 \n弘景曰∶巫阳在建平。今西间者色浅而虚，不及东阳、新安诸县最胜。临海诸县者不佳。 \n用之当布裹 去毛，令如连珠。保升曰∶苗似茶，丛生，一茎生三叶，高尺许，凌冬不凋， \n花黄色。江左者，节高若连珠；蜀都者，节下不连珠。今秦地及杭州、柳州者佳。 \n颂曰∶今江、湖、荆、夔州郡亦有，而以宣城九节坚重相击有声者为胜，施、黔者次之 \n，东阳、歙州、处州者又次之。苗高一尺以来，叶似甘菊，四月开花黄色，六月结实似芹子 \n，色亦黄。江左者，根若连珠，其苗经冬不凋，叶如小雉尾草，正月开花作细穗，淡白微黄 \n色。六、七月根紧，始堪采。恭曰∶蜀道者粗大，味极浓苦，疗渴为最。江东者节如连珠， \n疗痢大善。澧州者更胜。时珍曰∶黄连，汉末李当之本草，惟取蜀郡黄肥而坚者为善。唐时 \n以澧州者为胜。今虽吴、蜀皆有，惟以雅州、眉州者为良。药物之兴废不同如此。大抵有二 \n种∶一种根粗无毛有珠，如鹰、鸡爪形而坚实，色深黄；一种无珠多毛而中虚，黄色稍淡。 \n各有所宜。 \n\\x根\\x \n【修治】 曰∶凡使以布拭去肉毛，用浆水浸二伏时，漉出，于柳木火上焙干用。 \n时珍曰∶五脏六腑皆有火，平则治，动则病，故有君火、相火之说，其实一气而已。黄 \n连入手少阴心经，为治火之主药∶治本脏之火，则生用之；治肝胆之实火，则以猪胆汁浸炒； \n治肝胆之虚火，则以醋浸炒；治上焦之火，则以酒炒；治中焦之火，则以姜汁炒；治下焦之 \n火，则以盐水或朴硝研细调水和炒；治气分湿热之火，则以茱萸汤浸炒；治血分块中伏火， \n则以干漆末调水炒；治食积之火，则以黄土研细调水和炒。诸法不独为之引导，盖辛热能制 \n其苦寒，咸寒能制其燥性，在用者详酌之。 \n【气味】苦，寒，无毒。《别录》曰∶微寒。普曰∶神农、岐伯、黄帝、雷公∶苦，无 \n毒；李当之∶小寒。之才曰∶黄芩、龙骨、理石为之使，恶菊花、玄参、白藓皮、芫花、白 \n僵蚕，畏款冬、牛膝，胜乌头，解巴豆毒。权曰∶忌猪肉，恶冷水。 \n曰∶服此药至十两，不得食猪肉；若服至三年，一生不得食也。时珍曰∶道书言服黄 \n连犯猪肉令人泄泻，而方家有猪肚黄连丸、猪脏黄连丸，岂只忌肉而不忌脏腑乎？ \n【主治】热气，目痛 伤泣出，明目，肠 腹痛下痢，妇人阴中肿痛。久服令人不忘（ \n《本经》）。主五脏冷热，久下泄 脓血，止消渴大惊，除水利骨，调胃浓肠益胆，疗口疮（ \n《别录》）。治五劳七伤，益气，止心腹痛，惊悸烦躁，润心肺，长肉止血，天行热疾，止 \n盗汗并疮疥。猪肚蒸为丸，治小儿疳气，杀虫（大明）。羸瘦气急（藏器）。治郁热在中，烦 \n躁恶心，兀兀欲吐，心下痞满（元素）。主心病逆而盛，心积伏梁（好古）。去心窍恶血，解 \n服药 \n【发明】元素曰∶黄连性寒味苦，气味俱浓，可升可降，阴中阳也，入手少阴经。其用 \n有六∶泻心脏火，一也；去中焦湿热，二也；诸疮必用，三也；去风湿，四也；赤眼暴发， \n五也；止中部见血，六也。张仲景治九种心下痞，五等泻心汤，皆用之。 \n成无己曰∶苦入心，寒胜热，黄连、大黄之苦寒，以导心下之虚热。蛔得甘则动，得苦 \n则安，黄连、黄柏之苦，以安蛔也。 \n好古曰∶黄连苦燥，苦入心，火就燥。泻心者，其实泻脾也，实则泻其子也。 \n震亨曰∶黄连，去中焦湿热而泻心火。若脾胃气虚，不能转运者，则以茯苓、黄芩代之 \n。以猪胆汁拌炒，佐以龙胆草，则大泻肝胆之火。下痢胃口热禁口者，用黄连、人参煎汤， \n终日呷之，如吐再强饮，但得一呷下咽便好。 \n刘完素曰∶古方以黄连为治痢之最。盖治痢惟宜辛苦寒药，辛能发散开通郁结，苦能燥 \n湿，寒能胜热，使气宣平而已。诸苦寒药多泄，惟黄连、黄柏性冷而燥，能降火去湿而止泻 \n痢，故治痢以之为君。 \n宗 曰∶今人多用黄连治痢，盖执以苦燥之义。下俚但见肠虚渗泄，微似有血，便即用 \n之，又罔顾寒热多少，惟欲尽剂，由是多致危困。若气实初病，热多血痢，服之便止，不必 \n尽剂。虚而冷者，慎勿轻用。 \n杲曰∶诸痛痒疮疡，皆属心火。凡诸疮宜以黄连、当归为君，甘草、黄芩为佐。凡眼暴 \n发赤肿，痛不可忍者，宜黄连、当归以酒浸煎之。宿食不消，心下痞满者，须用黄连、枳实 \n。 \n颂曰∶黄连治目方多，而羊肝丸尤奇异。今医家洗眼，以黄连、当归、芍药等分，用雪 \n水或甜水煎汤热洗之，冷即再温，甚益眼目。但是风毒赤目花翳，用之无不神效。盖眼目之 \n病，皆是血脉凝滞使然，故以行血药合黄连治之。血得热则行，故乘热洗也。 \n韩 曰∶火分之病，黄连为主，不但泻心火，而与芩、柏诸苦药例称者比也。目疾，入 \n以人乳浸蒸，或点或服之。生用为君，佐以官桂少许，煎百沸，入蜜空心服之，能使心肾 \n交于顷刻。入五苓、滑石，大治梦遗。以黄土、姜汁、酒、蜜四炒为君，以使君子为臣，白 \n芍药酒煮为佐，广木香为使，治小儿五疳。以茱萸炒者，加木香等分，生大黄倍之，水丸， \n治五痢。此皆得制方之法也。 \n时珍曰∶黄连，治目及痢为要药。古方治痢∶香连丸，用黄连、木香；姜连散，用干姜 \n、黄连；变通丸，用黄连、茱萸；姜黄散，用黄连、生姜。治消渴，用酒蒸黄连；治伏暑， \n用酒煮黄连；治下血，用黄连、大蒜；治肝火，用黄连、茱萸；治口疮，用黄连、细辛。皆 \n是一冷一热，一阴一阳，寒因热用，热因寒用，君臣相佐，阴阳相济，最得制方之妙，所以 \n有成功而无偏胜之害也。 \n弘景曰∶俗方多用黄连治痢及渴，道方服食长生。 \n慎微曰∶刘宋王微《黄连赞》云∶黄连味苦，左右相因。断凉涤暑，阐命轻身。缙云昔 \n御，飞跸上 。不行而至，吾闻其人。又梁江淹《黄连颂》云∶黄连上草，丹砂之次。御孽 \n辟妖，长灵久视。骖龙行天，驯马匝地。鸿飞以仪，顺道则利。 \n时珍曰∶《本经》、《别录》并无黄连久服长生之说，惟陶弘景言道方久服长生。 \n《神仙传》载封君达、黑穴公，并服黄连五十年得仙。窃谓黄连大苦大寒之药，用之降火燥 \n湿，中病即当止。岂可久服，使肃杀之令常行，而伐其生发冲和之气乎？《素问》载岐伯言 \n∶五味入胃，各归所喜攻。久而增气，物化之常也。气增而久，夭之由也。王冰注云∶酸入 \n肝为温，苦入心为热，辛入肺为清，咸入肾为寒，甘入脾为至阴而四气兼之，皆增其味而益 \n其气，故各从本脏之气为用。所以久服黄连、苦参反热，从火化也，余味皆然。久则脏气偏 \n胜，即有偏绝，则有暴夭之道。是以绝粒服饵之人不暴亡者，无五味偏助也。又秦观与乔希 \n圣论黄连书云∶闻公以眼疾饵黄连，至十数两犹不巳，殆不可也。医经有久服黄连、苦参反 \n热之说。此虽大寒，其味至苦，入胃则先归于心，久而不己，心火偏胜则热，乃其理也。况 \n眼疾本于肝热，肝与心为子母。心火也，肝亦火也，肾孤脏也，人患一水不胜二火。岂可久 \n服苦药，使心有所偏胜，是以火救火，其可乎？秦公此书，盖因王公之说而推详之也。我明 \n荆端王素多火病，医令服金花丸，乃芩、连、栀、柏四味，饵至数年，其火愈炽，遂至内障 \n丧明。观此，则寒苦之药，不但使人不能长生，久则气增偏胜，速夭之由矣。当以《素问》 \n之言为法，陶氏道书之说，皆谬谈也。杨士瀛云∶黄连能去心窍恶血。 \n【附方】旧二十二，新五十三。 \n心经实热∶泻心汤∶用黄连七钱。水一盏半，煎一盏，食远温服。小儿减之。（《和剂 \n局方》） \n猝热心痛∶黄连八钱。 咀，水煎热服。（《外台秘要》） \n肝火为痛∶黄连（姜汁炒），为末，粥糊丸梧子大。每服三十丸，白汤下。左金丸∶用 \n黄连六两，茱萸一两。同炒为末，神曲糊丸梧子大。每服三、四十丸，白汤下。（丹溪方） \n伏暑发热，作渴呕恶，及赤白痢，消渴，肠风酒毒，泄泻诸病，并宜酒煮黄龙丸主之。川 \n黄连一斤（切）。以好酒二升半，煮干焙研，糊丸梧子大。每服五十丸，熟水下，日三服。（ \n《和剂局方》）阳毒发狂，奔走不定。宜黄连、寒水石等分，为末。每服三钱，浓煎甘草汤 \n下。（《易简方》）骨节积热，渐渐黄瘦。黄连四分（切）。以童子小便五大合，浸经宿，微煎 \n三、四沸，去滓，分作二服。（《广利方》）小儿疳热流注，遍身疮蚀，或潮热，肚胀作渴。 \n猪肚黄连丸∶用猪肚一个（洗净），宣黄连五两。切碎，水和，纳入肚中缝定，放在五 \n升粳米上，蒸烂，石臼捣千杵，或入少饭同杵，丸绿豆大。每服二十丸，米饮下。仍服调血 \n清心之药佐之。盖小儿之病，不出于疳，则出于热，常须识此。（《直指方》）三消骨蒸∶黄 \n连末，以冬瓜自然汁浸一夜，晒干又浸，如此七次，为末，以冬瓜汁和丸梧子大。每服三、 \n四十丸，大麦汤下。寻常渴，只一服见效。（《易简方》）消渴尿多∶《肘后方》∶用黄连末， \n蜜丸梧子大。每服三十丸，白汤下。《宝鉴》∶用黄连半斤，酒一升浸，重汤内煮一伏时，取 \n晒为末，水丸梧子大。每服五十丸，温水下。 \n崔氏∶治消渴，小便滑数如油。黄连五两，栝蒌根五两，为末，生地黄汁丸梧子大。每 \n牛乳下五十丸，日二服。忌冷水、猪肉。《总录》∶用黄连末，入猪肚内蒸烂，捣丸梧子大， \n饭 \n》）破伤风病∶黄连五钱，酒二盏，煎七分，入黄蜡三钱，溶化热服之。（高文虎《蓼花洲闲 \n录》）小便白淫∶因心肾气不足，思想无穷所致。黄连、白茯苓等分，为末，酒糊丸梧子大 \n。每服三十丸，煎补骨脂汤下，日三服。（《普济方》）热毒血痢∶宣黄连一两。水二升，煮 \n取半升，露一宿，空腹热服，少卧将息，一二日即止。（《千金方》）赤痢久下，累治不瘥。 \n黄连一两。鸡子白和为饼，炙紫为末，以浆水三升，慢火煎成膏。每服半合，温米饮下。一 \n方∶只以鸡子白和丸服。（《胜金方》） \n热毒赤痢∶黄连二两（切，瓦焙令焦），当归一两（焙），为末，入麝香少许。每服二钱， \n陈米饮下。佛智和尚在闽，以此济人。（《本事方》）赤白久痢，并无寒热，只日久不止。用 \n黄连四十九个，盐梅七个。入新瓶内，烧烟尽，热研。每服二钱，盐米汤下。（杨子建《护 \n命方》）赤白暴痢，如鹅鸭肝者，痛不可忍。用黄连、黄芩各一两，水二升，煎一升，分三 \n次热服。（《经验方》） \n冷热诸痢∶胡洽九盏汤∶治下痢，不问冷热赤白，谷滞休息久下，悉主之。黄连（长三 \n寸）三十枚（重一两半），龙骨（如棋子大）四枚（重一两），大附子一枚，干姜一两半，胶 \n一两半。细切。以水五合著铜器中，去火三寸煎沸，便取下，坐土上，沸止，又上水五合， \n如此九上九下。纳诸药入水内，再煎沸，辄取下，沸止又上，九上九下，度可得一升，顿服 \n即止。（《图经本草》）下痢腹痛、赤白痢下，令人下部疼重，故名重下，日夜数十行，脐腹 \n绞痛。以黄连一斤。酒五升，煮取一升半，分再服，当止绞痛也。（《肘后方》） \n治痢香连丸∶李绛《兵部手集》∶治赤白诸痢，里急后重，腹痛。用宣黄连、青木香等 \n分；捣筛，白蜜丸梧子大。每服二、三十丸，空腹饮下，日再服，其效如神。久冷者，以煨 \n蒜捣和丸之。不拘大人婴孺皆效。《易简方》∶黄连（茱萸炒过）四两，木香（面煨）一两， \n粟米饭丸。钱仲阳香连丸∶治小儿冷热痢，加煨熟诃子肉。又治小儿泻痢，加煨熟肉豆蔻。 \n又治小儿气虚泻痢腹痛，加白附子尖。刘河间治久痢，加龙骨。朱丹溪治禁口痢，加石莲肉。 \n王 \n五疳八痢∶四治黄连丸∶用连珠黄连一斤（分作四分∶一分用酒浸炒，一分用自然姜汁 \n炒，一分用吴茱萸汤浸炒，一分用益智仁同炒，去益智，研末），白芍药（酒煮，切焙）四 \n两，使君子仁（焙）四两，广木香二两，为末，蒸饼和丸绿豆大。每服三十丸，米饮食前下， \n日三服。忌猪肉冷水。（《韩氏医通》）伤寒下痢，不能食者。黄连一斤，乌梅二十枚（去核， \n炙燥为末），蜡一棋子大，蜜一升。合煎，和丸梧子大。一服二十丸，日三服。又方∶黄连 \n二两，熟艾（如鸭子大）一团。水三升，煮取一升，顿服立止。（并《肘后方》）气痢后重， \n里急或下泄。《杜壬方》 \n姜连散∶用宣连一两，干姜半两。各为末，收。每用连一钱，姜半钱，和匀，空心温酒 \n下，或米饮下。神妙。《济生方》秘传香连丸∶用黄连四两，木香二两，生姜四两。以姜铺 \n砂锅底，次铺连，上铺香，新汲水三碗，煮焙研，醋调仓米糊为丸。如常，日服五次。 \n小儿下痢，赤白多时，体弱不堪。以宣连用水浓煎，和蜜，日服五、六次。《子母秘录》 \n诸痢脾泄，脏毒下血。雅州黄连半斤，去毛切，装肥猪大肠内，扎定，入砂锅中，以水 \n酒煮烂，取连焙，研末，捣肠和丸梧子大。每服百丸，米汤下，极效。（《直指》） \n湿痢肠风∶《百一选方》变通丸∶治赤白下痢，日夜无度，及肠风下血。用川黄连（去 \n毛）、吴茱萸（汤泡过）各二两，同炒香，拣出各为末，以粟米饭和丸梧子大，各收。每服 \n三十丸，赤痢，甘草汤下黄连丸；白痢，姜汤下茱萸丸；赤白痢，各用十五丸，米汤下。此 \n乃浙西河山纯老方，救人甚效。《局方》戊己丸∶治脾胃受湿，下痢腹痛，米谷不化。用二 \n味加白芍药，同炒研，蒸饼和丸服。 \n积热下血∶聚金丸∶治肠胃积热，或因酒毒下血，腹痛作渴，脉弦数。黄连四两（分作 \n四 \n面糊丸如梧子大。每服五十丸，米泔浸枳壳水，食前送下。冬月，加酒蒸大黄一两。（《杨 \n氏家藏方》） \n脏毒下血∶黄连为末，独头蒜煨研，和丸梧子大，每空心陈米饮下四十丸。（《济生方》） \n酒痔下血∶黄连（酒浸，煮熟）为末，酒糊丸梧子大。每服三、四十丸，白汤下。一方∶ \n用自然姜汁浸焙炒。（《医学集成》） \n鸡冠痔疾∶黄连末敷之。加赤小豆末尤良。（《斗门方》）痔病秘结，用此宽肠。黄连、 \n枳壳等分，为末，糊丸梧子大。每服五十丸，空心米饮下。 \n痢痔脱肛∶冷水调黄连末涂之，良。（《经验良方》） \n脾积食泄∶川黄连二两。为末。大蒜捣和丸梧子大。每服五十丸，白汤下。（《活人心 \n统 \n水泄脾泄∶神圣香黄散∶宣连一两，生姜四两。同以文火炒至姜脆，各自拣出为末。水 \n泄，用姜末；脾泄，用连末，每服二钱，空心白汤下。甚者不过二服。亦治痢疾。（《博济 \n方》） \n吐血不止∶黄连一两捣散。每服一钱，水七分，入豉二十粒，煎至五分，去滓温服。大 \n人、小儿皆治。（《简要济众方》） \n眼目诸病∶《胜金》黄连丸∶用宣连不限多少，捶碎，以新汲水一大碗，浸六十日，绵 \n滤取汁，入原碗内，重汤上熬之，不住搅之，候干。即穿地坑子可深一尺，以瓦铺底，将熟 \n艾四两坐在瓦上，以火燃之。以药碗覆上，四畔泥封，开孔出烟尽，取刮下，丸小豆大，每 \n甜竹叶汤下十丸。刘禹锡《传信方》羊肝丸∶治男女肝经不足，风热上攻，头目昏暗羞明， \n及障翳青盲。用黄连末一两，羊子肝一具，去膜，擂烂和丸梧子大。每食后暖浆水吞十四丸， \n连作五剂，瘥。昔崔承元活一死囚，囚后病死。一旦崔病内障，逾年半夜独坐，闻阶除悉 \n之声，问之。答曰∶是昔蒙活之囚，今故报恩。遂告以此方而没。崔服之，不数月，眼复明。 \n因传于世 \n暴赤眼痛∶宣黄连锉，以鸡子清浸，置地下一夜，次早滤过，鸡羽蘸滴目内。又方∶苦 \n竹两头留节，一头开小孔，入黄连片在内，油纸封，浸井中一夜。次早服竹节内水，加片脑 \n少许，外洗之。《海上方》∶用黄连、冬青叶煎汤洗之。《选奇方》∶用黄连、干姜、杏仁等 \n分，为末，绵包浸汤，闭目乘热淋洗之。 \n小儿赤眼∶水调黄连末，贴足心，甚妙。（《全幼心鉴》） \n烂弦风眼∶黄连十文，槐花、轻粉少许，为末。男儿乳汁和之，饭上蒸过，帛裹，熨眼 \n上 \n目猝痒痛∶乳汁浸黄连，频点 中。《抱朴子》云∶治目中百病。（《外台秘要》） \n泪出不止∶黄连浸浓汁，渍拭之。（《肘后方》） \n牙痛恶热∶黄连末掺之，立止。（李楼《奇方》） \n口舌生疮∶《肘后》∶用黄连煎酒，时含呷之。赴筵散∶用黄连、干姜等分，为末掺之。 \n小儿口疳∶黄连、芦荟等分，为末，每蜜汤服五分。走马疳，入蟾灰等分，青黛减半， \n麝香少许。（《简便方》）小儿鼻 ，鼻下两道赤色，有疳。以米泔洗净，用黄连末敷之，日 \n三、四次。（张杰《子母 \n小儿食土∶取好黄土，煎黄连汁搜之，晒干与食。（姚和众《童子秘诀》） \n预解胎毒∶小儿初生，以黄连煎汤浴之，不生疮及丹毒。又方∶未出声时，以黄连煎汁 \n灌 \n腹中儿哭∶黄连煎浓汁，母常呷之。（《熊氏补遗》）因惊胎动、出血。取黄连末。酒服 \n方寸匕，日三服。（《子母秘录》）妊娠子烦，口干不得卧。黄连末。每服一钱，粥饮下。或 \n酒蒸黄连丸，亦妙。（《妇人良方》）痈疽肿毒，已溃、未溃皆可用。黄连、槟榔等分。为末。 \n以鸡子清调搽之。（王氏《简易方》）中巴豆毒，下利不止∶黄连、干姜等分。为末。水服方 \n寸匕。（《肘后方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>胡黄连\n\n内容：（宋《开宝》） \n【释名】割孤露泽。 \n时珍曰∶其性味功用似黄连，故名。割孤露泽，胡语也！ \n【集解】恭曰∶胡黄连出波斯国，生海畔陆地。苗若夏枯草，根头似鸟嘴，折之内似 \n鹆眼者，良。八月上旬采之。颂曰∶今南海及秦陇间亦有之。初生似芦，干则似杨柳枯枝， \n心黑外黄，不拘时月收采。承曰∶折之尘出如烟者，乃为真也！ \n\\x根\\x \n【气味】苦，平，无毒。 \n恭曰∶大寒。恶菊花、玄参、白藓皮，解巴豆毒。忌猪肉，令人漏精。 \n【主治】补肝胆，明目，治骨蒸劳热，三消，五心烦热，妇人胎蒸虚惊，冷热泄痢，五 \n痔，浓肠胃，益颜色。浸人乳汁，点目甚良（苏恭）。治久痢成疳，小儿惊痫、寒热、不下 \n食，霍乱下痢，伤寒咳嗽温疟，理腰肾，去阴汗（《开宝》）。去果子积（震亨）。 \n【附方】旧二，新一十二。 \n伤寒劳复∶身热，大小便赤如血色。用胡黄连一两，山栀子二两（去壳）。入蜜半两， \n拌和，炒令微焦为末，用猪胆汁和丸梧子大。每服十丸，用生姜二片，乌梅一个，童子小便 \n三合，浸半日去滓，食后暖小便令温吞之，卧时再服，甚效。（苏颂《图经本草》）小儿潮热， \n往来盗汗。用南番胡黄连、柴胡等分。为末，炼蜜丸芡子大。每服一丸至五丸，安器中，以 \n酒少许化开，更入水五分，重汤煮二三十沸，和滓服。（孙兆《秘宝方》） \n小儿疳热∶肚胀潮热发焦，不可用大黄、黄芩伤胃之药，恐生别证。以胡黄连五钱，灵 \n脂 \n肥热疳疾∶胡黄连丸∶用胡黄连、黄连各半两，朱砂二钱半。为末，入猪胆内扎定，以 \n杖子钩悬于砂锅内，浆水煮一炊久，取出研烂，入芦荟、麝香各一分，饭和丸麻子大。每服 \n五、七丸至一、二十丸，米饮下。（钱乙《小儿方诀》）五心烦热∶胡黄连末，米饮服一钱。 \n（《易简方》）小儿疳泻，冷热不调。胡黄连半两，绵姜一两（炮）。为末。每服半钱，甘草 \n节汤下。（《卫生总微论》）小儿自汗∶盗汗，潮热往来。胡黄连、柴胡等分，为末，蜜丸芡 \n子大。每用一、二丸，水化开，入酒少许，重汤煮一、二十沸，温服。（《保幼大全》） \n小儿黄胆∶胡黄连、川黄连各一两。为末，用黄瓜一个，去瓤留盖，入药在内合定，面 \n裹煨熟，去面，捣丸绿豆大。每量大小温水下。（《总微论》） \n吐血衄血∶胡黄连、生地黄等分。为末，猪胆汁丸梧子大，卧时茅花汤下五十丸。（《普 \n济方》）血痢不止∶胡黄连、乌梅肉、灶下土等分，为末，腊茶清下。（《普济方》） \n热痢腹痛∶胡黄连末，饭丸梧子大，每米汤下三十丸。（鲜于枢《钩玄》） \n婴儿赤目∶茶调胡黄连末，涂手足心，即愈。（《济急仙方》）痈疽疮肿，已溃、未溃皆 \n可用之。胡黄连、穿山甲（烧存性）等分为末，以茶或鸡子清调涂。（《简易方》）痔疮疼肿， \n不可忍者。胡黄连末，鹅胆汁调搽之。（孙氏《集效方》） \n血余怪病∶方见木部茯苓下。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>黄芩\n\n内容：（《本经》中品） \n【释名】腐肠（《本经》）、空肠（《别录》）、内虚（《别录》）、妒妇（《吴普》）、经芩 \n（《别录》）、黄文（《别录》）、印头（《吴普》）、苦督邮（《记事》），内实者名子芩（弘景） \n、条芩（《纲目》）、 尾芩（《唐本》）、鼠尾芩。弘景曰∶圆者，名子芩；破者，名宿芩， \n其腹中皆烂，故名腐肠。时珍曰∶芩，《说文》作 ，谓其色黄也。或云芩者，黔也，黔乃 \n黄黑之色也。宿芩乃旧根，多中空，外黄内黑，即今所谓片芩，故又有腐肠、妒妇诸名。妒 \n妇心黯，故以比之。子芩乃新根，多内实，即今所谓条芩。或云西芩多中空而色黔，北芩多 \n内实而深黄。 \n【集解】《别录》曰∶黄芩，生秭归川谷及冤句。三月三日采根，阴干。 \n弘景曰∶秭归，属建平郡。今第一出彭城，郁州亦有之，惟深色坚实者好。俗方多用， \n道家不须。恭曰∶今出宜州、 州、泾州者，佳。兖州大实亦好，名 尾芩。 \n颂曰∶今川蜀、河东、陕西近郡，皆有之。苗长尺余，茎干粗如箸，叶从地四面作丛生， \n类紫草，高一尺许。亦有独茎者，叶细长，青色，两两相对。六月开紫花，根如知母粗细， \n长四、五寸，二月、八月采根，曝干。 \n《吴普本草》云∶二月生赤黄叶，两两四四相值。其茎空中，或方圆，高三、四尺。四 \n月花紫红赤，五月实黑、根黄。二月至九月采，与今所说有小异也。 \n\\x根\\x \n【气味】苦，平，无毒。《别录》曰∶大寒。普曰∶神农、桐君、雷公∶苦，无毒 \n；李当之∶小温。杲曰∶可升可降，阴也。好古曰∶气寒，味微苦而甘，阴中微阳，入手太 \n阴血分。元素曰∶气凉，味苦、甘，气浓味薄，浮而升，阳中阴也，入手少阳、阳明经。酒 \n炒则上行。之才曰∶山茱萸、龙骨为之使，恶葱实，畏丹砂、牡丹、藜芦。得浓朴、黄连， \n止腹痛；得五味子、牡蒙、牡蛎，令人有子；得黄 、白蔹、赤小豆，疗鼠 。 \n时珍曰∶得酒，上行；得猪胆汁，除肝胆火；得柴胡，退寒热；得芍药，治下痢；得桑 \n白皮，泻肺火；得白术，安胎。 \n【主治】诸热黄胆，肠 泄痢，逐水，下血闭，恶疮疽蚀火疡（《本经》）。疗痰热胃中 \n热，小腹绞痛，消谷，利小肠，女子血闭，淋露下血，小儿腹痛（《别录》）。治热毒骨蒸， \n寒热往来，肠胃不利，破拥气，治五淋，令人宣畅，去关节烦闷，解热渴（甄权）。下气， \n主天行热疾，疔疮排脓，治乳痈发背（大明）。凉心，治肺中湿热，泻肺火上逆，疗上热， \n目中肿赤，瘀血壅盛，上部积血，补膀胱寒水，安胎，养阴退阳（元素）。治风热湿热头疼， \n奔豚热痛，火咳肺痿喉腥，诸失血（时珍）。 \n【发明】杲曰∶黄芩之中枯而飘者，泻肺火，利气，消痰，除风热，清肌表之热；细实 \n而坚者，泻大肠火，养阴退阳，补膀胱寒水，滋其化源。高下之分与枳实、枳壳同例。 \n元素曰∶黄芩之用有九∶泻肺热，一也；上焦皮肤风热风湿，二也；去诸热，三也；利 \n胸中气，四也；消痰膈，五也；除脾经诸湿，六也；夏月须用，七也；妇人产后养阴退阳， \n八也；安胎，九也。酒炒上行，主上部积血，非此不能除。下痢脓血，腹痛后重，身热久不 \n能止者，与芍药、甘草同用之。凡诸疮痛不可忍者，宜芩、连苦寒之药，详上下，分身、 \n梢及引经药用之。 \n震亨曰∶黄芩降痰，假其降火也。凡去上焦湿热，须以酒洗过用。片芩泻肺火，须用桑 \n白皮佐之。若肺虚者，多用则伤肺，必先以天门冬保定肺气而后用之。黄芩、白术乃安胎圣 \n药，俗以黄芩为寒而不敢用，盖不知胎孕宜清热凉血，血不妄行，乃能养胎。黄芩乃上、中 \n二焦药，能降火下行，白术能补脾也。 \n罗天益曰∶肺主气，热伤气，故身体麻木。又五臭入肺为腥，故黄芩之苦寒，能泻火、 \n补气而利肺，治喉中腥臭。颂曰∶张仲景治伤寒心下痞满，泻心汤。凡四方皆用黄芩，以其 \n主诸热、利小肠故也。又太阳病下之利不止，喘而汗出者，有葛根黄芩黄连汤，及主妊娠安 \n胎散，亦多用之。 \n时珍曰∶洁古张氏言∶黄芩泻肺火，治脾湿；东垣李氏言∶片芩治肺火，条芩治大肠火； \n丹溪朱氏言∶黄芩治上中二焦火；而张仲景治少阳证小柴胡汤，太阳少阳合病下利黄芩汤， \n少阳证下后心下满而不痛泻心汤，并用之；成无己言黄芩苦而入心，泄痞热。是黄芩能入手 \n少阴阳明、手足太阴少阳六经矣。盖黄芩气寒味苦，色黄带绿，苦入心，寒胜热，泻心火， \n治脾之湿热，一则金不受刑，一则胃火不流入肺，即所以救肺也。肺虚不宜者，苦寒伤脾胃， \n损其母也。少阳之证，寒热胸胁痞满，默默不欲饮食，心烦呕，或渴或痞，或小便不利。虽 \n曰病在半表半里，而胸胁痞满，实兼心肺上焦之邪。心烦喜呕，默默不欲饮食，又兼脾胃中 \n焦之证。故用黄芩以治手足少阳相火，黄芩亦少阳本经药也。成无己《注伤寒论》，但云柴 \n胡、黄芩之苦，以发传邪之热；芍药、黄芩之苦，以坚敛肠胃之气，殊昧其治火之妙。杨士 \n瀛《直指方》云∶柴胡退热，不及黄芩。盖亦不知柴胡之退热，乃苦以发之，散火之标也； \n黄芩之退热，乃寒能胜热，折火之本也。仲景又云∶少阳证腹中痛者，去黄芩，加芍药。心 \n下悸，小便不利者，去黄芩，加茯苓。似与《别录》治少腹绞痛、利小肠之文不合。成氏言 \n黄芩寒中，苦能坚肾，故去之，盖亦不然。至此当以意逆之，辨以脉证可也。若因饮寒受寒 \n，腹中痛，及饮水心下悸，小便不利，而脉不数者，是里无热证，则黄芩不可用也。若热厥 \n腹痛，肺热而小便不利者，黄芩其可不用乎？故善观书者，先求之理，毋徒泥其文。昔有人 \n素多酒欲，病少腹绞痛不可忍，小便如淋，诸药不效。偶用黄芩、木通、甘草三味煎服，遂 \n止。王海藏言有人因虚服附子药多，病小便秘，服芩、连药而愈。此皆热厥之痛也，学人其 \n可拘乎？予年二十时，因感冒咳嗽既久，且犯戒，遂病骨蒸发热，肤如火燎，每日吐痰碗许 \n，暑月烦渴，寝食几废，六脉浮洪。遍服柴胡、麦门冬、荆沥诸药，月余益剧，皆以为必死 \n矣。先君偶思李东垣治肺热如火燎，烦躁引饮而昼盛者，气分热也。宜一味黄芩汤，以泻肺 \n经气分之火。遂按方用片芩一两，水二钟，煎一钟，顿服。次日身热尽退，而痰嗽皆愈。药 \n中肯綮，如鼓应桴，医中之妙，有如此哉。 \n【附方】旧三，新一十四。 \n三黄丸∶孙思邈《千金方》云∶巴郡太守奏∶加减三黄丸∶疗男子五痨七伤，消渴不生 \n肌肉，妇人带下，手足寒热，泻五脏火。春三月，黄芩四两，大黄三两，黄连四两；夏三月， \n黄芩六两，大黄一两，黄连七两；秋三月，黄芩六两，大黄二两，黄连三两；冬三月，黄芩 \n三两，大黄五两，黄连二两。三物随时合捣下筛，蜜丸乌豆大。米饮每服五丸，日三。不知 \n，增至七丸，服一月病愈。久服走及奔马，人用有验。禁食猪肉。（《图经本草》） \n三补丸∶治上焦积热，泻五脏火。黄芩、黄连、黄柏等分，为末，蒸饼丸梧子大。每白 \n汤下二、三十丸。（《丹溪纂要》）肺中有火∶清金丸∶用片芩（炒）为末，水丸梧子大。每 \n服二、三十丸，白汤下。（同上）肤热如燎∶方见发明下。小儿惊啼∶黄芩、人参等分，为 \n末。每服一字，水饮下。（《普济方》）肝热生翳，不拘大人小儿。黄芩一两，淡豉三两。为 \n末。每服三钱，以熟猪肝裹吃，温汤送下，日二服。忌酒、面。（《卫生家宝方》）少阳头痛， \n亦治太阳头痛，不拘偏正。小清空膏∶用片黄芩（酒浸透，晒干）为末。每服一钱，茶、酒 \n任下。（东垣《兰室秘藏》）眉眶作痛，风热有痰。黄芩（酒浸）、白芷等分。为末。每服二 \n钱，茶下。（《洁古家珍》）吐血衄血，或发或止，积热所致。黄芩一两（去中心黑朽者），为 \n末。每服三钱，水一盏，煎六分，和滓温服。（《圣惠方》） \n吐衄下血∶黄芩三两。水三升，煎一升半，每温服一盏。亦治妇人漏下血。（庞安时《总 \n病论》） \n血淋热痛∶黄芩一两。水煎热服。（《千金方》） \n经水不断∶芩心丸∶治妇人四十九岁以后，天癸当住，每月却行，或过多不止。用条芩 \n心二两（米醋浸七日，炙干又浸，如此七次）。为末，醋糊丸梧子大。每服七十丸，空心温 \n酒下，日二次。（《瑞竹堂方》） \n崩中下血∶黄芩为细末。每服一钱，霹雳酒下，以秤锤烧赤，淬酒中也。 \n许学士云∶崩中，多用止血及补血药。此方乃治阳乘于阴，所谓天暑地热，经水沸溢者 \n也。（《本事方》） \n安胎清热∶条芩、白术等分。炒为末，米饮和丸梧子大。每服五十丸，白汤下。或加神 \n曲。凡妊娠调理，以四物去地黄，加白术、黄芩为末，常服甚良。（《丹溪纂要》）产后血渴， \n饮水不止。黄芩、麦门冬等分。水煎温服，无时。（《杨氏家藏方》） \n灸疮血出∶一人灸火至五壮，血出不止如尿，手冷欲绝。以酒炒黄芩二钱为末，酒服即 \n止 \n老小火丹∶黄芩末，水调涂之。（《梅师方》） \n\\x子\\x \n【主治】肠 脓血（《别录》）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>秦艽\n\n内容：（音交。《本经》中品） \n【释名】秦 （《唐本》）、秦爪（萧炳）。 \n恭曰∶秦艽，俗作秦胶，本名秦 ，与纠同。 \n时珍曰∶秦艽出秦中，以根作罗纹交纠者佳，故名秦艽、秦 。 \n【集解】《别录》曰∶秦艽，生飞鸟山谷，二月、八月采根，曝干。 \n弘景曰∶今出甘松、龙 \n用宜破去。 \n恭曰∶今出泾州、 州、岐州者，良。 \n颂曰∶今河陕州郡多有之。其根土黄色而相交纠，长一尺以来，粗细不等。枝干高五、 \n六寸。叶婆娑，连茎梗俱青色，如莴苣叶。六月中开花紫色，似葛花，当月结子。每于春秋 \n采根，阴干。 \n\\x根\\x \n【修治】 曰∶秦艽须于脚纹处认取∶左纹列为秦，治疾；右纹列为艽，即发香港脚。凡 \n用秦，以布拭去黄白毛，乃用还元汤浸一宿，晒干用。 \n时珍曰∶秦艽，但以左纹者为良，分秦与艽为二名，谬矣。 \n【气味】苦，平，无毒。《别录》曰∶辛，微温。大明曰∶苦，冷。 \n元素曰∶气微温，味苦、辛，阴中微阳，可升可降，入手阳明经。 \n之才曰∶菖蒲为之使，畏牛乳。 \n【主治】寒热邪气，寒湿风痹，肢节痛，下水利小便（《本经》）。疗风无问久新，通身 \n挛急（《别录》）。传尸骨蒸，治疳及时气（大明）。牛乳点服，利大小便，疗酒黄、黄胆，解 \n酒毒，去头风（甄权）。除阳明风湿，及手足不遂，口噤牙痛口疮，肠风泻血，养血荣筋（元 \n素）。泄热，益胆气（好古）。治胃热虚劳发热（时珍）。 \n【发明】时珍曰∶秦艽，手足阳明经药也，兼入肝胆，故手足不遂、黄胆烦渴之病须之 \n，取其去阳明之湿热也。阳明有湿，则身体酸疼烦热；有热，则日晡潮热骨蒸。所以《圣惠 \n方》治急劳烦热，身体酸疼。用秦艽、柴胡各一两，甘草五钱。为末，每服三钱，白汤调下 \n。治小儿骨蒸潮热，减食瘦弱。用秦艽、炙甘草各一两。每用一、二钱，水煎服之。钱乙加 \n薄荷叶五钱。 \n【附方】旧六，新七。 \n五种黄胆∶崔元亮《海上方》云∶凡黄有数种∶伤酒发黄，误食鼠粪亦作黄，因劳发黄， \n多痰涕，目有赤脉，益憔悴，或面赤恶心者是也。用秦艽一大两，锉作两帖。每帖用酒半 \n升，浸绞取汁，空腹服，或利便止。就中饮酒人易治，屡用得力。《贞元广利方》∶治黄病 \n内外皆黄，小便赤，心烦口干者。以秦艽三两，牛乳一大升，煮取七合，分温再服。此方出 \n于许仁则。又孙真人方∶加芒硝六钱。暴泻引饮∶秦艽二两，甘草（炙）半两。每服三钱， \n水 \n（《太平圣惠方》）急劳烦热∶方见发明下。小儿骨蒸∶同上。小便艰难或转胞，腹满闷，不 \n急疗，杀人。用秦艽一两，水一盏，煎七分，分作二服。又方∶加冬葵子等分，为末，酒服 \n一匕。（《圣惠方》）胎动不安∶秦艽、甘草（炙）、鹿角胶（炒）各半两。为末。每服三钱， \n水 \n发背初起疑似者。便以秦艽、牛乳煎服，得快利三、五行，即愈。（崔元亮《海上集验方》） \n疮口不合，一切皆治。秦艽为末，掺之。（《直指方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>茈胡\n\n内容：（《本经》上品） \n【释名】地熏（《本经》）、芸蒿（《别录》）、山菜（《吴普》）、茹草（《吴普》）。 \n恭曰∶茈，是古柴字。《上林赋》云茈姜，及《尔雅》云茈草，并作此茈字。此草根紫 \n色，今太常用茈胡是也。又以木代系，相承呼为柴胡。且检诸本草无名此者。 \n时珍曰∶茈字，有柴、紫二音。茈姜、茈草之茈，皆音紫；茈胡之茈，音柴。茈胡生山 \n中，嫩则可茹，老则采而为柴，故苗有芸蒿、山菜、茹草之名，而根名柴胡也。苏恭之说殊 \n欠明。古本张仲景《伤寒论》， \n【集解】《别录》曰∶茈胡，叶名芸蒿，辛香可食。生弘农川谷及冤句。二月、八月采 \n根，曝干。弘景曰∶今出近道，状如前胡而强。《博物志》云∶芸蒿叶似邪蒿，春秋有白 ， \n长四、五寸，香美可食，长安及河内并有之。恭曰∶伤寒大小柴胡汤，为痰气之要。若以芸 \n蒿根为之，大谬矣。颂曰∶今关陕、江湖间近道皆有之，以银州者为胜。二月生苗甚香。茎 \n青紫坚硬，微有细线。叶似竹叶而稍紧小，亦有似斜蒿者，亦有似麦门冬叶而短者。七月开 \n黄花。根淡赤色，似前胡而强。生丹州者结青子，与他处者不类。其根似芦头，有赤毛如鼠 \n尾，独窠长者好。 曰∶茈胡，出在平州平县，即今银州银县也。西畔生处，多有白鹤、绿 \n鹤于此飞翔，是茈胡香直上云间，若有过往闻者，皆气爽也。承曰∶柴胡以银、夏者最良， \n根如鼠尾，长一、二尺，香味甚佳。今《图经》所载，俗不识其真，市人以同、华者代之。 \n然亦胜于他处者，盖银、夏地方多沙，同、华亦沙苑所出也。机曰∶解散用北柴胡，虚热用 \n海阳软柴胡为良。时珍曰∶银州，即今延安府神木县，五原城是其废迹。所产柴胡长尺余而 \n微白且软，不易得也。北地所产者，亦如前胡而软，今人谓之北柴胡是也，入药亦良。南土 \n所产者，不似前胡，正如蒿根，强硬不堪使用。其苗有如韭叶者、竹叶者，以竹叶者为胜。 \n其如邪蒿者最下也。按∶《夏小正月令》云∶仲春芸始生。《仓颉解诂》云∶芸，蒿也。似 \n邪蒿，可食。亦柴胡之类，入药不甚良，故苏恭以为非柴胡云。近时有一种，根似桔梗、沙 \n参，白色而大，市人以伪充银柴胡，殊无气味，不可不辨。 \n\\x根\\x \n【修治】 曰∶凡采得银州柴胡，去须及头，用银刀削去赤薄皮少许，以粗布拭净 \n，锉用。勿令犯火，立便无效也。 \n【气味】苦，平，无毒。《别录》曰∶微寒。普曰∶神农、岐伯、雷公∶苦，无毒。大 \n明曰∶甘。元素曰∶气味俱轻，阳也，升也，少阳经药，引胃气上升。苦寒以发散表热。杲 \n曰∶升也，阴中之阳，手足少阳、厥阴四经引经药也。在脏主血，在经主气。欲上升，则用 \n根，以酒浸；欲中及下降，则用梢。之才曰∶半夏为之使，恶皂荚，畏女菀、藜芦。时珍曰∶ \n行手、足少阳，以黄芩为佐；行手、足厥阴，以黄连为佐。 \n【主治】心腹、去肠胃中结气，饮食积聚，寒热邪气，推陈致新。久服轻身明目益精（ \n《本经》）。除伤寒心下烦热，诸痰热结实，胸中邪逆，五脏间游气，大肠停积水胀，及湿 \n痹拘挛，亦可作浴汤（《别录》）。治热劳骨节烦疼，热气肩背疼痛，劳乏羸瘦，下气消食， \n宣畅气血，主时疾内外热不解，单煮服之良（甄权）。补五劳七伤，除烦止惊，益气力，消 \n痰止嗽，润心肺，添精髓，健忘（大明）。除虚劳，散肌热，去早晨潮热，寒热往来，胆瘅， \n妇人产前、产后诸热，心下痞，胸胁痛（元素）。治阳气下陷，平肝胆三焦包络相火，及头 \n痛眩运，目昏赤痛障翳，耳聋鸣，诸疟，及肥气寒热，妇人热入血室，经水不调，小儿痘疹 \n余热， \n【发明】之才曰∶茈胡，得茯苓、桔梗、大黄、石膏、麻子仁、甘草、桂。以水一斗， \n煮取四升入硝石三方寸匕，疗伤寒寒热头痛，心下烦满。 \n颂曰∶张仲景治伤寒，有大、小柴胡，及柴胡加龙骨、柴胡加芒硝等汤，故后人治寒热， \n此为最要之药。 \n杲曰∶能引清气而行阳道，伤寒外，诸有热则加之，无热则不加也。又能引胃气上行、 \n升腾而行春令者，宜加之。又凡诸疟，以柴胡为君，随所发时所在经分，佐以引经之药。十 \n二经疮疽中，须用柴胡以散诸经血结气聚，功与连翘同也。 \n好古曰∶柴胡能去脏腑内外俱乏，既能引清气上行而顺阳道，又入足少阳。在经主气， \n在脏主血。证前行则恶热，却退则恶寒。惟气之微寒，味之薄者，故能行经。若佐以三棱、 \n广术、巴豆之类，则能消坚积，是主血也。妇人经水适来适断，伤寒杂病，易老俱用小柴胡 \n汤，加以四物之类，并秦艽、牡丹皮辈，为调经之剂。又言妇人产后血热必用之药也。 \n宗 曰∶柴胡，《本经》并无一字治劳，今人治劳方中鲜有不用者。呜呼！凡此误世甚 \n多。尝原病劳，有一种其脏虚损，复受邪热，因虚而致劳，故曰劳者牢也，当须斟酌用之。 \n如《经验方》中治劳热青蒿煎之用柴胡，正合宜尔，服之无不效，热去即须急止。若或无热 \n，得此愈甚，虽至死，人亦不怨，目击甚多。《日华子》又谓补五劳七伤，《药性论》亦谓 \n治劳乏羸瘦。若此等病，苟无实热，医者执而用之，不死何待？注释本草，一字亦不可忽。 \n盖万世之后，所误无穷，可不谨哉？如张仲景治寒热往来如疟状，用柴胡汤，正合其宜也。 \n时珍曰∶劳有五劳，病在五脏。若劳在肝、胆、心，及包络有热，或少阳经寒热者，则 \n柴胡乃手足厥阴、少阳必用之药；劳在脾胃有热，或阳气下陷，则柴胡乃引清气、退热必用 \n之药；惟劳在肺、肾者，不用可尔。然东垣李氏言诸有热者，宜加之；无热，则不加。又言 \n诸经之疟，皆以柴胡为君。十二经疮疽，须用柴胡以散结聚。则是肺疟、肾疟，十二经之疮 \n，有热者皆可用之矣。但要用者精思病原，加减佐使可也。寇氏不分脏腑经络、有热无热， \n乃谓柴胡不治劳乏，一概摈斥，殊非通论。如《和剂局方》治上下诸血，龙脑鸡苏丸，用银 \n柴胡浸汁熬膏之法，则世人知此意者鲜矣。按∶庞元英《谈薮》云∶张知 久病疟，热时如 \n火，年余骨立。医用茸、附诸药，热益甚。召医官孙琳诊之。琳投小柴胡汤一帖，热减十之 \n九，三服脱然。琳曰∶此名劳疟，热从髓出，加以刚剂，气血愈亏，安得不瘦？盖热有在 \n皮肤、在脏腑、在骨髓，非柴胡不可。若得银柴胡，只须一服；南方者力减，故三服乃效也 \n。观此，则得用药之妙的矣。寇氏之说，可尽凭乎？ \n【附方】旧一，新五。 \n伤寒余热∶伤寒之后，邪入经络，体瘦肌热，推陈致新，解利伤寒时气伏暑，仓卒并治， \n不论长幼。柴胡四两，甘草一两。每用三钱，水一盏，煎服。（许学士《本事方》）小儿骨热∶ \n十五岁以下，遍身如火，日渐黄瘦，盗汗，咳嗽烦渴。柴胡四两，丹砂三两。为末， 猪胆 \n汁拌和，饭上蒸熟，丸绿豆大。每服一丸，桃仁、乌梅汤下，日三服。（《圣济总录》）虚劳 \n发热∶柴胡、人参等分。每服三钱，姜、枣同水煎服。（《澹寮方》）湿热黄胆∶柴胡一两， \n甘草二钱半。作一剂，以水一碗，白茅根一握，煎至七分，任意时时服，一日尽。（孙尚药 \n《秘宝方》） \n眼目昏暗∶柴胡六铢，决明子十八铢。治筛，人乳汁和敷目上，久久夜见五色。（《千 \n金方》） \n积热下痢∶柴胡、黄芩等分。半酒半水煎七分，浸冷，空心服之。（《济急方》） \n\\x苗\\x \n【主治】猝聋，捣汁频滴之（《千金》）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>前胡\n\n内容：（《别录》中品） \n【释名】时珍曰∶按∶孙 《唐韵》作湔胡，名义未解。 \n【集解】《别录》曰∶前胡，二月、八月采根，曝干。 \n弘景曰∶近道皆有，生下湿地，出吴兴者为胜。根似柴胡而柔软，为疗殆欲同，而《本 \n经》上品有茈胡而无此，晚来医乃用之。 \n大明曰∶越、衢、婺、睦等处者，皆好，七、八月采之，外黑里白。颂曰∶今陕西、梁 \n汉、江淮、荆襄州郡及相州、孟州皆有之。春生苗，青白色，似斜蒿。初出时有白芽，长三、 \n四寸，味甚香美，又似芸蒿。七月内开白花，与葱花相类。八月结实。根青紫色。今 延将 \n来者，大与柴胡相似。但柴胡赤色而脆，前胡黄而柔软，为不同尔。一说∶今诸方所用前胡 \n皆不同。汴京北地者，色黄白，枯脆，绝无气味。江东乃有三、四种∶一种类当归，皮斑黑， \n肌黄而脂润，气味浓烈；一种色理黄白，似人参而细短，香味都微；一种如草乌头，肤赤而 \n坚，有两、三歧为一本，食之亦戟人咽喉，中破以姜汁渍捣服之，甚下膈解痰实。然皆非真 \n前胡也。今最上者，出吴中。又寿春生者，皆类柴胡而大，气芳烈，味亦浓苦，疗痰下气， \n最胜诸道者。 曰∶凡使勿用野蒿根，缘真似前胡，只是味粗酸。若误用之，令人反胃不受 \n食。若是前胡，味甘微苦也。时珍曰∶前胡有数种，惟以苗高一、二尺，色似斜蒿，叶如野 \n菊而细瘦，嫩时可食。秋月开黪白花，类蛇床子花，其根皮黑肉白，有香气为真。大抵北地 \n者为胜，故方书称北前胡云。 \n\\x根\\x \n【修治】 曰∶修事，先用刀刮去苍黑皮并髭土了，细锉，以甜竹沥浸令润，日中 \n晒干用。 \n【气味】苦，微寒，无毒。权曰∶甘、辛，平。 \n之才曰∶半夏为之使，恶皂荚，畏藜芦。 \n【主治】痰满，胸胁中痞，心腹结气，风头痛，去痰实，下气，治伤寒寒热，推陈致新， \n明目益精（《别录》）。能去热实，及时气内外俱热，单煮服之。（甄权）治一切气，破症结 \n，开胃下食，通五脏，主霍乱转筋，骨节烦闷，反胃呕逆，气喘咳嗽，安胎，小儿一切疳气 \n（大明）。清肺热，化痰热，散风邪（时珍）。 \n【发明】时珍曰∶前胡味甘、辛，气微平，阳中之阴，降也。乃手足太阴、阳明之药， \n与柴胡纯阳上升入少阳、厥阴者不同也。其功长于下气，故能治痰热喘嗽、痞膈呕逆诸疾， \n气下则火降，痰亦降矣。所以有推陈致新之绩，为痰气要药。陶弘景言其与柴胡同功，非矣 \n。治证虽同，而所入所主则异。 \n【附方】旧一。 \n小儿夜啼∶前胡捣筛，蜜丸小豆大。日服一丸，熟水下，至五、六丸，以瘥为度。（《普 \n济方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>防风\n\n内容：（《本经》上品） \n【释名】铜芸（《本经》）、茴芸（《吴普》）、茴草（《别录》）、屏风（《别录》）、 根 \n（《别录》）、百枝（《别录》）、百蜚（《吴普》）。时珍曰∶防者，御也。其功疗风最要，故 \n名 \n【集解】《别录》曰∶防风，生沙苑川泽及邯郸、琅琊、上蔡。二月、十月采根，曝干。 \n普曰∶正月生叶细圆，青黑黄白。五月黄花。六月结实黑色。弘景曰∶郡县无名沙苑。 \n今第一出彭城兰陵，即近琅琊者。郁州百市亦有之。次出襄阳、义阳县界，亦可用。惟以实 \n而脂润，头节坚如蚯蚓头者为好。恭曰∶今出齐州龙山最善，淄州、兖州、青州者亦佳。叶 \n似牡蒿、附子苗等。沙苑在同州南，亦出防风，轻虚不如东道者。陶云无沙苑，误矣。 \n颂曰∶今汴东、淮、浙州郡皆有之。茎叶俱青绿色，茎深而叶淡，似青蒿而短小。春初 \n时嫩紫红色，江东宋毫人采作菜茹，极爽口。五月开细白花，中心攒聚作大房，似莳萝花。 \n实似胡荽子而大。根土黄色，与蜀葵根相类，二月、十月采之。关中生者，三月、六月采之， \n然轻虚不及齐州者良。又有石防风，出河中府，根如蒿根而黄，叶青花白，五月开花，六月 \n采根曝干，亦疗头风眩痛。时珍曰∶江淮所产多是石防风，生于山石之间。二月采嫩苗作菜， \n辛甘而香，呼为珊瑚菜。其根粗丑，其子亦可种。吴绶云∶凡使，以黄色而润者为佳，白者 \n多沙条，不堪。 \n【气味】甘，温，无毒。《别录》曰∶辛，无毒。叉头者，令人发狂；叉尾者，发人痼 \n疾。 \n普曰∶神农、黄帝、岐伯、桐君、雷公、扁鹊∶甘，无毒。李当之∶小寒。元素曰∶味 \n辛而甘，气温，气味俱薄，浮而升，阳也。手足太阳经之本药。好古曰∶又行足阳阴、太阴 \n二经，为肝经气分药。杲曰∶防风能制黄 ，黄 得防风其功愈大，乃相畏而相使者也。 \n之才曰∶得葱白，能行周身；得泽泻、蒿本，疗风；得当归、芍药、阳起石、禹余粮， \n疗妇人子脏 \n【主治】大风，头眩痛恶风，风邪目盲无所见，风行周身，骨节疼痹，烦满。久服轻身 \n（《本经》）。胁痛胁风，头面去来，四肢挛急，字乳金疮内痉（《别录》）。治三十六般风， \n男子一切劳劣，补中益神，风赤眼，止冷泪及瘫痪，通利五脏关脉，五劳七伤，羸损盗汗， \n心烦体重，能安神定志，匀气脉（大明）。治上焦风邪，泻肺实，散头目中滞气，经络中留 \n湿，主上部见血（元素）。搜肝气（好古）。 \n\\x叶\\x \n【主治】中风热汗出（《别录》）。颂曰∶江东一种防风，茹其嫩苗，云动风，与此文相 \n反，岂别是一物耶？ \n\\x花\\x \n【主治】四肢拘急，行履不得，经脉虚羸，骨节间痛，心腹痛（甄权）。 \n\\x子\\x \n【主治】疗风更优，调食之（苏恭）。 \n【发明】元素曰∶防风，治风通用。身半以上风邪用身，身半以下风邪，用梢，治风去 \n湿之仙药也，风能胜湿故尔。能泻肺实，误服泻人上焦元气。杲曰∶防风治一身尽痛，乃猝 \n伍卑贱之职，随所引而至，乃风药中润剂也。若补脾胃，非此引用不能行。凡脊痛项强，不 \n可回顾，腰似折，项似拔者，乃手足太阳证，正当用防风。凡疮在胸膈以上，虽无手足太阳 \n证，亦当用之，为能散结，去上部风。病患身体拘倦者，风也，诸疮见此证，亦须用之。钱 \n仲阳泻黄散中倍用防风者，乃于土中泻木也。 \n【附方】旧二，新十一。 \n自汗不止∶防风（去芦）为末，每服二钱，浮麦煎汤服。《朱氏集验方》∶防风用麸炒， \n猪皮煎汤下。睡中盗汗∶防风二两，芎 一两，人参半两。为末。每服三钱，临卧饮下。（《易 \n简方》） \n消风顺气∶老人大肠秘涩。防风、枳壳（麸炒）一两，甘草半两，为末，每食前白汤服 \n二钱。（《简便方》） \n偏正头风∶防风、白芷等分。为末，炼蜜丸弹子大。每嚼一丸，茶清下。（《普济方》） \n破伤中风，牙关紧急。天南星、防风等分。为末。每服二、三匙，童子小便五升，煎至四升， \n分二服，即止也。（《经验后方》） \n小儿解颅∶防风、白芨、柏子仁等分，为末。以乳汁调涂，一日一换。（《养生主论》） \n妇人崩中∶独圣散∶用防风（去芦头，炙赤）为末。每服一钱，以面糊酒调下，更以面 \n糊酒投之。此药累经效验。一方∶加炒黑蒲黄等分。（《经验后方》）解乌头毒∶附子、天雄 \n毒。并用防风煎汁饮之。（《千金方》） \n解芫花毒∶同上。 \n解野菌毒∶同上。解诸药毒∶已死，只要心间温暖者，乃是热物犯之。只用防风一味， \n擂冷水灌之。（万氏《积善堂》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>独活\n\n内容：（《本经》上品） \n【释名】羌活（《本经》）、羌青（《本经》）、独摇草（《别录》）、护羌使者（《本经》）、 \n胡王使者（《吴普》）、长生草。弘景曰∶一茎直上，不为风摇，故曰独活。《别录》曰∶此 \n草得风不摇，无风自动，故名独摇草。大明曰∶独活，是羌活母也。 \n时珍曰∶独活以羌中来者为良，故有羌活、胡王使者诸名，乃一物二种也。正如川芎、 \n抚芎，白术、苍术之义，入用 \n【集解】《别录》曰∶独活，生雍州川谷，或陇西南安。二月、八月采根，曝干。 \n弘景曰∶此州郡县并是羌地。羌活形细而多节软润，气息极猛烈。出益州、北都、西川 \n者为独活，色微白，形虚大，为用亦相似而小不如。至易蛀，宜密器藏之。颂曰∶独活、羌 \n活，今出蜀汉者佳。春生苗，叶如青麻。六月开花作丛，或黄或紫。结实时叶黄者，是夹石 \n上所生；叶青者，是土脉中所生。《本经》云二物同一类。今人以紫色而节密者，为羌活； \n黄色而作块者，为独活。而陶隐居言独活色微白，形虚大，用与羌活相似。今蜀中乃有大独 \n活，类桔梗而大，气味亦不与羌活相类，用之微寒而少效。今又有独活，亦自蜀中来，类羌 \n活，微黄而极大，收时寸解干之，气味亦芳烈，小类羌活，又有槐叶气者，今京下多用之， \n极效验，意此为真者。而市人或择羌活之大者为独活，殊未为当。大抵此物有两种∶西蜀者， \n黄色，香如蜜；陇西者，紫色，秦陇人呼为山前独活。古方但用独活，今方既用独活，而又 \n用羌活，兹为谬矣。机曰∶《本经》独活一名羌活，本非二物。后人见其形色气味不同，故 \n为异论。然物多不齐，一种之中自有不同。仲景治少阴所用独活，必紧实者；东垣治太阳所 \n用羌活，必轻虚者。正如黄芩，取枯飘者，名片芩，治太阴；条实者，名子芩，治阳明之义 \n同也。况古方但用独活无羌活，今方俱用，不知病宜两用耶？抑未之考耶？ \n时珍曰∶独活、羌活乃一类二种，以他地者，为独活；西羌者，为羌活，苏颂所说颇明。 \n按∶王贶《全生指迷方》云∶羌活，须用紫色有蚕头鞭节者。独活，是极大羌活有臼如鬼眼 \n者，寻常皆以老宿前胡为独活者，非矣。近时江淮山中出一种土当归，长近尺许，白肉黑皮， \n气亦芬香，如白芷气，人亦谓之水白芷，用充独活，解散亦或用之，不可不辨。 \n\\x根\\x \n【修治】 曰∶采得细锉，以淫羊藿拌，蒸二日，曝干，去藿用，免烦人心。 \n时珍曰∶此乃服食家治法，寻常去皮或焙用尔。 \n【气味】苦、甘，平，无毒。《别录》曰∶微温。权曰∶苦、辛。 \n元素曰∶独活微温，甘、苦、辛，气味俱薄，浮而升，阳也，足少阴行经气分之药。羌 \n活性温，辛苦，气味俱薄，浮而升，阳也，手足太阳行经风药，并入足厥阴、少阴经气分。 \n之才曰∶豚实为之使。弘景曰∶药无豚实，恐是蠡实也。 \n【主治】风寒所击，金疮止痛，奔豚痫痉，女子疝瘕。久服轻身耐老（《本经》）。疗诸 \n贼风，百节痛风，无问久新（《别录》）。独活∶治诸中风湿冷，奔喘逆气，皮肤苦痒，手足 \n挛痛劳损，风毒齿痛。羌活∶治贼风失音不语，多痒，手足不遂，口面 斜，遍身 痹、血 \n癞（甄权）。羌、独活∶治一切风并气，筋骨挛拳，骨节酸疼，头旋目赤疼痛，五劳七伤， \n利五脏及伏梁水气（大明）。治风寒湿痹，酸痛不仁，诸风掉眩，颈项难伸（李杲）。去肾间 \n风邪 \n【发明】恭曰∶疗风，宜用独活；兼水，宜用羌活。 \n刘完素曰∶独活不摇风而治风，浮萍不沉水而利水，因其所胜而为制也。张元素曰∶风 \n能胜湿，故羌活能治水湿。独活与细辛同用，治少阴头痛，头运目眩，非此不能除；羌活与 \n川芎同用，治太阳、少阴头痛，透关利节，治督脉为病，脊强而厥。好古曰∶羌活乃足太阳、 \n厥阴、少阴药，与独活不分二种。后人因羌活气雄，独活气细。故雄者，治足太阳风湿相搏， \n头痛、肢节痛、一身尽痛者，非此不能除，乃却乱反正之主君药也。细者，治足少阴伏风， \n头痛、两足湿痹、不能动止者，非此不能治，而不治太阳之证。时珍曰∶羌活、独活皆能逐 \n风胜湿，透关利节，但气有刚、劣不同尔。《素问》云∶从下上者，引而去之。二味苦辛而 \n温，味之薄者，阴中之阳，故能引气上升，通达周身，而散风胜湿。按文系曰∶唐刘师贞之 \n兄病风，梦神人曰∶但取胡王使者浸酒服，便愈。师贞访问，皆不晓。复梦其母曰∶胡王使 \n者，即羌活也。求而用之，兄疾遂愈。嘉谟曰∶羌活，本手足太阳表里引经之药，又入足少 \n阴、厥阴。名列君部之中，非比柔懦之主。小无不入，大无不通。故能散肌表八风之邪，利 \n周身百节之痛。 \n【附方】旧八，新七。 \n中风口噤，通身冷，不知人。独活四两。好酒一升，煎半升服。（《千金方》） \n中风不语∶独活一两。酒二升，煎一升，大豆五合，炒有声，以药酒热投，盖之良久， \n温服三合，未瘥再服。（陈延之《短剧方》）热风瘫痪，常举发者。羌活二斤，构子一升。为 \n末。每酒服方寸匕，日三服。（《广济方》）产后中风语涩，四肢拘急。羌活三两。为末。每 \n服五钱，酒、水各一盏，煎减半服。（《短剧方》） \n产后风虚∶独活、白藓皮各三两，水三升，煮二升，分三服。耐酒者，入酒同煮。（ \n《短剧方》）产后腹痛∶羌活二两，煎酒服。（《必效方》） \n产肠脱出∶方同上。（《子母秘录》） \n妊娠浮肿∶羌活、萝卜子同炒香，只取羌活为末。每服二钱，温酒调下，一日一服，二 \n日二服，三日三服。乃嘉兴主簿张昌明所传。（许学士《本事方》） \n风水浮肿∶方同上。历节风痛∶独活、羌活、松节等分。用酒煮过，每日空心饮一杯。 \n（《外台秘要》） \n风牙肿痛∶《肘后方》∶用独活煮酒，热漱之。文潞公《药准》∶用独活、地黄各三两， \n为末。每服三钱，水一盏煎，和滓温服，卧时再服。 \n喉闭口噤∶羌活三两，牛蒡子二两，水煎一钟，入白矾少许，灌之取效。（《圣济录》） \n睛垂至鼻∶人睛忽垂至鼻，如黑角色，痛不可忍，或时时大便血出，名曰肝胀。用羌活 \n煎汁，服数盏，自愈。（夏子益《奇疾方》） \n太阳头痛∶羌活、防 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>土当归\n\n内容：（《纲目》） \n【集解】生密县山野，茎圆而有线楞，叶似芹菜叶而硬，边有细锯齿刺。又似苍术叶而 \n大，每三叶攒生一处，开黄花，根似前胡，又似野胡萝卜根。 \n\\x根\\x \n【气味】辛，温，无毒。 \n【主治】除风和血，煎酒服之。闪拗手足，同荆芥、葱白煎汤淋洗之（时珍。出《卫生 \n易简方》）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>都管草\n\n内容：（宋《图经》） \n【集解】颂曰∶都管草生宜州田野，根似羌活头，岁长一节。苗高一尺许，叶似土当归 \n，有重台。二月、八月采根，阴干。施州生者作蔓，又名香球，蔓长丈余，赤色，秋结红实 \n，四时皆有，采其根枝，淋洗风毒疮肿。时珍曰∶按∶范成《大桂海志》云∶广西出之，一 \n茎六叶。 \n\\x根\\x \n【气味】苦、辛，寒，无毒。 \n【主治】风肿痈毒赤疣，以醋摩涂之。亦治咽喉肿痛，切片含之，立愈（苏颂）。解蜈 \n蚣、蛇毒（时珍）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>升麻\n\n内容：（《别录》上品） \n【释名】周麻。时珍曰∶其叶似麻，其性上升，故名。按∶张揖《广雅》及《吴普本草》 \n并云∶升麻，一名周升麻。则周或指周地，如今人呼川升麻之义。今《别录》作周麻， \n非省文，即脱误也。 \n【集解】《别录》曰∶升麻，生益州山谷。二月、八月采根，晒干。 \n弘景曰∶旧出宁州者第 \n之鸡骨升麻。北部亦有，而形虚大，黄色。建平亦有，而形大味薄，不堪用。人言是落新妇 \n根，不然也。其形相似，气色非也。落新妇亦解毒，取叶 作小儿浴汤，主惊忤。 \n藏器曰∶落新妇，今人多呼为小升麻，功用同于升麻，亦大小有殊也。 \n志曰∶升麻，今嵩高出者色青，功用不如蜀者。 \n颂曰∶今蜀汉、陕西、淮南州郡皆有之，以蜀川者为胜。春生苗，高三尺以来。叶似麻 \n叶，并青色。四月、五月着花，似粟穗，白色。六月以后结实，黑色。根如蒿根，紫黑色， \n多须。 \n\\x根\\x \n【修治】 曰∶采得刮去粗皮，用黄精自然汁浸一宿，曝干，锉蒸，再爆用。 \n时珍曰∶今人惟取里白外黑而紧实者，谓之鬼脸升麻，去须及头芦，锉用。 \n【气味】甘、苦，平、微寒，无毒。 \n元素曰∶性温，味辛微苦，气味俱薄，浮而升，阳也，为足阳明、太阴引经的药。得葱 \n白、白芷，亦入手阳明、太阴。杲曰∶引葱白，散手阳明风邪。引石膏，止阳明齿痛。人参 \n、黄 ，非此引之，不能上行。时珍曰∶升麻，同柴胡，引生发之气上行；同葛根，能发阳 \n明之汗。 \n【主治】解百毒，杀百精老物殃鬼，辟瘟疫瘴气邪气，蛊毒入口皆吐出，中恶腹痛，时 \n气毒疠，头痛寒热，风肿诸毒，喉痛口疮。久服不夭，轻身长年（《别录》）。安魂定魄，鬼 \n附啼泣，疳 ，游风肿毒（大明）。小儿惊痫，热壅不通，疗痈肿豌豆疮，水煎绵沾拭疮上 \n（甄权）。治阳明头痛，补脾胃，去皮肤风邪，解肌肉间风热，疗肺痿咳唾脓血，能发浮汗 \n（元素）。牙根浮烂恶臭，太阳鼽衄，为疮家圣药（好古）。消斑疹，行瘀血，治阳陷眩运， \n胸胁虚痛，久泄下痢，后重遗浊，带下崩中，血淋下血，阴痿足寒（时珍）。 \n【发明】元素曰∶补脾胃药，非此为引用不能取效。脾痹非此不能除。其用有四∶手足 \n阳明引经，一也；升阳气于至阴之下，二也；去至高之上及皮肤风邪，三也；治阳明头痛， \n四也。杲曰∶升麻，发散阳明风邪，升胃中清气，又引甘温之药上升，以补卫气之散而实其 \n表。故元气不足者，用此于阴中升阳，又缓带脉之缩急。有胃虚伤冷，郁遏阳气于脾土者， \n宜升麻、葛根以升散其火郁。好古曰∶升麻葛根汤，乃阳明发散药。若初病太阳证便服之， \n发动其汗，必传阳明，反成其害也。朱肱《活人书》言∶瘀血入里，吐血衄血者，犀角地黄 \n汤，乃阳明经圣药。如无犀角，以升麻代之。二物性味相远，何以代之？盖以升麻能引地黄 \n及余药同入阳明也。时珍曰∶升麻引阳明清气上行，柴胡引少阳清气上行。此乃禀赋素弱， \n元气虚馁，及劳役饥饱生冷内伤，脾胃引经最要药也。升麻葛根汤，乃发散阳明风寒药也。 \n时珍用治阳气郁遏，及元气下陷诸病，时行赤眼，每有殊效，神而明之，方可执泥乎？一人 \n素饮酒，因寒月哭母受冷，遂病寒中，食无姜、蒜，不能一啜。至夏酷暑，又多饮水，兼怀 \n怫郁。因病右腰一点胀痛，牵引右胁，上至胸口，则必欲卧。发则大便里急后重，频欲登圊， \n小便长而数，或吞酸，或吐水，或作泻，或阳痿，或厥逆，或得酒少止，或得热稍止。但受 \n寒食寒，或劳役，或入房，或怒或饥，即时举发。一止则诸证泯然，如无病患，甚则日发数 \n次。服温脾胜湿、滋补消导诸药，皆微止随发。时珍思之，此乃饥饱劳逸，内伤元气，清阳 \n陷遏，不能上升所致也。遂用升麻葛根汤合四君子汤，加柴胡、苍术、黄 ，煎服，服后仍 \n饮酒一二杯助之。其药入腹，则觉清气上行，胸膈爽快，手足和暖，头目精明，神采迅发， \n诸证如扫。每发一服即止，神验无比。若减升麻、葛根，或不饮酒，则效便迟。大抵人年五 \n十以后，其气消者多，长者少；降者多，升者少；秋冬之令多，而春夏之令少。若禀受弱而 \n有前诸证者，并宜此药活法治之。《素问》云∶阴精所奉其人寿，阳精所降其人夭。千古之 \n下，窥其奥而阐其微者，张洁古、李东垣二人而已。外此，则着《参同契》、《悟真篇》者， \n旨与此同也。又升麻能解痘毒，惟初发热时，可用解毒；痘已出后，气弱或泄泻者，亦可少 \n用；其升麻葛根汤，则见斑后必不可用，为其解散也。本草以升麻为解毒、吐蛊毒要药，盖 \n以其为阳明本经药，而性又上升故也。按《范石湖文集》云∶李焘为雷州推官，鞫狱得治蛊 \n方∶毒在上，用升麻吐之；在腹，用郁金下之，或合二物服之，不吐则下。此方活人甚多也。 \n【附方】旧五，新八。 \n服食丹砂∶石泉公王方庆《岭南方》云∶南方养生治病，无过丹砂。其方用升麻末三两 \n（ \n豌豆斑疮∶比岁有病天行发斑疮，头面及身，须臾周匝，状如火烧疮，皆戴白浆，随决 \n随生，不治数日必死，瘥后瘢黯，弥岁方减，此恶毒之气所为。云晋元帝时，此病自西北流 \n起，名虏疮。以蜜煎升麻，时时食之。并以水煮升麻，绵沾拭洗之。（葛洪《肘后方》）辟瘴 \n明目∶七物升麻丸∶升麻、犀角、黄芩、朴硝、栀子、大黄各二两，豉二升（微熬）。同捣 \n末，蜜丸梧子大。觉四肢大热，大便难，即服三十丸，取微利为度。若四肢小热，只食后服 \n二十丸。非但辟瘴，甚能明目。（王方庆《岭南方》）猝肿毒起∶升麻磨醋，频涂之。（《肘后》） \n喉痹作痛∶升麻片，含咽。或以半两，煎服取吐。（《直指方》）胃热齿痛∶升麻煎汤， \n热漱咽之，解毒。或加生地黄。（《直指方》）口舌生疮∶升麻一两，黄连三分。为末，绵裹 \n含咽。（《本事方》）热痱瘙痒∶升麻，煎汤饮，并洗之。（《千金方》）小儿尿血∶蜀升麻五分。 \n水五合，煎一合，服之。一岁儿，一日一服。（姚和众《至宝方》）产后恶血不尽，或经月半 \n年。以升麻三两，清酒五升，煮取二升，分半再服。当吐下恶物，极良。（《千金翼方》） \n解莨菪毒∶升麻煮汁，多服之。（《外台秘要》）挑生蛊毒∶野葛毒。并以升麻多煎，频 \n饮之。（《直指方》）射工溪毒∶升麻、乌 。煎水服，以滓涂之。（《肘后方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>苦参\n\n内容：（《本经》中品） \n【释名】苦 （《本经》）、苦骨（《纲目》）、地槐（《别录》）、水槐（《本经》）、菟槐 \n（《别录》）、骄槐（《别录》）、野槐（《纲目》）、白茎（《别录》，又名芩茎、禄白、陵郎、 \n虎 \n【集解】《别录》曰∶苦参，生汝南山谷及田野。三月、八月、十月采根，曝干。"}, {"n": 13, "text": "卷十三\n\n弘景曰∶近道处处有之。叶极似槐叶，花黄色，子作荚，根味至苦恶。颂曰∶其根黄色， \n长五、七寸许，两指粗细。三、五茎并生，苗高三、四尺以来，叶碎青色，极似槐叶，春生 \n冬凋，其花黄白色，七月结实如小豆子。河北生者无花子。五月、六月、八月、十月采根， \n曝干。 \n时珍曰∶七、八月结角如萝卜子，角内有子二、三粒，如小豆而坚。 \n\\x根\\x \n【修治】 曰∶采根，用糯米浓泔汁浸一宿，其腥秽气并浮在水面上，须重重淘过，即 \n蒸之，从巳至申，取晒切用。 \n【气味】苦，寒，无毒。之才曰∶玄参为之使，恶贝母、菟丝、漏芦，反藜芦。时珍曰∶ \n伏汞，制雌黄、焰硝。 \n【主治】心腹结气，症瘕积聚，黄胆，溺 \n本经》）。养肝胆气，安五脏，平胃气，令人嗜食轻身，定志益精，利九窍，除伏热肠 ， \n止渴醒酒，小便黄赤，疗恶疮、下部蚀（《别录》）。渍酒饮，治疥杀虫（弘景）。治恶虫、胫 \n酸（苏恭）。治热毒风，皮肌烦躁生疮，赤癞眉脱，除大热嗜睡，治腹中冷痛，中恶腹痛（甄 \n权）。杀疳虫。炒存性，米饮服，治肠风泻血并热痢（《大明》）。 \n【发明】元素曰∶苦参，味苦，气沉，纯阴，足少阴肾经君药也。治本经须用，能逐湿。 \n颂曰∶古今方用治风热疮疹最多。 \n宗 曰∶沈存中《笔谈》，载其苦腰重，久坐不能行。有一将佐曰∶此乃病齿数年， \n用苦参揩齿，其气味入齿伤肾所致也。后有太常少卿舒昭亮，亦用苦参揩齿，岁久亦病腰。 \n自后悉不用之，腰疾皆愈。此皆方书不载者。震亨曰∶苦参能峻补阴气，或得之而致腰重者 \n，因其气降而不升也，非伤肾之谓也。其治大风有功，况风热细疹乎？时珍曰∶子午乃少阴 \n君火对化，故苦参、黄柏之苦寒，皆能补肾。盖取其苦燥湿、寒除热也。热生风，湿生虫， \n故又能治风杀虫。惟肾水弱而相火胜者，用之相宜。若火衰精冷，真元不足，及年高之人， \n不可用也。《素问》云∶五味入胃，各归其所喜攻，久而增气，物化之常也。气增而久，夭 \n之由也。王冰注云∶入肝为温，入心为热，入肺为清，入肾为寒，入脾为至阴而兼四气，皆 \n为增其味而益其气，各从本脏之气。故久服黄连、苦参而反热者，此其类也。气增不已，则 \n脏气有偏胜，偏胜则脏有偏绝，故有暴夭。是以药不具五味，不备四气，而久服之，虽且获 \n胜，久必暴夭。但人疏忽，不能精候尔。张从正亦云∶凡药皆毒也。虽甘草、苦参，不可不 \n谓之毒。久服则五味各归其脏，必有偏胜气增之患。诸药皆然，学人当触类而长之可也。至 \n于饮食亦然。又按∶《史记》云∶太仓公淳于意医齐大夫病龋齿，灸左手阳明脉，以苦参汤 \n日漱三升，出入五六日，其风愈。此亦取其去风气湿热、杀虫之义。 \n【附方】旧十，新一十八。热病狂邪，不避水火，欲杀人。苦参末，蜜丸梧子大。每服 \n十丸，薄荷汤下。亦可为末，二钱，水煎服。（《千金方》）伤寒结胸∶天行病四、五日，结 \n胸满痛壮热。苦参一两，以醋三升，煮取一升二合，饮之取吐，即愈。天行毒病，非苦参、 \n醋药不解，及温覆取汗良。（《外台秘要》） \n谷疸食劳∶食毕头旋，心怫郁不安而发黄。由失饥大食，胃气冲熏所致。苦参三两，龙 \n胆 \n小儿身热∶苦参，煎汤，浴之良。（《外台秘要》）毒热足肿作痛欲脱者。苦参，煮酒渍 \n之。（姚僧坦《集验方》） \n梦遗食减∶白色苦参三两，白术五两，牡蛎粉四两。为末。用雄猪肚一具，冼净，砂罐 \n煮烂，石臼捣和药，干则入汁，丸小豆大。每服四十丸，米汤下，日三服。久服身肥食进， \n而梦遗立止。（刘松石《保寿堂方》）小腹热痛，青黑或赤色，不能喘者。苦参一两，醋一升 \n半，煎八合，分二服。（张杰《子 \n中恶心痛∶苦参三两。苦酒一升半，煮取八合，分二服。（《肘后方》）饮食中毒，鱼肉 \n菜等毒。上方煎服，取吐即愈。（《梅师方》） \n血痢不止∶苦参炒焦为末，水丸梧子大。每服十五丸，米饮下。（孙氏《仁存堂方》） \n大肠脱肛∶苦参、五倍子、陈壁土等分。煎汤洗之，以木贼末敷之。（《医方摘要》） \n妊娠尿难∶方见贝母下。产后露风，四肢苦烦热、头痛者，与小柴胡；头不痛者，用苦 \n参二两，黄芩一两，生地黄 \n齿缝出血∶苦参一两，枯矾一钱。为末，日三揩之，立验。（《普济方》） \n龋齿风痛∶方见发明下。鼻疮脓臭，有虫也。苦参、枯矾一两，生地黄汁三合。水二盏， \n煎三合，少少滴之。（《普济方》）肺热生疮，遍身皆是。用苦参末，粟米饮，丸梧子大。每 \n服五十丸。空心米饮下。（《御 \n遍身风疹∶痒痛不可忍，胸颈脐腹及近隐皆然者，亦多涎痰，夜不得睡。用苦参末一两， \n皂角二两。水一升，揉滤取汁。银石器熬成膏，和末丸梧子大。每服三十丸，食后温水服， \n次日便愈。（寇宗 《衍义》） \n大风癞疾∶颂曰∶用苦参五两（切）。以好酒三斗渍三十日。每饮一合，日三服，常服 \n不绝。若觉痹，即瘥。张子和《儒门事亲》∶用苦参末二两，以猪肚盛之，缝合煮熟，取出 \n去药。先饿一日，次早先饮新水一盏，将猪肚食之，如吐再食。待一、二时，以肉汤调无忧 \n散五、七钱服，取出大、小虫一、二万为效。后以不蛀皂角一斤，去皮子，煮汁，入苦参末 \n调糊。下何首乌末二两，防风末一两半，当归末一两，芍药末五钱，人参末三钱，丸梧子大。 \n每服三、五十丸，温酒或茶下，日三服。仍用麻黄、苦参、荆芥煎水洗之。《圣济总录》苦 \n参丸∶治大风癞及热毒风疮疥癣。苦参（九月末掘取，去皮曝干，取粉）一斤，枳壳（麸炒） \n六两。为末，蜜丸。每温酒下三十丸，日二夜一服。一方∶去枳壳。肾脏风毒及心肺积热， \n皮肤生疥癞，瘙痒时出黄水，及大风手足坏烂，一切风疾。苦参三十二两，荆芥穗一十六两。 \n为末，水糊丸梧子大。每服三十丸，茶下。（《和剂局方》）上下诸 ，或在项，或在下部。 \n用苦参五升。苦酒一斗，渍三、四日服之，以知为度。（《肘后方》）鼠 恶疮∶苦参二斤， \n露蜂房二两，曲二斤。水三斗，渍二宿，去滓，入黍米二升，酿熟，稍饮，日三次。（《肘 \n后方》） \n下部漏疮∶苦参煎汤，日日洗之。（《直指方》）瘰 结核∶苦参四两捣末。牛膝汁丸绿 \n豆大。每暖水下二十丸。（张文仲《备急方》） \n汤火伤灼∶苦参末，油调敷之。（《卫生宝鉴》） \n赤白带下∶苦参二两，牡蛎粉一两五钱。为末。以雄猪肚一个，水三碗煮烂，捣泥和丸 \n梧子大。每服百丸，温酒下。（陆氏《积德堂方》）实（十月收采） \n【气味】同根。 \n【主治】久服轻身不老，明目。饵如槐子法，有验（苏恭）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>白藓\n\n内容：（音仙。《本经》中品） \n【释名】白膻（弘景）、白羊藓（弘景）、地羊藓（《图经》）、金雀儿椒（《日华》）。 \n弘景曰∶俗呼为白羊藓。气息正似羊膻，故又名白膻。 \n时珍曰∶藓者，羊之气也。此草根白色，作羊膻气，共子累累如椒，故有诸名。 \n【集解】《别录》曰∶白藓皮，生上谷川谷及冤句。四月、五月采根，阴干。 \n弘景曰∶近道处处有，以蜀中者为良。 \n恭曰∶其叶似茱萸，苗高尺余，根皮白而心实，花紫白色。根宜二月采，若四月、五月 \n采，便虚恶矣。 \n颂曰∶今河中、江宁府、滁州、润州皆有之。苗高尺余，茎青，叶稍白，如槐亦似茱萸 \n。四月开花淡紫色，似小蜀葵花。根似小蔓菁，皮黄白而心实。山人采嫩苗为菜茹。 \n\\x根皮\\x \n【气味】苦，寒，无毒。《别录》曰∶咸。之才曰∶恶螵蛸、桔梗、茯苓、萆 \n【主治】头风黄胆，咳逆淋沥，女子阴中肿痛，湿痹死肌，不可屈伸起止行步（《本经 \n》）。疗四肢不安，时行腹中大热饮水，欲走大呼，小儿惊痫，妇人产后余痛（《别录》 \n）。治一切热毒风、恶风，风疮疥癣赤烂，眉发脱脆，皮肌急，壮热恶寒，解热黄、酒黄、 \n急黄、谷黄、劳黄（甄权）。通关节，利九窍及血脉，通小肠水气，天行时疾，头痛、眼 \n疼。其花同功（大明）。治肺嗽（苏颂）。 \n【发明】时珍曰∶白藓皮气寒善行，味苦性燥，足太阴、阳明经去湿热药也，兼入手太 \n阴、阳明，为诸黄风痹要药。世医只施之疮科，浅矣。 \n【附方】旧一，新一。 \n鼠 已破，出脓血者。白藓皮煮汁，服一升，当吐若鼠子也。（《肘后方》）产后中风， \n人虚不可服他药者。一物白藓皮汤，用新汲水三升，煮取一升，温服。（陈延之《短剧方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>延胡索\n\n内容：（宋《开宝》） \n【释名】玄胡索。好古曰∶本名玄胡索，避宋真宗讳，改玄为延也。 \n【集解】藏器曰∶延胡索生于奚，从安东道来，根如半夏，色黄。时珍曰∶奚乃东北夷 \n也。今二茅山西上龙洞种之。每年寒露后栽，立春后生苗，叶如竹叶样，三月长三寸高，根 \n丛生如芋卵样，立夏掘起。 \n\\x根\\x \n【气味】辛，温，无毒。 曰∶苦，甘。杲曰∶甘、辛，温，可升可降，阴中阳也。 \n好古曰∶苦、辛，温，纯阳，浮也，入手、足太阴经。 \n【主治】破血，妇人月经不调，腹中结块，崩中淋露，产后诸血病，血运，暴血冲上， \n因损下血。煮酒或酒磨服（《开宝》）。除风治气，暖腰膝，止暴腰痛，破症癖，扑损瘀血， \n落胎（大明）。治心气小腹痛，有神（好古）。散气，治肾气，通经络（李 ）。活血利气， \n止痛，通小便（时珍）。 \n【发明】 曰∶主肾气，及破产后恶露或儿枕。与三棱、鳖甲、大黄为散，甚良，虫蛀 \n成末者，尤良。 \n时珍曰∶玄胡索，味苦微辛，气温，入手、足太阴、厥阴四经，能行血中气滞，气中血 \n滞，故专治一身上下诸痛，用之中的，妙不可言。荆穆王妃胡氏，因食荞麦面着怒，遂病胃 \n脘当心痛，不可忍。医用吐下行气化滞诸药，皆入口即吐，不能奏功。大便三日不通。因思 \n《雷公炮炙论》云∶心痛欲死，速觅延胡。乃以玄胡索末三钱，温酒调下，即纳入，少顷大 \n便行而痛遂止。又华老年五十余，病下痢腹痛垂死，已备棺木。予用此药三钱，米饮服之， \n痛即减十之五，调理而安。按∶《方勺泊宅编》云∶一人病遍体作痛，殆不可忍。都下医或 \n云中风，或去中湿，或云香港脚，药悉不效。周离亨言∶是气血凝滞所致。用玄胡索、当归、 \n桂心等分，为末，温酒服三四钱，随量频进，以止为度，遂痛止。盖玄胡索能活血化气， \n第一品药也。其后赵待制霆因导引失节，肢体拘挛，亦用此数服而愈。 \n【附方】旧三，新一十二。 \n老小咳嗽∶玄胡索一两，枯矾二钱半。为末。每服二钱，软饧一块和，含之。（《仁存 \n堂方》）鼻出衄血∶玄胡索末，绵裹塞耳内，左衄塞右，右衄塞左。（《普济方》）小便尿血∶ \n玄胡索一两，朴硝七钱半，为末。每服四钱，水煎服。（《活人书》）小便不通∶捻头散∶治 \n小儿小便不通。用玄胡索、川苦楝子等分，为末。每服半钱或一钱，白汤滴油数点调下。（钱 \n仲阳《小儿直诀》）膜外气疼及气块。玄胡索不限多少。为末。猪胰一具，切作块子，炙熟 \n蘸末，频食之。（《胜金方》）热厥心痛，或发或止，久不愈，身热足寒者。用玄胡索（去皮）、 \n金铃子肉等分，为末，每温酒或白汤下二钱。（《圣惠方》） \n下痢腹痛∶方见发明下。妇女血气，腹中刺痛，经候不调。用玄胡索（去皮，醋炒）、 \n当归（酒浸炒）各一两，橘红二两。为末，酒煮米糊丸梧子大。每服一百丸，空心艾醋汤下。 \n（《济生方》）产后诸病∶凡产后，秽污不尽，腹满，及产后血运，心头硬，或寒热不禁，或 \n心闷、手足烦热、气力欲绝诸病。并用玄胡索炒研，酒服一钱，甚效。（《圣惠方》）小儿盘 \n肠气痛。玄胡索、茴香等分，炒研，空心米饮量儿大小与服。（《卫生易简方》）疝气危急∶ \n玄胡索（盐炒）、全蝎（去毒生用）等分。为末。每服半钱，空心盐酒下。（《直指方》）冷气 \n腰痛∶玄胡索、当归、桂心三味，方见发明下。肢体拘痛∶方同上。偏正头痛，不可忍者。 \n玄胡索七枚，青黛二钱，牙皂二个（去皮子）。为末，水和丸如杏仁大。每以水化一丸，灌 \n入病患鼻内，随左右，口咬铜钱一个，当有涎出成盆而愈。（《永类方》）坠落车马，筋骨痛 \n不止。玄胡索末。豆淋酒服二钱，日二服。（《圣惠方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>贝母\n\n内容：（《本经》中品） \n【释名】 （《尔雅》，音萌）、勤母（《别录》）、苦菜（《别录》）、苦花（《别录》）、 \n空草（《本经》）、药实。弘景曰∶形似聚贝子，故名贝母。时珍曰∶《诗》云言采其 ，即 \n此。一作虻，谓根状如虻也。苦菜、药实，与野苦 、黄药子同名。 \n【集解】《别录》曰∶贝母，生晋地，十月采根，曝干。恭曰∶其叶似大蒜。四月蒜熟 \n时采之，良。若十月，苗枯，根亦不佳也。出润州、荆州、襄州者，最佳；江南诸州亦有。 \n颂曰∶今河中、江陵府、郢、寿、随、郑、蔡、润、滁州皆有之。二月生苗，茎细，青 \n色。叶亦青，似荞麦叶，随苗出。七月开花，碧绿色，形如鼓子花。八月采根，根有瓣子， \n黄白色，如聚贝子。此有数种。陆玑《诗疏》云∶ ，贝母也。叶如栝蒌而细小。其子在根 \n下，如芋子，正白，四方连累相着，有分解。今近道出者正类此。郭璞注《尔雅》言∶白花 \n叶似韭，此种罕复见之。 曰∶贝母中有独颗团不作两片无皱者，号曰丹龙精，不入药用。 \n误服 \n\\x根\\x \n【修治】 曰∶凡使，先于柳木灰中炮黄，擘破，去内口鼻中有米许大者心一颗， \n后拌糯米于 上同炒，待米黄，去米用。 \n【气味】辛，平，无毒。《别录》曰∶苦，微寒。恭曰∶味甘、苦，不辛。之才曰∶浓 \n朴、白薇为之使，恶桃花，畏秦艽、莽草、 石，反乌头。 \n【主治】伤寒烦热，淋沥邪气，疝瘕，喉痹乳难，金疮风痉（《本经》）。疗腹中结实， \n心下满，洗洗恶风寒，目眩项直，咳嗽上气，止烦热渴，出汗，安五脏，利骨髓（《别录》） \n。服之不饥断谷（弘景）。消痰，润心肺。末和沙糖丸含，止嗽。烧灰油调，敷人畜恶疮， \n敛疮口（大明）。主胸胁逆气，时疾黄胆。研末点目，去肤翳。以七枚作末酒服，治产难及 \n胞 \n【发明】承曰∶贝母能散心胸郁结之气，故《诗》云言∶采其 ，是也。作诗者，本以 \n不得志而言。今用治心中气不快、多愁郁者，殊有功。信矣。好古曰∶贝母乃肺经气分药也。 \n仲景治寒实结胸、外无热证者，三物小陷胸汤主之，白散亦可，以其内有贝母也。成无己云∶ \n辛散而苦泄，桔梗、贝母之苦辛，用以下气。机曰∶俗以半夏有毒，用贝母代之。夫贝母乃 \n太阴肺经之药，半夏乃太阴脾经、阳明胃经之药，何可以代？若虚劳咳嗽、吐血咯血、肺痿 \n肺痈、妇人乳痈、痈疽及诸郁之证，半夏乃禁忌，皆贝母为向导，犹可代也；至于脾胃湿热， \n涎化为痰，久则生火，痰火上攻，昏愦僵仆蹇涩诸证，生死旦夕，亦岂贝母可代乎？颂曰∶ \n贝母治恶疮。唐人记其事云∶江左尝有商人，左膊上有疮如人面，亦无他苦。商人戏以酒滴 \n口中，其面赤色。以物食之，亦能食，多则膊内肉胀起。或不食，则一臂痹焉。有名医教其 \n历试诸药，金石草木之类，悉无所苦，至贝母，其疮乃聚眉闭口。商人喜，因以小苇筒毁其 \n口灌之，数日成痂遂愈，然不知何疾也。《本经》言主金疮，此岂金疮之类欤？ \n【附方】新二十一。 \n忧郁不伸，胸膈不宽。贝母去心，姜汁炒研，姜汁面糊丸。每服七十丸，征士锁甲煎汤 \n下。（《集效方》）化痰降气，止咳解郁，消食除胀，有奇效。用贝母（去心）一两，姜制浓 \n朴半两。蜜丸梧子大。每白汤下五十丸。（《笔峰方》）小儿 嗽，百日内咳嗽痰壅。贝母五 \n钱，甘草（半生半炙）二钱。为末，沙糖丸芡子大，每 \n孕妇咳嗽∶贝母去心，麸炒黄为末，沙糖拌丸芡子大。每含咽一丸，神效。（《救急易 \n方》）妊娠尿难，饮食如故。用贝母、苦参、当归各四两。为末，蜜丸小豆大，每饮服三丸 \n至十丸。（《金匮要略》）乳汁不下∶二母散∶贝母、知母、牡蛎粉等分。为细末。每猪蹄汤 \n调服二钱，此祖传方也。（王海藏《汤液本草》）冷泪目昏∶贝母一枚，胡椒七粒。为末点之。 \n（《儒门事亲》方）目生弩肉∶《肘后》∶用贝母、真丹等分为末，日点。《摘玄方》∶用贝母、 \n丁香等分，为末。乳汁调点。吐血不止∶贝母炮研，温浆水服二钱。（《圣惠方》） \n衄血不止∶贝母（炮）研末，浆水服二钱，良久再服。（《普济方》）小儿鹅口，满口白 \n烂。贝母（去心为末）半钱，水五分，蜜少许，煎三沸，缴净抹之，日四五度。（《圣惠方》） \n吹奶作痛∶贝母末，吹鼻中，大效。（危氏《得效方》） \n乳痈初肿∶贝母末，酒服二钱，仍令人吮之，即通。（《仁斋直指方》） \n便痈肿痛∶贝母、白芷等分为末，酒调服或酒煎服，以滓贴之。（《永类钤方》） \n紫白癜斑∶贝母、南星等分为末生姜带汁擦之。《德生堂方》∶用贝母、干姜等分，为末， \n如澡豆，入密室中浴擦，得汗为妙。《谈野翁方》∶以生姜擦动，醋磨贝母涂之。《圣惠方 \n》∶用贝母、百部等分为末，自然姜汁调搽。蜘蛛咬毒∶缚定咬处，勿使毒行。以贝母末酒 \n服半两，至醉。良久酒化为水，自疮口出，水尽，仍塞疮口，甚妙。（《仁斋直指方》） \n蛇蝎咬伤∶方同上。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>山慈菇\n\n内容：（宋《嘉 》） \n【释名】金灯（《拾遗》）、鬼灯檠（《纲目》）、朱姑（《纲目》）、鹿蹄草（《纲目》）、 \n无义草。时珍曰∶根状如水慈菇，花状如灯笼而朱色，故有诸名。段成式《酉阳杂俎》云∶ \n金灯之花与叶不相见，人恶种之，谓之无义草。又有试剑草，亦名鹿蹄草，与此同名，见后 \n草之五。 \n【集解】藏器曰∶山慈菇生山中湿地，叶似车前，根如慈菇。大明曰∶零陵间有一种团 \n慈菇，根如小蒜，所主略同。时珍曰∶山慈菇处处有之。冬月生叶，如水仙花之叶而狭。二 \n月中抽一茎，如箭杆，高尺许。茎端开花白色，亦有红色、黄色者，上有黑点，其花乃众花 \n簇成一朵，如丝纽成可爱。三月结子，有三棱。四月初苗枯，即掘取其根，状如慈菇及小蒜， \n迟则苗腐难寻矣。根苗与老鸦蒜极相类，但老鸦根无毛，慈菇有毛壳包裹为异尔。用之，去 \n毛壳。 \n\\x根\\x \n【气味】甘、微辛，有小毒。 \n【主治】痈肿疮 、瘰 结核等，醋磨敷之。亦剥人面皮，除 （藏器）。主疔肿， \n攻毒破皮，解诸毒蛊毒，蛇虫狂犬伤（时珍）。 \n【附方】新五。粉 \n牙龈肿痛∶红灯笼枝根，煎汤漱吐。（孙天仁《集效方》）痈疽疔肿，恶疮及黄胆。慈菇 \n连根同苍耳草等分，捣烂，以好酒一钟，滤汁温服。或干之为末，每酒服三钱。（《乾坤生 \n意》） \n风痰痫疾∶金灯花根（似蒜者）一个，以茶清研如泥，日中时以茶调下，即卧日中，良 \n久，吐出鸡子大物，永不发。如不吐，以热茶投之。（《奇效良方》） \n万病解毒丸∶一名太乙紫金丹，一名玉枢丹。解诸毒，疗诸疮，利关节，治百病，起死 \n回生，不可尽述。凡居家远出，行兵动众，不可无此。山慈菇（去皮洗极净，焙）二两，川 \n五倍子（洗刮，焙）二两，千金子仁（白者，研，纸压去油）一两，红芽大戟（去芦洗，焙） \n一两半，麝香三钱。以端午七夕重阳或天德、月德、黄道上吉日，预先斋戒盛服，精心治药， \n为末，陈设拜祷，乃重罗令匀，用糯米浓饮和之，木臼杵千下，作一钱一锭。病甚者连服； \n取利一二行，用温粥补之。凡一切饮食药毒，蛊毒瘴气，河豚、土菌、死牛马等毒，并用凉 \n水磨服一锭，或吐或利即愈。痈疽发背，疔肿杨梅等，一切恶疮，风疹赤游，痔疮，并用凉 \n水或酒磨涂，日数次，立消。阴阳二毒伤寒，狂乱瘟疫，喉痹喉风，并用冷水入薄荷汁数匙 \n化下。心气痛并诸气，用淡酒化下。泄泻痢下，霍乱绞肠沙，用薄荷汤下。中风中气，口紧 \n眼歪，五癫五痫，鬼邪鬼胎，筋挛骨痛，并暖酒下。自缢、溺水、鬼迷，心头温者，冷水磨 \n灌之。传尸痨瘵，凉水化服，取下恶物虫积为妙。久近疟疾，将发时，东流水煎桃枝汤化服。 \n女人经闭，红花酒化服。小儿惊风，五疳五痢，薄荷汤下。头风头痛，酒研贴两太阳上。诸 \n腹鼓胀，麦芽汤化下。风虫牙痛，酒磨涂之，亦吞少许。打扑伤损，松节煎酒下；汤火伤， \n毒蛇恶犬，一切虫伤，并冷水磨涂，仍服之。（王 《百一选方》） \n\\x叶\\x \n【主治】疮肿，入蜜捣涂疮口，候清血出，效（慎微）。涂乳痈、便毒，尤妙（时珍）。 \n【附方】新一。中溪毒生疮∶朱菇叶捣烂涂之。生东间，叶如蒜叶。（《外台秘要》） \n\\x花\\x \n【主治】小便血淋涩痛，同地柏花阴干，每用三钱，水煎服（《圣惠》）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>石蒜\n\n内容：（宋《图经》） \n【释名】乌蒜（《纲目》）、老鸦蒜（《救荒》）、蒜头草（《纲目》）、婆婆酸（《纲目》）、 \n一 \n【集解】颂曰∶水麻生鼎州、黔州，其根名石蒜，九月采之。或云金灯花根，亦名石蒜， \n即此类也。时珍曰∶石蒜，处处下湿地有之，古谓之乌蒜，俗谓之老鸦蒜、一枝箭是也。春 \n初生叶，如蒜秧及山慈菇叶，背有剑脊，四散布地。七月苗枯，乃于平地抽出一茎如箭杆， \n长尺许。茎端开花四、五朵，六出红色，如山丹花状而瓣长，黄蕊长须。其根状如蒜，皮色 \n紫赤，肉白色。此有小毒，而《救荒本草》言其可炸熟水浸过食，盖为救荒尔。一种叶如大 \n韭，四、五月抽茎，开花如小萱花黄白色者，谓之铁色箭，功与此同。二物并抽茎开花，后 \n乃生叶，叶、花不相见，与金灯同。 \n\\x根\\x \n【气味】辛、甘，温，有小毒。 \n【主治】敷贴肿毒（苏颂）。疔疮恶核，可水煎服取汗，及捣敷之。又中溪毒者，酒煎 \n半升服，取吐良（时珍）。 \n【附方】新三。 \n便毒诸疮∶一枝箭，捣烂涂之即消。若毒太甚者，冼净，以生白酒煎服，得微汗即愈。 \n（王永辅《济世方》）产肠脱下∶老鸦蒜（即酸头草）一把。以水三碗，煎一碗半，去滓熏 \n洗，神效。（危氏《得效方》）小儿惊风∶大叫一声就死者，名老鸦惊。以散麻缠住胁下及手 \n心足心，以灯火爆之。用老鸦蒜（晒干）、车前子等分，为末，水调贴手足心。仍以灯心淬 \n手足心，及肩膊、眉心、鼻 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>水仙\n\n内容：（《会编》） \n【释名】金盏银台。时珍曰∶此物宜卑湿处，不可缺水，故名水仙。金盏银台，花之状 \n也。 \n【集解】机曰∶水仙花叶似蒜，其花香甚清。九月初栽于肥壤，则花茂盛，瘦地则无花。 \n五月初收根，以童尿浸一宿，晒干，悬火暖处。若不移宿根更旺。时珍曰∶水仙丛生下湿处。 \n其根似蒜及薤而长，外有赤皮裹之。冬月生叶，似薤及蒜。春初抽茎，如葱头。茎头开花数 \n朵，大如簪头，状如酒杯，五尖上承，黄心，宛然盏样，其花莹韵，其香清幽。一种千叶者 \n，花皱，下轻黄而上淡白，不作杯状，人重之，指为真水仙，盖不然，乃一物二种尔。亦有 \n红花者。按∶段成式《酉阳杂俎》云∶捺祗出拂林国，根大如鸡卵，苗长三四尺，叶似蒜 \n叶，中心抽条，茎端开花，六出红白色，花心黄赤，不结子，冬生夏死。取花压油，涂身去 \n风气。据此形状，与水仙仿佛，岂外国名谓不同耶？ \n\\x根\\x \n【气味】苦、微辛，滑，寒，无毒。土宿真君曰∶取汁伏汞，煮雄黄，拒火。 \n【主治】 \n\\x花\\x \n【气味】缺。 \n【主治】作香泽，涂身理发，去风气。又疗妇人五心发热，同干荷叶、赤芍药等分，为 \n末，白汤每服二钱，热自退也（时珍，出《卫生易简方》）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>白茅\n\n内容：（《本经》中品） \n【释名】根名茹根（《本经》）、兰根（《本经》）、地筋（《别录》）。时珍曰∶茅叶如矛， \n故谓之茅。其根牵连，故谓之茹。《易》曰∶拔茅连茹，是也。有数种∶夏花者，为茅；秋 \n花者，为菅，二物功用相近，而名谓不同。《诗》云∶白华菅兮，白茅束兮，是也。《别录》 \n不分茅、菅乃二种，谓茅根一名地菅，一名地筋，而有名未用又出地筋，一名菅根。盖二物 \n之根状皆如筋，可通名地筋，不可并名菅也，正之。 \n【集解】《别录》曰∶茅根，生楚地山谷田野，六月采根。 \n弘景曰∶此即今白茅菅，《诗》云∶露彼菅茅，是也。其根如渣芹甜美。 \n颂曰∶处处有之。春生芽，布地如针，俗谓之茅针，亦可啖，甚益小儿。夏生白花茸茸 \n然，至秋而枯。其根至洁白，六月采之。又有菅，亦茅类也。陆玑《草木疏》云∶菅，似茅 \n而滑无毛，根下五寸中有白粉者，柔韧宜为索，沤之尤善。其未沤者名野菅，入药与茅功等。 \n时珍曰∶茅有白茅、菅茅、黄茅、香茅、芭茅数种，叶皆相似。白茅短小，三、四月开 \n白花成穗，结细实。其根甚长，白软如筋而有节，味甘，俗呼丝茅，可以苫盖，及供祭祀苞 \n苴之用，《本经》所用茅根是也。其根干之，夜视有光，故腐则变为萤火。菅茅只生山上， \n似白茅而长，入秋抽茎，开花成穗如荻花，结实尖黑，长分许，粘衣刺人。其根短硬如细竹 \n根，无节而微甘，亦可入药，功不及白茅，《尔雅》所谓白华野菅是也。黄茅似菅茅，而茎 \n上开叶，茎下有白粉，根头有黄毛，根亦短而细硬无节。秋深开花穗如菅，可为索 ，古名 \n黄菅，《别录》所用菅根是也。香茅，一名菁茅，一名琼茅，生湖南及江淮间，叶有三脊， \n其气香芬，可以包藉及缩酒，禹贡所谓荆州苞匦菁茅是也。芭茅丛生，叶大如蒲，长六、七 \n尺，有二种，即芒也。见后芒下。 \n\\x茅根\\x \n【气味】甘，寒，无毒。 \n【主治】劳伤虚羸，补中益气，除瘀血、血闭寒热，利小便（《本经》）。下五淋，除客 \n热在肠胃，止渴坚筋，妇人崩中。久服利人（《别录》）。主妇人月经不匀，通血脉淋沥（大 \n明）。止吐衄诸血，伤寒哕逆，肺热喘急，水肿黄胆，解酒毒（时珍）。 \n【发明】弘景曰∶茅根，服食断谷甚良。俗方稀用，惟煎汁疗淋及崩中尔。时珍曰∶ \n白茅根甘，能除伏热，利小便，故能止诸血哕逆、喘急消渴，治黄胆水肿，乃良物也。世人 \n因微而忽之，惟事苦寒之剂，致伤冲和之气，乌足知此哉？ \n【附方】旧二，新一十三。 \n山中辟谷∶凡辟难无人之境，取白茅根冼净，咀嚼，或石上晒焦捣末，水服方寸匕，可 \n辟谷不饥。（《肘后方》）温病冷 ∶因热甚饮水成暴冷 者。茅根（切）、枇杷叶（拭去毛， \n炙香）各半斤。水四升，煎二升，去滓，稍热饮之。（庞安常《伤寒总病论》） \n温病热哕∶乃伏热在胃，令人胸满则气逆，逆则哕，或大下后，胃中虚冷，亦致哕也。 \n茅 \n反胃上气，食入即吐。茅根、芦根二两。水四升，煮二升，顿服得下，良。（《圣济总录 \n肺热气喘∶生茅根一握。 咀，水二盏，煎一盏，食后温服。甚者三服止，名如神汤。 \n（ \n虚后水肿∶因饮水多，小便不利。用白茅根一大把，小豆三升。水三升，煮干，去茅食 \n豆，水随小便下也。（《肘后方》） \n五种黄病∶黄胆、谷疸、酒疸、女疸、劳疸也。黄汗者，乃大汗出入水所致，身体微肿， \n汗出如黄柏汁。用生茅根一把，细切，以猪肉一斤，合作羹食。（《肘后》） \n解中酒毒，恐烂五脏。茅根汁，饮一升。（《千金方》） \n小便热淋∶白茅根四升，水一斗五升，煮取五升，适冷暖饮之，日三服。（《肘后方》） \n小便出血∶茅根煎汤，频饮为佳。（《谈野翁方》） \n劳伤溺血∶茅根、干姜等分。入蜜一匙，水二钟，煎一钟，日一服。 \n鼻衄不止∶茅根为末，米泔水服二钱。（《圣惠方》） \n吐血不止∶《千金翼》∶用白茅根一握，水煎服之。《妇人良方》∶用根洗捣汁，日饮一 \n合。 \n竹木入肉∶白茅根烧末，猪脂和涂之。风入成肿者，亦良。（《肘后方》） \n茅针（即初生苗也。《拾遗》） \n【气味】甘，平，无毒。大明曰∶凉。 \n【主治】下水（《别录》）。治消渴，能破血（甄权）。通小肠，治鼻衄及暴下血，水煮服 \n之。恶疮痈肿、软疖未溃 \n\\x花\\x \n【气味】甘，温，无毒。 \n【主治】煎饮，止吐血衄血，并塞鼻。又敷灸疮不合， 刀箭金疮，止血并痛（大明）。 \n\\x屋上败茅\\x \n【气味】苦，平，无毒。 \n【主治】猝吐血，锉三升，酒浸煮一升服。和酱汁研，敷斑疮及蚕啮疮（藏器）。屋四 \n角 \n【发明】时珍曰∶按《陈文中小儿方》∶治痘疮溃烂，难靥不干。多年墙屋上烂茅，择 \n洗焙干，为末掺之。此盖取其性寒而解毒，又多受雨露霜雪之气，兼能燥湿也。 \n【附方】新三。 \n妇人阴痒∶墙头烂茅、荆芥、牙皂等分。煎水频熏洗之。（《摘玄方》）大便闭塞，服药 \n不通者。沧盐三钱，屋檐烂草节七个。为末。每用一钱，竹筒吹入肛内一寸即通，名提金散。 \n（《圣济录》）卒中五尸∶其状腹痛胀急，不得气息，上冲心胸，旁攻两胁，或 涌起，或 \n牵引腰脊，此乃身中尸鬼接引为害。取屋上四角茅，入铜器中，以三赤布覆腹，着器布上， \n烧茅令热，随痛追逐，跖下痒即瘥也。（《肘后方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>地筋\n\n内容：（《别录》有名未用） \n【释名】菅根（《别录》）、土筋（同）。 \n【集解】《别录》曰∶地筋生泽中，根有毛。三月生，四月实白，三月三日采根。弘景 \n曰∶疑此即是白茅而小异也。藏器曰∶地筋如地黄，根叶并相似，而细多毛，生平泽，功用 \n亦同地黄，李邕方中用之。时珍曰∶此乃黄菅茅之根也，功与白茅根相同，详见白茅下。陈 \n藏器所说，别是一物， \n【气味】甘，平，无毒。 \n【主治】益气止渴，除热在腹脐，利筋（《别录》）。根、苗、花，功与白茅同（时珍）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>芒\n\n内容：（《拾遗》） \n【校正】并入《拾遗》石芒、败芒箔。 \n【释名】杜荣（《尔雅》）、笆芒（《寰宇志》）、笆茅。 \n时珍曰∶芒，《尔雅》作 。今俗谓之笆茅，可以为篱笆故也。 \n【集解】藏器曰∶《尔雅》∶ ，杜荣。郭璞注云∶草似茅，皮可为绳索履 也。今东人 \n多以为箔。又曰∶石芒生高山，如芒而节短，江西呼为折草，六、七月生穗如荻。时珍曰∶ \n芒有二种，皆丛生，叶皆如茅而大，长四、五尺，甚快利，伤人如锋刃。七月抽长茎，开白 \n花成穗，如芦苇花者，芒也；五月抽短茎，开花如芒者，石芒也。并于花将放时剥其箨皮， \n可为绳箔草履诸物，其茎穗可为扫帚也。 \n\\x茎\\x \n【气味】甘，平，无毒。 \n【主治】人畜为虎野狼等伤，恐毒入内，取茎杂葛根浓煮汁服，亦生取汁服。（藏器）。煮 \n汁服，散血（时珍）。 \n\\x败芒箔\\x \n【主治】产妇血满腹胀痛，血渴，恶露不尽，月闭，止好血，下恶血，去鬼气疰痛症结， \n酒煮服之。亦烧末，酒下。弥久着烟者佳（藏器）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>龙胆\n\n内容：（《本经》上品） \n【释名】陵游（《本经》）。志曰∶叶如龙葵，味苦如胆，因以为名。 \n【集解】《别录》曰∶龙胆生齐朐山谷及冤句，二月、八月、十一月、十二月采根阴干。 \n弘景曰∶今出近道，以吴兴者为胜。根状似牛膝，其味甚苦。 \n颂曰∶宿根黄白色，下抽根十余条，类牛膝而短。直上生苗，高尺余。四月生叶如嫩蒜 \n，细茎如小竹枝。七月开花，如牵牛花，作铃铎状，青碧色。冬后结子，苗便枯。俗呼草龙 \n胆。又有山龙胆，味苦涩，其叶经霜雪不凋。山人用治四肢疼痛，与此同类而别种也。采无 \n时。 \n\\x根\\x \n【修治】 曰∶采得阴干。用时，铜刀切去须，土，头了，锉细，甘草汤浸一宿， \n漉出，曝干用。 \n【气味】苦、涩，大寒，无毒。 \n曰∶空腹饵之，令人溺不禁。 \n之才曰∶贯众、小豆为之使，恶地黄、防葵。 \n【主治】骨间寒热，惊痫邪气，续绝伤，定五脏，杀蛊毒（《本经》）。除胃中伏热，时 \n气温热，热泄下痢，去肠中小虫，益肝胆气，止惊惕，久服益智不忘，轻身耐老（《别录》） \n。治小儿壮热骨热，惊痫入心，时疾热黄，痈肿口疮（甄权）。客忤疳气，热病狂语，明目 \n止烦，治疮疥（大明）。去目中黄及睛赤肿胀，瘀肉高起，痛不可忍（元素）。退肝经邪热， \n除下焦湿热之肿，泻膀胱火（李杲）。疗咽喉痛，风热盗汗（时珍）。 \n【发明】元素曰∶龙胆味苦性寒，气味俱浓，沉而降，阴也，足厥阴、少阳经气分药也 \n。其用有四∶除下部风湿，一也；及湿热，二也；脐下至足肿痛，三也；寒湿香港脚，四也。 \n下行之功与防己同，酒浸则能上行，外行以柴胡为主，龙胆为使治眼中疾必用之药。好古曰 \n∶益肝胆之气而泄火。时珍曰∶相火寄在肝胆，有泻无补，故龙胆之益肝胆之气，正以其能 \n泻肝胆之邪热也。但大苦大寒，过服恐伤胃中生发之气，反助火邪，亦久服黄连反从火化之 \n义。《别录》久服轻身之说，恐不足信。 \n【附方】旧四，新六。 \n伤寒发狂∶草龙胆为末，入鸡子清、白蜜，化凉水服二钱。（《伤寒蕴要》） \n四肢疼痛∶山龙胆根，细切，用生姜自然汁浸一宿，去其性，焙干捣末，水煎一钱匕， \n温 \n谷疸劳疸∶谷疸，因食而得；劳疸，因劳而得。用龙胆一两，苦参三两。为末，牛胆汁 \n和丸梧子大。先食以麦饮服五丸，日三服，不愈稍增。劳疸，加龙胆一两，栀子仁三七枚， \n以猪胆和丸。（《删繁方》） \n一切盗汗∶妇人、小儿一切盗汗，又治伤寒后盗汗不止。龙胆草研末，每服一钱，猪胆 \n汁三两，点入温酒少许调服。（《杨氏家藏方》）小儿盗汗身热。龙胆草、防风各等分。为末。 \n每服一钱，米饮调下。亦可丸服，及水煎 \n咽喉热痛∶龙胆，擂水服之。（《集简方》） \n暑行目涩∶生龙胆（捣汁）一合，黄连（二寸切烂浸汁）一匙，和点之。（危氏《得效 \n方》） \n\\x眼中漏脓\\x \n龙胆草、当归等分。为末。每服二钱，温水下。（《鸿飞集》）蛔虫攻心刺痛，吐 \n清水。龙胆一两，去头锉，水二盏，煮一盏，隔宿勿食，平旦顿服之。（《圣惠方》）猝然下 \n血不止。龙胆一虎口，水五升，煮取二升半，分为五服。（姚僧坦《集验方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>细辛\n\n内容：（《本经》上品） \n【释名】小辛（《本经》）、少辛。 \n颂曰∶华州真细辛，根细而味极辛，故名之曰细辛。 \n时珍曰∶小辛、少辛，皆此义也。按《山海经》云，浮戏之山多少辛。《管子》云，五 \n沃之土，群药生少辛，是矣。 \n【集解】《别录》曰∶细辛，生华阴山谷，二月、八月采根阴干。弘景曰∶今用东阳临 \n海者，形段乃好，而辛烈不及华阴、高丽者。用之去其头节。当之曰∶细辛如葵赤黑，一根 \n一叶相连。颂曰∶今处处有之，皆不及华阴者为真，其根细而极辛。今人多以杜衡为之，杜 \n衡根似饭帚密闹，细长四、五寸，微黄白色，江淮呼为马蹄香，不可误用。宗 曰∶细辛， \n叶如葵，赤黑色，非此则杜衡也。杜衡叶如马蹄之下，故俗名马蹄香。盖根似白前，又似细 \n辛。按∶沈括《梦溪笔谈》云∶细辛出华山，极细而直，柔韧，深紫色，味极辛，嚼之习习 \n如椒而更甚于椒。本草云∶细辛水渍令直，是以杜衡伪为之也。东南所用细辛，皆杜衡也。 \n杜衡黄白色，拳曲而脆，干则作团，又谓之马蹄。襄汉间又有一种细辛，极细而直，色黄白 \n，乃是鬼督邮，亦非细辛也。时珍曰∶《博物志》言杜衡乱细辛，自古已然矣。沈氏所说甚 \n详。大抵能乱细辛者，不止杜衡，皆当以根苗色味细辨之。叶似小葵，柔茎细根，直而色紫 \n，味极辛者，细辛也。叶似马蹄，茎微粗，根曲而黄白色，味亦辛者，杜衡也。一茎直上， \n茎端生叶如伞，根似细辛，微粗直而黄白色，味辛微苦者，鬼督邮也。似鬼督邮而色黑者， \n及己也。叶似小桑，根似细辛，微粗长而黄色，味辛而有臊气者，徐长卿也。叶似柳而根似 \n细辛，粗长黄白色而味苦者，白薇也。似白薇而白直味甘者，白前也。 \n\\x根\\x \n【修治】 曰∶凡使细辛，切去头、土了，以瓜水浸一宿，曝干用。须拣去双叶者，服 \n之害人。 \n【气味】辛，温，无毒。普曰∶神农、黄帝、雷公、桐君∶辛，小温；岐伯∶无毒 \n；李当之∶小寒。权曰∶苦、辛。之才曰∶曾青、枣根为之使。得当归、芍药、白芷、芎 \n、牡丹、 本、甘草，共疗妇人；得决明、鲤鱼胆、青羊肝，共疗目痛。恶黄 、野狼毒、山 \n茱萸，忌生菜、狸肉，畏硝石、滑石，反藜芦。 \n【主治】咳逆上气，头痛脑动，百节拘挛，风湿痹痛死肌。久服明目利九窍，轻身长年 \n（《本经》）。温中下气，破痰利水道，开胸中滞结，除喉痹 鼻不闻香臭，风痫癫疾，下乳 \n结，汗不出，血不行，安五脏，益肝胆，通精气（《别录》）。添胆气、治嗽，去皮风湿痒， \n风眼泪下，除齿痛，血闭，妇人血沥腰痛（甄权）。含之，去口臭（弘景）。润肝燥，治督脉 \n为病，脊强而厥（好古）。治口舌 \n【发明】宗 曰∶治头面风痛，不可缺此。元素曰∶细辛气温，味大辛，气浓于味， \n阳也，升也，入足厥阴、少阴血分，为手少阴引经之药。香味俱细，故入少阴，与独活相类 \n。以独活为使，治少阴头痛如神。亦止诸阳头痛，诸风通用之。味辛而热，温少阴之经，散 \n水气以去内寒。成无己曰∶水停心下不行，则肾气燥，宜辛以润之。细辛之辛，以行水气而 \n润燥。杲曰∶胆气不足，细辛补之。又治邪气自里之表，故仲景少阴证，用麻黄附子细辛汤 \n。时珍曰∶气之浓者能发热，阳中之阳也。辛温能散，故诸风寒、风湿头痛、痰饮、胸中滞 \n气、惊痫者，宜用之。口疮、喉痹、 齿诸病用之者，取其能散浮热，亦火郁则发之之义也 \n。辛能泄肺，故风寒咳嗽上气者，宜用之。辛能补肝，故胆气不足，惊痫眼目诸病，宜用之 \n。辛能润燥，故通少阴及耳窍，便涩者宜用之。承曰∶细辛非华阴者不得为真。若单用末， \n不可过一钱。多则气闷塞不通者死，虽死无伤。近年开平狱中尝治此，不可不记。非本有毒 \n，但不识多寡耳。 \n【附方】旧二，新六。暗风猝倒，不省人事。细辛末，吹入鼻中。（危氏《得效方》）虚 \n寒呕哕，饮食不下。细辛（去叶）半两，丁香二钱半。为末。每服一钱，柿蒂汤下。小儿客 \n忤口不能言。细辛、桂心末等分，以少许纳口中。（《外台秘要》）小儿口疮∶细辛末，醋调， \n贴脐上。（《卫生家宝方》）口舌生疮∶细辛、黄连等分，为末掺之，漱涎甚效，名兼金散。 \n一方用细辛、黄柏。（《三因方》）口臭 齿肿痛。细辛煮浓汁，热含冷吐，取瘥。（《圣惠 \n方》）鼻中息肉∶细辛末，时时吹之。（《圣惠方》）诸般耳聋∶细辛末，溶黄蜡丸鼠屎大， \n绵裹一丸塞之，一、二次即愈。须戒怒气，名聪耳丸。（龚氏《经验方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>杜衡\n\n内容：（《别录》中品） \n【释名】杜葵（《纲目》）、马蹄香（《唐本》）、土卤（《尔雅》）、土细辛（《纲目》）。 \n恭曰∶杜衡，叶似葵，形似马蹄，故俗名马蹄香。颂曰∶《尔雅》杜又名土卤，然杜若 \n亦名杜衡，或疑是杜若。而郭璞注云∶似葵，当是杜衡也。 \n【集解】《别录》曰∶杜衡生山谷，三月三日采根，熟洗曝干。弘景曰∶根叶都似细辛， \n惟气小异尔。处处有之。方药少用，惟道家服之。令人身衣香。恭曰∶生山之阴，水泽下湿 \n地。叶似葵，形如马蹄。根似细辛、白前等。今俗以及己代之，谬矣。及己独茎，茎端四叶， \n叶间白花，殊无芳气。有毒，服之令人吐，惟疗疮疥，不可乱杜衡也。颂曰∶今江淮间皆有 \n之。春初于宿根上生苗，叶似马蹄下状，高二、三寸，茎如麦稿粗细，每窠上有五七叶，或 \n八九叶，别无枝蔓。又于茎叶间罅内芦头上贴地生紫花，其花似见不见，暗结实如豆大，窠 \n内有碎子，似天仙子。苗叶俱青，经霜即枯，其根成空，有似饭帚密闹，细长四五寸，粗于 \n细辛，微黄白色，味辛，江淮俗呼为马蹄香。谨按《山海经》云∶天帝之山有草焉。其状如 \n葵，其臭如蘼芜，名曰杜衡。可以走马，食之已瘿。郭璞注云∶带之可以走马。或曰∶马得 \n之而健走也。宗 曰∶杜衡用根似细辛，但根色白，叶如马蹄之下。市人往往以乱细辛，将 \n二物相对，便见真伪。况细辛惟出华州者良。杜衡色黄，拳局而脆，干则作团。详细辛下。 \n时珍曰∶按《土宿本草》云∶杜细辛，叶圆如马蹄，紫背者良，江南、荆、湖、川、陕、闽、 \n广俱有之。取自然汁，可伏硫、砒，制汞。 \n\\x根\\x \n【气味】辛，温，无毒。 \n【主治】风寒咳逆。作浴汤，香人衣体（《别录》）。止气奔喘促，消痰饮，破留血、项 \n间瘿瘤之疾（甄权）。下气杀虫（时珍）。 \n【发明】时珍曰∶古方吐药往往用杜衡者，非杜衡也，乃及己也。及己似细辛而有毒， \n吐人。昔人多以及己当杜衡，杜衡当细辛，故尔错误也。杜衡则无毒，不吐人，功虽不及细 \n辛，而亦能散风寒，下气消痰，行水破血也。 \n【附方】新六。风寒头痛∶伤风伤寒，头痛发热，初觉者。马蹄香为末，每服一钱，热 \n酒调下，少顷饮热茶一碗，催之出汗即愈，名香汗散。（王英《杏林摘要》）饮水停滞∶大热 \n行极，及食热饼后，饮冷水过多不消，停滞在胸不利，呼吸喘息者。杜衡三分，瓜蒂二分， \n人参一分。为末。汤服一钱，日二服，取吐为度。（《肘后方》）痰气哮喘∶马蹄香焙研，每 \n服二、三钱，正发时淡醋调下，少顷吐出痰涎为验。（《普济方》）噎食膈气∶马蹄香四两。 \n为末，好酒三升，熬膏。每服二匙，好酒调下，日三服。（孙氏《集效方》）吐血瘀聚∶凡吐 \n血后，心中不闷者必止；若烦躁闷乱刺胀者，尚有瘀血在胃，宜吐之。方同饮水停滞。喉闭 \n肿痛∶草药金锁匙，即马蹄草，以根捣，井华水调下即效。（《救急方》） \n【附录】木细辛 藏器曰∶味苦，温，有毒。主腹内结聚症瘕，大便不利，推陈去恶， \n破冷气。未可轻服，令人利下至困。生终南山，冬月不凋，苗如大戟，根似细辛。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>及己\n\n内容：（《别录》下品） \n【释名】獐耳细辛。时珍曰∶及己名义未详。二月生苗，先开白花，后方生叶三片，状 \n如獐耳，根如细辛，故名獐耳细辛。 \n【集解】恭曰∶及己生山谷阴虚软地。其草一茎，茎头四叶，隙着白花。根似细辛而黑， \n有 \n\\x根\\x \n【气味】苦，平，有毒。恭曰∶入口使人吐血。 \n【主治】诸恶疮疥痂 蚀，及牛马诸疮（《唐本》）。头疮白秃风瘙，皮肤虫痒，可煎汁 \n浸并敷之（大明）。杀虫（时珍）。 \n【发明】弘景曰∶今人以合疮疥膏，甚验。时珍曰∶今人不知及己，往往以当杜衡，却 \n以杜衡当细辛，故杜衡诸方多是及己也。辩见细辛、杜衡二条。 \n【附方】新一。头疮白秃∶獐耳细辛，其味香辣，为末，以槿木煎油调搽。（《活幼全 \n书》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>鬼督邮\n\n内容：（《唐本草》） \n【释名】独摇草（《唐本》）。时珍曰∶此草独茎而叶攒其端，无风自动，故曰鬼独摇草， \n后人讹为鬼督邮尔。因其专主鬼病，犹司鬼之督邮也。古者传舍有督邮之官主之。徐长卿、 \n赤箭皆治鬼病，故并有鬼督邮之名，名同而物异。 \n【集解】恭曰∶鬼督邮所在有之。有必丛生，苗唯一茎，茎端生叶若伞状，根如牛膝而 \n细黑。今人以徐长卿代之，非也。保升曰∶茎似细箭杆，高二尺以下。叶生茎端，状如伞。 \n花生叶心，黄白色。根横生而无须，二月、八月采根。徐长卿、赤箭并有鬼督邮之名，而主 \n治不同，宜审用之。时珍曰∶鬼督邮与及己同类，根苗皆相似。但以根如细辛而色黑者，为 \n及己；根如细辛而色黄白者，为鬼督邮。 \n\\x根\\x \n【修治】 曰∶凡采得细锉，用生甘草水煮一伏时 \n【气味】辛、苦，平，无毒。时珍曰∶有小毒。 \n【主治】鬼疰卒忤中恶，心腹邪气，百精毒，温疟疫疾，强腰脚，益膂力（《唐本》）。 \n【发明】时珍曰∶按东晋《深师方》，治上气嗽、饮嗽、邪嗽、燥嗽、冷嗽，四满丸， \n用鬼督邮同蜈蚣、芫花、踯躅诸毒药为丸，则其有毒可知矣。非毒药不能治鬼疰邪恶之病， \n《唐本》云无毒，盖不然。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>徐长卿\n\n内容：（《本经》上品） \n【校正】今据《吴氏本草》，并入石下长卿。 \n【释名】鬼督邮（《本经》）、别仙踪（苏颂）。 \n时珍曰∶徐长卿，人名也，常以此药治邪病，人遂以名之。《名医别录》于有名未用复 \n出石下长卿条，云一名徐长卿。陶弘景注云∶此是误尔。方家无用，亦不复识。今考二条功 \n疗相似。按《吴普本草》云∶徐长卿一名石下长卿。其为一物甚明，但石间生者为良。前人 \n欠 \n气亦相似。今狗脊散用鬼督邮者，取其强悍宜腰脚，故知是徐长卿，而非鬼箭、赤箭。 \n【集解】《别录》曰∶徐长卿，生泰山山谷及陇西，三月采。又曰∶石下长卿生陇西山 \n谷池泽，三月采。恭曰∶所在川泽有之。叶似柳，两叶相当，有光泽。根如细辛，微粗长， \n黄色而有臊气。今俗以代鬼督邮，非也。鬼督邮自有本条。保升曰∶生下湿川泽之间。苗似 \n小桑，两叶相对。三月苗青，七月、八月着子，似萝摩子而小。九月苗黄，十月凋。八月采 \n根，晒干。颂曰∶今淄、齐、淮、泗间皆有之，三月、四月采，谓之别仙踪。时珍曰∶鬼督 \n邮、及己之乱杜衡，其功不同，苗亦不同也。徐长卿之乱鬼督邮，其苗不同，其功同也。杜 \n衡之乱细辛，则根苗功用皆仿佛，乃弥近而大乱也。不可不审。 \n\\x根\\x \n【修治】 曰∶凡采得粗杵，拌少蜜令遍，以瓷器盛，蒸三伏时，晒干用。 \n【气味】辛，温，无毒。《别录》曰∶石下长卿∶咸，平，有毒。普曰∶徐长卿一名石 \n下长卿。神农、雷公∶辛。时珍曰∶治鬼之药多有毒，当从《别录》。 \n【主治】鬼物百精蛊毒，疫疾邪恶气，温疟。久服强悍轻身（《本经》）。益气延年。又 \n曰∶石下长卿∶主鬼疰精物邪恶气，杀百精蛊毒，老魅注易，亡走啼哭，悲伤恍惚（《别录 \n【发明】时珍曰∶《抱朴子》言∶上古辟瘟疫有徐长卿散，良效。今人不知用此。 \n【附方】新二。 \n小便关格∶徐长卿汤∶治气壅关格不通，小便淋结，脐下妨闷。徐长卿（炙）半两，茅 \n根三分，木通、冬葵子一两，滑石二两，槟榔一分，瞿麦穗半两。每服五钱，水煎，入朴硝 \n一钱，温服，日二服。（《圣惠方》）注车注船∶凡人登车船烦闷，头痛欲吐者。宜用徐长卿、 \n石长生、车前子、车下李根皮各等分。捣碎，以方囊系半合于衣带及头上，则免此患。（《肘 \n后方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>白薇\n\n内容：（《本经》中品） \n【释名】薇草（《别录》）、白幕（《别录》）、春草（《别录》）、 （音尾）、骨美。时珍 \n曰∶薇，细也。其根细而白也。按∶《尔雅》∶ ，春草也。薇、 音相近，则白薇又 音之 \n转也。《别录》以 为莽草之名，误矣。 \n【集解】《别录》曰∶白薇生平原川谷。三月三日采根阴干。弘景曰∶近道处处有之。 \n颂曰∶今陕西诸郡及舒、滁、润、辽州亦有之。茎叶俱青，颇类柳叶。六、七月开红花， \n八月结实。其根黄白色，类牛膝而短小，今人八月采之。 \n\\x根\\x \n【修治】 曰∶凡采得，以糯米泔汁浸一宿，取出去髭，于槐砧上细锉，蒸之，从巳至 \n申，晒干用。时珍曰∶后人惟以酒洗用。 \n【气味】苦、咸，平，无毒。《别录》曰∶大寒。之才曰∶恶黄 、大黄、大戟、干姜、 \n大枣、干漆、山茱萸。 \n【主治】暴中风身热肢满，忽忽不知人，狂惑邪气，寒热酸疼，温疟洗洗，发作有时（《本 \n经》）。疗伤中淋露，下水气，利阴气，益精。久服利人（《别录》）。治惊邪风狂 病，百 \n邪鬼魅（弘景）。风温灼热多眠，及热淋遗尿，金疮出血（时珍）。 \n【发明】好古曰∶古方多用治妇人，以本草有疗伤中淋露之故也。 \n时珍曰∶白薇古人多用，后世罕能知之。按∶张仲景治妇人产中虚烦呕逆，安中益气， \n竹皮丸方中，用白薇同桂枝各一分，竹皮、石膏各三分，甘草七分。枣肉为大丸，每以饮化 \n一丸服。云有热者，倍白薇，则白薇性寒，乃阳明经药也。徐之才《药对》言白薇恶大枣， \n而此方又以枣肉为丸，盖恐诸药寒凉伤脾胃尔。朱肱《活人书》治风温发汗后，身犹灼热， \n自汗身重多眠，鼻息必鼾，语言难出者，葳蕤汤中亦用之。孙真人《千金方》，有诏书发汗 \n白薇散焉。 \n【附方】新五。 \n肺实鼻塞，不知香臭。白薇、贝母、款冬花各一两，百部二两。为末。每服一钱，米饮 \n下。（《普济方》）妇人遗尿，不拘胎前产后。白薇、芍药各一两。为末。酒服方寸匕，日三 \n服。（《千金方》） \n血淋热淋∶方同上。妇人血厥∶人平居无疾苦，忽如死人，身不动摇，目闭口噤，或微 \n知人，眩冒，称时方寤，此名血厥，亦名郁冒。出汗过多，血少，阳气独上，气塞不行，故 \n身如死。气过血还，阴阳复通，故移时方寤。妇人尤多此证。宜服白薇汤∶用白薇、当归各 \n一两，人参半两，甘草二钱半。每服五钱，水二盏，煎一盏，温服。（《本事方》） \n金疮血出∶白薇为末，贴之。（《儒门事亲》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>白前\n\n内容：（《别录》中品） \n【释名】石蓝（《唐本》）、嗽药（同上）。时珍曰∶名义未详。 \n【集解】弘景曰∶白前出近道，根似细辛而大，色白不柔易折，气嗽方多用之。恭曰∶ \n苗高尺许，其叶似柳，或似芫花，根长于细辛，白色。生州渚沙碛之上，不生近道。俗名石 \n蓝，又名嗽药。今用蔓生者味苦，非真也。志曰∶根似白薇、牛膝辈，二月、八月采，阴干 \n用。 \n嘉谟曰∶似牛膝，粗长坚直易断者，白前也。似牛膝，短小柔软能弯者，白薇也。近道 \n俱有，形色颇同，以此别之，不致差误。 \n\\x根\\x \n【修治】 曰∶凡用，以生甘草水浸一伏时，漉出，去头须了，焙干收用。 \n【气味】甘，微温，无毒。权曰∶辛。恭曰∶微寒。 \n【主治】胸胁逆气，咳嗽上气，呼吸欲绝（《别录》）。主一切气，肺气烦闷，奔豚肾气 \n（大 \n【发明】宗 曰∶白前能保定肺气，治嗽多用，以温药相佐使尤佳。时珍曰∶白前色白 \n而味微辛甘，手太阴药也。长于降气，肺气壅实而有痰者宜之。若虚而长哽气者，不可用也。 \n张 \n【附方】旧二，新一。 \n久嗽唾血∶白前、桔梗、桑白皮三两（炒），甘草一两（炙）。水六升，煮一升，分三服。 \n忌猪肉、菘菜。（《外台》）久咳上气体肿，短气胀满，昼夜倚壁不得卧，常作水鸡声者，白 \n前汤主之。白前二两，紫菀、半夏各三两，大戟七合。以水一斗，渍一宿，煮取三升，分作 \n三服。禁食羊肉、饧糖大佳。（《深师方》） \n久患暇呷∶咳嗽，喉中作声，不得眠。取白前焙捣为末，每温酒服二钱。（《梅师方》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>草犀\n\n内容：（《拾遗》） \n【释名】时珍曰∶其解毒之功如犀角，故曰草犀。 \n【集解】藏器曰∶草犀生衢、婺、洪、饶间。苗高二、三尺，独茎 \n，根如细辛。生水中者名水犀。 \n曰∶《广州记》云∶生岭南及海中，独茎对叶而生，如灯台草，根若细辛。 \n\\x根\\x \n【气味】辛，平，无毒。 \n【主治】解一切毒瓦斯，虎野狼虫虺所伤，溪毒野蛊恶刺等毒，并宜烧研服之，临死者亦得 \n活（李 ）。天行疟瘴寒热，咳嗽痰壅，飞尸喉痹疮肿，小儿寒热丹毒，中恶注忤，痢血等 \n病，煮汁服之。岭南及睦、婺间中毒者，以此及千金藤并解之（藏器）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>钗子股\n\n内容：（《海药》） \n【校正】并入《拾遗》金钗股。 \n【释名】金钗股。时珍曰∶石斛名金钗花，此草状似之，故名。 \n【集解】藏器曰∶金钗股生岭南及南海山谷，根如细辛，每茎三四十根。 曰∶忠州、 \n万州者亦佳，草茎功力相似。缘岭南多毒，家家贮之。时珍曰∶按《岭表录》云∶广中多蛊 \n毒，彼人以草药金钗股治之，十救八、九，其状如石斛也。又忍冬藤解毒，亦号金钗股，与 \n此同名云。 \n\\x根\\x \n【气味】苦，平，无毒。 \n【主治】解毒痈疽神验，以水煎服（李 ）。解诸药毒，煮汁服。亦生研，更烈，必大 \n吐下。如无毒，亦吐去热痰。疟瘴天行，蛊毒喉痹（藏器）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>吉利草\n\n内容：（《纲目》） \n【集解】时珍曰∶按嵇含《南方草木状》云∶此草生交广，茎如金钗股，形类石斛，根 \n类芍药。吴黄武中，江夏李俣徙合浦遇毒，其奴吉利偶得此草与服，遂解，而吉利即遁去。 \n俣以此济人，不知其数也。又高凉郡产良耀草，枝叶如麻黄，花白似牛李，秋结子如小粟， \n煨食解毒，功亚于吉利草。始因梁耀得之，因以为名，转梁为良耳。 \n\\x根\\x \n【气味】苦，平，无毒。 \n【主治】解蛊毒，极验（时珍）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>朱砂根\n\n内容：（《纲目》） \n【集解】时珍曰∶朱砂根生深山中，今惟太和山人采之。苗高尺许，叶似冬青叶，背甚 \n赤，夏月长茂。根大如箸，赤色，此与百两金仿佛。 \n\\x根\\x \n【气味】苦，凉，无毒。 \n【主治】咽喉肿痹，磨水或醋咽之，甚良（时珍）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>辟虺雷\n\n内容：（《唐本草》） \n【释名】辟蛇雷（《唐本》）。时珍曰∶此物辟蛇虺有威，故以雷名之。 \n【集解】恭曰∶辟虺雷状如粗块苍术，节中有眼。时珍曰∶今川中峨嵋、鹤鸣诸山皆有 \n之。根状如苍术，大者若拳。彼人以充方物，苗状当俟访问。 \n\\x根\\x \n【气味】苦，大寒，无毒。 \n【主治】解百毒，消痰，祛大热，疗头痛，辟瘟疫（《唐本》）。治咽喉痛，痹解蛇虺毒 \n（时 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>锦地罗\n\n内容：（《纲目》） \n【集解】时珍曰∶锦地罗出广西庆远山岩间，镇安、归顺、柳州皆有之。根似萆 及栝 \n蒌根状。彼人颇重之，以充方物。 \n\\x根\\x \n【气味】微苦，平，无毒。 \n【主治】山岚瘴毒疮毒，并中诸毒。以根研生酒服一钱匕，即解（时珍）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>紫金牛\n\n内容：（宋《图经》） \n【集解】颂曰∶生福州。叶如茶叶，上绿下紫。结实圆，红色如丹朱。根微紫色，八月 \n采根，去心曝干，颇似巴戟。 \n【气味】辛，平，无毒。 \n【主治】时疾膈气，去风痰（苏颂）。解毒破血（时珍）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>拳参\n\n内容：（宋《图经》） \n【集解】颂曰∶生淄州田野，叶如羊蹄，根似海虾，黑色，土人五月采之。 \n【气味】缺。 \n【主治】为末，淋渫肿气（苏颂）。 \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>铁线草\n\n内容：（宋《图经》） \n【集解】颂曰∶生饶州，三月采根阴干。时珍曰∶今俗呼 蓄为铁线草，盖同名耳。 \n【气味】微苦，平，无毒。 \n【主治】疗风消肿毒，有效（苏颂）。 \n【附方】新一。男女诸风，产后风尤妙。铁线草根五钱，五加皮一两，防风二钱。为末。 \n以乌骨鸡一斤重者，水内淹死，去毛肠，砍作肉松，入药剁匀，下麻油些少，炒黄色，随人 \n量入酒煮熟。先以排风藤煎浓汤，沐浴头身，乃饮酒食鸡，发出粘汗即愈。如不沐浴，必发 \n出风丹，乃愈。（滑伯仁《撄宁心要》） \n\n\n\n<目录>草部第十三卷\\草之二\n\n<篇名>金丝草\n\n内容：（《纲目》） \n【集解】时珍曰∶金丝草出庆阳山谷，苗状当俟访问。 \n【气味】苦，寒，无毒。 \n【主治】吐血咳血，衄血下血，血崩瘴气，解诸药毒，疗痈疽疔肿恶疮，凉血散热 \n（时珍）。 \n【附方】新四。 \n妇人血崩∶金丝草、海柏枝、砂仁、花椒、蚕退纸、旧锦灰，等分，为末，煮酒空心服。 \n陈光述传。（《谈野翁方》）痈疽疔肿，一切恶疮。金丝草、忍冬藤、五叶藤、天荞麦等分。 \n煎汤温洗。黑色者，加醋。又铁箍散∶用金丝草灰二两（醋拌晒干），贝母五两（去心），白 \n芷二两，为末，以凉水调贴疮上，香油亦可。或加龙骨少许。天蛇头毒落苏（即金丝草）、 \n金银花藤、五叶紫葛、天荞 \n麦，等分。切碎，用绝好醋浓煎，先熏后洗。（《救 \n\n\n\n<目录>草部卷十四\n\n<篇名>草之三\n\n内容：\\x芳草类五十六种\\x \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>当归\n\n内容：（《本经》中品） \n【释名】干归（《本经》）、山蕲（《尔雅》）、白蕲（《尔雅》）、文无（《纲目》）。颂曰∶ \n按 \n而粗大。许慎《说文》云∶生山中者，名薜，一名山蕲。然则当归，芹类也。在平地者名芹 \n，生山中粗大者，名当归也。宗 曰∶今川蜀皆以畦种，尤肥好多脂，不以平地、山中为等 \n差也。时珍曰∶当归本非芹类，特以花叶似芹，故得芹名。古人娶妻为嗣续也，当归调血为 \n女人要药，有思夫之意，故有当归之名，正与唐诗胡麻好种无人种，正是归时又不归之旨相 \n同。崔豹《古今注》云∶古人相赠以芍药，相招以文无。文无一名当归，芍药一名将离故也 \n。承曰∶当归治妊妇产后恶血上冲，仓猝取效。气血昏乱者，服之即定。能使气血各有所归 \n，恐当归之名必因此出也。 \n【集解】《别录》曰∶当归生陇西川谷，二月、八月采根，阴干。弘景曰∶今陇西四阳 \n黑水当归，多肉少枝气香，名马尾当归。西川北部当归，多根枝而细。历阳所出者，色白而 \n气味薄，不相似，呼为草当归，缺少时亦用之。恭曰∶今出当州、宕州、翼州、松州，以宕 \n州者最胜。有二种∶一种似大叶芎 者，名马尾当归，今人多用；一种似细叶芎 者，名蚕 \n头当归，即陶称历阳者，不堪用，茎叶并卑下于芎 。颂曰∶今川蜀、陕西诸郡及江宁府、 \n滁州皆有之，以蜀中者为胜。春生苗，绿叶有三瓣。七八月开花似莳萝，浅紫色。根黑黄色， \n以肉浓而不枯者为胜。时珍曰∶今陕、蜀、秦州、汶州诸处人多栽莳为货。以秦归头圆尾多 \n色紫气香肥润者，名马尾归，最胜他处；头大尾粗色白坚枯者，为搀头归，止宜入发散药尔。 \n韩言∶川产者力刚而善攻，秦产者力柔而善补，是矣。 \n\\x根\\x \n【修治】 曰∶凡用去芦头，以酒浸一宿入药。止血破血，头尾效各不同。若要破血， \n即使头一节硬实处。若要止痛止血，即用尾。若一并用，服食无效，不如不使，惟单使妙也 \n。元素曰∶头，止血；尾，破血；身，和血；全用，即一破一止也。先以水洗净土。治上， \n酒浸；治外，酒洗过，或火干、晒干入药。 \n杲曰∶头，止血而上行；身，养血而中守；梢，破血而下流；全活血而不走。 \n时珍曰∶雷、张二氏所说头尾功效各异。凡物之根，身半以上，气脉上行，法乎天；身 \n半以下，气脉下行，法乎地。人身法象天地，则，治上当用头，治中当用身，治下当用尾， \n通治则全用，乃一定之理也。当以张氏之说为优。凡晒干乘热纸封瓮收之，不蛀。 \n【气味】甘，温，无毒。《别录》曰∶辛，大温。普曰∶神农、黄帝、桐君、扁鹊∶甘， \n无毒；岐伯、雷公∶辛，无毒；李当之∶小温。杲曰∶甘、辛，温，无毒。气浓味薄，可升 \n可降，阳中微阴，入手少阴、足太阴、厥阴经血分。之才曰∶恶 茹、湿面，畏菖蒲、海藻、 \n牡蒙、生姜，制雄黄。 \n【主治】咳逆上气，温疟寒热洗洗在皮肤中，妇人漏下绝子，诸恶疮疡金疮，煮汁饮之 \n（《本经》）。温中止痛，除客血内塞，中风 汗不出，湿痹中恶，客气虚冷，补五脏，生肌 \n肉（《别录》）。止呕逆，虚劳寒热，下痢腹痛齿痛，女人沥血腰痛，崩中，补诸不足（甄权）。 \n治一切风，一切血，补一切劳，破恶血，养新血，及症癖，肠胃冷（大明）。治头痛，心腹 \n诸痛，润肠胃筋骨皮肤，治痈疽，排脓止痛，和血补血（时珍）。主痿癖嗜卧，足下热而痛。 \n冲脉为病，气逆里急。带脉为病，腹痛，腰溶溶如坐水中（好古）。 \n【发明】权曰∶患人虚冷者，加而用之。承曰∶世俗多谓惟能治血，而《金匮》、《外台》 \n、《千金》诸方皆为大补不足、决取立效之药。古方用治妇人产后恶血上冲，取效无急于此 \n。凡气血昏乱者，服之即定。可以补虚，备产后要药也。宗 曰∶《药性论》补女子诸不足 \n一说，尽当归之用矣。成无己曰∶脉者血之府，诸血皆属心。凡通脉者，必先补心益血。故 \n张仲景治手足厥寒、脉细欲绝者，用当归之苦温以助心血。元素曰∶其用有三∶一，心经 \n本药；二，和血；三，治诸病夜甚。凡血受病，必须用之。血壅而不流则痛，当归之甘温能 \n和血，辛温能散内寒，苦温能助心散寒，使气血各有所归。 \n好古曰∶入手少阴，以其心生血也。入足太阴，以其脾裹血也。入足厥阴，以其肝藏血 \n也。头，能破血；身，能养血，尾能行血。全用，同人参、黄 ，则补气而生血；同牵牛、 \n大 \n治头痛，诸痛皆属木，故以血药主之。 \n机曰∶治头痛，酒煮服清，取其浮而上也。治心痛，酒调末服，取其浊而半沉半浮也。 \n治小便出血，用酒煎服，取其沉入下极也。自有高低之分如此。王海藏言当归血药，如何治 \n胸中咳逆上气？按∶当归其味辛散，乃血中气药也。况咳逆上气，有阴虚阳无所附者，故用 \n血药补阴，则血和而气降矣。 \n韩 曰∶当归主血分之病。川产力刚可攻，秦产力柔宜补。凡用，本病宜酒制，有痰以 \n姜制，导血归源之理。血虚以人参、石脂为佐，血热以生地黄、条芩为佐，不绝生化之源。 \n血积配以大黄。要之，血药不容舍当归。故古方四物汤以为君，芍药为臣，地黄为佐，芎 \n为使也。 \n【附方】旧八，新一十九。血虚发热∶当归补血汤∶治肌热燥热，目赤面红，烦渴引饮， \n昼夜不息，其脉洪大而虚，重按全无力，此血虚之候也。得于饥困劳役，证象白虎，但脉不 \n长实为异耳。若误服白虎汤即死，宜此主之。当归身（酒洗）二钱，绵黄 （蜜炙）一两。 \n作一服。水二钟，煎一钟，空心温服，日再服。（东垣《兰室秘藏》）失血眩运∶凡伤胎去血， \n产后去血，崩中去血，金疮去血，拔牙去血，一切去血过多，心烦眩运，闷绝不省人事。当 \n归二两，芎 一两。每用五钱，水七分，酒三分，煎七分，热服，日再。（《妇人良方》） \n衄血不止∶当归（焙）研末，每服一钱，米饮调下。（《圣济录》） \n小便出血∶当归四两（锉），酒三升，煮取一升，顿服。（《肘后》） \n头痛欲裂∶当归二两，酒一升，煎取六合，饮之，日再服。（《外台秘要》方） \n内虚目暗∶补气养血。用当归（生晒）六两，附子（火炮）一两，为末，炼蜜丸梧子大。 \n每服三十丸，温酒下，名六一丸。（《圣济总录》）心下痛刺∶当归为末，酒服方寸匕。（《必 \n效方》）手臂疼痛∶当归三两（切），酒浸三日，温饮之。饮尽，别以三两再浸，以瘥为度。 \n（《事林广记》）温疟不止∶当归一两。水煎饮，日一服。（《圣济总录》）久痢不止∶当归二 \n两， \n（ \n妇人百病，诸虚不足者。当归四两，地黄二两，为末，蜜丸梧子大。每食前，米饮下十五丸 \n。（《太医支法存方》）月经逆行，从口鼻出。先以京墨磨汁服，止之。次用当归尾、红花各 \n三钱。水一钟半，煎八分，温服，其经即通。（《简便方》）室女经闭∶当归尾、没药各一钱。 \n为末，红花浸酒，面北饮之，一日一服。（《普济方》）妇人血气，脐下气胀，月经不利，血 \n气上攻欲呕，不得睡。当归四钱，干漆（烧存性）二钱，为末，炼蜜丸梧子大。每服十五丸， \n温酒下。（《永类方》）堕胎下血不止。当归（焙）一两，葱白一握。每服五钱，酒一盏半， \n煎八分，温服。（《圣济总录》）妊娠胎动，神妙。佛手散∶治妇人妊娠伤动，或子死腹中， \n血下疼痛，口噤欲死。服此探之，不损则痛止，已损便立下，此乃徐王神验方也。当归二两， \n芎一两。为粗末。每服三钱，水一盏，煎令泣泣欲干，投酒一盏，再煎一沸，温服，或灌 \n之。如人行五里，再服。不过三、五服，便效。（张文仲《备急方》）产难胎死，横生倒生。 \n用当归三两，芎 一两。为末，先以大黑豆炒焦，入流水一盏，童便一盏，煎至一盏，分为 \n二服。未效再服。（《妇人良方》）倒产子死不出。当归末，酒服方寸匕。（《子母秘录》）产 \n后血胀，腹痛引胁。当归二钱，干姜（炮）五分。为末。每服三钱，水一盏，煎八分，入盐、 \n酢少许，热服。（《妇人良方》）产后腹痛如绞。当归末五钱，白蜜一合，水一盏，煎一盏， \n分为二服。未效再服。（《妇人良方》）产后自汗∶壮热，气短，腰脚痛不可转。当归三钱， \n黄、白芍药（酒炒）各二钱，生姜五片。水一盏半，煎七分，温服。（《和剂局方》）产后 \n中风∶不省人事，口吐涎沫，手足螈 。当归、荆芥穗等分，为末。每服三钱，水一盏，酒 \n少许，童尿少许，煎七分，灌之，下咽即有生意，神效。（《圣惠方》）小儿胎寒好啼，昼夜 \n不止，因此成痫。当归末一小豆大，以乳汁灌之，日夜三四度。（《肘后方》）小儿脐湿不早 \n治，成脐风。或肿赤，或出水。用当归末敷之。一方，入麝香少许。一方，用胡粉等分。试 \n之最验。若愈后因尿入复作，再敷即愈。（《圣惠方》）汤火伤疮， 赤溃烂，用此生肌，拔 \n热止痛。当归、黄蜡各一两，麻油四两。以油煎当归焦黄，去滓，纳蜡搅成膏，出火毒，摊 \n贴之。（《和剂局方》） \n白黄色枯∶舌缩、恍惚若语乱者死。当归、白术二两，水煎，入生 汁、蜜和服。（《三 \n十 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>芎\n\n内容：（音穷穹。《本经》上品） \n【释名】胡 （《别录》）、川芎（《纲目》）、香果（《别录》）、山鞠穷（《纲目》）。 \n时珍曰∶芎本作营，名义未详。或云∶人头穹窿穷高，天之象也。此药上行，专治头脑 \n诸疾，故有芎 之名。以胡戎者为佳，故曰胡芎。古人因其根节状如马衔，谓之马衔芎 。 \n后世因其状如雀脑，谓之雀脑芎。其出关中者，呼为京芎，亦曰西芎；出蜀中者，为川芎； \n出天台者，为台芎；出江南者，为抚芎，皆因地而名也。《左传》∶楚人谓萧人曰∶有麦曲乎？ \n有山鞠穷乎？河鱼腹疾柰何？二物皆御湿，故以谕之。丹溪朱氏治六郁越鞠丸中用越桃、鞠 \n穷，故以命名。《金光明经》谓之 莫迦。 \n【集解】《别录》曰∶芎 叶名蘼芜，生武功川谷、斜谷西岭。三月、四月，采根，曝 \n干。 \n普曰∶芎 ，或生胡无桃山阴，或泰山。叶细香，青黑纹，赤如 本，冬夏丛生，五月 \n花赤，七月实黑，附端两叶。三月采根，有节如马衔。弘景曰∶武功、斜谷西岭，俱近长安。 \n今出历阳，处处亦有，人家多种之。叶似蛇床而香，节大茎细，状如马衔，谓之马衔芎 。 \n蜀中亦有而细。恭曰∶今出秦州，其历阳出者不复用。其人间种者，形块大，重实多脂。山 \n中采者，瘦细。味苦、辛。以九月、十月采之为佳，若三月、四月虚恶非时也。颂曰∶关陕、 \n川蜀、江东山中多有之，而以蜀川者为胜。四五月生叶，似水芹、胡荽、蛇床辈，作丛而茎 \n细。其叶倍香，江东、蜀人采叶作饮。七八月开碎白花，如蛇床子花。根坚瘦，黄黑色。关 \n中出者形块重实，作雀脑状者为雀脑芎，最有力。 \n时珍曰∶蜀地少寒，人多栽莳，深秋茎叶亦不萎也。清明后宿根生苗，分其枝横埋之， \n则节节生根。八月根下始结芎 ，乃可掘取，蒸曝货之。《救荒本草》云∶叶似芹而微细窄， \n有丫叉，又似白芷，叶亦细，又似胡荽叶而微壮，一种似蛇床叶而亦粗。嫩叶可炸食。 \n宗 曰∶凡用，以川中大块，里色白，不油，嚼之微辛甘者佳。他种不入药，止可为末， \n煎汤沐浴而已。 \n\\x根\\x \n【气味】辛，温，无毒。普曰∶神农、黄帝、岐伯、雷公∶辛，无毒。扁鹊∶ \n酸，无毒；李当之∶生温，熟寒。 \n元素曰∶性温，味辛苦，气浓味薄，浮而升，阳也。少阳本经引经药，入手、足厥阴气 \n分。 \n之才曰∶白芷为之使，畏黄连，伏雌黄。得细辛，疗金疮止痛；得牡蛎，疗头风吐 \n逆。 \n【主治】中风入脑头痛，寒痹筋挛缓急，金疮，妇人血闭无子（《本经》）。除脑中冷动， \n面上游风去来，目泪出，多涕唾，忽忽如醉，诸寒冷气，心腹坚痛，中恶猝急肿痛，胁风痛， \n温中内寒（《别录》）。腰脚软弱，半身不遂，胞衣不下（甄权）。一切风，一切气，一切劳损， \n一切血。补五劳，壮筋骨，调众脉，破症结宿血，养新血，吐血鼻血溺血，脑痈发背，瘰 \n瘿赘，痔 疮疥，长肉排脓，消瘀血（大明）。搜肝气，补肝血，润肝燥，补风虚（好古）。 \n燥湿，止泻痢，行气开郁（时珍）。蜜和大丸，夜服，治风痰殊效（苏颂）。齿根出血，含之 \n多瘥（弘景）。 \n【发明】宗 曰∶今人用此最多，头面风不可缺也，然须以他药佐之。 \n元素曰∶川芎上行头目，下行血海，故清神及四物汤皆用之。能散肝经之风，治少阳厥 \n阴经头痛，及血虚头痛之圣药也。其用有四∶为少阳引经，一也；诸经头痛，二也；助清阳 \n之气，三也；去湿气在头，四也。 \n杲曰∶头痛必用川芎。如不愈，加各引经药∶太阳羌活，阳明白芷，少阳柴胡，太阴苍 \n术，厥阴吴茱萸，少阴细辛，是也。 \n震亨曰∶郁在中焦，须抚芎开提其气以升之，气升则郁自降。故抚芎总解诸郁，直达三 \n焦，为通阴阳气血之使。 \n时珍曰∶芎 ，血中气药也。肝苦急，以辛补之，故血虚者宜之。辛以散之，故气郁者 \n宜之。《左传》言∶麦曲鞠穷御湿，治河鱼腹疾。予治湿泻每加二味，其应如响也。血痢已 \n通而痛不止者，乃阴亏气郁，药中加芎为佐，气行血调，其病立止。此皆医学妙旨，圆机之 \n士，始可语之。 \n宗 曰∶沈括《笔谈》云∶一族子旧服芎 ，医郑叔熊见之云∶芎 不可久服，多令人 \n暴死。后族子果无疾而卒。又朝士张子通之妻，病脑风，服芎 甚久，一旦暴亡。皆目见者。 \n此皆单服既久，则走散真气。若使他药佐使，又不久服，中病便已，则焉能至此哉？ \n虞搏曰∶骨蒸多汗，及气弱之人，不可久服。其性辛散，令真气走泄，而阴愈虚也。 \n时珍曰∶五味入胃，各归其本脏。久服则增气偏胜，必有偏绝，故有暴夭之患。若药具 \n五味，备四气，君臣佐使配合得宜，岂有此害哉？如芎 ，肝经药也。若单服既久，则辛喜 \n归肺，肺气偏胜，金来贼木，肝必受邪，久则偏绝，岂不夭亡？故医者贵在格物也。 \n【附方】旧七，新一十三。 \n生犀丸∶宋真宗赐高相国，去痰清目，进饮食。生犀丸∶用川芎十两，紧小者，粟米泔 \n浸二日换，切片子，晒干为末，分作两料。每料入麝、脑各一分，生犀半两，重汤煮，蜜和 \n丸小弹子大。茶、酒嚼下一丸。痰，加朱砂半两；膈壅，加牛黄一分，水飞铁粉一分。头目 \n昏眩，加细辛一分。口眼 斜，加炮天南星一分。（《御药院方》） \n气虚头痛∶真川芎 为末，腊茶调服二钱，甚捷。曾有妇人产后头痛，一服即愈。（《集 \n简方》）气厥头痛∶妇人气盛头痛，及产后头痛。川芎 、天台乌药等分，为末。每服二钱， \n葱茶调下。《御药院方》∶加白术，水煎服。 \n风热头痛∶川芎一钱，茶叶二钱，水一钟，煎五分，食前热服。（《简便方》） \n头风化痰∶川芎洗切，晒干为末，炼蜜丸如小弹子大。不拘时嚼一丸，茶清下。（《经 \n验后方》） \n偏头风痛∶京芎细锉，浸酒日饮之。（《斗门方》） \n风热上冲∶头目运眩，或胸中不利。川芎、槐子各一两。为末。每服三钱，用茶清调下。 \n胸中不利，以水煎服。（张洁古《保命集》）首风旋运及偏正头疼，多汗恶风，胸膈痰饮。川 \n芎一斤，天麻四两，为末，炼蜜丸如弹子大。每嚼一丸，茶清下。（刘河间《宣明方》） \n失血眩晕∶方见当归下。一切心痛∶大芎一个，为末，烧酒服之。一个住一年，两个住 \n二年。（《孙氏集效方》）经闭验胎∶经水三个月不行。验胎法∶川芎生为末，空心煎艾汤服 \n一匙。腹内微动者是有胎不动者非也。（《灵苑方》） \n损动胎气∶因跌扑举重，损胎不安，或子死腹中者。芎 为末，酒服方寸匕，须臾一二 \n服。立出。（《续十全方》）崩中下血，昼夜不止。《千金方》∶用芎 一两，清酒一大盏，煎 \n取五分，徐徐进之。《圣惠》∶加生地黄汁二合，同煎。酒癖胁胀，时复呕吐，腹有水声。川 \n芎、三棱（炮）各一两，为末。每服二钱，葱白汤下。（《圣济总录》）小儿脑热好闭目， \n或太阳痛，或目赤肿。川芎 、薄荷、朴硝各二钱，为末，以少许吹鼻中。（《全幼心鉴》） \n齿败口臭∶水煎芎 ，含之。（《广济方》） \n牙齿疼痛∶大川芎 一个，入旧糟内藏一月，取焙，入细辛同研末，揩牙。（《本事方》） \n诸疮肿痛∶抚芎 研，入轻粉，麻油调涂。（《普济方》） \n产后乳悬∶妇人产后，两乳忽长，细小如肠，垂过小肚，痛不可忍，危亡须臾，名曰乳 \n悬。将芎 、当归各一斤。以半斤锉散，于瓦石器内，用水浓煎，不拘多少频服；仍以一斤 \n半锉块，于病患桌下烧烟，令将口鼻吸烟。用尽未愈，再作一料。仍以蓖麻子一粒，贴其顶 \n心。（夏子益《奇疾方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>蘼芜\n\n内容：（《本经》上品） \n【释名】薇芜（《本经》）、蕲 、 \n颂曰∶蕲 ，古芹芷字也。时珍曰∶蘼芜，一作 芜，其茎叶靡弱而繁芜，故以名之。 \n当归名蕲，白芷名蓠。其叶似当归，其香似白芷，故有蕲 、江蓠之名。王逸云∶蓠草生江 \n中，故曰江蓠，是也。余见 \n【集解】《别录》曰∶芎 叶名蘼芜。又曰∶蘼芜，一名江蓠，芎 苗也。生雍州川泽 \n及冤句，四月、五月采叶曝干。 \n弘景曰∶今出历阳，处处人家多种之。叶似蛇床而香，骚人借以为譬，方药稀用。 \n恭曰∶此有二种∶一种似芹叶，一种似蛇床。香气相似，用亦不殊。 \n时珍曰∶《别录》言∶蘼芜一名江蓠，芎 苗也。而司马相如《子虚赋》称∶芎 菖 \n蒲，江蓠蘼芜。《上林赋》云∶被以江蓠，揉以蘼芜。似非一物，何耶？盖嫩苗未结根时， \n则为蘼芜；既结根后，乃为芎 。大叶似芹者为江蓠，细叶似蛇床者为蘼芜。如此分别，自 \n明白矣。《淮南子》云∶乱人者，若芎 之与 本，蛇床之与蘼芜。亦指细叶者言也。《广志》 \n云∶蘼芜香草，可藏衣中。《管子》云∶五沃之土生蘼芜。郭璞赞云∶蘼芜香草，乱之蛇床。 \n不损其真，自烈以芳 \n【气味】辛，温，无毒。 \n【主治】咳逆，定惊气，辟邪恶，除蛊毒鬼疰，去三虫。久服通神（《本经》）。 \n主身中老风，头中久风、风眩（《别录》）。作饮，止泄泻（苏颂）。 \n\\x花\\x \n【主治】入面脂用（时珍）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>蛇床\n\n内容：（《本经》上品） \n【释名】蛇粟（《本经》）、蛇米（《本经》）、 \n（《别录》，又名思益、绳毒、枣棘）。 \n时珍曰∶蛇虺喜卧于下食其子，故有蛇床、蛇粟诸名。其叶似蘼芜，故曰墙蘼。《尔雅》 \n云∶盱，虺床也。 \n【集解】《别录》曰∶蛇床，生临淄川谷及田野。五月采实阴干。 \n弘景曰∶田野墟落甚多，花叶正似蘼芜。 \n保升曰∶叶似小叶芎 ，花白，子如黍粒，黄白色。生下湿地，所在皆有，以扬州、襄 \n州者为良。 \n颂曰∶三月生苗，高三二尺，叶青碎，作丛似蒿枝。每枝上有花头百余，结同一窠，似 \n马芹类。四五月乃开白色，又似伞状。子黄褐色，如黍米，至轻虚。 \n时珍曰∶其花如碎米攒簇。其子两片合成，似莳罗子而细，亦有细棱。凡花实似蛇床者 \n，当归、芎 、水芹、 本、胡萝卜是也。 \n\\x子\\x \n【修治】 曰∶凡使，须用浓蓝汁并百部草根自然汁，同浸一伏时，漉出晒干。却用生 \n地黄汁相拌蒸之，从巳至亥，取出晒干用。 \n大明曰∶凡服食，即 去皮壳，取仁微炒杀毒，即不辣也。作汤洗浴，则生用之。 \n【气味】苦，平，无毒。《别录》曰∶辛、甘，无毒。权曰∶有小 \n毒。之才曰∶恶牡丹、贝母、巴豆。伏硫黄。 \n【主治】妇人阴中肿痛，男子阴痿湿痒，除痹气，利关节，癫痫恶疮。久服轻身（《本 \n经》）。温中下气，令妇人子脏热，男子阴强。久服好颜色，令人有子（《别录》）。治男子 \n女人虚湿痹，毒风 痛，去男子腰痛，浴男子阴，去风冷，大益阳事（甄权）。暖丈夫阳气， \n助女人阴气，治腰胯酸疼，四肢顽痹，缩小便，去阴汗湿癣齿痛，赤白带下，小儿惊痫，扑 \n损瘀血，煎汤浴大风身痒（大明）。 \n【发明】 曰∶此药令人阳气盛数，号曰鬼考也。 \n时珍曰∶蛇床乃右肾命门、少阳三焦气分之药，神农列之上品，不独辅助男子，而又有 \n益妇人。世人舍此而求补药于远域，岂非贱目贵耳乎？ \n【附方】旧四，新十二。 \n阳事不起∶蛇床子、五味子、菟丝子等分，为末，蜜丸梧子大。每服三十丸，温酒下， \n日三服。（《千金方》）赤白带下，月水不来。用蛇床子、枯白矾等分，为末，醋面糊丸弹子 \n大，胭脂为衣，绵裹纳入阴户。如热极，再换，日一次。（《儒门事亲》方）子宫寒冷，温阴 \n中坐药。蛇床子散∶取蛇床子仁为末，入粉少许，和匀如枣大，绵裹纳之，自然温也。（《金 \n匮玉函方》） \n妇人阴痒∶蛇床子一两，白矾二钱。煎汤频洗。（《集简方》） \n产后阴脱∶绢盛蛇床子，蒸热熨之。又法∶蛇床子五两，乌梅十四个。煎水，日洗五六 \n次 \n妇人阴痛∶方同上。 \n大肠脱肛∶蛇床子、甘草各一两，为末。每服一钱，白汤下，日三服。并以蛇床末敷之。 \n（《经验方》） \n小儿癣疮∶蛇床子杵末，和猪脂涂之。（《千金方》）小儿甜疮，头面耳边连引，流水极 \n痒，久久不愈者。蛇床子一两，轻粉三钱。为细末，油调搽之。（《普济方》） \n耳内湿疮∶蛇床子、黄连各一钱，轻粉一字。为末吹之。（《全幼心鉴》） \n风虫牙痛∶《千金》∶用蛇床子、烛烬。同研，涂之。《集简方》∶用蛇床子煎汤，乘热漱 \n数次，立止。冬月喉痹肿痛，不可下药者。蛇床子烧烟于瓶中，口含瓶嘴吸烟，其痰自出。 \n（《圣惠方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>本\n\n内容：（《本经》中品） \n【释名】 茇（《纲目》）、鬼卿（《本经》）、 \n恭曰∶根上苗下似禾 ，故名 本。本，根也。 \n时珍曰∶古人香料用之，呼为 本香。《山海经》名 茇。 \n【集解】《别录》曰∶ 本，生崇山山谷。正月、二月采根曝干，三十日成。 \n弘景曰∶俗中皆用芎 根须，其形气乃相类。而《桐君药录》说芎 苗似 本，论说花 \n实皆不同，所生处又异。今东山别有 本，形气甚相似，惟长大耳。 \n恭曰∶ 本茎叶根味与芎 小别。今出宕州者佳。 \n颂曰∶今西川、河东州郡及兖州、杭州皆有之。叶似白芷香，又似芎 ，但芎 似水芹 \n而大， 本叶细尔。五月有白花，七、八月结子。根紫色。 \n时珍曰∶江南深山中皆有之。根似芎 而轻虚，味麻，不堪作饮也。 \n\\x根\\x \n【气味】辛，温，无毒。《别录》曰∶微寒。权曰∶微温。 \n元素曰∶气温，味苦、大辛，无毒。气浓味薄，升也，阳也。足太阳本经药。 \n之才曰∶恶 茹，畏青葙子。 \n【主治】妇人疝瘕，阴中寒肿痛，腹中急，除风头痛，长肌肤，悦颜色（《本经》）。 \n辟雾露润泽，疗风邪 曳金疮，可作沐药面脂（《别录》）。治一百六十种恶风鬼疰，流入腰 \n痛冷，能化小便，通血，去头风 （甄权）。治皮肤疵 ，酒 粉刺，痫疾（大明）。治太 \n阳头痛巅顶痛，大寒犯脑，痛连齿颊（元素）。头面身体皮肤风湿（李杲）。督脉为病，脊强 \n而厥（好古）。治痈疽，排脓内塞（时珍）。 \n【发明】元素曰∶ 本乃太阳经风药，其气雄壮，寒气郁于本经，头痛必用之药。巅 \n顶痛非此不能除。与木香同用，治雾露之清邪中于上焦；与白芷同作面脂。既治风，又治湿， \n亦各从其类也。时珍曰∶《邵氏闻见录》云∶夏英公病泄，太医以虚治不效。霍翁曰∶风客 \n于胃也。饮以 本汤而止。盖 本能去风湿故耳。 \n【附方】新三。 \n大实心痛∶以用利药，用此彻其毒。 本半两，苍术一两。作二服。水二钟，煎一钟， \n温服。（《活法机要》） \n干洗头屑∶ 本、白芷等分。为末，夜擦旦梳，垢自去也。（《便民图纂》） \n小儿疥癣∶ 本煎汤浴之，并以浣衣。（《保幼大全》） \n\\x实\\x \n【主治】风邪流入四肢（《别录》）。 \n【附录】徐黄 《别录》有名未用曰∶味辛，平，无毒。主心腹积瘕。茎，主恶疮，生 \n泽中，大茎细叶，香如 本。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>蜘蛛香\n\n内容：（《纲目》） \n【集解】《时珍》曰∶蜘蛛香，出蜀西茂州松潘山中，草根也。黑色有粗须，状如蜘蛛 \n及本、芎 ，气味芳香，彼人亦重之。或云猫喜食之。 \n\\x根\\x \n【气味】辛，温，无毒。 \n【主治】辟瘟疫，中恶邪精，鬼气尸疰（时珍）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>白芷\n\n内容：（《本经》中品） \n【释名】白 （音止，又昌海切）、 \n（许骄切）、莞（音官），叶名 麻（音力）、药 \n时珍曰∶徐锴云∶初生根干为芷，则白芷之义取乎此也。王安石《字说》云∶ 香可以 \n养鼻，又可养体，故 字从臣。臣音怡，养也。许慎《说文》云∶晋谓之 ，齐谓之 ，楚 \n谓之蓠，又谓之药。生于下泽，芬芳与兰同德，故骚人以兰 为咏，而本草有芬香、泽芬之 \n名，古人谓之香白芷云 \n【集解】《别录》曰∶白芷生河东川谷下泽，二月、八月采根曝干。 \n弘景曰∶今处处有之，东间甚多。叶可合香。 \n颂曰∶所在有之，吴地尤多。根长尺余，粗细不等，白色。枝干去地五寸以上。春生叶， \n相对婆娑，紫色，阔三指许。花白微黄。入伏后结子，立秋后苗枯。二月、八月采根曝干。 \n以黄泽者为佳。 \n曰∶凡采勿用四条一处生者，名丧公藤。又勿用马兰根。 \n\\x根\\x \n【修治】 曰∶采得刮去土皮，细锉，以黄精片等分，同蒸一伏时，晒干去黄精用。 \n时珍曰∶今人采根洗刮寸截，以锻石拌匀，晒收，为其易蛀，并欲色白也。入药微焙。 \n【气味】辛，温，无毒。 \n元素曰∶气温，味苦、大辛。气味俱轻，阳也。手阳明引经本药，同升麻则通行手、足 \n阳明经，亦入手太阴经。 \n之才曰∶当归为之使，恶旋复花，制雄黄、硫黄。 \n【主治】女人漏下赤白，血闭阴肿，寒热，头风侵目泪出，长肌肤，润泽颜色，可作 \n面脂（《本经》）。疗风邪，久渴吐呕，两胁满，风痛，头眩目痒。可作膏药（《别录》）。治 \n目赤弩肉，去面 疵瘢，补胎漏滑落，破宿血，补新血，乳痈发背瘰 ，肠风痔 ，疮痍疥 \n癣，止痛排脓（大明）。能蚀脓，止心腹血刺痛，女人沥血腰痛，血崩（甄权）。解利手阳明 \n头痛，中风寒热，及肺经风热，头面皮肤风痹燥痒（元素）。治鼻渊鼻衄，齿痛，眉棱骨痛， \n大肠风秘，小便去血，妇人血风眩运，翻胃吐食，解砒毒蛇伤，刀箭金疮（时珍）。 \n【发明】杲曰∶白芷疗风通用，其气芳香，能通九窍，表汗不可缺也。 \n刘完素曰∶治正阳明头痛，热厥头痛，加而用之。 \n好古曰∶同辛夷、细辛用治鼻病，入内托散用长肌肉，则入阳明可知矣。 \n时珍曰∶白芷色白味辛，行手阳明庚金；性温气浓，行足阳明戊土；芳香上达，入 \n手太阴肺经。肺者，庚之弟，戊之子也。故所主之病不离三经。如头目眉齿诸病，三经之风 \n热也；如漏带痈疽诸病，三经之湿热也。风热者辛以散之，湿热者温以除之。为阳明主 \n药，故又能治血病胎病，而排脓生肌止痛。按王 《百一选方》云∶王定国病风头痛，至都 \n梁求名医杨介治之，连进三丸，即时病失。恳求其方，则用香白芷一味，洗晒为末，炼蜜丸 \n弹子大。每嚼一丸，以茶清或荆芥汤化下。遂命名都梁丸。其药治头风眩运，女人胎前产后， \n伤风头痛，血风头痛，皆效。戴原礼《要诀》亦云∶头痛挟热，项生磊块者，服之甚宜。又 \n《仙神隐书》言∶种白芷能辟蛇，则《夷坚志》所载治腹蛇伤之方，亦制以所畏也，而本 \n草不曾言及。 \n宗 曰∶《药性论》言白芷能蚀脓。今人用治带下，肠有败脓，淋露不已，腥秽殊甚， \n遂致脐腹冷痛，皆由败脓血所致，须此排脓。白芷一两，单叶红蜀葵根二两，白芍药、白枯 \n矾各半两。为末，以蜡化丸梧子大。每空心及饭前，米饮下十丸或十五丸。俟脓尽，乃以他 \n药补之。 \n【附方】旧一，新三十四。 \n一切伤寒∶神白散，又名圣僧散∶治时行一切伤寒，不问阴阳轻重、老少男女孕妇，皆 \n可服之。用白芷一两，生甘草半两，姜三片，葱白三寸，枣一枚，豉五十粒。水二碗，煎服 \n取汗。不汗再服。病至十余日未得汗者，皆可服之。此药可卜人之好恶也。如煎得黑色，或 \n误打翻，即难愈；如煎得黄色，无不愈者。煎时要至诚，忌妇人鸡犬见。（《卫生家宝方》） \n一切风邪∶方同上。 \n风寒流涕∶香白芷一两，荆芥穗一钱。为末，蜡茶点服二钱。（《百一选方》）小儿流涕， \n是风寒也。白芷末、葱白。捣丸小豆大。每茶下二十丸。仍以白芷末，姜汁调，涂太阳穴， \n乃食热葱粥取汗。（《圣惠方》） \n小儿身热∶白芷煮汤浴之。取汗避风。（《子母秘录》）头面诸风∶香白芷切，以萝卜汁 \n浸透，晒干为末。每服二钱，白汤下。或以搐鼻。（《直指方》）偏正头风，百药不治，一服 \n便可，天下第一方也。香白芷（炒）二两五钱，川芎（炒）、甘草（炒）、川乌头（半生半熟） \n各一两，为末。每服一钱，细茶、薄荷汤调下。（《谈野翁试效方》） \n头风眩运∶都梁丸，见发明下。 \n眉棱骨痛∶属风热与痰。白芷、片芩（酒炒）等分，为末。每服二钱，茶清调下。（《丹 \n溪纂要》） \n风热牙痛∶香白芷一钱，朱砂五分。为末，蜜丸芡子大。频用擦牙。此乃濠州一村妇以 \n医人者，庐州郭医云∶绝胜他药也。或以白芷、吴茱萸等分。浸水漱涎。（《医林集要》） \n一切眼疾∶白芷、雄黄为末，炼蜜丸龙眼大，朱砂为衣。每服一丸，食后茶下，日二服。 \n名还睛丸。（《普济方》） \n口齿气臭∶《百一选方》∶用香白芷七钱。为末。食后井水服一钱。《济生方》∶用白芷、 \n川芎等分。为末，蜜丸芡子大，日噙之。 \n盗汗不止∶太平白芷一两，辰砂半两。为末。每服二钱，温酒下，屡验。（《朱氏集验 \n方》）血风反胃∶香白芷一两（切片，瓦炒黄）。为末。用猪血七片，沸汤泡七次，蘸末食之， \n日一次。（《妇人良方》） \n香港脚肿痛∶白芷、芥子等分，为末。姜汁和，涂之效。（《医方摘要》） \n妇人白带∶白芷四两，以锻石半斤，淹三宿，去灰切片，炒研末。酒服二钱，日二服。 \n（《医学集成》） \n妇人难产∶白芷五钱，水煎服之。（唐瑶《经验》）胎前产后 乌金散∶治胎前产后虚损， \n月经不调，崩漏及横生逆产。用白芷、百草霜等分。为末。以沸汤入童子小便同醋调服二钱。 \n丹溪加滑石，以芎归汤调之。（《普济方》） \n大便风秘∶香白芷。炒，为末。每服二钱，米饮入蜜少许，连进二服。（《十便良方》） \n小便气淋，结涩不通。白芷（醋浸焙干）二两，为末。煎木通、甘草，酒调下一钱，连进二 \n服。 \n（《普济方》） \n鼻衄不止∶就以所出血调白芷末，涂山根，立止。（《简便方》） \n小便出血∶白芷、当归等分，为末，米饮每服二钱。（《经验方》） \n肠风下血∶香白芷为末，每服二钱，米饮下，神效。（余居士《选奇方》） \n痔漏出血∶方同上，并煎汤熏洗。（《直指方》） \n痔疮肿痛∶先以皂角烟熏之，后以鹅胆汁调白芷末涂之，即消。（《医方摘要》） \n肿毒热痛∶醋调白芷末敷之。（《卫生易简方》）乳痈初起白芷、贝母各二钱。为末，温 \n酒服之。（《秘传外科方》） \n疔疮初起∶白芷一钱，生姜一两。擂酒一盏，温服取汗，即散。此陈指挥方也。（《袖 \n珍方》） \n痈疽赤肿∶白芷、大黄等分。为末，米饮服二钱。（《经验方》）小儿丹瘤，游走入腹必 \n死。初发，急以截风散截之。白芷、寒水石为末，生葱汁调涂。（《全幼心鉴》） \n刀箭伤疮∶香白芷嚼烂涂之。（《集简方》） \n解砒石毒∶白芷末，井水服二钱。（《事林广记》） \n诸骨哽咽∶白芷、半夏等分。为末。水服一钱，即呕出。（《普济方》） \n毒蛇伤螫∶临川有人被蝮伤，即昏死，一臂如股，少顷遍身皮胀，黄黑色。一道人以新 \n汲水调香白芷末一斤，灌之。觉脐中 然，黄水自口出，腥秽逆人，良久消缩如故云。以 \n麦门冬汤调尤妙，仍以末搽之。又经山寺僧为蛇伤，一脚溃烂，百药不愈。一游僧以新水数 \n洗净腐败，见白筋、挹干，以白芷末，入胆矾、麝香少许掺之，恶水涌出。日日如此，一月 \n平复。（洪迈《夷坚志》） \n\\x叶\\x \n【主治】作浴汤，去尸虫（《别录》）。浴丹毒瘾疹风瘙（时珍）。 \n【附方】新一。 \n小儿身热∶白芷苗、苦参等分。煎浆水，入盐少许洗之。（《卫生总微论》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>芍药\n\n内容：（芍音杓，又音勺。《本经》中品） \n【释名】将离（《纲目》）、犁食（《别录》）、白术（《别录》）、余容（《别录》）、 \n铤（《别录》），白者名金芍药（《图经》）， \n时珍曰∶芍药，犹 约也。 约，美好貌。此草花容 约， \n雅翼言》∶制食之毒，莫良于芍，故得药名，亦通。郑风诗云∶伊芳其相谑，赠之以芍药 \n。《韩诗外传》云∶芍药，离草也。董子云∶芍药一名将离，故将别赠之。俗呼其花之 \n千叶者，为小牡丹；赤者为木芍药，与牡丹同名也。 \n【集解】《别录》曰∶芍药生中岳川谷及丘陵，二月、八月采根，曝干。 \n弘景曰∶今出白山、蒋山、茅山最好，白而长尺许。余处亦有而多赤，赤者小利。 \n志曰∶此有赤白两种，其花亦有赤白二色。 \n颂曰∶今处处有之，淮南者胜。春生红芽作丛，茎上三枝五叶，似牡丹而狭长，高一、 \n二尺。夏初开花，有红白紫数种，结子似牡丹子而小。秋时采根。崔豹《古今注》云∶芍药 \n有二种∶有草芍药、木芍药。木者花大而色深，俗呼为牡丹，非矣。《安期生服炼法》∶芍药 \n有金芍药，色白多脂肉；木芍药，色紫瘦多脉。 \n承曰∶《本经》芍药生丘陵。今世多用人家种植者，乃欲其花叶肥大，必加粪壤。每岁 \n八、九月取根分削，因利以为药。今淮南真阳尤多，根虽肥大而香味不佳，入药少效。 \n时珍曰∶昔人言洛阳牡丹、扬州芍药甲天下。今药中所用，亦多取扬州者。十月生芽， \n至春乃长，三月开花。其品凡三十余种，有千叶、单叶、楼子之异。入药宜单叶之根，气味 \n全浓。根之赤白，随花之色也。 \n\\x根\\x \n【修治】 曰∶凡采得，竹刀刮去皮并头土，锉细，以蜜水拌蒸，从巳至未，晒干用。 \n时珍曰∶今人多生用，惟避中寒者以酒炒，入女人血药以醋炒耳。 \n【气味】苦，平，无毒。《别录》曰∶酸，微寒，有小毒。普曰∶神农∶苦；桐君∶甘， \n无毒；岐伯∶咸；雷公∶酸。李当之∶小寒。 \n元素曰∶性寒，味酸，气浓味薄，升而微降，阳中阴也。 \n杲曰∶白芍药酸，平，有小毒，可升可降，阴也。 \n好古曰∶味酸而苦，气薄味浓，阴也，降也，为手足太阴行经药，入肝脾血分。 \n之才曰∶须丸为之使，恶石斛、芒硝，畏硝石、鳖甲、小蓟，反藜芦。 \n禹锡曰∶别本须丸作雷丸。时珍∶同白术补脾，同芎 泻肝，同人参补气，同当归补血， \n以酒炒补阴，同甘草止腹痛，同黄连 \n【主治】邪气腹痛，除血痹，破坚积，寒热疝瘕，止痛，利小便，益气（《本经》）。通 \n顺血脉，缓中，散恶血，逐贼血，去水气，利膀胱大小肠，消痈肿，时行寒热，中恶腹痛腰 \n痛（《别录》）。治脏腑壅气，强五脏，补肾气，治时疾骨热，妇人血闭不通，能蚀脓（甄权）。 \n女人一切病，胎前产后诸疾，治风补劳，退热除烦 \n，发背疮疥（大明）。泻肝，安脾肺，收胃气，止泻利，固腠理，和血脉，收阴气，敛逆 \n气（元素）。理中气，治脾虚中满，心下痞，胁下痛，善噫，肺急胀逆喘咳，太阳鼽衄目涩， \n肝血不足，阳维病苦寒热，带脉病苦腹痛满，腰溶溶如坐水中（好古）。止下痢腹痛后重（时 \n珍）。 \n【发明】志曰∶赤者，利小便下气；白者，止痛散血。 \n大明曰∶赤者补气，白者补血。 \n弘景曰∶赤者小利，俗方以止痛不减当归。白者道家亦服食之，及煮石用。 \n成无己曰∶白补而赤泻，白收而赤散。酸以收之，甘以缓之，故酸甘相合，用补阴血。 \n收逆气而除肺燥。又云∶芍药之酸，敛津液而益营血，收阴气而泄邪热。 \n元素曰∶白补赤散，泻肝补脾胃。酒浸行经，止中部腹痛；与姜同用，温经散湿通塞， \n利腹中痛，胃气不通。白芍入脾经补中焦，乃下利必用之药。盖泻利皆太阴病，故不可缺此。 \n得炙甘草为佐，治腹中痛，夏月少加黄芩，恶寒加桂，此仲景神方也。其用凡六∶安脾经， \n一也；治腹痛，二也；收胃气，三也；止泻痢，四也；和血脉，五也；固腠理，六也。 \n宗 曰∶芍药须用单叶红花者为佳，然血虚寒人禁之。古人云∶减芍药以避中寒。诚不 \n可忽。 \n震亨曰∶芍药泻脾火，性味酸寒，冬月必以酒炒。凡腹痛多是血脉凝涩，亦必酒炒用。 \n然止能治血虚腹痛，余并不治。为其酸寒收敛，无温散之功也。下痢腹痛必炒用，后重者不 \n炒。产后不可用者，以其酸寒伐生发之气也。必不得已，亦酒炒用之。 \n时珍曰∶白芍药益脾，能于土中泻木。赤芍药散邪，能行血中之滞。《日华子》言∶赤 \n补气，白治血，欠审矣。产后肝血已虚，不可更泻，故禁之。酸寒之药多矣，何独避芍药耶？ \n以此 \n杲曰∶或言古人以酸涩为收，《本经》何以言利小便？曰∶芍药能益阴滋湿而停津液， \n故小便自行，非因通利也。曰∶又言缓中何也？曰∶损其肝者缓其中，即调血也，故四物汤 \n用芍药。大抵酸涩者为收敛停湿之剂，故主手足太阴经收敛之体，又能治血海而入于九地之 \n下，后至厥阴经。白者色在西方，故补；赤者色在南方，故泻。 \n【附方】旧六，新一十。 \n服食法∶颂曰∶安期生服炼芍药法云∶芍药有二种∶救病用金芍药，色白多脂肉；其木 \n芍药，色紫瘦多脉。若取审看，勿令差错。凡采得，净洗去皮，以东流水煮百沸，阴干。停 \n三日，又于木甑内蒸之，上覆以净黄土，一日夜熟，出阴干，捣末。以麦饮或酒服三钱匕， \n日三。服满三百日，可以登岭绝谷不饥。（《图经本草》） \n腹中虚痛∶白芍药三钱，炙甘草一钱。夏月，加黄芩五分；恶寒，加肉桂一钱；冬月大 \n寒，再加桂一钱。水二盏，煎一半，温服。（《洁古用药法象》）风毒骨痛在髓中。芍药二分， \n虎骨一两（炙），为末，夹绢袋盛，酒三升，渍五日。每服三合，日三服。（《经验后方》） \n香港脚肿痛∶白芍药六两，甘草一两。为末，白汤点服。（《事林广记》） \n消渴引饮∶白芍药、甘草等分。为末。每用一钱，水煎服，日三服。鄂渚辛 之患此九 \n年，服药止而复作。苏朴授此方，服之七日顿愈。古人处方，殆不可晓，不可以平易而忽之 \n也。（陈日华《经验方》） \n小便五淋∶赤芍药一两，槟榔一个（面裹煨）。为末。每服一钱，水一盏，煎七分，空 \n心服。（《博济方》） \n衄血不止∶赤芍药为末，水服二钱匕。（《事林广记》） \n衄血咯血∶白芍药一两，犀角末二钱半。为末。新水服一钱匕，血止为限。（《古今录 \n验》） \n煎六合，入酒五合，再煎七合，空心分为两服。亦可为末，酒服二钱。（《圣惠方》） \n经水不止∶白芍药、香附子、熟艾叶各一钱半。水煎服之。（《熊氏补遗》） \n血崩带下∶赤芍药、香附子等分。为末。每服二钱，盐一捻，水一盏，煎七分，温服， \n日二服。十服见效，名如神散。（《良方》）赤白带下，年深月久不瘥者。取白芍药三两，并 \n干姜半两。锉熬令黄，捣末。空心水饮服二钱匕，日再服。《广济方》∶只用芍药炒黑，研末， \n酒服之。（《贞元广利方》） \n金疮血出∶白芍药一两。熬黄为末。酒或米饮服二钱，渐加之。仍以末敷疮上即止，良 \n验。（《广利方》） \n痘疮胀痛∶白芍药为末，酒服半钱匕。（《痘疹方》）木舌肿满，塞口杀人。红芍药、甘 \n草煎水热漱。（《圣济总录》） \n鱼骨哽咽∶白芍药嚼细咽汁。（《事林广记》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>牡丹\n\n内容：（《本经》中品） \n【释名】鼠姑（《本经》）、鹿韭（《本经》）、百两金（《唐本》）、木芍药（《纲目》）、 \n花王。时珍曰∶牡丹，以色丹者为上，虽结子而根上生苗，故谓之牡丹。唐人谓之木芍药， \n以其花似芍药，而宿干似木也。群花品中，以牡丹第一，芍药第二，故世谓牡丹为花王，芍 \n药为花相。欧阳修《花谱》所载，凡三十余种。其名或以地，或以人，或以色，或以异，详 \n见本书。 \n【集解】《别录》曰∶牡丹生巴郡山谷及汉中，二月、八月采根阴干。 \n弘景曰∶今东间亦有，色赤者为好。 \n恭曰∶生汉中、剑南。苗似羊桃，夏生白花，秋实圆绿，冬实赤色，凌冬不凋。根似芍 \n药，肉白皮丹。土人谓之百两金，长安谓之吴牡丹者，是真也。今俗用者异于此，别有臊气 \n也。 \n炳曰∶今出合州者佳，和州、宣州者并良。白者补，赤者利。 \n大明曰∶此便是牡丹花根也。巴、蜀、渝、合州者上，海盐者次之。 \n颂曰∶今丹、延、青、越、滁、和州山中皆有，但花有黄紫红白数色。此当是山牡丹， \n其茎梗枯燥，黑白色。二月于梗上生苗叶，三月开花。其花叶与人家所种者相似，但花瓣止 \n五六叶尔。五月结子黑色，如鸡头子大。根黄白色，可长五七寸，大如笔管。近世人多贵重， \n欲其花之诡异，皆秋冬移接，培以壤土，至春盛开，其状百变。故其根性殊失本真，药中不 \n可用此，绝无力也。 \n宗 曰∶牡丹花亦有绯者、深碧色者。惟山中单叶花红者，根皮入药为佳。市人或以枝 \n梗皮充之，尤谬。 \n时珍曰∶牡丹，惟取红白单瓣者入药。其千叶异品，皆人巧所致，气味不纯，不可用。 \n《花谱》载丹州、延州以西及褒斜道中最多，与荆棘无异，土人取以为薪，其根入药尤妙。 \n凡栽花者，根下着白蔹末辟虫，穴中点硫黄杀蠹，以乌贼骨针其树必枯，此物性，亦不可不 \n知也。 \n\\x根皮\\x \n【修治】 曰∶凡采得根晒干，以铜刀劈破去骨，锉如大豆许，用清酒拌蒸，从巳至未， \n晒干用。 \n【气味】辛，寒，无毒。《别录》曰∶苦，微寒。普曰∶神农、岐伯∶辛。雷公、桐君∶ \n苦，无毒。黄帝∶苦，有毒。 \n好古曰∶气寒，味苦、辛，阴中微阳，入手厥阴、足少阴经。 \n之才∶畏贝母、大黄、菟丝子。大明曰∶忌蒜、胡荽，伏砒。 \n【主治】寒热，中风螈 ，惊痫邪气，除症坚瘀血留舍肠胃，安五脏，疗痈疮（《本经》）。 \n除时气头痛，客热五劳，劳气头腰痛，风噤癞疾（《别录》）。久服轻身益寿（吴普）。治冷气， \n散诸痛，女子经脉不通，血沥腰痛（甄权）。通关腠血脉，排脓，消扑损瘀血，续筋骨，除 \n风痹，落胎下胞，产后一切冷热血气（大明）。治神志不足，无汗之骨蒸，衄血吐血（元素）。 \n和血生血凉血，治血中伏火，除 \n【发明】元素曰∶牡丹乃天地之精，为群花之首。叶为阳，发生也；花为阴，成实也。 \n丹者赤色，火也。故能泻阴胞中之火。四物汤加之，治妇人骨蒸。又曰∶牡丹皮入手厥阴、 \n足少阴，故治无汗之骨蒸；地骨皮入足少阴、手少阳，故治有汗之骨蒸。神不足者手少阴 \n，志不足者足少阴，故仲景肾气丸用之，治神志不足也。又能治肠胃积血，及吐血、衄血 \n，必用之药，故犀角地黄汤用之。 \n杲曰∶心虚，肠胃积热，心火炽甚，心气不足者，以牡丹皮为君。 \n时珍曰∶牡丹皮治手、足少阴、厥阴四经血分伏火。盖伏火即阴火也，阴火即相火也。 \n古方惟以此治相火，故仲景肾气丸用之。后人乃专以黄柏治相火，不知牡丹之功更胜也。此 \n乃千载秘奥，人所不知，今为拈出。赤花者利，白花者补，人亦罕悟，宜分别之。 \n【附方】旧三，新三。 \n疝偏坠，气胀不能动者。牡丹皮、防风等分。为末，酒服二钱，甚效。（《千金方》） \n辨疑》） \n伤损瘀血∶牡丹皮二两，虻虫二十一枚（熬过同捣末。）每旦温酒服方寸匕，血当化为 \n水下。（《贞元广利方》） \n金方》） \n解中蛊毒∶牡丹根捣末，服一钱匕，日三服。（《外台秘要》） \n【附录】鼠姑《别录》曰∶味苦，平，无毒。主咳逆上气，寒热鼠 ，恶疮邪气。一 \n名，生丹水。弘景曰∶今人不识，而牡丹一名鼠姑，鼠妇亦名鼠姑，未知孰是？ \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>木香\n\n内容：（《本经》上品） \n【释名】蜜香（《别录》）、青木香（弘景） \n时珍曰∶木香，草类也。本名蜜香，因其香气如蜜也。缘沉香中有蜜香，遂讹此为木香 \n尔。昔人谓之青木香。后人因呼马兜铃根为青木香，乃呼此为南木香、广木香以别之。今人 \n又呼一种蔷薇为木香，愈乱真矣。《三洞珠囊》云∶五香者，即青木香也。一株五根，一茎 \n五枝，一枝五叶，叶间五节，故名五香，烧之能上彻九天也。古方治痈疽有五香连翘汤，内 \n用青木香。《古乐府》云∶氍毹 五木香，皆指此也。颂曰∶《修养书》云∶正月一日取五 \n木煮汤以浴，令人至老须发黑。徐锴注云∶道家谓青木香为五香，亦云五木，多以为浴是矣。 \n《金光明经》谓之矩琵佗香。 \n弘景曰∶此即青木香也。永昌不复贡，今多从外国舶上来，乃云出大秦国。今皆以合香， \n不入药用。 \n恭曰∶此有二种，当以昆仑来者为佳，西胡来者不善。叶似羊蹄而长大，花如菊花，结 \n实黄黑，所在亦有之，功用极多。陶云不入药用，非也。 \n权曰∶《南州异物志》云∶青木香出天竺，是草根，状如甘草也。 \n颂曰∶今惟广州舶上来，他无所出。根窠大类茄子，叶似羊蹄而长大，亦有叶如山药而 \n根大开紫花者。不拘时月，采根芽为药。以其形如枯骨，味苦粘牙者为良。江淮间亦有此种， \n名土青木香，不堪药用。《蜀本草》言∶孟昶苑中亦尝种之，云苗高三、四尺，叶长八、九 \n寸，皱软而有毛，开黄花，恐亦是土木香种也。 \n曰∶其香是芦蔓根条，左盘旋。采得二十九日，方硬如朽骨。其有芦头丁盖子色青者， \n是木香神也。 \n宗 曰∶常自岷州出塞，得青木香，持归西洛。叶如牛蒡，但狭长，茎高二、三尺，花 \n黄一如金钱，其根即香也。生嚼极辛香，尤行气。 \n承曰∶木香今多从外国来，陶说为是。苏颂《图经》所载广州者，乃是木类。又载滁州、 \n海州者，乃是马兜铃根。治疗冷热，殊不相似，皆误图耳。 \n时珍曰∶木香，南方诸地皆有。《一统志》云∶叶类丝瓜，冬月取根，晒干。 \n\\x根\\x \n【修治】时珍曰∶凡入理气药，只生用，不见火。若实大肠，宜面煨熟用。 \n【气味】辛，温，无毒。 \n元素曰∶气热，味辛、苦，气味俱浓，沉而降，阴也。 \n杲曰∶苦、甘、辛，微温，降也，阴也。 \n好古曰∶辛、苦，热，味浓于气，阴中阳也。 \n【主治】邪气，辟毒疫温鬼，强志，主淋露。久服不梦寤魇寐（《本经》）。消毒，杀鬼 \n精物，温疟蛊毒，气劣气不足，肌中偏寒，引药之精（《别录》）。治心腹一切气，膀胱冷痛， \n呕逆反胃，霍乱泄泻痢疾，健脾消食，安胎（大明）。九种心痛，积年冷气， 癖症块胀痛， \n壅气上冲，烦闷羸劣，女人血气刺心，痛不可忍，末酒服之（甄权）。散滞气，调诸气，和 \n胃气，泄肺气（元素）。行肝经气。煨熟，实大肠（震亨）。治冲脉为病，逆气里急，主脬渗 \n小便秘（好古）。 \n【发明】弘景曰∶青木香，大秦国人以疗毒肿、消恶气有验。今惟制蛀虫丸用之。常以 \n煮汁沐浴大佳。 \n宗 曰∶木香专泄决胸腹间滞塞冷气，他则次之。得橘皮、肉豆蔻、生姜相佐使绝佳， \n效尤速。 \n元素曰∶木香除肺中滞气，若治中、下二焦气结滞，及不转运，须用槟榔为使。 \n震亨曰∶调气用木香，其味辛，气能上升，如气郁不达者宜之。若阴火冲上者，则反助 \n火邪，当用黄柏、知母，而少以木香佐之。 \n好古曰∶本草云∶主气劣，气不足，补也；通壅气，导一切气，破也。安胎，健脾胃， \n补也；除 癖症块，破也。其不同如此。洁古张氏 \n机曰∶与补药为佐则补，与泄药为君则泄也。 \n时珍曰∶木香乃三焦气分之药，能升降诸气。诸气 郁，皆属于肺，故上焦气滞用之者， \n乃金郁则泄之也。中气不运，皆属于脾，故中焦气滞宜之者，脾胃喜芳香也。大肠气滞则后 \n重，膀胱气不化则癃淋，肝气郁则为痛，故下焦气滞者宜之，乃塞者通之也。 \n权曰∶《隋书》言∶樊子盖为武威太守，车驾入吐谷浑，子盖以彼多瘴气，献青木香以 \n御雾露之邪。 \n颂曰∶《续传信方》着张仲景青木香丸，主阳衰诸不足。用昆仑青木香、六路诃子皮各 \n二十两。捣筛，糖和丸梧桐子大。每空腹酒下三十丸，日再，其效尤速。郑驸马去沙糖用白 \n蜜，加羚羊角十二两。用药不类古方，而云仲景，不知何从而得也？ \n【附方】旧二，新一十八。 \n中气不省，闭目不语，如中风状。南木香为末，冬瓜子煎汤灌下三钱。痰盛者，加竹沥、 \n姜汁。（《济生方》）气胀懒食∶即青木香丸，见发明下。热者牛乳下，冷者酒下。（《圣惠 \n方》） \n心气刺痛∶青木香一两，皂角（炙）一两。为末，糊丸梧子大。每汤服五十丸，甚效。 \n（《摄生方》） \n内钓腹痛∶木香、乳香、没药各五分。水煎服之。（阮氏《小儿方》） \n小肠疝气∶青木香四两，酒三斤。煮过，每日饮三次。（孙天仁《集效方》） \n气滞腰痛∶青木香、乳香各二钱。酒浸，饭上蒸，均以酒调服。（《圣惠方》） \n耳猝聋闭∶昆仑真青木香一两（切）。以苦酒浸一夜，入胡麻油一合，微火煎，三上三 \n下，以绵滤去滓，日滴三、四次，以愈为度。（《外台秘要》） \n耳内作痛∶木香末，以葱黄染鹅脂，蘸末深纳入耳中。（《圣济录》）霍乱转筋腹痛。木 \n香末一钱，木瓜汁一盏。入热酒调服。（《圣济总录》）一切下痢，不拘丈夫妇人小儿。木香 \n一块（方圆一寸），黄连半两。二味用水半升同煎干，去黄连，薄切木香，焙干为末。分作 \n三服∶第一服橘皮汤下，二服陈米饮下，三服甘草汤下。此乃李景纯所传。有一妇人久痢将 \n死，梦中观音授此方，服之而愈也。（孙兆《秘宝方》） \n香连丸方∶方见黄连下。 \n肠风下血∶木香、黄连等分为末，入肥猪大肠内，两头扎定，煮极烂，去药食肠。或连 \n药捣为丸服。（刘松石《保寿堂方》）小便混浊如精状。木香、没药、当归等分，为末，以刺 \n棘心自然汁和丸梧子大，每食前盐汤下三十丸。（《 \n小儿阴肿∶小儿阳明经风热湿气相搏，阴茎无故肿，或痛缩，宜宽此一经自愈。广木香、 \n枳壳（麸炒）二钱半，炙甘草二钱。水煎服。（曾氏《小儿方》）小儿天行壮热头痛。木香六 \n分，白檀香三分，为末，清水和服。仍温水调涂囟顶上取瘥。（《圣惠方》）天行发斑赤黑色。 \n青木香二两。水二升，煮一升服。（《外台秘要》） \n一切痈疽∶疮疖、疳 恶疮、下疰 疮溃后，外伤风寒，恶汁臭败不敛，并主之。木香、 \n黄连、槟榔等分，为末油调频涂之，取效。（《和剂局方》） \n恶蛇虺伤∶青木香不拘多少，煎水服，效不可述。（《袖珍方》） \n腋臭阴湿∶凡腋下、阴下湿臭，或作疮。青木香以好醋浸，夹于腋下、阴下。为末敷之。 \n（《外台秘要》） \n牙齿疼痛∶青木香末，入麝香少许，揩牙，盐汤漱之。（《圣济录》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>甘松香\n\n内容：（宋《开宝》） \n【释名】苦弥哆（音扯）。 \n时珍曰∶产于川西松州，其味甘，故名。《金光明经》谓之苦弥哆。 \n【集解】志曰∶《广志》云∶甘松出姑臧、凉州诸山，细叶，引蔓丛生，可合诸香及 \n衣。 \n颂曰∶今黔、蜀州郡及辽州亦有之。丛生山野，叶细如茅草，根极繁密，八月采之，作 \n汤浴令人身香。 \n\\x根\\x \n【气味】甘，温，无毒。好古曰∶平。 \n【主治】恶气，猝心腹痛满，下气（《开宝》）。黑皮 ，风疳齿 ，野鸡痔。得白芷、 \n附子良（藏器）。理元气，去气郁（好古）。香港脚膝浮，煎汤淋洗（时珍）。 \n【发明】时珍曰∶甘松芳香能开脾郁，少加入脾胃药中，甚醒脾气。杜宝《拾遗录》云∶ \n寿禅师妙医术，作五香饮。更加别药，止渴兼补益最妙。一、沉香饮；二、丁香饮；三、檀 \n香饮；四、泽兰饮；五、甘松饮也。 \n【附方】新四。 \n劳瘵熏法∶甘松六两，玄参一斤。为末。每日焚之。（《奇效方》）风疳虫牙，蚀肉至尽。 \n甘松、腻粉各二钱半，芦荟半两，猪肾一对（切，炙）。为末。夜漱口后贴之，有涎吐出。（《圣 \n济总录》） \n肾虚齿痛∶甘松、硫黄等分。为末。泡汤漱之。神效。（《经效济世方》） \n面 风疮∶香附子、甘松各 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>山柰\n\n内容：（《纲目》） \n【释名】山辣（《纲目》）、三柰。 \n时珍曰∶山柰俗讹为三柰，又讹为三赖，皆土音也。或云∶本名山辣，南人舌音呼山为 \n三，呼辣如赖，故致谬误。其说甚通。 \n【集解】时珍曰∶山柰生广中，人家栽之。根叶皆如生姜，作樟木香气。土人食其根如 \n食姜，切断曝干，则皮赤黄色，肉白色。古之所谓廉姜，恐其类也。段成式《酉阳杂俎》云 \n∶柰只出拂林国，苗长三、四尺，根大如鸭卵，叶似蒜，中心抽条甚长，茎端有花六出，红 \n白色，花心黄赤，不结子，其草冬生夏死。取花压油，涂身去风气。按此说颇似山柰，故附 \n之。 \n\\x根\\x \n【气味】辛，温，无毒。 \n【主治】暖中，辟瘴疠恶气，治心腹冷气痛，寒湿霍乱，风虫牙痛。入合诸香用（时珍）。 \n【附方】新六。 \n一切牙痛∶三柰子一钱（面包煨熟），入麝香二字。为末。随左右 一字入鼻内，口含 \n温水漱去，神效。名海上一 \n字散。（《普济方》） \n风虫牙痛∶《仁存方》∶用山柰为末，铺纸上卷作筒，烧灯吹灭，乘热和药吹入鼻内，痛 \n即止。《摄生方》∶用肥皂一个（去穣），入山柰、甘松各三分，花椒、食盐不拘多少，填满， \n面包 红，取研，日用擦牙漱去。 \n面上雀斑∶三柰子、鹰粪、密陀僧、蓖麻子等分，研匀，以乳汁调之，夜涂旦洗去。 \n醒头去屑∶三柰、甘松香、零陵香一钱，樟脑二分，滑石半两。为末。夜擦旦篦去。（《水 \n云录》） \n心腹冷痛∶三柰、丁香、当归、甘草等分为末，醋糊丸梧子大。每服三十丸，酒下。（《 \n集简方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>廉姜\n\n内容：（《拾遗》） \n【释名】姜汇（《纲目》）、蔟 （音族绥）。 \n【集解】弘景曰∶杜若苗似廉姜。 \n藏器曰∶廉姜似姜，生岭南、剑南，人多食之。 \n时珍曰∶按《异物志》云∶生沙石中，似姜，大如螺，气猛近于臭。南人以为齑。其法 \n削皮，以黑梅及盐汁渍之，乃成也。又郑樵云∶廉姜似山姜而根大。 \n【气味】辛，热，无毒。 \n【主治】胃中冷，吐水，不下食（藏器）。温中下气 \n，消食益智（时珍）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>杜若\n\n内容：（《本经》上品） \n【校正】并入《图经》外类山姜。 \n【释名】杜衡（《本经》）、杜莲（《别录》） \n子姜（ 音爪。《药性论》）、 \n颂曰∶此草一名杜衡，而草部中品自有杜衡条，即《尔雅》所谓土卤者也。杜若，即《广 \n雅》所谓楚衡者也。其类自别，古人多相杂引用。故《九歌》云∶采芳洲兮杜若。《离骚》 \n云∶杂杜衡与芳芷。王逸辈皆不分别，但云香草，故二名相混。古方或用，今人罕使，故少 \n有识者。 \n【集解】《别录》曰∶杜若，生武陵川泽及冤句，二月、八月采根，曝干。 \n弘景曰∶今处处有之。叶似姜而有纹理，根似高良姜而细，味辛香。又绝似旋复根，殆 \n欲相乱，叶小异尔。《楚辞》云∶山中人兮芳杜若，是矣。 \n恭曰∶今江湖多有之，生阴地，苗似廉姜，根似高良姜，全少辛味。陶云，似旋复根者， \n即真杜若也。 \n保升曰∶苗似山姜，花黄赤，子赤，大如棘子，中似豆蔻。今出岭南、硖州者甚好。《范 \n子计然》云∶杜衡、杜若出南郡、汉中，大者 \n颂曰∶卫州一种山姜，茎叶如姜，开紫花，不结子，八月采根入药。 \n时珍曰∶杜若人无识者，今楚地山中时有之。山人亦呼为良姜，根似姜，味亦辛。甄权 \n注豆蔻所谓 子姜，苏颂《图经》外类所谓山姜，皆此物也。或又以大者为高良姜，细者为 \n杜若。唐时峡州贡之。 \n【修治】 曰∶凡使勿用鸭喋草根，真相似，只是味效不同。凡采得根，以刀刮去黄赤 \n皮，细锉，用三重绢袋阴干。临使以蜜浸一夜，漉出用。 \n\\x根\\x \n【气味】辛，微温，无毒。 \n之才曰∶得辛夷、细辛良，恶柴胡、前胡。 \n苏颂曰∶山姜∶辛，平，有小毒。 \n【主治】胸胁下逆气，温中，风入脑户，头肿痛，多涕泪出。久服益精明目轻身。令人 \n不忘（《本经》）。治眩倒目 ，止痛，除口臭气（《别录》）。山姜∶去皮间风热，可作炸 \n汤。又主暴冷，及胃中逆冷，霍乱腹痛 \n【发明】时珍曰∶杜若乃神农上品，治足少阴、太阳诸证要药，而世不知用，惜哉。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>山姜\n\n内容：（《拾遗》） \n【释名】美草。 \n弘景曰∶东人呼为山姜，南人呼为美草。 \n时珍曰∶与杜若之山姜，名同物异也。 \n【集解】藏器曰∶山姜根及苗，并如姜而大，作樟木臭，南人食之。又有 子姜，黄色 \n而紧，辛辣，破血气殊强于此姜。 \n颂曰∶山姜出九真交趾，今闽广皆有之。刘恂《岭表录异》云∶茎叶皆姜也，但根不堪 \n食。亦与豆蔻花相似，而微小尔。花生叶间，作穗如麦粒，嫩红色。南人取其未大开者，谓 \n之含胎花，以盐水淹藏入甜糟中，经冬如琥珀色，辛香可爱，用为 ，无以加矣。又以盐杀 \n治曝干者，煎汤服之，极除冷气，甚佳。 \n时珍曰∶山姜生南方，叶似姜，花赤色甚辛，子似草豆蔻，根如杜若及高良姜。今人以 \n其子伪充草豆蔻，然其气甚猛烈。 \n\\x根\\x \n【气味】辛，热，无毒。 \n【主治】腹中冷痛，煮服甚效。作丸散服，辟谷止饥（弘景）。去恶气，温中，中恶霍 \n乱，心腹冷痛，功用如姜（藏器）。 \n\\x花及子\\x \n【气味】辛，温，无毒。 \n【主治】调中下气，破冷气作痛，止霍乱，消食，杀酒毒（大明）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>高良姜\n\n内容：（《别录》中品） \n【校正】并入《开宝本草》红豆蔻。 \n【释名】蛮姜（《纲目》），子名红豆蔻。 \n时珍曰∶陶隐居言此姜始出高良郡，故得此名。按高良，即今高州也。汉为高凉县，吴 \n改为郡。其山高而稍凉，因以为名，则高良当作高凉也。 \n【集解】弘景曰∶出高良郡，二月、三月采根。形气与杜若相似，而叶如山姜。 \n恭曰∶出岭南者，形大虚软，生江左者细紧，亦不甚辛，其实一也。今人呼细者为杜若， \n大者，为高良姜，亦非也。 \n颂曰∶今岭南诸州及黔、蜀皆有之，内郡虽有而不堪入药。春生茎叶如姜苗而大，高一、 \n二尺许。花红紫色，如山姜花。 \n曰∶红豆蔻生南海诸谷，高良姜子也。其苗如芦，其叶如姜，花作穗，嫩叶卷之而生， \n微带红色。嫩者入盐，累累作朵不散落，须以朱槿花染令色深。善醒醉，解酒毒，无他要使 \n也。 \n时珍曰∶按∶范成大《桂海志》云∶红豆蔻花丛生，叶瘦如碧芦。春末始发，初开花抽 \n一干，有大箨包之，箨拆花见。一穗数十蕊，淡红鲜妍，如桃杏花色。蕊重则下垂如葡萄， \n又如火齐璎珞及剪彩鸾枝之状。每蕊有心两瓣，人比之连理也。其子亦似草豆蔻。 \n【修治】时珍曰∶高良姜、红豆蔻，并宜炒过入药。亦有以姜同吴茱萸、东壁土炒过入 \n药用者。 \n\\x根\\x \n【气味】辛，大温，无毒。志曰∶辛、苦，大热，无毒。 \n张元素曰∶辛，热，纯阳，浮也。入足太阴、阳明经。 \n【主治】暴冷，胃中冷逆，霍乱腹痛（《别录》）。下气益声，好颜色。煮饮服之，止痢 \n（藏器）。治风破气，腹内久冷气痛，去风冷痹弱（甄权）。转筋泻痢，反胃呕食，解酒毒， \n消宿食（大明）。含块咽津，治忽然恶心，呕清水，逡巡即瘥。若口臭者，同草豆蔻为末， \n煎饮（苏颂）。健脾胃，宽噎膈，破冷癖，除瘴疟（时珍）。 \n【发明】杨士瀛曰∶噫逆胃寒者，高良姜为要药，人参、茯苓佐之，为其温胃，解散胃 \n中风邪也。 \n时珍曰∶《十全方》言∶心脾冷痛，用高良姜，细锉微炒为末，米饮服一钱，立止。太 \n祖高皇帝御制周颠仙碑文，亦载其有验云。又秽迹佛有治心口痛方云∶凡男女心口一点痛者， \n乃胃脘有滞或有虫也。多因怒及受寒而起，遂致终身。俗言心气痛者，非也。用高良姜（以 \n酒洗七次焙研），香附子（以醋洗七次焙研），各记收之。病因寒得，用姜末二钱，附末一钱； \n因怒得，用附末二钱，姜末一钱；寒怒兼有，各一钱半，以米饮加入生姜汁一匙，盐一捻， \n服之立止。韩飞霞《医通》书亦称其功云。 \n【附方】旧三，新十。 \n霍乱吐利∶火炙高良姜令焦香。每用五两，以酒一升，煮三、四沸，顿服。亦治腹痛中 \n恶。（《外台》） \n霍乱腹痛∶高良姜一两（锉）。以水三大盏，煎二盏半，去滓，入粳米一合，煮粥食之。 \n便止。（《圣惠方》）霍乱呕甚不止。用高良姜（生锉）二钱，大枣一枚。水煎冷服，立定。 \n名冰壶汤。（《普济方》） \n香港脚欲吐∶苏恭曰∶凡患香港脚人，每旦饱食，午后少食，日晚不食。若饥，可食豉粥。 \n若觉不消，欲致霍乱者。即以高良姜一两，水三升，煮一升，顿服尽，即消。若猝无者，以 \n母姜一两代之，清酒煎服。虽不及高良姜，亦甚效也。 \n心脾冷痛∶高良姜丸∶用高良姜四两（切片，分作四分∶一两用陈廪米半合，炒黄去米； \n一两用陈壁土半两，炒黄去土；一两用巴豆三十四个，炒黄去豆；一两，用斑蝥三十四个， \n炒黄去蝥），吴茱萸一两（酒浸一夜，同姜再炒）。为末，以浸茱酒打糊丸梧桐子大，每空心 \n姜汤下五十丸。《永类钤方》∶用高良姜三钱，五灵脂六 \n养脾温胃∶去冷消痰，宽胸下气，大治心脾疼及一切冷物所伤。用高良姜、干姜等分。 \n炮研末，面糊丸梧子大，每食后橘皮汤下十五丸。妊妇勿服。（《和剂局方》）脾虚寒疟，寒 \n多热少，饮食不思。用高良姜（麻油炒）、干姜（炮）各一两。为末。每服五钱，用猪胆汁 \n调成膏子，临发时热酒调服。以胆汁和丸，每服四十丸，酒下亦佳。吴开内翰，政和丁酉居 \n全椒县，岁疟大作，用此救人以百计。张大亨病此，甚欲致仕，亦服之愈。大抵寒发于胆， \n用猪胆引二姜入胆，去寒而燥脾胃，一寒一热，阴阳相制，所以作效也。一方∶只用二姜（半 \n生半炮）各半两，穿山甲（炮）三钱。为末。每服二钱，猪肾煮酒下。（《朱氏集验方》） \n妊妇疟疾∶先因伤寒变成者。用高良姜三钱（锉）。以 猪胆汁浸一夜，东壁土炒黑， \n去土，以肥枣肉十五枚，同焙为末。每用三钱，水一盏，煎热，将发时服。神妙。（《永类钤 \n方》） \n暴赤眼痛∶以管吹良姜末入鼻取嚏，或弹出鼻血，即散。（《谈野翁试验方》） \n风牙痛肿∶高良姜二寸，全蝎（焙）一枚。为末掺之，吐涎，以盐汤漱口。此乃乐清丐 \n者所传。鲍季明病此，用之果效。（王 《百一选方》） \n头痛搐鼻∶高良姜生研频搐。（《普济方》）红豆蔻（《开宝》） \n【气味】辛，温，无毒。 \n权曰∶苦，辛，多食令人舌粗，不思饮食。 \n时珍曰∶辛热，阳也，浮也，入手、足太阴经。《生生编》云。最能动火伤目致衄，食 \n料不宜用之。 \n【主治】肠虚水泻，心腹绞痛，霍乱呕吐酸水，解酒毒（志）。冷气腹痛，消瘴雾毒瓦斯， \n去宿食，温腹肠，吐泻痢疾（甄权）。治噎膈反胃，虚疟寒胀，燥湿散寒（时珍）。 \n【发明】时珍曰∶红豆蔻，李东垣脾胃药中常用之，亦取其辛热芳香，能醒脾温肺、散 \n寒燥湿、消食之功尔。若脾肺素有伏火者，切不宜用。 \n【附方】新一。 \n风寒牙痛∶红豆蔻为末，随左右以少许搐鼻中，并掺牙取涎。或加麝香。（《卫生家宝 \n方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>豆蔻\n\n内容：（《别录》上品） \n【校正】自果部移入此。 \n【释名】草豆蔻（《开宝》）、漏蔻（《异物志 \n宗 曰∶豆蔻，草豆蔻也。此是对肉豆蔻而名。若作果，则味不和。前人编入果部，不 \n知有何义意？花性热，淹至京师，味微苦不甚美，干则色淡紫。为能消酒毒，故为果尔。 \n时珍曰∶按扬雄《方言》云∶凡物盛多曰蔻。豆蔻之名，或取此义。豆象形也。《南方 \n异物志》作漏蔻，盖南人字无正音也。今虽不专为果，犹入茶食料用，尚有草果之称焉。《金 \n光明经》三十二品香药，谓之苏乞迷罗（细）。 \n【集解】《别录》曰∶豆蔻生南海。 \n恭曰∶苗似山姜，花黄白色，苗根及子亦似杜若。 \n颂曰∶草豆蔻，今岭南皆有之。苗似芦，其叶似山姜、杜若辈，根似高良姜。二月开花 \n作穗房，生于茎下，嫩叶卷之而生，初如芙蓉花，微红，穗头深红色。其叶渐展，花渐出， \n而色渐淡，亦有黄白色者。南人多采花以当果，尤贵其嫩者。并穗入盐同腌治，叠叠作朵不 \n散。又以木槿花同浸，欲其色红尔。其结实若龙眼子而锐，皮无鳞甲，皮中子如石榴瓣，夏 \n月熟时采之曝干。根苗微作樟木香，根茎子并辛香。 \n曰∶豆蔻生交趾。其根似益智，皮壳小浓，核如石榴而辛香，叶如芄兰而小。三月采 \n其叶，细破阴干用。味近苦而有甘。 \n时珍曰∶草豆蔻、草果虽是一物，然微有不同。今建宁所产豆蔻，大如龙眼而形微长， \n其皮黄白薄而棱峭，其仁大如缩砂仁而辛香气和。滇广所产草果，长大如诃子，其皮黑浓而 \n棱密，其子粗而辛臭，正如斑蝥之气。彼人皆用 茶及作食料，恒用之物。广人取生草蔻入 \n梅汁，盐渍令红，曝干荐酒，名红盐草果。其初结小者，名鹦哥舌。元朝《饮膳》，皆以草 \n果为上供。南人复用一种火杨梅伪充草豆蔻，其形圆而粗，气味辛猛而不和，人亦多用之， \n或云即山姜实也，不可不辨。 \n【修治】 曰∶凡使须去蒂，取向里子及皮，用茱萸同于 上缓炒，待茱萸微黄黑，即 \n去茱萸，取草豆蔻皮及子杵用之。 \n时珍曰∶今人惟以面裹 火煨熟，去皮用之。 \n\\x仁\\x \n【气味】辛，温，涩，无毒。 \n好古曰∶大辛热，阳也，浮也。入足太阴、阳明经。 \n【主治】温中，心腹痛，呕吐，去口臭气（《别录》）。下气，止霍乱，一切冷气，消酒 \n毒（《开宝》）。调中补胃，健脾消食，去客寒，心与胃痛（李杲）。治瘴疠寒疟，伤暑吐下泄 \n痢，噎膈反胃，痞满吐酸，痰饮积聚，妇人恶阻带下，除寒燥湿，开郁破气，杀鱼肉毒。制 \n丹砂（时珍）。 \n【发明】弘景曰∶豆蔻辛烈甚香，可常食之。其五和糁中物，皆宜人。豆蔻、廉姜、枸 \n橼、甘蕉、麂目是也。 \n宗 曰∶草豆蔻气味极辛微香，性温而调散冷气甚速。虚弱不能饮食者，宜此与木瓜 \n、乌梅、缩砂、益智、曲 、甘草、生姜同用也。 \n杲曰∶风寒客邪在胃口之上，当心作疼者，宜煨熟用之。 \n震亨曰∶草豆蔻性温，能散滞气，消膈上痰。若明知身受寒邪，口食寒物，胃脘作疼， \n方可温散，用之如鼓应桴。或湿痰郁结成病者，亦效。若热郁者不可用，恐积温成热也。必 \n用栀子之剂。 \n时珍曰∶豆蔻治病，取其辛热浮散，能入太阴阳明，除寒燥湿，开郁化食之力而已。南 \n地卑下，山岚烟瘴，饮啖酸咸，脾胃常多寒湿郁滞之病。故食料必用，与之相宜。然过多亦 \n能助脾热伤肺损目。或云∶与知母同用，治瘴疟寒热，取其一阴一阳无偏胜之害。盖草果治 \n太阴独胜之寒，知母治阳明独胜之火也。 \n【附方】旧一，新九。 \n心腹胀满短气。用草豆蔻一两，去皮为末，以木瓜生姜汤，调服半钱。（《千金方》）胃 \n弱呕逆不食。用草豆蔻仁二枚，高良姜半两，水一盏，煮取汁，入生姜汁半合，和白面作拨 \n刀，以羊肉 汁煮熟，空心食之。（《普济》 \n霍乱烦渴∶草豆蔻、黄连各一钱半，乌豆五十粒，生姜三片。水煎服之。（《圣济总录》） \n虚疟自汗不止。用草果一枚（面裹煨熟，连面研），入平胃散二钱。水煎服。（《经效济世方》） \n气虚瘴疟，热少寒多，或单寒不热，或虚热不寒。用草果仁、熟附子等分，水一盏，姜七片， \n枣一枚，煎半盏服。名果附汤。（《济生方》）脾寒疟疾，寒多热少，或单寒不热，或大便泄 \n而小便多，不能食。用草果仁、熟附子各二钱半，生姜七片，枣肉二枚。水三盏，煎一盏， \n温服。（《医方大成》） \n脾肾不足∶草果仁一两（以舶茴香一两炒香，去茴不用），吴茱萸（汤泡七次，以破故 \n纸一两炒香，去故纸不用），葫芦巴一两（以山茱萸一两炒香，去茱萸不用）。上三味为散， \n酒糊丸梧子大。每服六十丸，盐汤下。（《百一选方》） \n赤白带下∶连皮草果一枚，乳香一小块。面裹煨焦黄，同面研细。每米饮服二钱，日二 \n服。（《卫生易简方》） \n香口辟臭∶豆蔻、细辛为末，含之。（《肘后方》） \n脾痛胀满∶草果仁二个。酒煎服之。（《直指方》） \n\\x花\\x \n【气味】辛，热，无毒。 \n【主治】下气，止呕逆，除霍乱，调中补胃气，消酒毒（大明）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>白豆蔻\n\n内容：（宋《开宝》） \n【释名】多骨。 \n【集解】志曰∶白豆蔻，出伽古罗国，呼为多骨。其草形如芭蕉，叶似杜若，长八九尺"}, {"n": 14, "text": "卷十四\n\n而光滑，冬夏不凋，花浅黄色，子作朵如葡萄，初出微青，熟则变白，七月采之。 \n颂曰∶今广州、宜州亦有之，不及番舶来者佳。 \n时珍曰∶白豆蔻子圆大如白牵牛子，其壳白浓，其仁如缩砂仁。入药，去皮炒用。 \n\\x仁\\x \n【气味】辛，大温，无毒。 \n好古∶大辛热，味薄气浓，轻清而升，阳也，浮也。入手太阴经。 \n【主治】积冷气，止吐逆反胃，消谷下气（《开宝》）。散肺中滞气，宽膈进食，去白睛 \n翳膜（李杲）。补肺气，益脾胃，理元气，收脱气（好古）。治噎膈，除疟疾寒热，解酒毒（时 \n珍）。 \n【发明】颂曰∶古方治胃冷，吃食即欲吐，及呕吐六物汤，皆用白豆蔻，大抵主胃冷， \n即相宜也。 \n元素曰∶白豆蔻气味俱薄，其用有五∶专入肺经本药，一也；散胸中滞气，二也；去感 \n寒腹痛，三也；温暖脾胃，四也；治赤眼暴发，去太阳经目内大 红筋，用少许，五也。 \n时珍曰∶按杨士瀛云∶白豆蔻治脾虚疟疾，呕吐寒热，能消能磨，流行三焦，营卫一转， \n诸证自平。 \n【附方】旧一，新四。 \n胃冷恶心∶凡食即欲吐。用白豆蔻子三枚。捣细。好酒一盏，温服，并饮数服佳。（张 \n文仲《备急方》） \n人忽恶心∶多嚼白豆蔻子，最佳。（《肘后方》）小儿吐乳，胃寒者。白豆蔻仁十四个， \n缩砂仁十四个，生甘草二钱，炙甘草二钱。为末。常掺入儿口中。（危氏 \n脾虚反胃∶白豆蔻、缩砂仁各二两，丁香一两，陈廪米一升，黄土炒焦，去土研细，姜 \n汁和丸梧子大。每服百丸，姜汤下。名太仓丸。（《济生方》） \n产后呃逆∶白豆蔻、丁香各半两。研细，桃仁汤服一钱，少顷再服。（《乾坤生意》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>缩砂密\n\n内容：（宋《开宝》） \n【释名】时珍曰∶名义未详。藕下白 多密，取其密藏之意。此物实在根下，仁藏壳内， \n亦或此意欤。 \n【集解】 曰∶缩砂密，生西海及西戎等地、波斯诸国。多从安东道来。志曰∶生南地。 \n苗 \n颂曰∶今惟岭南山泽间有之。苗茎似高良姜，高三、四尺。叶青，长八、九寸，阔半寸 \n以来。三月、四月开花在根下，五、六月成实，五、七十枚作一穗，状似益智而圆，皮紧浓 \n而皱，有粟纹，外有细刺，黄赤色。皮间细子一团，八隔，可四十余粒，如大黍米，外微黑 \n色，内白而香，似白豆蔻仁。七月、八月采之，辛香可调食味，及蜜煎糖缠用。 \n\\x仁\\x \n【气味】辛，温，涩，无毒。权曰∶辛、苦。藏器曰∶酸。 \n曰∶辛、咸，平。得诃子、豆蔻、白芜夷、鳖甲良。好古曰∶辛，温，阳也，浮也。 \n入手足太阴、阳明、太阳、足少阴七经。得白檀香、豆蔻为使，入肺；得人参、益智为使， \n入脾；得黄柏、茯苓为使，入肾；得赤、白石脂为使，入大小肠也。 \n【主治】虚劳冷泻，宿食不消，赤白泄痢，腹中虚痛下气（《开宝》）。主冷气腹痛，止 \n休息气痢劳损，消化水谷，温暖脾胃（甄权）。上气咳嗽，奔豚鬼疰，惊痫邪气（藏器）。一 \n切气，霍乱转筋。能起酒香味（大明）。 \n（元素）。补肺醒脾，养胃益肾，理元气，通滞气，散寒饮胀痞，噎膈呕吐，止女子崩中， \n除咽喉口齿 \n【发明】时珍曰∶按韩 《医通》云∶肾恶燥，以辛润之。缩砂仁之辛，以润肾燥。又 \n云∶缩砂属土，主醒脾调胃，引诸药归宿丹田。香而能窜，和合五脏冲和之气，如天地以土 \n为冲和之气，故补肾药用同地黄丸蒸，取其达下之旨也。又化骨，食草木药及方士炼三黄皆 \n用之，不知其性何以能制此物也？ \n【附方】旧三，新一十三。 \n冷滑下痢，不禁虚羸。用缩砂仁熬为末，以羊子肝薄切掺之，瓦上焙干为末，入干姜末 \n等分，饭丸梧子大。每服四十丸，白汤下，日二服。又方∶缩砂仁、炮附子、干姜、浓朴、 \n陈橘皮等分。为末，饭丸梧子大。每服四十丸，米饮下，日二服。（并《药性论》）大便泻血， \n三代相传者。缩砂仁为末，米饮热服二钱，以愈为度。（《十便良方》） \n小儿脱肛∶缩砂（去皮）为末。以猪腰子一片，批开擦末在内，缚定，煮熟与儿食，次 \n服白矾丸。如气逆肿喘者，不治。（《保幼大全》）遍身肿满，阴亦肿者。用缩砂仁、土狗一 \n个，等分，研，和老酒服之。（《直指方》） \n痰气膈胀∶砂仁捣碎，以萝卜汁浸透，焙干为末。每服一、二钱，食远沸汤服。（《简 \n便方》） \n上气咳逆∶砂仁（洗净，炒研）、生姜（连皮）等分。捣烂，热酒食远泡服。（《简便 \n方》） \n子痫昏冒∶缩砂（和皮炒黑），热酒调下二钱。不饮者，米饮下。此方安胎止痛皆效， \n不可尽述。（陶隐居方）妊娠胎动，偶因所触，或跌坠伤损，致胎不安，痛不可忍者。缩砂 \n（熨斗内炒熟，去皮用仁），捣碎。每服二钱，热酒调下。须臾觉腹中胎动处极热，即胎已 \n安矣。神 \n妇人血崩∶新缩砂仁，新瓦焙研末。米饮服三钱。（《妇人良方》） \n热拥咽痛∶缩砂壳为末，水服一钱。（戴原礼方） \n牙齿疼痛∶缩砂常嚼之良。（《直指方》） \n口吻生疮∶缩砂壳 研，擦之即愈。此蔡医博秘方也。（黎居士《简易方》） \n鱼骨入咽∶缩砂、甘草等分。为末，绵裹含之咽汁，当随痰出矣。（王 《百一选方》） \n误吞诸物∶金银铜钱等物不化者，浓煎缩砂汤饮之，即下。（危氏《得效方》） \n一切食毒∶缩砂仁末，水服一、二钱。（《事林广记》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>益智子\n\n内容：（宋《开宝》） \n【释名】时珍曰∶脾主智，此物能益脾胃故也，与龙眼名益智义同。按苏轼记云∶海南 \n产益智，花实皆长穗，而分为三节。观其上中下节，以候早中晚禾之丰凶。大丰则皆实，大 \n凶皆不实，罕有三节并熟者。其为药只治水，而无益于智，其得此名，岂以其知岁耶？此亦 \n一说也，终近穿凿。 \n【集解】藏器曰∶益智出昆仑及交趾国，今岭南州郡往往有之。顾微《广州记》云∶其 \n叶似襄荷，长丈余。其根上有小枝，高八九寸，无华萼。茎如竹箭，子从心出。一枝有十子 \n丛生，大如小枣。其中核黑而皮白，核小者佳，含之摄涎秽。或四破去核，取外皮蜜煮为粽 \n食，味辛。晋卢循遗刘裕益智粽，是此也。 \n恭曰∶益智子似连翘子头未开者，苗叶花根与豆无别，惟子小尔。 \n时珍曰∶按嵇含《南方草木状》云∶益智二月花，连着实，五、六月熟。其子如笔头而 \n两头尖，长七八分，杂五味中，饮酒芬芳，亦可盐曝及作粽食。观此则顾微言其无华者，误 \n矣。今之益智子形如枣核，而皮及仁，皆似草豆蔻云。 \n\\x仁\\x \n【气味】辛，温，无毒。 \n【主治】遗精虚漏，小便余沥，益气安神，补不足，安三焦，调诸气。夜多小便者，取 \n二十四枚碎，入盐同煎服，有奇验（志）。治客寒犯胃，和中益气，及人多唾（李杲）。益脾 \n胃，理元气，补肾虚滑沥（好古）。冷气腹痛，及心气不足，梦泄赤浊，热伤心系，吐血血 \n崩诸证（时珍）。 \n【发明】刘完素曰∶益智辛热，能开发郁结，使气宣通。王好古曰∶益智本脾药，主君 \n相二火。在集香丸，则入肺；在四君子汤则入脾，在大凤髓丹则入肾，三藏互有子母相关之 \n义。当于补药中兼用之，勿多服。 \n时珍曰∶益智大辛，行阳退阴之药也，三焦、命门气弱者宜之。按杨士瀛《直指方》云∶ \n心者脾之母，进食不止于和脾，火能生土，当使心药入脾胃药中，庶几相得。故古人进食药 \n中，多用益智，土中益火也。又按洪迈《夷坚志》云∶秀川进士陆迎，忽得吐血不止，气蹶 \n惊颤，狂躁直视，至深夜欲投户而出。如是两夕，遍用方药弗瘳。夜梦观音授一方，命但服 \n一料，永除病根。梦觉记之，如方治药，其病果愈。其方∶用益智子仁一两，生朱砂二钱， \n青橘皮五钱，麝香一钱。碾为细末。每服一钱，空心灯心汤下。 \n【附方】新八。 \n小便频数，脬气不足也。雷州益智子（盐炒，去盐）、天台乌药等分，为末，酒煮山药 \n粉为糊，丸如梧子大。每服七十丸，空心盐汤下。名缩泉丸。（《朱氏集验方》）心虚尿滑， \n及赤白二浊。益智子仁、白茯苓、白术等分，为末。每服三钱，白汤调下。白浊腹满，不拘 \n男妇。用益智仁（盐水浸炒）、浓朴（姜汁炒）等分，姜三片，枣一枚，水煎服。（《永类钤 \n方》） \n小便赤浊∶益智子仁、茯神各二两，远志、甘草（水煮）各半斤，为末，酒糊丸梧子大， \n空心姜汤下五十丸。腹胀忽泻日夜不止，诸药不效，此气脱也。用益智子仁二两，浓煎饮之， \n立愈。（危氏《得效方》）妇人崩中∶益智子炒碾细。米饮入盐，服一钱。（《产宝》） \n香口辟臭∶益智子仁一两，甘草二钱。碾粉舐之。（《经验良方》） \n漏胎下血∶益智仁半两，缩砂仁一两。为末。每服三钱，空心白汤下，日二服。（胡氏 \n《济阴方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>荜茇\n\n内容：（宋《开宝》） \n【释名】荜拨。 \n时珍曰∶荜拨当作荜茇，出《南方草木状》，番语也。陈藏器《本草》作毕勃，《扶南传》 \n作逼拨，《大明会典》作毕茇。又段成式《酉阳杂俎》云∶摩伽陀国呼为荜拨梨，拂林国呼 \n为阿梨诃陀。 \n【集解】恭曰∶荜茇生波斯国。丛生，茎叶似 酱，其子紧细，味辛烈于 酱。胡人将 \n来，入食味用也。 \n藏器曰∶其根名毕勃没，似柴胡而黑硬。 \n颂曰∶今岭南有之，多生竹林内。正月发苗作丛，高三四尺，其茎如箸。叶青圆如蕺菜， \n阔二、三寸如桑，面光而浓。三月开花白色在表。七月结子如小指大，长二寸以来，青黑色， \n类椹子而长。九月取采，灰杀曝干。南人爱其辛香，或取叶生茹之。复有舶上来者，更辛香。 \n时珍曰∶段成式言∶青州防风子可乱荜茇，盖亦不然。荜茇气味正如胡椒，其形长一二 \n寸，防风子圆如胡荽子，大不相侔也。 \n【修治】 曰∶凡使，去挺用头，以醋浸一宿，焙干，以刀刮去皮粟子令净乃用，免伤 \n人肺，令人上气。 \n【气味】辛，大温，无毒。 \n时珍曰∶气热味辛，阳也，浮也。入手足阳明经。然辛热耗散，能动脾肺之火。多用令 \n人目昏，食料尤不宜之。 \n【主治】温中下气，补腰脚，杀腥气，消食，除胃冷，阴疝 癖（藏器）。霍乱冷气， \n心痛血气（大明）。水泻虚痢，呕逆醋心，产后泄痢，与阿魏和合良。得诃子、人参、桂心、 \n干姜，治脏腑虚冷肠鸣泄痢，神效（李 ）。治头痛鼻渊牙痛 \n【发明】宗 曰∶荜茇走肠胃，冷气呕吐、心腹满痛者宜之。多服走泄真气，令人肠虚 \n下重。 \n颂曰∶按《唐太宗实录》云∶贞观中，上以气痢久未痊，服名医药不应，因诏访求其 \n方。有卫士进黄牛乳煎荜茇方，御用有效。刘禹锡亦记其事云，后累试于虚冷者必效。 \n时珍曰∶牛乳煎详见兽部牛乳下。荜茇为头痛、鼻渊、牙痛要药，取其辛热，能入阳明 \n经散浮热也。 \n【附方】旧二，新八。 \n冷痰恶心∶荜茇一两，为末，食前用米汤服半钱。（《圣惠方》）暴泄身冷自汗，甚则欲 \n呕，小便清，脉微弱，宜已寒丸治之。荜茇、肉桂各二钱半，高良姜、干姜各三钱半。为末， \n糊丸梧子大。每服三十丸，姜汤下。（《和剂局》）胃冷口酸流清水，心下连脐痛。用荜茇半 \n两，浓朴（姜汁浸炙）一两。为末，入热鲫鱼肉，和丸绿豆大。每米饮下二十丸，立效。（余 \n居士《选奇方》）瘴气成块，在腹不散。用荜茇一两，大黄一两，并生为末，入麝香少许， \n炼蜜丸梧子大，每冷酒服三十丸。（《永类钤方》）妇人血气作痛，及下血无时，月水不调。 \n用荜茇（盐炒）、蒲黄（炒）等分为末，炼蜜丸梧子大。每空心温酒服三十丸，两服即止。 \n名二神丸。（陈氏方） \n偏头风痛∶荜茇为末，令患者口含温水，随左右痛，以左右鼻吸一次，有效。（《经验 \n后方》） \n鼻流清涕∶荜茇末吹之，有效。（《卫生易简方》） \n风虫牙痛∶荜茇末揩之，煎苍耳汤漱去涎。《本草权度》∶用荜茇末、木鳖子肉。研膏化 \n开，搐鼻。《圣济总录 \n\\x荜勃没\\x \n【气味】辛，温，无毒。 \n【主治】五劳七伤，冷气呕逆，心腹胀满，食不消化，阴汗寒疝核肿，妇人内冷无子， \n治腰肾冷，除血气（藏器）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>酱\n\n内容：（ ，音矩。《唐本草》） \n【释名】 子（《广志》）、土荜茇（《食疗》） \n时珍曰∶按∶嵇含云∶ 子可以调食，故谓之酱，乃荜茇之类也，故孟诜《食疗》谓之 \n土荜茇。其蔓叶名扶留藤，一作扶檑，一作浮留，莫解其义。蒌则留字之讹也。 \n【集解】恭曰∶ 酱生巴蜀中，《蜀都赋》所谓流味于番禺者。蔓生，叶似王瓜而浓大 \n光泽，味辛香，实似桑椹，而皮黑肉白。西戎亦时将来，细而辛烈。交州、爱州人家多种之， \n蔓生，其子长大，苗名浮留藤。取叶合槟榔食之，辛而香也。 \n颂曰∶今夔川、岭南皆有之。昔汉武帝使唐蒙晓谕南越。越王食蒙以 酱，曰∶西北 \n江，广数里，出番禺城下。武帝感之，遂开 、越 也。刘渊林注《蜀都赋》云∶ 酱 \n缘木而生。其子如桑椹，熟时正青，长二、三寸。以蜜及盐藏而食之，辛香。与苏恭所说大 \n同小异。盖渊林所云乃蜀产，苏恭所云乃海南者尔。今惟贵荜茇而不尚 酱，故鲜有用者。 \n李 曰∶《广州记》云∶出波斯国，实状若桑椹，紫褐色者为上，黑者是老不堪。然近 \n多黑色，少见褐者。黔中亦有，形状滋味一般。 \n时珍曰∶ 酱，今两广、滇南及川南、渝、泸、威、茂、施诸州皆有之。其苗谓之蒌叶， \n蔓生依树，根大如箸。彼人食槟榔者，以此叶及蚌灰少许同嚼食之，云辟瘴疠，去胸中恶气。 \n故谚曰∶槟榔浮留，可以忘忧。其花实即 子也。按嵇含《草木状》云∶ 酱即荜茇也。 \n生于番国者大而紫，谓之荜茇。生于番禺者小而青，谓之 子。本草以 易蒌子，非矣。蒌 \n子一名扶留，其草形全不相同。时珍窃谓 子蔓生，荜茇草生，虽同类而非一物，然其花实 \n气味功用则一也。嵇氏以二物为一物，谓 子非扶留，盖不知扶留非一种也。刘歆期《交州 \n记》云∶扶留有三种∶一名获扶留，其根香美；一名扶留藤，其味亦辛；一名南扶留，其叶 \n青味辛是矣。 \n【修治】 曰∶凡采得后，以刀刮去粗皮，捣细。每五两，用生姜自然汁五两拌之，蒸 \n一日，曝干用。 \n\\x根、叶、子\\x \n【气味】辛，温，无毒。 \n时珍曰∶气热味辛，阳也，浮也。 \n【主治】下气温中，破痰积（《唐本》）。咳逆上气，心腹虫痛，胃弱虚泻，霍乱吐逆， \n解酒食味（李 ）。散结气，心腹冷痛，消谷（孟诜）。解瘴疠，去胸中恶邪气，温脾燥热（时 \n珍）。 \n【附方】新一。 \n牙疼∶ 酱、细辛各半两，大皂荚五铤（去子，每孔入青盐烧存性）。同研末。频掺吐 \n涎。（《御药院方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>肉豆蔻\n\n内容：（宋《开宝》） \n【释名】肉果（《纲目》）、迦拘勒。 \n宗 曰∶肉豆蔻对草豆蔻为名，去壳只用肉。肉油色者佳，枯白瘦虚者劣。 \n时珍曰∶花实皆似豆蔻而无核，故名。 \n【集解】藏器曰∶肉豆蔻生胡国，胡名迦拘勒。大舶来即有，中国无之。其形圆小，皮 \n紫紧薄，中肉辛辣。 \n曰∶生昆仑，及大秦国。 \n颂曰∶今岭南人家亦种之。春生苗，夏抽茎开花，结实似豆蔻，六月、七月采。 \n时珍曰∶肉豆蔻花及实状虽似草豆蔻，而皮肉之颗则不同。颗外有皱纹，而内有斑缬纹， \n如槟榔纹。最易生蛀，惟烘干蜜封，则稍可留。 \n\\x实\\x \n【修治】 曰∶凡使，须以糯米粉熟汤搜裹豆蔻，于 灰火中煨熟，去粉用。勿令犯铁。 \n【气味】辛，温，无毒。权曰∶苦、辛。好古曰∶入手足阳明经。 \n【主治】温中，消食止泄，治积冷心腹胀痛，霍乱中恶，鬼气冷疰，呕沫冷气，小儿乳 \n霍（《开宝》）。调中下气，开胃，解酒毒，消皮外络下气（大明）。治宿食痰饮，止小儿吐逆， \n不下乳，腹痛（甄权）。主心腹虫痛，脾胃虚冷，气并冷热，虚泄赤白痢，研末粥饮服之（李 \n）。暖脾胃，固大肠 \n【发明】大明曰∶肉豆蔻调中下气，消皮外络下气，味珍，力更殊。 \n宗 曰∶亦善下气，多服则泄气，得中则和平其气。 \n震亨曰∶属金与土，为丸温中补脾。《日华子》称其下气，以脾得补而善运化，气自下 \n也。非若陈皮、香附之快泄。寇氏不详其实，遂以为不可服也。 \n机曰∶痢疾用此涩肠，为伤乳泄泻之要药。 \n时珍曰∶土爱暖而喜芳香，故肉豆蔻之辛温，理脾胃而治吐利。 \n【附方】旧一，新七。 \n暖胃除痰，进食消食。肉豆蔻二个，半夏（姜汁炒）五钱，木香二钱半，为末，蒸饼丸 \n芥子大，每食后津液下五丸、十丸。（《普济》） \n霍乱吐利∶肉豆蔻为末，姜汤服一钱。（《普济方》） \n久泻不止∶肉豆蔻（煨）一两，木香二钱半，为末，枣肉和丸，米饮服四五十丸。又方∶ \n肉豆蔻（煨）一两，熟附子七钱。为末糊丸。米饮服四五十丸。又方∶肉豆蔻（煨）、粟壳 \n（炙）等分为末，醋糊丸，米饮服四、五十丸。（并《百一选方》） \n老人虚泻∶肉豆蔻三钱（面裹煨熟，去面研），乳香一两，为末，陈米粉糊丸梧子大。 \n每服五七十丸，米饮下。此乃常州侯教授所传方。（《瑞竹堂方》） \n小儿泄泻∶肉豆蔻五钱，乳香二钱半，生姜五片。同炒黑色，去姜，研为膏收，旋丸绿 \n豆大。每量大小，米饮下。（《全幼心鉴》） \n脾泄气痢∶豆蔻一颗（米醋调面裹，煨令焦黄，和面研末），更以 子（炒研末）一两， \n相和。又以陈廪米炒焦，为末和匀。每以二钱煎作饮，调前二味三钱，旦暮各一服，便瘥。 \n（《续传信方》）冷痢腹痛，不能食者。肉豆蔻一两（去皮）。醋和面裹煨，捣末。每服一钱， \n粥饮调下。（《圣惠方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>补骨脂\n\n内容：（宋《开宝》） \n【释名】破故纸（《开宝》）、婆固脂（《药性 \n时珍曰∶补骨脂言其功也。胡人呼为婆固脂，而俗讹为破故纸也。胡韭子，因其子之状 \n相似，非胡地之韭子也。 \n【集解】志曰∶补骨脂生岭南诸州及波斯国。 \n颂曰∶今岭外山 间多有之，四川合州亦有，皆不及番舶者佳。茎高三四尺，叶小似薄 \n荷，花微紫色，实如麻子，圆扁而黑，九月采。 \n大明曰∶徐表《南州记》云，是胡韭子也。南番者，色赤；广南者色绿，入药微炒用。 \n\\x子\\x \n【修治】 曰∶此性燥毒，须用酒浸一宿，漉出，以东流水浸三日夜，蒸之，从巳至申， \n晒干用。一法∶以盐同炒过，曝干用。 \n【气味】辛，大温，无毒。权曰∶苦，辛。 \n曰∶恶甘草。 \n时珍曰∶忌芸苔及诸血，得胡桃、胡麻良。 \n【主治】五劳七伤，风虚冷，骨髓伤败，肾冷精流，及妇人血气堕胎（《开宝》）。男子 \n腰疼，膝冷囊湿，逐诸冷痹顽，止小便，利腹中冷（甄权）。兴阳事，明耳目（大明）。治肾 \n泄，通命门，暖丹田，敛精神（时珍）。 \n【发明】颂曰∶破故纸今人多以胡桃合服，此法出于唐郑相国。自叙云∶予为南海节度 \n，年七十有五。越地卑湿，伤于内外，众疾俱作，阳气衰绝，服乳石补药，百端不应。元和 \n七年，有诃陵国舶主李摩诃，知予病状，遂传此方并药。予初疑而未服，摩诃稽首固请，遂 \n服之。经七八日而觉应验。自尔常服，其功神效。十年二月，罢郡归京，录方传之。用破 \n故纸十两（净择去皮，洗过曝，捣筛令细），胡桃瓤二十两（汤浸去皮，细研如泥）。即入前 \n末，更以好蜜和，令如饴糖，瓷器盛之。旦日以暖酒二合，调药一匙服之，便以饭压。如不 \n饮酒人，以暖熟水调之。弥久则延年益气，悦心明目，补添筋骨。但禁芸苔、羊血，余无所 \n忌。此物本自外番随海舶而来，非中华所有。番人呼为补骨脂，语讹为破故纸也。王绍颜《续 \n传信方》，载其事颇详，故录之。 \n时珍曰∶此方亦可作丸，温酒服之。按白飞霞《方外奇方》云∶破故纸属火，收敛神明， \n能使心包之火与命门之火相通。故元阳坚固，骨髓充实，涩以治脱也。胡桃属木，润燥养血。 \n血属阴，恶燥，故油以润之。佐破故纸，有木火相生之妙。故语云∶破故纸无胡桃，犹水母 \n之无虾也。又破故纸恶甘草，而《瑞竹堂方》青娥丸内加之，何也？岂甘草能调和百药，恶 \n而不恶耶？又许叔微学士《本事方》云∶孙真人言补肾不若补脾，予曰补脾不若补肾。肾气 \n虚弱，则阳气衰劣，不能熏蒸脾胃。脾胃气寒，令人胸膈痞塞，不进饮食，迟于运化，或腹 \n胁虚胀，或呕吐痰涎，或肠鸣泄泻。譬如鼎釜中之物，无火力，虽终日不熟，何能消化？《济 \n生》二神丸，治脾胃虚寒泄泻，用破故纸补肾，肉豆蔻补脾。二药虽兼补，但无斡旋。往往 \n常加木香以顺其气，使之斡旋，空虚仓廪。仓廪空虚，则受物矣。屡用见效，不可不知。 \n【附方】旧二，新一十四。 \n补骨脂丸∶治下元虚败，脚手沉重，夜多盗汗，纵欲所致。此药壮筋骨，益元气。补骨 \n脂四两（炒香），菟丝子四两（酒蒸），胡桃肉一两（去皮），乳香、没药、沉香各研二钱半， \n炼蜜丸如梧子大。每服二三十丸，空心盐汤、温酒任下。自夏至起冬至止，日一服。此乃唐 \n宣宗时，张寿太尉知广州，得方于南番人。有诗云∶三年时节向边隅，人信方知药力殊。夺 \n得春光来在手，青娥休笑白髭须。（《和剂方》） \n男女虚劳∶男子女人五劳七伤，下元久冷，一切风病，四肢疼痛，驻颜壮气，乌髭须。 \n补骨脂一斤，酒浸一宿，晒干，却用乌油麻一升和炒，令麻子声绝，簸去，只取补骨脂为末， \n醋煮面糊丸如梧子大。每服二三十丸，空心温酒、盐汤任下。（《经验后方》） \n肾虚腰痛∶《经验后方》∶用破故纸一两，炒为末，温酒服三钱，神妙。或加木香一钱。 \n《和剂局方》青娥丸∶治肾气虚弱，风冷乘之，或血气相搏，腰痛如折，俯仰不利，或因劳 \n役伤肾，或卑湿伤腰，或损坠堕伤，或风寒客搏，或气滞不散，皆令腰痛，或腰间如物重坠。 \n用破故纸（酒浸炒）一斤，杜仲（去皮姜汁浸炒）一斤，胡桃肉（去皮）二十个，为末，以 \n蒜捣膏一两，和丸梧子大，每空心温酒服二十丸。妇人淡醋汤下。常服壮筋骨，活血脉，乌 \n髭须，益颜色。 \n妊娠腰痛∶通气散∶用破故纸二两，炒香为末。先嚼胡桃肉半个，空心温酒调下二钱。 \n此药神妙。（《妇人良方》） \n定心补肾∶养血返精丸∶破故纸（炒）二两，白茯苓一两（为末），没药五钱，以无灰 \n酒浸高一指，煮化和末，丸梧子大。每服三十丸，白汤下。昔有人服此，至老不衰。盖故纸 \n补肾，茯苓补心，没药养血，三者既壮，自然身安。（《朱氏集验方》）∶ \n精气不固∶破故纸、青盐等分同炒为末。每服二钱，米饮下。（《三因方》）小便无度， \n肾气虚寒。破故纸十两（酒蒸），茴香十两（盐炒），为末，酒糊丸梧子大。每服百丸，盐酒 \n下。或以末糁猪肾煨食之。（《普济方》）小儿遗尿，膀胱冷也。夜属阴，故小便不禁。破故 \n纸炒为末，每夜热汤服五分。（《婴童百问》）玉茎不痿，精滑无歇，时时如针刺，捏之则脆， \n此名肾漏。用破故纸、韭子各一两，为末。每用三钱，水二盏，煎六分服，日三次，愈则止。 \n（夏子益《奇方》） \n脾肾虚泻∶二神丸∶用破故纸（炒）半斤，肉豆蔻（生用）四两，为末，肥枣肉研膏， \n和丸梧子大，每空心米饮服五、七十丸。《本事方》∶加木香二两，名三神丸。 \n水泻久痢∶破故纸（炒）一两，粟壳（炙）四两，为末，炼蜜丸弹子大。每服一丸，姜、 \n枣同水煎服。（《百一选方》）牙痛日久肾虚也。补骨脂二两，青盐半两，炒研擦之。（《御药 \n院方》）风虫牙痛，上连头脑。补骨脂（炒）半两，乳香二钱半。为末擦之。或为丸塞孔内。 \n自用有效。（《传信适用方》）打坠腰痛，瘀血凝滞。破故纸（炒）、茴香（炒）、辣桂等分， \n为末，每热酒服二钱。故纸主腰痛行血。（《直指方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>姜黄\n\n内容：（《唐本草》） \n【释名】 \n【集解】恭曰∶姜黄根叶都似郁金。其花春生于根，与苗并出，入夏花烂无子。根有黄 \n、青、白三色。其作之方法，与郁金同。西戎人谓之 \n生异耳。 \n藏器曰∶姜黄真者，是经种三年以上老姜，能生花。花在根际，一如 荷。根节坚硬， \n气味辛辣。种姜处有之，终是难得。西番亦有来者。与郁金、 药相似。如苏恭所说，即是 \n药而非姜黄。又言姜黄是 ，郁金是胡 。如此则三物无别，递相连名，总称为 ，则功 \n状当不殊。而今郁金味苦寒，色赤，主马热病；姜黄味辛温，色黄； 味苦色青。三物不同， \n所用各别。 \n大明曰∶海南生者，即蓬莪术；江南生者，即为姜黄。 \n颂曰∶姜黄今江、广、蜀川多有之。叶青绿，长一、二尺许，阔三、四寸，有斜纹如红 \n蕉叶而小。花红白色，至中秋渐凋。春末方生，其花先生，次方生叶，不结实。根盘屈黄色， \n类生姜而圆，有节。八月采根，片切曝干。蜀人以治气胀，及产后败血攻心，甚验。蛮 \n人生啖，云可以祛邪辟恶。按郁金、姜黄、术药三物相近，苏恭不能分别，乃如一物。陈 \n藏器以色味色味分别三物，又言姜黄是三年老姜所生。近年汴都多种姜，往往有姜黄生卖乃 \n是老姜。市人买啖，云治气为最。大方亦时用之。又有廉姜，亦是其类，而自是一物。 \n时珍曰∶近时以扁如干姜形者，为片子姜黄；圆如蝉腹形者，为蝉肚郁金，并可浸水染 \n色。术形虽似郁金，而色不黄也。 \n\\x根\\x \n【气味】辛、苦，大寒，无毒。 \n藏器曰∶辛少苦多，性热不冷。云大寒，误矣。 \n【主治】心腹结积疰忤，下气破血，除风热，消痈肿，功力烈于郁金（《唐本》）。治症 \n瘕血块，通月经，治扑损瘀血，止暴风痛冷气，下食（大明）。祛邪辟恶，治气胀，产后败 \n血攻心（苏颂）。治风痹臂痛（时 \n【发明】时珍曰∶姜黄、郁金、术药三物，形状功用皆相近。但郁金入心治血；而姜黄 \n兼入脾，兼治气；术药则入肝，兼治气中之血，为不同尔。古方五痹汤用片子姜黄，治 \n风寒湿气手臂痛。戴原礼《要诀》云∶片子姜黄能入手臂治痛，其兼理血中之气可知。 \n【附方】旧二，新二。 \n心痛难忍 姜黄一两，桂三两。为末。醋汤服一钱。（《经验后方》）胎寒腹痛，啼哭吐 \n乳，大便泻青，状若惊搐，出冷汗。姜黄一钱，没药、木香、乳香二钱。为末，蜜丸芡子大。 \n每服一丸，钩藤煎汤化下。（《和剂方》）产后血痛有块。用姜黄、桂心等分，为末，酒服方 \n寸匕。血下尽即愈。（昝殷《产宝》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>郁金\n\n内容：（《唐本草》） \n【释名】马术。 \n震亨曰∶郁金无香而性轻扬，能致达酒气于高远。古人用治郁遏不能升者，恐命名因此 \n也。 \n时珍曰∶酒和郁鬯，昔人言是大秦国所产郁金花香，惟郑樵《通志》言即是此郁金。其 \n大秦三代时未通中国，安得有此草？罗愿《尔雅翼》亦云是此根，和酒令黄如金，故谓之黄 \n流。其说并通。此根形状皆似莪术 \n【集解】恭曰∶郁金生蜀地及西戎。苗似姜黄，花白质红，末秋出茎心而无实。其根黄 \n赤，取四畔子根去皮火干，马药用之，破血而补，胡人谓之马术。岭南者有实似小豆蔻 \n，不堪啖。 \n颂曰∶今广南、江西州郡亦有之，然不及蜀中者佳。四月初生苗似姜黄，如苏恭所说。 \n宗 曰∶郁金不香。今人将染妇人衣最鲜明，而不耐日炙，微有郁金之气。 \n时珍曰∶郁金有二∶郁金香是用花，见本条；此是用根者。其苗如姜，其根大小如指头， \n长者寸许，体圆有横纹如蝉腹状，外黄内赤。人以浸水染色，亦微有香气。 \n\\x根\\x \n【气味】辛、苦，寒，无毒。 \n元素曰∶气味俱浓，纯阴。 \n独孤滔曰∶灰可结砂子。 \n【主治】血积下气，生肌止血，破恶血，血淋尿血，金疮（《唐本》）。单用，治女人宿 \n血气心痛，冷气结聚，温醋摩服之。亦治马胀（甄权）。凉心（元素）。治阳毒入胃，下血频 \n痛（李杲）。治血气心腹痛，产后败血冲心欲死，失心颠狂蛊毒（时珍）。 \n【发明】震亨曰∶郁金，属火、属土与水，其性轻扬上行，治吐血衄血，唾血血腥，及 \n经脉逆行，并宜郁金末加韭汁、姜汁、童尿同服，其血自清。痰中带血者，加竹沥。又鼻血 \n上行者，郁金、韭汁加四物汤服之。 \n时珍曰∶郁金入心及包络，治血病。《经验方》治失心颠狂，用真郁金七两，明矾三两， \n为末，薄糊丸梧子大，每服五十丸，白汤下。有妇人颠狂十年，至人授此。初服心胸间有物 \n脱去，神气洒然，再服而苏。此惊忧痰血络聚心窍所致。郁金入心去恶血，明矾化顽痰故也。 \n庞安常《伤寒论》云∶斑豆始有白泡，忽搐入腹，渐作紫黑色，无脓，日夜叫乱者。郁金一 \n枚，甘草二钱半，水半碗煮干，去甘草，切片焙研为末，入真脑子（炒）半钱。每用一钱， \n以生猪血五七滴，新汲水调下。不过二服，甚者毒瓦斯从手足心出，如痈状乃瘥。此乃五死一 \n生之候也。又《范石湖文集》云∶岭南有挑生之害。于饮食中行厌胜法，鱼肉能反生于人腹 \n中，而人以死，则阴役其家。初得觉胸腹痛，次日刺人，十日则生在腹中也。凡胸膈痛，即 \n用升麻或胆矾吐之。若膈下痛，急以米汤调郁金末二钱服，即泻出恶物。或合升麻、郁金服 \n之，不吐则下。李巽岩侍郎为雷州推官，鞫狱得此方，活人甚多也。 \n【附方】旧三，新十。 \n失心颠狂∶方见发明下。 \n痘毒入心∶方见发明下。厥心气痛不可忍。郁金、附子、干姜等分，为末，醋糊丸梧子 \n大，朱砂为衣。每服三十丸，男酒女醋下。（《奇效方》）产后心痛，血气上冲欲死。郁金（烧 \n存性，为末）二钱，米醋一呷，调灌即苏。（《袖珍方》） \n自汗不止∶郁金末，卧时调涂于乳上。（《集简方》） \n衄血吐血∶川郁金为末，井水服二钱。甚者再服。（黎居士《易简方》）阳毒下血，热气 \n入胃，痛不可忍。郁金五大个，牛黄一皂荚子。为散。每服用醋浆水一盏，同煎三沸，温服。 \n（孙用和《秘宝方》） \n尿血不定∶郁金末一两，葱白一握，水一盏，煎至三合，温服，日三服。（《经验方》） \n风痰壅滞∶郁金一分，藜芦十分，为末。每服一字，温浆水调下。仍以浆水一盏漱口， \n以食压之。（《经验后方》） \n挑生蛊毒∶方见发明下。 \n中砒霜毒∶郁金末二钱。入蜜少许，冷水调服。（《事林广记》） \n痔疮肿痛∶郁金末，水调涂之，即消。（《医方摘要》） \n耳内作痛∶郁金末一钱，水调，倾入耳内，急倾出之。（《圣济总录》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>蓬莪术\n\n内容：（音述。宋《开宝》） \n【释名】 药。 \n【集解】志曰∶蓬莪术生西戎及广南诸州。叶似 荷，子似干椹，术在根下并生，一好 \n一恶，恶者有毒。西戎人取之，先放羊食，羊不食者弃之。 \n藏器曰∶一名蓬莪，黑色；二名 ，黄色；三名波杀，味甘， \n大明曰∶即南中姜黄根也。海南生者名蓬莪术。 \n颂曰∶今江浙或有之，三月生苗，在田野中。其茎如钱大，高二、三尺。叶青白色，长 \n一、二尺，大五寸以来，颇类 荷。五月有花作穗，黄色，头微紫。根如生姜，而术在根 \n下，似鸡鸭 \n\\x根\\x \n【修治】 曰∶凡使，于砂盆中以醋磨令尽，然后于火畔 \n颂曰∶此物极坚硬，难捣治，用时热灰火中煨令透，乘热捣之，即碎如粉。 \n时珍曰∶今人多以醋炒或煮熟入药，取其引入血分也。 \n【气味】苦、辛，温，无毒。 \n大明曰∶得酒、醋良。 \n【主治】心腹痛，中恶疰忤鬼气，霍乱冷气，吐酸水，解毒，食饮不消，酒研服之。又 \n疗妇人血气结积，丈夫奔豚（《开宝》）。破 癖冷气，以酒醋磨服（甄权）。治一切气，开胃 \n消食，通月经，消瘀血，止扑损痛下血，及内损恶血（大明）。通肝经聚血（好古）。 \n【发明】颂曰∶蓬莪术，古方不见用者。今医家治积聚诸气，为最要之药。与荆三棱同 \n用之良，妇人药中亦多使。 \n好古曰∶蓬莪色黑，破气中之血，入气药发诸香。虽为泄剂，亦能益气，故孙尚药用治 \n气短不能接续，及大小七香丸、集香丸、诸汤散多用此也。又为肝经血分药。 \n时珍曰∶郁金入心，专治血分之病；姜黄入脾，兼治血中之气；术入肝，治气中之血， \n稍为不同。按王执中《资生经》云∶执中久患心脾疼，服醒脾药反胀。用耆域所载蓬莪术面 \n裹炮熟研末，以水与酒醋煎服，立愈。盖此药能破气中之血也。 \n【附方】旧二，新六。 \n一切冷气，抢心切痛，发即欲死。久患心腹痛时发者，此可绝根。蓬莪术二两（醋煮）， \n木香一两（煨）。为末。每服半钱，淡醋汤下。（《卫生家宝方》）小肠脏气，非时痛不可忍。 \n蓬莪术研末，空心葱酒服一钱。（杨子建《护命方》）妇人血气，游走作痛，及腰痛。蓬莪术、 \n干漆二两，为末，酒服二钱。腰痛，核桃酒下。（《普济方》）小儿盘肠内钓痛。以莪术半两， \n用阿魏一钱，化水浸一日夜，焙研。每服一字，紫苏汤下。（《保 \n小儿气痛∶蓬莪术炮熟为末。热酒服一大钱。（《十全博救方》） \n上气喘急∶蓬莪术五钱，酒一盏半，煎八分服。（《保生方》） \n气短不接∶正元散∶治气不接续，兼治滑泄，及小便数。王丞相服之有验。用蓬莪术 \n一两，金铃子（去核）一两，为末，入蓬砂一钱，炼过研细。每服二钱，温酒或盐汤空心服。 \n（孙用和《秘宝方》） \n去滓，入牛黄两粟大，服之，甚效也。（《保幼大全》） \n浑身燎泡∶方见荆三棱。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>荆三棱\n\n内容：（宋《开宝》） \n【校正】并入《开宝》草三棱。 \n【释名】京三棱（《开宝》）、草三棱（《开宝》）、鸡爪三棱（《开宝》）、黑三棱（《图 \n经》）、石三棱。颂曰∶三棱，叶有三棱也。生荆楚地，故名荆三棱以着其地。《开宝本草》 \n作京者误矣。又出草三棱条，云即鸡爪三棱，生蜀地。二月、八月采之。其实一类，随形命 \n名尔，故并见之。 \n【集解】藏器曰∶三棱总有三、四种。京三棱，黄色体重，状若鲫鱼而小。又有黑三棱， \n状如乌梅而稍大，体轻有须，相连蔓延，作漆色，蜀人以织为器，一名 者，是也。疗体并 \n同。 \n颂曰∶京三棱旧不着所出地土，今荆襄、江淮、济南、河陕间皆有之。多生浅水旁及 \n陂泽中。春生苗，高三四尺，叶似莎草，极长，又似茭蒲叶而有三棱。五六月抽茎，高 \n四五尺，大如人指，有三棱如削成。茎端开花，大体皆如莎草而大，黄紫色。苗下即魁，初 \n生成块如附子大，或有扁者。其旁有根横贯，一根则连数魁，魁上亦出苗。其魁皆扁长，如 \n小鲫鱼，体重者，三棱也。其根末将尽一魁，未发苗，小圆如乌梅者，黑三棱也。又根之端 \n钩曲如爪者，鸡爪三棱也，皆皮黑肌白而至轻。或云∶不出苗只生细根者，谓之鸡爪三棱。 \n又不生细根者，谓之黑三棱，大小不常，其色黑，去皮即白。三者本一种，但力有刚柔，各 \n适其用。因其形为名，如乌头、乌喙，云母、云华之类，本非两物也。今人乃妄以凫茈、香 \n附子为之。又河中府有石三棱，根黄白色，形如钗股，叶绿如蒲，苗高及尺，叶上亦有三棱， \n四月开花，白色如蓼 花，五月采根，亦消积气。今举世所用三棱，皆淮南红蒲根也，泰州 \n尤多。其体至坚重，刻削鱼形，叶扁茎圆，不复有三棱，不知何缘命名为三棱也？虽太医亦 \n不以为谬。流习既久，用根者不识其苗，采药者莫究其用，因缘差失，不复辨别。今三棱皆 \n独旁引二根，无直下根，其形大体多如鲫鱼。 \n时珍曰∶三棱多生荒废陂池湿地。春时丛生，夏秋抽高茎，茎端复生数叶，开花六七枝， \n花皆细碎成穗，黄紫色，中有细子。其叶茎花实俱有三棱，并与香附苗叶花实一样，但长大 \n尔。其茎光滑三棱，如棕之叶茎。茎中有白穣，剖之织物，柔韧如藤。吕忱《字林》云∶ \n草生水中，根可缘器。即此草茎，非根也。《抱朴子》言 根花 ，亦是此草。其根多黄黑 \n须，削去须皮，乃如鲫状，非本根似鲫也。 \n\\x根\\x \n【修治】元素曰∶入用须炮熟。 \n时珍曰∶消积须用醋浸一日，炒或煮熟焙干，入药乃良。 \n【气味】苦，平，无毒。志曰∶甘，平，温。大明曰∶甘、涩，凉。 \n元素曰∶苦、甘，无毒，阴中之阳。能泻真气。真气虚者勿用。 \n【主治】老癖症瘕，积聚结块，产后恶血血结，通月水，堕胎，止痛利气（《开宝》）。 \n治气胀，破积气，消扑损瘀血，妇人血脉不调，心腹痛，产后腹痛血运（大明）。心膈痛， \n饮食不消（元素）。通肝经积血，治疮肿坚硬（ \n【发明】好古曰∶三棱色白属金，破血中之气，肝经血分药也。三棱、莪术治积块疮硬 \n者，乃坚者削之也。 \n志曰∶俗传昔人患症癖死，遗言令开腹取之。得病块，干硬如石，纹理有五色。以为异 \n物，削成刀柄。后因以刀刈三棱，柄消成水，乃知此药可疗症 \n时珍曰∶三棱能破气散结，故能治诸病。其功可近于香附而力峻，故难久服。按戴原礼 \n《证治要诀》云∶有人病症癖腹胀，用三棱、莪术，以酒煨煎服之，下一黑物如鱼而愈也。 \n【附方】旧三，新五。 \n症瘕鼓胀∶三棱煎∶用三棱根（切）一石。水五石，煮三石，去滓更煎，取三斗汁入锅 \n中，重汤煎如稠糖，密器收之。每旦酒服一匕，日二服。（《千金翼方》） \n癖气块∶草三棱、荆三棱、石三棱、青橘皮、陈橘皮、木香各半两，肉豆蔻、槟榔各 \n一两， 砂二钱，为末，糊丸梧子大，每姜汤服三十丸。（《奇效方》） 癖不瘥，胁下硬如 \n石。京三棱一两（炮），川大黄一两，为末，醋熬成膏。每日空心生姜橘皮汤下一匙，以利 \n下为度。（《圣惠方》） \n小儿气癖∶三棱煮汁作羹粥，与奶母食，日亦以枣许与儿食。小儿新生百日及十岁以下， \n无问痫热 癖等皆理之。秘妙不可具言，大效。（《子母秘录》） \n痞气胸满∶口干，肌瘦食减，或时壮热。石三棱、京三棱、鸡爪三棱（并炮），蓬莪术 \n三枚，槟榔一枚，青橘皮五十片（醋浸去白），陈仓米一合（醋浸淘过），巴豆五十个（去皮， \n同青皮、仓米炒干，去豆）。为末，糊丸绿豆大。每米饮下三丸，日一服。（《圣济总录》） \n反胃恶心，药食不下。京三棱（炮）一两半，丁香三分，为末。每服一钱，沸汤点服。（《圣 \n济总录》） \n乳汁不下∶京三棱三个，水二碗，煎汁一碗，洗奶取汁出为度，极妙。（《外台秘要》） \n浑身燎泡，如棠梨状，每个出水，有石一片，如指甲大，其泡复生，抽尽肌肤肉，即不可治。 \n用荆三棱、蓬莪术各五两，为末，分三服，酒调连进愈。（危氏《得 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>莎草、香附子\n\n内容：（《别录》中品） \n【释名】雀头香（《唐本》）、草附子（《图经》）、水香棱（《图经》）、水巴戟（《图经》）、 \n水莎（《图经》）、侯莎（《尔雅》）、莎结（《图经》）、夫须（《别录》）、续根草（《图经》）、 \n地 \n时珍曰∶《别录》止云莎草，不言用苗用根。后世皆用其根，名香附子，而不知莎草之 \n名也。其草可为笠及雨衣，疏而不沾，故字从草从沙。亦作蓑字，因其为衣垂 ，如孝子衰 \n衣之状，故又从 \n苔乃笠名，贱夫所须也。其根相附连续而生，可以合香，故谓之香附子。上古谓之雀头香。 \n按《江表传》云∶魏文帝遣使于吴求雀头香，即此。其叶似三棱及巴戟，而生下湿地，故有 \n水三棱、水巴戟之名。俗人呼为雷公头。《金光明经》谓之月萃哆。《记事珠》谓之抱灵居士。 \n【集解】《别录》曰∶莎草生田野，二月、八月采。 \n弘景曰∶方药不复用，古人为诗多用之，而无识者。乃有鼠蓑，疗体异此。 \n恭曰∶此草根名香附子，一名雀头香，所在有之，茎叶都似三棱，合和香用之。 \n颂曰∶今处处有之。苗叶如薤而瘦，根如箸头大。谨按∶唐玄宗《天宝单方图》，载水 \n香棱功状与此相类。云水香棱原生博平郡池泽中，苗名香棱，根名莎结，亦名草附子。河南 \n及淮南下湿地即有，名水莎。陇西谓之地 根。蜀郡名续根草，亦名水巴戟。今涪都最饶， \n名三棱草。用茎作鞋履，所在皆有。采苗及花与根疗病。 \n宗 曰∶香附子今人多用。虽生于莎草根，然根上或有或无。有薄皲皮，紫黑色，非多 \n毛也。刮去皮则色白。若便以根为之，则误矣。 \n时珍曰∶莎叶如老韭叶而硬，光泽有剑脊棱。五、六月中抽一茎，三棱中空，茎端复出 \n数叶。开青花成穗如黍，中有细子。其根有须，须下结子一、二枚，转相延生，子上有细黑 \n毛，大者如羊枣而两头尖。采得燎去毛，曝干货之。此乃近时日用要药，而陶氏不识，诸注 \n亦略，乃知古今药物兴废不同。如此则本草诸药，亦不可以今之不识，便废弃不收，安知异 \n时不为要药如香附者乎？ \n\\x根\\x \n【修治】 曰∶凡采得阴干，于石臼中捣之，切忌铁器。 \n时珍曰∶凡采得连苗曝干，以火燎去苗及毛。用时以水洗净，石上磨去皮，用童子小便 \n浸透，洗晒捣用。或生或炒，或以酒醋盐水浸，诸法各从本方，详见于下。又稻草煮之，味 \n不苦。 \n【气味】甘，微寒，无毒。宗 曰∶苦。颂曰∶《天宝单方》云∶辛，微寒，无毒，性 \n涩。 \n元素曰∶甘、苦，微寒，气浓于味，阳中之阴，血中之气药也。 \n时珍曰∶辛、微苦、甘，平。足厥阴、手少阳药也。能兼行十二经，入脉气分。得童子 \n小便、醋、芎 、苍术良。 \n【主治】除胸中热，充皮毛，久服利人，益气，长须眉（《别录》）。治心中客热，膀胱 \n间连胁下气妨。常日忧愁不乐，兼心忪者（苏颂）。治一切气，霍乱吐泻腹痛，肾气膀胱冷 \n气（李杲）。散时气寒疫，利三焦，解六郁，消饮食积聚，痰饮痞满， 肿腹胀，香港脚，止 \n心腹肢体头目齿耳诸痛，痈疽疮疡，吐血下血尿血，妇人崩漏带下，月候不调，胎前产后百 \n病（时珍）。 \n\\x苗及花\\x \n【主治】丈夫心肺中虚风及客热，膀胱间连胁下时有气妨，皮肤瘙痒瘾疹，饮食不多， \n日渐瘦损，常有忧愁心忪少气等证。并收苗花二十余斤锉细，以水二石五斗，煮一石五斗， \n斛中浸浴，令汗出五、六度，其瘙痒即止。四时常用，瘾疹风永除（《天宝单方图》）。煎饮 \n散气郁，利胸膈，降痰热（时珍）。 \n【发明】好古曰∶香附治膀胱两胁气妨，心忪少气，是能益气，乃血中之气药也。本草 \n不言治崩漏，而方中用治崩漏，是能益气而止血也。又能逐去瘀血，是推陈也。正如巴豆治 \n大便不通而又止泄泻同意。又云∶香附阳中之阴，血中之气药，凡气郁血气必用之。炒黑能 \n止血治崩漏，此妇人之仙药也。多服亦能走气。 \n震亨曰∶香附须用童子小便浸过，能总解诸郁，凡血气必用之药，引至气分而生血， \n此正阴生阳长之义。本草不言补，而方家言于老人有益，意有存焉。盖于行中有补理。天之 \n所以为天者，健而有常也。健运不息，所以生生无穷，即此理尔。今即香中亦用之。 \n时珍曰∶香附之气平而不寒，香而能窜。其味多辛能散，微苦能降，微甘能和。乃足厥 \n阴肝、手少阳三焦气分主药，而兼通十二经气分。生则上行胸膈，外达皮肤；熟则下走肝肾， \n外彻腰足。炒黑则止血，得童溲浸炒则入血分而补虚，盐水浸炒则入血分而润燥，青盐炒则 \n补肾气，酒浸炒则行经络，醋浸炒则消积聚，姜汁炒则化痰饮。得参、术，则补气；得归、 \n，则补血；得木香，则疏滞和中；得檀香则理气醒脾，得沉香则升降诸气，得芎 、苍术 \n则总解诸郁，得栀子、黄连则能降火热，得茯神则交济心肾，得茴香、破故纸则引气归元， \n得浓朴、半夏则决壅消胀，得紫苏、葱白则解散邪气，得三棱、莪术则消磨积块，得艾叶则 \n治血气暖子宫，乃气病之总司，女科之主帅也。飞霞子韩 云∶香附能推陈致新，故诸书皆 \n云益气。而俗有耗气之说，宜于女人不宜于男子者，非矣。盖妇人以血用事，气行则无疾。 \n老人精枯血闭，惟气是资。小儿气日充，则形乃日固。大凡病则气滞而馁，故香附于气分为 \n君药，世所罕知。臣以参、 ，佐以甘草，治虚怯甚速也。 游方外时，悬壶轻赉，治百病 \n黄鹤丹，治妇人青囊丸，随宜用引，辄有小效。人索不已，用者当思法外意可也。黄鹤丹乃 \n铢衣翁在黄鹤楼所授之方，故名。其方用香附一斤，黄连半斤，洗晒为末，水糊丸梧子大。 \n假如外感，葱姜汤下；内伤，米饮下；气病，木香汤下；血病，酒下；痰病，姜汤下；火病， \n白汤下。余可类推。青囊丸乃邵应节真人祷母病，感方士所授者。方用香附（略炒）一斤， \n乌药（略炮）五两三钱，为末，水醋煮面糊为丸。随证用引，如头痛，茶下；痰气，姜汤下； \n多用酒下，为妙。 \n【附方】旧一，新四十八。 \n服食法∶颂曰∶唐玄宗《天宝单方图》云∶水香棱根名莎结，亦名草附子，说已见前。 \n其 \n根二大升，捣熬令香，以生绢袋盛，贮于三大斗无灰清酒中浸之。春三月后，浸一日即堪服 \n；冬十月后，即七日，近暖处乃佳。每空腹温饮一盏，日夜三、四次，常令酒气相续，以知 \n为度。若不饮酒，即取根十两，加桂心五两，芜荑三两。和捣为散，以蜜和为丸，捣一千杵， \n丸 \n交感丹∶凡人中年精耗神衰。盖由心血少，火不下降；肾气惫，水不上升。致心肾隔绝， \n营卫不和。上则多惊；中则塞痞，饮食不下；下则虚冷遗精。愚医徒知峻补下田，非惟不能 \n生水滋阴，而反见衰悴。但服此方半年，屏去一切暖药，绝嗜欲，然后习秘固溯流之术，其 \n效不可殚述。俞通奉年五十一，遇铁瓮城申先生授此，服之老犹如少，年至八十五乃终也。 \n因普示群生，同登寿域。香附子一斤（新水浸一宿，石上擦去毛，炒黄），茯神（去皮木） \n四两，为末，炼蜜丸弹子大。每服一丸，侵早细嚼，以降气汤下。降气汤用香附子（如上法） \n半两，茯神二两，炙甘草一两半，为末，点沸汤服前药。（萨谦斋《瑞竹堂经验方》） \n一品丸∶治气热上攻，头目昏眩，及治偏正头痛。大香附子去皮，水煮一时，捣晒焙研 \n为末，炼蜜丸弹子大。每服一丸，水一盏，煎八分服。女人，醋汤煎之。（《奇效良方》） \n升降诸气∶治一切气病，痞胀喘哕，噫酸烦闷，虚痛走注。常服开胃消痰，散壅思食。 \n早行山行，尤宜服之，去邪辟瘴。香附子（炒）四百两，沉香十八两，缩砂仁四十八两，炙 \n甘草一百二十两，为末。每服一钱，入盐少许，白汤点服。（《和剂局方》） \n一切气疾∶心腹胀满，胸膈噎塞，噫气吞酸，痰逆呕恶，及宿酒不解。香附子一斤，缩 \n砂仁八两，甘草（炙）四两，为末，每白汤入盐点服。为粗末煎服亦可。名快气汤。（《和剂 \n局方》）调中快气，心腹刺痛。小乌沉汤∶香附子（擦去毛，焙）二十两，乌药十两，甘草 \n（炒）一两 \n心脾气痛∶白飞霞《方外奇方》云∶凡人胸膛软处一点痛者，多因气及寒起，或致终身， \n或子母相传。俗名心气痛，非也，乃胃脘有滞尔。惟此独步散，治之甚妙。香附（米醋浸， \n略炒为末），高良姜（酒洗七次，略炒为末）。俱各封收。因寒者，姜二钱，附一钱；因气者 \n，附二钱，姜一钱；因气与寒者，各等分，和匀。以热米汤入姜汁一匙，盐一捻，调下立止 \n。不过七八次除根。王 《百一方》云∶内翰吴开夫人，心痛欲死，服此即愈。《类编》 \n云∶梁混心脾痛数年不愈，供事秽迹佛，梦传此方，一服而愈，因名神授一匕散。 \n心腹诸病∶艾附丸∶治男女心气痛、腹痛、少腹痛、血气痛，不可忍者。香附子二两， \n蕲 \n》）停痰宿饮，风气上攻，胸膈不利。香附（皂荚水浸）、半夏各一两，白矾末半两，姜汁面 \n糊丸梧子大。每服三四十丸，姜汤随时下。（《仁存方》）元脏腹冷及开胃。香附子炒为末， \n每用二钱，姜、盐同煎服。（《普济方》） \n酒肿虚肿∶香附子去皮，米醋煮干，焙研为末，米醋糊丸服。久之败水从小便出，神效 \n。（《经验良方》） \n气虚浮肿∶香附子一斤，童子小便浸三日，焙为末，糊丸。每米饮下四、五十丸，日二。 \n（《丹溪心法》）老小 癖，往来疼痛。香附、南星等分，为末，姜汁糊丸梧子大，每姜汤下 \n三、三十丸。（《圣惠》） 疝胀痛及小肠气。香附末二钱，以海藻一钱煎酒，空心调下， \n并、食海藻。（《濒湖集 \n腰痛揩牙∶香附子五两，生姜二两，取自然汁浸一宿，炒黄为末，入青盐二钱，擦牙数 \n次 \n血气刺痛∶香附子（炒）一两，荔枝核（烧存性）五钱，为末。每服二钱，米饮调下。 \n（《妇 \n女人诸病∶《瑞竹堂方》∶四制香附丸∶治妇人女子经候不调，兼诸病。大香附子（擦去 \n毛）一斤，分作四分∶四两醇酒浸，四两醇醋浸，四两盐水浸，四两童子小便浸。春三、秋 \n五、夏一、冬七日。淘洗净，晒干捣烂，微焙为末，醋煮面糊丸梧子大，每酒下七十丸。瘦 \n人加泽兰、赤茯苓末二两，气虚加四君子料，血虚加四物料。《法生堂方》∶煮附济 \n阴丸∶治妇人月经不调，久成症积，一切风气。用香附子一斤（分作四分，以童溲、盐水、 \n酒、醋各浸三日），艾叶一斤（浆水浸过，醋糊和作饼，晒干），晚蚕砂半斤（炒），莪术四 \n两（酒浸），当归四两（酒浸）。各焙为末，醋糊丸梧子大。每服七十丸，米饮下，日二。醋 \n附丸∶治妇人室女一切经候不调，血气刺痛，腹胁膨胀，心怔乏力，面色痿黄，头晕恶心， \n崩漏带下，便血，症瘕积聚，及妇人数堕胎，由气不升降，服此尤妙。香附子米醋浸半日， \n砂锅煮干，捣焙，石臼为末，醋糊为丸，醋汤下。《澹寮方》艾附丸∶治同上。香附子一斤， \n熟艾四两（醋煮），当归（酒浸）二两，为末，如上丸服。妇人气盛血衰，变生诸症，头晕 \n腹满，皆宜抑气散主之。香附子四两（炒），茯苓、甘草（炙）各一两，橘红二两，为末。 \n每服二钱，沸汤下。（《济生方》）下血血崩，血如山崩，或五色漏带，并宜常服，滋血调气， \n乃妇人之仙药也。香附子去毛炒焦为末，极热酒服二钱立愈。昏迷甚者，三钱，米饮下。亦 \n可加棕灰。（许学士《本事方》）赤白带下及血崩不止。香附子、赤芍药等分，为末，盐一捻， \n水二盏，煎一盏，食前温 \n安胎顺气∶铁罩散∶香附子炒为末，浓煎紫苏汤服一二钱。一加砂仁。（《中藏经》） \n妊娠恶阻，胎气不安，气不升降，呕吐酸水，起坐不便，饮食不进。二香散∶用香附子一 \n两，藿香叶、甘草各二钱，为末。每服二钱，沸汤入盐调下。（《圣惠方》） \n临产顺胎∶九月、十月服此，永无惊恐。福胎饮∶用香附子四两，缩砂仁（炒）三两， \n甘草（炙）一两，为末。每服二钱，米饮下。（《朱氏集验方》）产后狂言，血晕，烦渴不止。 \n生香附子去毛为末，每服二钱，姜、枣水煎服。（同上） \n气郁吐血∶丹溪∶用童子小便调香附末二钱服。《澹寮方》∶治吐血不止。莎草根一两， \n白茯苓半两，为末。每服二钱，陈粟米饮下。 \n肺破咯血∶香附末一钱。米饮下，日二服。（《百一选方》） \n小便尿血∶香附子、新地榆等分各煎汤。先服香附汤三、五呷，后服地榆汤至尽。未效 \n再服。（《指迷方》）小便血淋，痛不可忍。香附子、陈皮、赤茯苓等分水煎服。（《十便良 \n方》） \n诸般下血∶香附，童子小便浸一日，捣碎，米醋拌焙为末。每服二钱，米饮下。《直指 \n方》∶用香附以醋、酒各半煮熟，焙研为末，黄秫米糊丸梧子大。每服四十丸，米饮下，日 \n二服。戴原礼云∶只以香附子末二钱，入百草霜、麝香各少许，同服，效尤速也。 \n老小脱肛∶香附子、荆芥穗等分，为末。每用三匙，水一大碗，煎十数沸淋洗。（《三 \n因 \n偏正头风∶香附子（炒）一斤，乌头（炒）一两，甘草二两，为末，炼蜜丸弹子大。每 \n服一丸，葱茶嚼下。（《本事方》） \n气郁头痛∶《澹寮方》∶用香附子（炒）四两，川芎 二两。为末。每服二钱，腊茶清调 \n下 \n头风睛痛∶方同妊娠恶阻。 \n女人头痛∶香附子末，茶服三钱，日三五服。（《经验良方》）肝虚睛痛，冷泪羞明。补 \n肝散∶用香附子一两，夏枯草半两，为末。每服一钱，茶清下。 \n耳卒聋闭∶香附子瓦炒研末，萝卜子煎汤，早夜各服二钱。忌铁器。（《卫生易简方》） \n耳出汁∶香附末，以绵杖送入。蔡邦度知府常用，有效。（《经验良方》） \n诸般牙痛∶香附、艾叶煎汤漱之，仍以香附末擦之，去涎。（《普济方》）牢牙去风，益 \n气乌髭，治牙疼牙宣，乃铁瓮先生妙方也。香附子（炒存性）三两，青盐、生姜各半两，为 \n末，日擦。（《济生方》）消渴累年不愈。莎草根一两，白茯苓半两，为末。每陈粟米饮服三 \n钱，日二。 \n痈疽疮疡∶曾孚先云∶凡痈疽疮疡，皆因气滞血凝而致，宜服诸香药，引气通血。常器 \n之云∶凡气血闻香即行，闻臭即逆。疮疡皆由气涩而血聚，最忌臭秽不洁，触之毒必引蔓。 \n陈正节公云∶大凡疽疾，多因怒气而得，但服香附子药，进食宽气，大有效也。独胜散∶ \n用香附子去毛，以生姜汁腌一宿，焙干碾为细末，无时以白汤服二钱。如疮初作，以此代茶。 \n疮溃后，亦宜服之。或只以《局方》小乌沉汤，少用甘草，愈后服至半年，尤妙。（陈自明 \n《外科精要》） \n蜈蚣咬伤∶嚼香附涂之，立效。（《袖珍方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>瑞香\n\n内容：（《纲目》） \n【集解】时珍曰∶南方州郡山中有之。枝干婆娑，柔条浓叶，四时青茂。冬春之交，开 \n花成簇，长三四分，如丁香状，有黄、白、紫三色。《格古论》云∶瑞香高者三四尺，有数 \n种∶有枇杷叶者，杨梅叶者，柯叶者，球子者，挛枝者。惟挛枝者花紫香烈，枇杷叶者结子。 \n其始出于庐山，宋时人家栽之，始著名。挛枝者其节挛曲，如断折之状也。其根绵软而香。 \n\\x根\\x \n【气味】甘、咸，无毒。 \n【主治】急喉风，用白花者研水灌之（时珍。出《医学集成》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>茉莉\n\n内容：（《纲目》） \n【释名】柰花。 \n时珍曰∶稽含《草木状》作末利，《洛阳名园记》作抹厉，《佛经》作抹利，《王龟龄集》 \n作没利，《洪迈集》作末丽。盖末利本胡语，无正字，随人会意而已。韦君呼为狎客，张敏 \n叔呼为远客。杨慎《丹铅录》云∶《晋书》都人簪柰花，即今末利花也。 \n【集解】时珍曰∶茉莉原出波斯，移植南海，今滇、广人栽莳之。其性畏寒，不宜中土 \n。弱茎繁枝，绿叶团尖。初夏开小白花，重瓣无蕊，秋尽乃止，不结实。有千叶者，红色者 \n，蔓生者。其花皆夜开，芬香可爱。女人穿为首饰，或合面脂。亦可熏茶，或蒸取液以代蔷 \n薇水。又有似茉莉而瓣大，其香清绝者，谓之狗牙，亦名雪瓣，海南有之。素馨、指甲，皆 \n其类也，并附于下。 \n\\x花\\x \n【气味】辛，热，无毒。 \n【主治】蒸油取液，作面脂头泽，长发润燥香肌，亦入茗汤（时珍）。 \n\\x根\\x \n【气味】热，有毒。 \n【主治】以酒磨一寸服，则昏迷一日乃醒；二寸二日，三寸三日。凡跌损骨节脱臼，接 \n骨者用此，则不知痛也（汪机）。 \n【附录】素馨 时珍曰∶素馨亦自西域移来，谓之耶悉茗花，即《酉阳杂俎》所载野悉 \n蜜花也。枝干袅娜，叶似茉莉而小。其花细瘦四瓣，有黄、白二色。采花压油泽头，甚香滑 \n也。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>郁金香\n\n内容：（宋《开宝》） \n【校正】禹锡曰∶陈氏言郁是草英，不当附于木部。今移入此。 \n【释名】郁金（《御览》）、红蓝花（《纲目》）、紫述香（《纲目》）、草麝香、茶矩摩（佛 \n书）。 \n颂曰∶许慎《说文解字》云∶郁，芳草也。十叶为贯，百二十贯筑以煮之。郁鬯乃百草 \n之英，合而酿酒以降神，乃远方郁人所贡，故谓之郁。郁，今郁林郡也。 \n时珍曰∶汉郁林郡，即今广西、贵州、浔、柳、邕、宾诸州之地。《一统志》惟载柳州 \n罗城县出郁金香，即此也。《金光明经》谓之茶矩摩香。此乃郁金花香，与今时所用郁金根， \n名同物异。《唐慎微本草》收此入彼下，误矣。按赵古则《六书本义》∶鬯字，象米在器中， \n以匕 之之意。郁字从臼，奉缶置于几上，鬯有 饰，五体之意。俗作郁。则郁乃取花筑酒 \n之意，非指地言，地乃因此草得名耳。 \n【集解】藏器曰∶郁金香生大秦国，二月、三月有花，状如红蓝，四月、五月采花，即 \n香也。 \n时珍曰∶按郑玄云∶郁草似兰。杨孚《南州异物志》云∶郁金出 宾，国人种之，先以 \n供佛，数日萎，然后取之。色正黄，与芙蓉花裹嫩莲者相似，可以香酒。又《唐书》云∶太 \n宗时，伽毗国献郁金香，叶似麦门冬，九月花开，状似芙蓉，其色紫碧，香闻数十步，花而 \n不实，欲种者取根。二说皆同，但花色不同，种或不一也。《古乐府》云∶中有郁金苏合香 \n者，是此郁金也。晋左贵嫔有《郁金颂》云∶伊芳有奇草，名曰郁金。越自殊域，厥珍来寻。 \n芳香酷烈，悦目怡心。明德惟馨，淑人是钦。 \n【气味】苦，温，无毒。藏器曰∶平。 \n【主治】蛊野诸毒，心腹间恶气鬼疰，鸦鹘等一切臭。入诸香药用（藏器）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>茅香\n\n内容：（宋《开宝》） \n【校正】并入宋《图经》香麻。 \n【释名】 尸罗（《金光明经》）、香麻。 \n时珍曰∶苏颂《图经》复出香麻一条，云出福州，煎汤浴风甚良，此即香茅也，闽人呼 \n茅如麻故尔。今并为一。 \n【集解】志曰∶茅香生剑南道诸州，其茎叶黑褐色，花白色，即非白茅香也。 \n颂曰∶今陕西、河东、汴东州郡亦有之，辽、泽州充贡。三月生苗，似大麦。五月开白 \n花，亦有黄花者。有结实者，有无实者。并正月、二月采根，五月采花，八月采苗。 \n宗 曰∶茅香根如茅，但明洁而长。可作浴汤，同 本尤佳。仍入印香中，合香附子用。 \n时珍曰∶茅香凡有二∶此是一种香茅也；其白茅香，别是南番一种香草。《唐慎微本草》 \n不知此义，乃以白 \n\\x花\\x \n【气味】苦，温，无毒。 \n【主治】中恶，温胃止呕吐，疗心腹冷痛（《开宝》）。 \n【附方】∶新一。 \n冷劳久病∶茅香花、艾叶四两，烧存性，研末，粟米饭丸梧子大。初以蛇床子汤下二十 \n丸至三十丸，微吐不妨，后用枣汤下，立效。（《圣济总录》） \n\\x苗、叶\\x \n【主治】作浴汤，辟邪气，令人身香（《开宝》）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>白茅香\n\n内容：（《拾遗》） \n【集解】藏器曰∶白茅香生安南，如茅根，道家用作浴汤。 \n曰∶《广志》云∶生广南山谷，合诸名香甚奇妙，尤胜舶上来者。 \n时珍曰∶此乃南海白茅香，亦今排香之类，非近道之白茅及北土茅香花也。 \n\\x根\\x \n【气味】甘，平，无毒。 \n【主治】恶气，令人身香。煮汤服，治腹内冷痛（藏器）。小儿遍身疮 ，合桃叶煎汤 \n浴之（李 ）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>排草香\n\n内容：（《纲目》） \n【集解】时珍曰∶排草香出交趾，今岭南亦或莳之。草根也，白色，状如细柳根，人多 \n伪杂之。案∶范成大《桂海志》云∶排草香状如白茅香，芬烈如麝香。人亦用以合香，诸香 \n无及之者。又有麝香木，出古城，乃老朽树心节，气颇类麝。 \n\\x根\\x \n【气味】辛，温，无毒。 \n【主治】辟臭，去邪恶气（时珍）。 \n【附录】瓶香 曰∶案陈藏器云∶生南海山谷，草之状也。其味寒无毒。主鬼魅邪精， \n天行时气，并宜烧之。水煮，洗水肿浮气。与生姜、芥子煎汤，浴风疟甚效。 \n\\x耕香\\x \n藏器曰∶生乌浒国，茎生细叶，味辛温无毒，主鬼气，调中去臭。 \n时珍曰∶二香皆草状，恐亦排草之类也，故附之。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>迷迭香\n\n内容：（《拾遗》） \n【集解】藏器曰∶《广志》云∶出西海。《魏略》云∶出大秦国。 \n时珍曰∶魏文帝时，自西域移植庭中，同曹植等各有赋。大意其草修干柔茎，细枝弱根。 \n繁花结实，严霜弗凋。收采幽杀，摘去枝叶。入袋佩之，芳香甚烈。与今之排香同气。 \n【气味】辛，温，无毒。 \n【主治】恶气，令人衣香，烧之去鬼（藏器）。 \n曰∶性平不温。合羌活为丸，烧之，辟蚊蚋。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>车香\n\n内容：（《拾遗》） \n【集解】藏器曰∶《广志》云∶ 车香生徐州，高数尺，黄叶白花。《尔雅》∶ 车，乞 \n舆。郭璞云∶香草也。 \n曰∶生海南山谷。《齐民要术》云∶凡诸树木虫蛀者。煎此香冷淋之，即辟也。 \n时珍曰∶《楚词》∶畦留夷与 车。则昔人常栽莳之，与今兰香、零陵相类也。 \n【气味】辛，温，无毒。 曰∶微寒。 \n【主治】鬼气，去臭，及虫鱼蛀蠹（藏器）。治霍乱，辟恶气，熏衣佳（ ）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>艾纳香\n\n内容：（宋《开宝》） \n【集解】志曰∶《广志》云∶艾纳出西国，似细艾。又有松树皮上绿衣，亦名艾纳，可 \n以和合诸香，烧之能聚其烟，青白不散，而与此不同。 \n禹锡曰∶案《古乐府》云∶行胡从何方？列国持何来？氍毹 五木香，迷迭艾纳及都 \n梁。是也。 \n【气味】甘，温、平，无毒。 \n【主治】去恶气杀虫，主腹冷泄痢（志）。伤寒五泄，心腹注气，止肠鸣，下寸白，烧 \n之辟瘟疫，合蜂窠浴香港脚良（ ）。治癣辟蛇（藏器）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>兜纳香\n\n内容：（《海药》） \n【集解】 曰∶案《广志》云∶出西海剽国诸 \n【气味】辛，平，无毒。藏器曰∶甘，温。 \n【主治】温中，除暴冷（藏器）。恶疮肿 ，止痛生肌，并入膏用。 \n烧之，辟远近恶气。带之夜行，壮胆安神。与茅香、柳枝煎汤浴小儿，易长（李 ）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>线香\n\n内容：（《纲目》） \n【集解】时珍曰∶今人合香之法甚多，惟线香可入疮科用。其料加减不等，大抵多用白 \n芷、芎 、独活、甘松、三柰、丁香、藿香、 本、高良姜、角茴香、连乔、大黄、黄芩、 \n柏木、兜娄香末之类，为末，以榆皮面作糊和剂，以唧 笮成线香，成条如线也。亦或盘成 \n物象字形，用铁铜丝悬 者，名龙挂香。 \n【气味】辛，温，无毒。 \n【主治】熏诸疮癣（时珍）。 \n【附方】新一。 \n杨梅毒疮∶龙挂香、孩儿茶、皂角子各一钱，银朱二钱，为末，纸卷作捻，点灯置桶中， \n以鼻吸烟，一日三次，三日止。内服解毒药，疮即干。（《集简方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>藿香\n\n内容：（宋《嘉 》） \n【校正】承曰∶宜入草部。 \n【释名】兜娄婆香。 \n时珍曰∶豆叶曰藿，其叶似之，故名。《楞严经》云∶坛前以兜娄婆香煎水洗浴。即此。 \n《法华经》谓之多摩罗跋香，《金光明经》谓之钵怛罗香，皆兜娄二字梵言也。涅 又谓之 \n迦算香。 \n【集解】禹锡曰∶按《南州异物志》云∶藿香出海边国，形如都梁，叶似水苏，可着衣 \n服中。嵇含《南方草木状》云∶出交 、九真、武平、兴古诸地，吏民自种之，榛生，五、 \n六月采，晒干乃芬香。 \n颂曰∶藿香岭南多有之，人家亦多种。二月生苗，茎梗甚密，作丛，叶似桑而小薄，六 \n月、七月采之，须黄色乃可收。《金楼子》及《俞益期笺》皆云∶扶南国人言五香共是一木。 \n其根是旃檀，节是沈香，花是鸡舌，叶是藿香，胶是熏陆。故本草以五香共条，义亦出此。 \n今南中藿香乃是草类，与嵇含所说正相符合。范晔《合香方》云∶零藿虚燥。古人乃以合熏 \n香，即此扶南之说，似涉欺罔也。 \n时珍曰∶藿香方茎有节中虚，叶微似茄叶。洁古、东垣惟用其叶，不用枝梗。今人并枝 \n梗用之，因叶多伪故耳。《唐史》云∶顿逊国出藿香，插枝便生，叶如都梁者，是也。刘欣 \n期《交州记》，言藿香似苏合香者，谓其气相似，非谓形状也。 \n\\x枝叶\\x \n【气味】辛，微温，无毒。 \n元素曰∶辛、甘。又曰∶甘、苦，气浓味薄，浮而升，阳也。 \n杲曰∶可升可降，阳也。入手、足太阴经。 \n【主治】风水毒肿，去恶气，止霍乱心腹痛（《别录》）。脾胃吐逆为要药（苏颂）。助胃 \n气，开胃口，进饮食（元素）。温中快气，肺虚有寒，上焦壅热，饮酒口臭，煎汤漱口（好 \n古）。 \n【发明】杲曰∶芳香之气助脾胃，故藿香能止呕逆，进饮食。好古曰∶手、足太阴之药。 \n故入顺气乌药散，则补肺；入黄 、四君子汤，则补脾也。 \n【附方】新六。升降诸气∶藿香一两，香附（炒）五两，为末，每以白汤点服一钱。（《经 \n效济世方》）霍乱吐泻垂死者，服之回生。用藿香叶、陈皮各半两，水二盏，煎一盏，温服。 \n（《百一选方》）暑月吐泻∶滑石（炒）二两，藿香二钱半，丁香五分为末。每服一二钱，淅 \n米泔调服。（禹讲师《经验方》）胎气不安，气不升降，呕吐酸水。香附、藿香、甘草二钱。 \n为末。每服二钱，入盐少许，沸汤调服之。（《圣惠》）香口去臭∶藿香洗净，煎汤，时时噙 \n漱。（《摘玄方》） \n冷露疮烂∶藿香叶、细茶等分，烧灰，油调涂叶上，贴之。（《应验方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>零陵香\n\n内容：（宋《开宝》） \n【释名】蕙草（《别录》）、香草（《开宝》）、 \n时珍曰∶古者烧香草以降神，故曰薰，曰蕙。薰者熏也，蕙者和也。《汉书》云∶薰以 \n香自烧，是矣。或云∶古人祓除，以此草熏之，故谓之薰，亦通。范成《大虞衡志》言∶零 \n陵即今永州，不出此香。惟融、宜等州甚多，土人以编席荐，性暖宜人。谨按∶零陵旧治在 \n今全州。全乃湘水之源，多生此香，今人呼为广零陵香者，乃真薰草也。若永州、道州、武 \n冈州，皆零陵属地也。今镇江、丹阳皆莳而刈之，以酒洒制货之，芬香更烈，谓之香草，与 \n兰草同称。《楚辞》云∶既滋兰之九畹，又树蕙之百亩，则古人皆栽之矣。张揖《广雅》云∶ \n卤，薰也。其叶谓之蕙。而黄山谷言一干数花者为蕙。盖因不识兰草、蕙草，强以兰花为分 \n别也。郑樵《修本草》，言兰即蕙，蕙即零陵香，亦是臆见，殊欠分明。但兰草、蕙草，乃 \n一类二种耳。 \n【集解】《别录》曰∶薰草，一名蕙草，生下湿地，三月采阴干，脱节者良。又曰∶蕙 \n实，生鲁山平泽。 \n弘景曰∶《桐君药录》∶薰草叶如麻，两两相对。《山海经》云∶浮山有草，麻叶而方 \n茎，赤华而黑实，气如蘼芜，名曰薰草，可以已疠。今俗人皆呼燕草状如茅而香者为薰草 \n，人家颇种之者，非也。诗书家多用蕙，而竟不知是何草，尚其名而迷其实，皆此类也。 \n藏器曰∶薰草即是零陵香，薰乃蕙草根也。 \n志曰∶零陵香生零陵山谷，叶如罗勒。《南越志》云∶土人名燕草，又名薰草，即香草 \n也。《山海经》薰草即是此。 \n颂曰∶零陵香今湖岭诸州皆有之，多生下湿地，叶如麻，两两相对，茎方，常以七月中 \n旬开花至香，古云薰草是也。岭南人皆作窑灶，以火炭焙干，令黄色乃佳。江淮亦有土生者， \n亦可作香，但不及湖岭者，至枯槁香尤芬熏耳。古方但用薰草，不用零陵香。今合香家及面 \n脂、澡豆诸法皆用之。都下市肆货之甚便。 \n时珍曰∶今惟吴人栽造，货之亦广。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>薰草\n\n内容：（《别录》中品） \n【气味】甘，平，无毒。权曰∶苦，无毒。 \n曰∶辛，温，无毒。不宜多服，令人气喘。 \n【主治】明目止泪，疗泄精，去臭恶气，伤寒头痛，上气腰痛（《别录》）。单用，治鼻 \n中息肉，鼻 （甄权）。零陵香∶主恶气疰心腹痛满，下气，令体香，和诸香作汤丸用，得 \n酒良（《开宝》）。主风邪冲心，虚劳疳 。得升麻、细辛煎饮，治牙齿肿痛善（李 ）。治血 \n气腹胀，茎叶煎酒服（大明）。妇人浸油饰发，香无以加 \n【发明】时珍曰∶薰草芳馨，其气辛散上达，故心腹恶气齿痛鼻塞皆用之。脾胃喜芳 \n香，芳香可以养鼻是也。多服作喘，为能耗散真气也。 \n【附方】新十。 \n伤寒下痢∶蕙草汤∶用蕙草、当归各二两，黄连四两，水六升，煮二升服，日三服。（《范 \n汪方》）伤寒狐惑，食肛者。蕙草、黄连各四两。 咀，以白酸浆一斗，渍一宿，煮取二升， \n分三服。（《短剧方》）头风旋运，痰逆恶心懒食。真零陵香、霍香叶、莎草根（炒）等分， \n为末。每服二钱，茶下，日三服。（《本事方》）小儿鼻塞头热。用薰草一两，羊髓三两。铫 \n内慢火熬成膏，去滓，日摩背上三、四次。（《圣惠方》） \n头风白屑∶零陵香、白芷等分，水煎汁，入鸡子白搅匀，敷数十次，终身不生。（《圣 \n惠方》）。 \n牙齿疼痛∶零陵香梗叶煎水，含漱之。（《普济方》） \n风牙疳牙∶零陵香（洗炙）、荜茇（炒）等分，为末掺之。（《普济方》） \n梦遗失精∶薰草汤∶用薰草、人参、白术、白芍药、生地黄各二两，茯神、桂心、甘草 \n（炙）各二两，大枣十二枚，水八升，煮三升，分二服。（《外台秘要》） \n妇人断产∶零陵香为末，酒服二钱。每服至一两，即一年绝孕。盖血闻香即散也。（《医 \n林集要》） \n五色诸痢∶返魂丹∶用零陵香草去根，以盐酒浸半月，炒干。每两入广木香一钱半，为 \n末。里急腹痛者，用冷水服一钱半，通了三、四次，用热米汤服一钱半，止痢。只忌生梨一 \n味。（《集简方》） \n【气味】辛，平，无毒。 \n【主治】明目补中（《别录》）。 \n\\x根茎中涕\\x \n【主治】伤寒寒热出汗，中风面肿，消渴热中，逐水（《别录》）。主五痔脱肛有虫（时 \n珍。出《千金》）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>兰草\n\n内容：（《本经》上品） \n【释名】 （音闲）、水香（《本经》）、香水兰（《开宝》）、女兰（《纲目》）、香草（《纲 \n目》）、燕尾香（《开宝》）、大泽兰（《炮炙论》）、煎泽草（弘景）、兰泽草（《唐本》）、省 \n头草（《纲目》）、都梁香（李当之）、孩儿菊（《纲目》）、千金草。 \n志曰∶叶似马兰，故名兰草。其叶有歧，俗呼燕尾香。时人煮水以浴，疗风，故又名香 \n水兰。藏器曰∶兰草生泽畔，妇人和油泽头，故云兰泽。盛弘之《荆州记》云∶都梁有山， \n下 \n时珍曰∶都梁即今之武冈州也，又临淮盱眙县亦有都梁山，产此香。兰乃香草，能辟不 \n祥。陆玑《诗疏》言∶郑俗，三月男女秉 于水际，以自祓除。盖兰以阑之， 以闲之，其 \n义一也。《淮南子》云∶男子种兰，美而不芳。则兰须女子种之，女兰之名，或因乎此。其 \n叶似菊，女子、小儿喜佩之，则女兰、孩菊之名，又或以此也。《唐瑶经验方》言∶江南人 \n家种之，夏月采置发中，令头不 ，故名省头草。其说正合煎泽之义。古人兰蕙皆称香草， \n如零陵香草、都梁香草。后人省之，通呼为香草尔。近世但知兰花，不知兰草。惟虚谷方回 \n考订，极言古之兰草即今之千金草，俗名孩儿菊者，其说可据。详下正误。 \n【集解】《别录》曰∶兰草生太吴池泽，四月、五月采。 \n弘景曰∶方药俗人并不识用。太吴应是吴国太伯所居，故呼太吴。今东间有煎泽草，名 \n兰香，或者此也。李当之云∶是今人所种都梁香草也。泽兰亦名都梁香。 \n恭曰∶兰即兰泽香草也。圆茎紫萼，八月花白。俗名兰香，煮以洗浴。生溪涧水旁，人 \n间亦多种之，以饰庭池。陶所引煎泽草、都梁香者是也，而不能的识。 \n保升曰∶生下湿地，叶似泽兰，尖长有歧，花红白色而香。 \n藏器曰∶兰草、泽兰二物同名，陶不能知，苏亦浪别。兰草生泽畔，叶光润，阴小紫， \n五月、六月采阴干，即都梁香也。泽兰叶尖微有毛，不光润，茎方节紫，初采微辛，干之亦 \n辛。苏云八月花白者，即泽兰也，以注兰草，殊误矣。 \n时珍曰∶兰草、泽兰一类二种也。俱生水旁下湿处。二月宿根生苗成丛，紫茎素枝，赤 \n节绿叶，叶对节生，有细齿。但以茎圆节长，而叶光有岐者，为兰草；茎微方，节短而叶有 \n毛者，为泽兰。嫩时并可 而佩之，八、九月后渐老，高者三四尺，开花成穗，如鸡苏花， \n红白色，中有细子。雷 《炮炙论》所谓大泽兰，即兰草也；小泽兰，即泽兰也。《礼记》 \n佩兰 ，《楚辞》纫秋兰以为佩，《西京杂记》载汉时池苑种兰以降神，或杂粉藏衣书中辟 \n蠹者，皆此二兰也。今吴人莳之，呼为香草，夏月刈取，以酒油洒制，缠作把子，货为头泽 \n佩带，与《别录》所出太吴之文正相符合。诸家不知二兰乃一物二种，但功用有气血之分， \n故无定指，惟寇氏、朱氏之误尤甚，故考证于下。或云家莳者为兰草，野生者为泽兰，亦通。 \n【正误】寇宗 曰∶兰草诸家之说异同，乃未的识，故无定论。今江陵、鼎、澧州山谷 \n之间颇有之，山外平田即无，多生阴地幽谷。叶如麦门冬而阔且韧，长及一、二尺，四时常 \n青。花黄绿色，中间瓣上有细紫点。春芳者为春兰，色深；秋芳者为秋兰，色淡。开时满室 \n尽香，与他花香又别。 \n朱震亨曰∶兰叶禀金水之气而似有火，人知其花香之贵，而不知其叶有药方。盖其叶能 \n散久积陈郁之气甚有力，即今之栽置座右者。 \n时珍曰∶二氏所说，乃近世所谓兰花，非古之兰草也。兰有数种，兰草、泽兰生水旁， \n山兰即兰草之生山中者。兰花亦生山中，与三兰迥别。兰花生近处者，叶如麦门冬而春花； \n生福建者，叶如菅茅而秋花。黄山谷所谓一干一花为兰，一干数花为蕙者，盖因不识兰草、 \n蕙草，遂以兰花强生分别也。兰草与泽兰同类，故陆玑言∶兰似泽兰，但广而长节。《离骚》 \n言∶其绿叶紫茎素枝，可纫可佩可藉可膏可浴。《郑诗》言∶士女秉 ；应劭《风俗通》言∶ \n尚书奏事，怀香握兰。《礼记》言∶诸侯贽薰，大夫贽兰。《汉书》言∶兰以香自烧也。若夫 \n兰花，有叶无枝，可玩而不可纫佩藉浴秉握膏焚。故朱子《离骚辨证》言∶古之香草必花叶 \n俱香，而燥湿不变，故可刈佩。今之兰蕙，但花香而叶乃无气，质弱易萎，不可刈佩，必非 \n古人所指甚明。古之兰似泽兰，而蕙即今之零陵香。今之似茅而花有两种者，不知何时误也？ \n熊太古《冀越集》言∶世俗之兰，生于深山穷谷，决非古时水泽之兰也。《遁斋闲览》言∶ \n楚骚之兰，或以为都梁香，或以为泽兰，或以为猗兰，当以泽兰为正。今人所种如麦门冬者， \n名幽兰，非真兰也。故陈止斋着《盗兰说》以讥之。方虚谷《订兰说》言∶古之兰草，即今 \n之千金草，俗名孩儿菊者。今之所谓兰，其叶如茅而嫩者，根名土续断，因花馥郁，故得兰 \n名也。杨升庵云∶世以如蒲萱者为兰，九畹之受诬久矣。又吴草庐有《兰说》甚详，云兰为 \n医经上品之药，有枝有茎，草之植者也。今所谓兰，无枝无茎，因黄山谷称之，世遂谬指为 \n《离骚》之兰。寇氏《本草》亦溺于俗，反疑旧说为非。夫医经为实用，岂可误哉？今之兰 \n，果可利水杀蛊而除痰癖乎？其种盛于闽，朱子乃闽人，岂不识其土产而反辨析如此？世俗 \n至今犹以非兰为兰，何其惑之难解也？呜呼！观诸儒之明析如此，则寇、朱二氏之误可知， \n而医家用兰草者当不复疑矣。 \n\\x叶\\x \n【修治】见泽兰下。 \n【气味】辛，平，无毒。杲曰∶甘、寒。 \n【主治】利水道，杀蛊毒，辟不祥。久服益气轻身不老，通神明（《本经》）。除胸中痰 \n癖（《别录》）。生血，调气，养营（雷 ）。其气清香，生津止渴，润肌肉，治消渴胆瘅（李 \n杲）。煮水，浴风病（马志）。消痈肿，调月经。煎水，解中牛马毒（时珍）。主恶气，香泽 \n可作膏涂发（藏器）。 \n【发明】时珍曰∶按《素问》云∶五味入口，藏于脾胃，以行其精气。津液在脾 \n，令人口甘，此肥美所发也。其气上溢，转为消渴。治之以兰，除陈气也。王冰注云∶辛能 \n发散故也。李东垣治消渴生津饮，用兰叶，盖本于此，详见泽兰下。又此草浸油涂发，去风 \n垢，令香润。《史记》所谓罗襦襟解，微闻香泽者是也。崔实《四时月令》作香泽法∶用清 \n油浸兰香、藿香、鸡舌香、苜蓿叶四种，以新绵裹，浸胡麻油，和猪脂纳铜铛中，沸定，下 \n少许青蒿，以绵幂瓶，铛嘴泻出，瓶收用之。 \n【附方】新一。 \n食牛马毒杀人者。省头草（连根叶），煎水服，即消。（《唐瑶经验方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>泽兰\n\n内容：（《本经》中品） \n【校正】并入《嘉 》地笋。 \n【释名】水香（《吴普》）、都梁香（弘景）、虎兰（《本经》）、虎蒲（《别录》）、龙枣（《本 \n经》）、孩儿菊（《纲目》）、风药（《纲目》），根名地笋（《嘉 》）。弘景曰∶生于泽旁， \n故名泽兰，亦名都梁香。时珍曰∶此草亦可为香泽，不独指其生泽旁也。齐安人呼为风药， \n《吴普本草》一名水香，陶氏云亦名都梁，今俗通呼为孩儿菊，则其与兰草为一物二种，尤 \n可证矣。其根可食，故曰地笋。 \n【集解】《别录》曰∶泽兰生汝南诸大泽旁，三月三日采，阴干。普曰∶生下地水旁， \n叶如兰，二月生苗，赤节，四叶相值枝节间。弘景曰∶今处处有之。多生下湿地。叶微香， \n可煎油及作浴汤。人家多种之，而叶小异。今山中又有一种甚相似，茎方，叶小强，不甚香。 \n既云泽兰，则山中者为非，而药家乃采用之。恭曰∶泽兰茎方节紫，叶似兰草而不甚香，今 \n京下用者是也。陶说乃是兰草，茎圆紫萼白花，殊非泽兰也。颂曰∶今荆、徐、随、寿、蜀 \n、梧州、河中府皆有之。根紫黑色，如粟根。二月生苗，高二三尺。茎干青紫色，作四棱。 \n叶生相对，如薄荷，微香。七月开花，带紫白色，萼通紫色，亦似薄荷花。三月采苗阴干。 \n荆湖岭南人家多种之。寿州出者无花子。此与兰草大抵相类。但兰草生水旁，叶光润，阴小 \n紫，五、六月盛；而泽兰生水泽中及下湿地，叶尖，微有毛，不光润，方茎紫节，七月八 \n月初采微辛，此为异尔。 曰∶凡使须别雌雄。大泽兰茎叶皆圆，根青黄，能生血调气 \n；与荣合小泽兰迥别，叶上斑，根头尖，能破血，通久积。 \n宗 曰∶泽兰出土，便分枝梗，叶皆如菊，但尖长尔。吴普言叶似兰，误矣。今兰叶如 \n麦门冬，殊不相似。 \n时珍曰∶吴普所说，乃真泽兰也。雷 所说，大泽兰即兰草也；小泽兰即此泽兰也。寇 \n宗所说泽兰则是，而破吴普之说则非，盖由误认兰花为兰草也。详见兰草正误下。 \n\\x叶\\x \n【修治】 曰∶凡用大、小泽兰，细锉，以绢袋盛，悬于屋南畔角上，令干用。 \n【气味】苦，微温，无毒。《别录》曰∶甘。普曰∶神农、黄帝、岐伯、桐君∶酸，无 \n毒。李当之∶小温。权曰∶苦、辛。 \n之才曰∶防己为之使。 \n【主治】乳妇内衄，中风余疾，大腹水肿，身面四肢浮肿，骨节中水，金疮，痈肿疮脓 \n（《本经》）。产后金疮内塞（《别录》）。产后腹痛，频产血气衰冷，成劳瘦羸，妇人血沥腰 \n痛（甄权）。产前产后百病，通九窍，利关节，养血气，破宿血，消症瘕，通小肠，长肌肉， \n消扑损瘀血，治鼻血吐血，头风目痛，妇人劳瘦，丈夫面黄（大明）。 \n【发明】颂曰∶泽兰，妇人方中最为急用。古人治妇人泽兰丸甚多。 \n时珍曰∶兰草、泽兰气香而温，味辛而散，阴中之阳，足太阴、厥阴经药也。脾喜芳香， \n肝宜辛散。脾气舒，则三焦通利而正气和；肝郁散，则营卫流行而病邪解。兰草走气道，故 \n能利水道，除痰癖，杀蛊辟恶，而为消渴良药；泽兰走血分，故能治水肿，涂痈毒，破瘀血， \n消症瘕，而为妇人要药。虽是一类而功用稍殊，正如赤、白茯苓、芍药，补泻皆不同也。雷 \n言∶雌者调气生血，雄者破血通积，正合二兰主治。大泽兰之为兰草，尤可凭据。血生于 \n气，故曰调气生血也。又荀子云∶泽芷以养鼻，谓泽兰、白芷之气，芳香通乎肺也。 \n【附方】旧一，新四。产后水肿，血虚浮肿。泽兰、防己等分，为末。每服二钱，醋汤 \n下。（张文仲《备急方》） \n疮肿初起∶泽兰，捣封之，良。（《集简方》） \n损伤瘀肿∶方同上。 \n产后阴翻∶产后阴户燥热，遂成翻花。泽兰四两，煎汤熏洗二、三次，再入枯矾煎洗之， \n即安。（《集简方》） \n\\x地笋\\x \n（宋《嘉 》） \n【气味】甘、辛，温，无毒。 \n【主治】利九窍，通血脉，排脓治血（藏器）。止鼻洪吐血，产后心腹痛。产妇可作蔬 \n菜食，佳（大明）。 \n\\x子\\x \n【主治】妇人三十六疾（《千金方》承泽丸中用之）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>马兰\n\n内容：（《日华》） \n【释名】紫菊。 \n时珍曰∶其叶似兰而大，其花似菊而紫，故名。俗称物之大者，为马也。 \n【集解】藏器曰∶马兰生泽旁，如泽兰而气臭，《楚词》以恶草喻恶人，北人见其花呼 \n为紫菊，以其似单瓣菊花而紫也。又有山兰，生山侧，似刘寄奴，叶无桠，不对生，花心微 \n黄赤。亦大破血，皆可用。 \n时珍曰∶马兰，湖泽卑湿处甚多。二月生苗，赤茎白根，长叶有刻齿，状似泽兰，但不 \n香尔。南人多采 晒干，为蔬及馒馅。入夏高二三尺，开紫花，花罢有细子。《楚辞》无马 \n兰之名，陈氏指为恶草，何据？ \n\\x根、叶\\x \n【气味】辛，平，无毒。 \n【主治】破宿血，养新血，止鼻衄吐血，合金疮，断血痢，解酒疸及诸菌毒、蛊毒。生 \n捣，涂蛇咬（大明）。主诸疟及腹中急痛，痔疮（ \n【发明】时珍曰∶马兰辛平，能入阳明血分，故治血与泽兰同功。近人用治痔漏云有效， \n春夏取生，秋冬取干者，不用盐醋，白水煮食，并饮其汁。或以酒煮焙研，糊丸，米饮日日 \n服之。仍用煎水入盐少许，日日熏洗之。《医学集成》云∶治痔用马兰根，捣敷片时，看肉 \n平即去之。稍迟，恐肉反出也。 \n【附方】新六。 \n诸疟寒热∶赤脚马兰捣汁，入水少许，发日早服，或入少糖亦可。（《圣济总录》）绞肠 \n沙痛∶马兰根叶，细嚼咽汁，立安。（《寿域神方》） \n打伤出血∶竹节草即马兰，同旱莲草、松香、皂子叶（即柜子叶，冬用皮）。为末。搽 \n入刀口。（《摘玄方》） \n喉痹口紧∶用地白根即马兰根，或叶捣汁，入米醋少许，滴鼻孔中，或灌喉中，取痰自 \n开。（孙一松《试效方》） \n水肿尿涩∶马兰菜一虎口，黑豆、小麦各一撮。酒、水各一钟，煎一钟，食前温服以利 \n小水，四五日愈。（杨起《简便方》） \n缠蛇丹毒∶马兰、甘草擂醋搽之。（《济急方》） \n【附录】麻伯 《别录》有名未用曰∶味酸、无毒。主益气出汗。一名君莒，一名衍草， \n一名道止，一名自死。生平陵，如兰，叶黑浓白裹茎，实赤黑。九月采根。相乌又曰∶味苦。 \n主阴痿。一名乌葵。如兰香，赤茎，生山阳，五月十五日采，阴干。天雄草又曰∶味甘，温， \n无毒。主益气阴痿。生山泽中，状如兰，实如大豆，赤色。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>益奶草\n\n内容：（《拾遗》） \n藏器曰∶味苦，平，无毒。主五痔脱肛，止血。炙令香，浸酒服。生永嘉山谷，叶如泽 \n兰，茎赤，高二、三尺也。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>香薷\n\n内容：（音柔。《别录》中品） \n【校正】自菜部移入此。 \n【释名】香柔（《食疗》）、香茸（同上）、 \n香菜（《千金》）、蜜蜂草（《纲目》）。 \n时珍曰∶薷，本作 。《玉篇》云∶ 菜苏之类，是也。其气香，其叶柔，故以名之。 \n草初生曰茸，孟诜《食疗》作香戎者，非是。俗呼蜜蜂草，象其花房也。 \n【集解】弘景曰∶家家有此，作菜生食。十月中取干之。 \n颂曰∶所在皆种，但北土差少，似白苏而叶更细，寿春及新安皆有之。彼间又有一种石 \n香，生石上，茎叶更细，色黄而辛香弥甚，用之尤佳。吴人以为茵陈用之。 \n宗 曰∶香薷生山野间，荆湖南北、二川皆有之，汴、洛作圃种之，暑月亦作菜蔬。叶 \n如茵陈，花茸紫，连边成穗，凡四、五十房为一穗，如荆芥穗，别是一种香气。 \n时珍曰∶香薷有野生，有家莳。中州人三月种之，呼为香菜，以充蔬品。丹溪朱氏惟取 \n大叶者为良，而细叶者香烈更甚，今人多用之。方茎，尖叶有刻缺，颇似黄荆叶而小，九月 \n开紫花成穗。有细子细叶者，仅高数寸，叶如落帚叶，即石香薷也。 \n【修治】 曰∶凡采得去根留叶，锉曝干，勿令犯火。服至十两，一生不得食白山桃也。 \n时 \n【气味】辛，微温，无毒。 \n【主治】霍乱腹痛吐下，散水肿（《别录》）。去热风，猝转筋者。煮 \n为末水服，止鼻衄（孟诜）。下气，除烦热，疗呕逆冷气（大明）。春月煮饮代茶，可无热病， \n调中温胃。含汁漱口，去臭气（汪颖）。主香港脚寒 \n【发明】弘景曰∶霍乱煮饮无不瘥者，作煎除水肿尤良。 \n颂曰∶霍乱转筋者，单煮服之。若四肢烦冷，汗出而渴者，加蓼子同煮服。 \n震亨曰∶香薷属金与水，有彻上彻下之功。解暑利小便，又治水甚捷，以大叶者浓煎丸 \n服。肺得之，清化行而热自降也。 \n时珍曰∶世医治暑病，以香薷饮为首药。然暑有乘凉饮冷，致阳气为阴邪所遏，遂病头 \n痛，发热恶寒，烦躁口渴，或吐或泻，或霍乱者。宜用此药，以发越阳气，散水和脾。若饮 \n食不节，劳役作丧之人，伤暑大热大渴，汗泄如雨，烦躁喘促，或泻或吐者。乃劳倦内伤之 \n证，必用东垣清暑益气汤、人参白虎汤之类，以泻火益元可也。若用香薷之药，是重虚其表， \n而又济之以热矣。盖香薷乃夏月解表之药，如冬月之用麻黄，气虚者尤不可多服。而今人不 \n知暑伤元气，不拘有病无病，概用代茶，谓能辟暑，真痴前说梦也。且其性温，不可热饮， \n反致吐逆。饮者惟宜冷服，则无拒格之患。其治水之功果有奇效。一士妻自腰以下 肿，面 \n目亦肿，喘急欲死，不能伏枕，大便溏泄，小便短少，服药罔效。时珍诊其脉沉而大，沉主 \n水，大主虚，乃病后冒风所致，是名风水也。用《千金》神秘汤加麻黄，一服喘定十之五。 \n再以胃苓汤吞深师薷术丸，二日小便长，肿消十之七，调理数日全安。益见古人方皆有至理， \n但神而明之，存乎其人而已。 \n【附方】旧四，新六。 \n一切伤暑∶《和剂局方》香薷饮∶治暑月卧湿当风，或生冷不节，真邪相干，便致吐利， \n或发热头痛体痛，或心腹痛，或转筋，或干呕，或四肢逆冷，或烦闷欲死，并主之。用香薷 \n一斤，浓朴（姜汁炙）、白扁豆（微炒）各半斤，锉散。每服五钱，水二盏，酒半盏，煎一 \n盏，水中沉冷，连进二服立效。《活人书》 \n水病洪肿∶胡洽居士香薷煎∶用干香薷五十斤（锉）。入釜中，以水淹过三寸，煮使气 \n力都尽，去滓澄之，微火煎至可丸，丸如梧子大。一服五丸，日三服，日渐增之，以小便利 \n则愈。（苏颂《图经本草》） \n通身水肿∶深师薷术丸∶治暴水风水气水，通身皆肿，服至小便利为效。用香薷叶一斤， \n水一斗，熬极烂去滓，再熬成膏，加白术末七两，和丸梧子大。每服十丸，米饮下，日五、 \n夜一服。（《外台秘要》）四时伤寒，不正之气。用水香薷为末，热酒调服一、二钱，取汗。 \n（《卫生易简方》）心烦胁痛，连胸欲死者。香薷捣汁一二升服。（《肘后》） \n鼻衄不止∶香薷研末，水服一钱。（《圣济总录》）舌上出血如钻孔者。香薷煎汁服一升， \n日三服（《肘后方》）。 \n口中臭气∶香薷一把，煎汁含之。（《千金方》） \n小儿发迟∶陈香薷二两，水一盏，煎汁三分，入猪脂半两，和匀，日日涂之。（《永类 \n钤方》） \n白秃惨痛∶即上方入胡粉，和涂之。（《子母秘录》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>石香\n\n内容：（宋《开宝》附） \n【释名】石苏。 \n【集解】志曰∶石香 ，生蜀郡陵、荣、资、简、州，及南中诸处，生山岩石缝中。二 \n月、八月采，苗茎花实俱可用。 \n宗 曰∶处处有之，但山中临水附崖处或有之，不必山岩石缝也。九月、十月尚有花 \n时珍曰∶香薷、石香薷，一物也，但随所生而名尔。生平地者，叶大；崖石者叶细， \n可通用之。 \n【气味】辛香，温，无毒。 \n【主治】调中温胃，止霍乱吐泻，心腹胀满，脐腹痛肠鸣，（《开宝》）。功比香薷更胜（萧 \n炳）。制硫黄（时珍）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>爵床\n\n内容：（《本经》中品） \n【释名】爵麻（《吴普》）、香苏（《别录》）、赤眼老母草（《唐本》）。 \n时珍曰∶爵床不可解。按吴氏本草作爵麻，甚通。 \n【集解】别录曰∶爵床生汉中川谷及田野。恭曰∶此草生平泽熟田近道旁，似香 ，叶 \n长而大，或如荏且细，俗名赤眼老母草。时珍曰∶原野甚多。方茎对节，与大叶香薷一样。 \n但香薷搓之气香，而爵床搓之不香微臭，以此为别。 \n\\x茎叶\\x \n【气味】咸，寒，无毒。时珍曰∶微辛。 \n【主治】腰脊痛，不得着床，俯仰艰难，除热，可作浴汤。（本经）疗血胀下气。治杖 \n疮，捣汁涂之立瘥。（苏恭） 赤车使者（唐本草） \n【释名】小锦枝（炮炙论。） \n【集解】恭曰∶赤车使者，苗似香 、兰香，叶茎赤，根紫赤色，八月、九月采根，晒 \n干。 \n保升曰∶生荆州、襄州，根紫如茜根，二月、八月采。时珍曰∶此与爵床相类，但以根 \n色紫赤为别尔。 \n\\x根\\x \n【修治】 曰∶此草原名小锦枝。凡用并粗捣，以七岁童子小便拌蒸，晒干入药。 \n【气味】辛、苦，温，有毒。（权曰∶有小毒。） \n【主治】风冷邪疰，蛊毒症瘕，五脏积气。（苏恭）治恶风冷气。服之悦泽肌皮，好颜 \n色（甄权）。 \n【发明】颂曰∶古方治大风风痹，有赤车使者酒。今人稀用，鲜有识者。 \n时珍曰∶上古辟瘟疫邪气，有赤车使者丸。此药不怪，苟加询采，必能得之，但古今名 \n称或不同耳。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>假苏\n\n内容：（《本经》中品） \n【校正】自菜部移入此。 \n【释名】姜芥（《别录》）、荆芥（《吴普》）、鼠 （《本经》）。 \n弘景曰∶假苏方药不复用。 \n恭曰∶此即菜中荆芥也，姜芥声讹尔。先居草部，今录入菜部。 \n士良曰∶荆芥本草呼为假苏。假苏又别是一物。叶锐圆，多野生，以香气似苏，故呼为 \n苏。 \n颂曰∶医官陈巽言∶江左人谓假苏、荆芥实两物。苏恭以本草一名姜芥，荆姜声讹，谓 \n为荆芥，非矣。 \n时珍曰∶按《吴普本草》云∶假苏一名荆芥，叶似落藜而细，蜀中生啖之。普乃东汉末 \n人，去《别录》时未远，其言当不谬，故唐人苏恭祖其说。而陈士良、苏颂复启为两物之疑， \n亦臆说尔。曰苏、曰姜、曰芥，皆因气味辛香，如苏、如姜、如芥也。 \n【集解】《别录》曰∶假苏生汉中川泽。 \n颂曰∶今处处有之，叶似落藜而细，初生香辛可啖，人取作生菜。古方稀用，近世医家 \n为要药，并取花实成穗者，曝干入药。又有胡荆芥，俗呼新罗荆芥。又有石荆芥，生山石间。 \n体性相近，入药亦同。 \n时珍曰∶荆芥原是野生，今为世用，遂多栽莳。二月布子生苗，炒食辛香。方茎细叶， \n似独帚叶而狭小，淡黄绿色。八月开小花，作穗成房，房如紫苏房，内有细子如葶苈子状， \n黄赤色，连穗收采用之。 \n【正误】藏器曰∶张鼎《食疗本草》，荆芥一名析 ，误矣。菥 自有本条，见草部。 \n时珍曰∶汪机《本草会编》，言假苏是白苏，亦误矣。白苏乃荏也。见后。 \n\\x茎穗\\x \n【气味】辛，温，无毒。 \n诜曰∶作菜食久，动渴疾，熏人五脏神。反驴肉、无鳞鱼，详后发明下。 \n【主治】寒热鼠 ，瘰 生疮，破结聚气，下瘀血，除湿痹（《本经》）。去邪，除劳渴 \n冷风，出汗，煮汁服之。捣烂醋和，敷疔肿肿毒（藏器）。单用治恶风贼风，口面 斜，遍 \n身痹，心虚忘事，益力添精，辟邪毒瓦斯，通利血脉，传送五脏不足气，助脾胃（甄权）。 \n主血劳，风气壅满，背脊疼痛，虚汗，理丈夫香港脚，筋骨烦疼，及阴阳毒伤寒头痛，头旋目 \n眩，手足筋急（士良）。利五脏，消食下气，醒酒。作菜生熟皆可食，并煎茶饮之。以豉汁 \n煎服，治暴伤寒，能发汗（《日华》）。治妇人血风及疮疥，为要药（苏颂）。产后中风身强直， \n研末酒服（孟诜）。散风热，清头目，利咽喉，消疮肿，治项强，目中黑花，及生疮阴 ， \n吐血衄血，下血血痢，崩中痔漏（时珍）。 \n【发明】元素曰∶荆芥辛苦，气味俱薄，浮而升，阳也。 \n好古曰∶肝经气分药也。能搜肝气。 \n时珍曰∶荆芥入足厥阴经气分，其功长于祛风邪，散瘀血，破结气，消疮毒。盖厥阴乃 \n风木也，主血，而相火寄之，故风病血病疮病为要药。其治风也，贾丞相称为再生丹，许学 \n士谓有神圣功，戴院使许为产后要药，萧存敬呼为一捻金，陈无择隐为举卿古拜散，夫岂无 \n故而得此隆誉哉？按《唐韵》∶荆字，举卿切，芥字古拜切。盖二字之反切，隐语以秘其方 \n也。 \n又曰∶荆芥反鱼蟹河豚之说，本草医方并未言及，而稗官小说往往载之。按李廷飞《延 \n寿书》云∶凡食一切无鳞鱼，忌荆芥。食黄 鱼后食之，令人吐血，惟地浆可解。与蟹同 \n食，动风。又《蔡绦铁围山丛话》云∶予居岭峤，见食黄颡鱼犯姜芥者立死，甚于钩吻。洪 \n迈《夷坚志》云∶吴人魏几道，啖黄颡鱼羹，后采荆芥和茶饮。少顷足痒，上彻心肺，狂走， \n足皮欲裂。急服药，两日乃解。陶九成《辍耕录》云∶凡食河豚，不可服荆芥药，大相反。 \n予在江阴见一儒者，因此丧命。《苇航纪谈》云∶凡服荆芥风药，忌食鱼。杨诚斋曾见一人 \n，立致于死也。时珍按∶荆芥乃日用之药，其相反如此，故详录之，以为警戒。又按《物类 \n相感志》言∶河豚用荆芥同煮，三五次换水，则无毒。其说与诸书不同，何哉？大抵养生者 \n，宁守前说为戒可也。 \n【附方】旧四，新二十七。 \n头项风强∶八月后，取荆芥穗作枕，及铺床下，立春日去之。（《千金方》） \n风热头痛∶荆芥穗、石膏等分，为末。每服二钱，茶调下。（《永类钤方》） \n风热牙痛∶荆芥根、乌 根、葱根等分煎汤频含漱之。小儿惊痫一百二十种。用荆芥穗 \n二两，白矾（半生半枯）一两，为末，糊丸黍米大，朱砂为衣。每姜汤下二十丸，日二服。 \n（《医学集成》）一切偏风，口眼 斜。用青荆芥一斤，青薄荷一斤，同入砂盆内研烂，生绢 \n绞汁，于瓷器中煎成膏，漉去滓三分之一，将二分晒干，为末，以膏和丸梧子大。每服三十 \n丸，白汤下，早暮各一服。忌动风物。（《经验后方》） \n中风口噤∶荆芥穗为末，酒服二钱，立愈，名荆芥散。贾似道云∶此方出《曾公谈录》， \n前后用之甚验。其子名顺者，病此已革，服之立定，真再生丹也。 \n产后中风∶华佗愈风散∶治妇人产后中风口噤，手足螈 如角弓，或产后血运，不省人 \n事，四肢强直，或筑心眼倒，吐泻欲死。用荆芥穗子，微焙为末。每服三钱，豆淋酒调服， \n或童子小便服之。口噤则挑齿灌之，龈噤则灌入鼻中，其效如神。大抵产后太暖，则汗出而 \n腠理疏，则易于中风也。 \n时珍曰∶此方诸书盛称其妙。姚僧坦《集验方》以酒服，名如圣散，云药下可立待应效 \n。陈氏方名举卿古拜散。萧存敬方用古老钱煎汤服，名一捻金。王贶《指迷方》加当归等分 \n，水煎服。许叔微《本事方》云∶此药委有奇效神圣之功。一妇人产后睡久，及醒则昏昏如 \n醉，不省人事。医用此药及交加散，云∶服后当睡，睡中必以左手搔头。用之果然。昝殷《产 \n宝方》云∶此病多因怒气伤肝，或忧气内郁，或坐草受风而成，急宜服此药也。戴原礼《证 \n治要诀》名独行散。贾似道《悦生随抄》呼为再生丹。产后迷闷，因怒气发热迷闷者。独行 \n散∶用荆芥穗，以新瓦半炒半生为末。童子小便服一二钱。若角弓反张，以豆淋酒下。或锉 \n散，童尿煎服极妙。盖荆芥乃产后要药，而角弓反张，乃妇人急候，得此证者，十存一二而 \n已。（戴原礼《要诀》） \n产后血运∶筑心眼倒，风缩欲死者。取干荆芥穗捣筛末。每用二钱匕，童子小便一酒盏， \n调匀，热服。立效。口噤者挑齿，口闭者灌鼻中，皆效。近世名医用之，无不如神也。（《图 \n经本草》）产后血眩风虚，精神昏冒。荆芥穗一两三钱，桃仁五钱（去皮尖）。炒为末。水服 \n三钱。若喘加杏仁（去皮尖，炒）、甘草（炒） \n产后下痢∶大荆芥四、五穗（于盏内烧存性，不得犯油火），入麝香少许。以沸汤些须 \n调下。此药虽微，能愈大病，不可忽之。（《深师方》） \n产后鼻衄∶荆芥（焙）研末。童子小便服二钱，《海上方》也。（《妇人良方》） \n九窍出血∶荆芥煎酒，通口服之。（《直指方》）口鼻出血如涌泉，因酒色太过者。荆芥 \n烧研，陈皮汤服二钱，不过二服也。 \n吐血不止∶《经验方》∶用荆芥（连根，洗），捣汁半盏服。干穗为末亦可。《圣惠方》∶ \n用荆芥穗为末。生地黄汁调服二钱。 \n小便尿血∶荆芥、缩砂等分，为末。糯米饮下三钱，日三服。（《集简》） \n崩中不止∶荆芥穗（于麻油灯上烧焦，为末）。每服二钱，童子小便服。此夏太君娘娘 \n方也。（《妇人良方》） \n痔漏肿痛∶荆芥煮汤，日日洗之。（《简易方》）大便下血∶《经验方》∶用荆芥（炒）为 \n末，每米饮服二钱，妇人用酒下，亦可拌面作馄饨食之。《简便方》∶用荆芥二两，槐花一两， \n同炒紫为末。每服三钱，清茶送下。 \n小儿脱肛∶荆芥、皂角等分，煎汤洗之，以铁浆涂上。亦治子宫脱出。（《经验方》） \n阴 肿痛∶荆芥穗（瓦焙）为散。酒服二钱，即消。（《寿域神方》） \n小儿脐肿∶荆芥煎汤洗净，以煨葱刮薄出火毒，贴之即消。（《海上方》） \n瘰 溃烂∶ 疮牵至胸前两腋，块如茄子大，或牵至两肩上，四、五年不能疗者，皆治 \n之，其效如神。武进县朱守仁传，云其项不能回头，用此数日减可。如疮烂破者，用荆芥根 \n下一段剪碎，煎沸汤温洗，良久，看烂破处紫黑，以针一刺去血，再洗三四次愈。用樟脑、 \n雄黄等分，为末，麻油调，扫上出水。次日再洗再扫，以愈为度。（《活法机要》） \n疔肿诸毒∶荆芥一握（切）。以水五升，煮取二升，分二服冷冻饮料。（《药性论》） \n一切疮疥∶荆芥末，以地黄自然汁熬膏，和丸梧子大。每服三、五十丸，茶酒任下。（《普 \n济方》） \n脚桠湿烂∶荆芥叶捣敷之。（《简便方》） \n缠脚生疮∶荆芥烧灰，葱汁调敷，先以甘草汤洗之。（《摘玄方》）小儿风寒，烦热有痰， \n不省人事。荆芥穗半两（焙），麝香、片脑各一字，为末。每茶服半钱。大人亦治。（《普济 \n方》） \n头目诸疾∶一切眼疾，血劳，风气头痛，头旋目眩。荆芥穗为末，每酒服三钱。（《龙 \n树论》）癃闭不通，小腹急痛，无问久新。荆芥、大黄（为末）等分，每温水服三钱。小便 \n不通，大黄减半；大便不通， \n荆芥减半。名倒换散。（《普济方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>薄荷\n\n内容：（《唐本草》） \n【校正】自菜部移入此。 \n【释名】菝 （音跋活）、蕃荷菜（蕃，音鄱）、吴菝 （《食性》）、南薄荷（《衍义》）、 \n金钱薄荷。 \n时珍曰∶薄荷，俗称也。陈士良《食性本草》作菝 ，扬雄《甘泉赋》作茇 ，吕忱《字 \n林》作茇 ，则薄荷之为讹称可知矣。孙思邈《千金方》作蕃荷，又方音之讹也。今人药用， \n多以苏州者为胜，故陈士良谓之吴菝 ，以别胡菝 也。 \n宗 曰∶世称此为南薄荷，为有一种龙脑薄荷，所以别之。 \n机曰∶小儿方多用金钱薄荷，谓其叶小颇圆如钱也，书作金银误矣。 \n【集解】颂曰∶薄荷处处有之。茎叶似荏而尖长，经冬根不死，夏秋采茎叶曝干。古方 \n稀用，或与薤作齑食。近世治风寒为要药，故人家多莳之。又有胡薄荷，与此相类，但味少 \n甘为别。生江浙间，彼人多以作茶饮之，欲呼新罗薄荷。近汴洛僧寺或植一、二本者，《天 \n宝单方》所谓连钱草者是也。又有石薄荷，生江南山石间，叶微小，至冬紫色，不闻有别功 \n用。 \n恭曰∶薄荷，人家种之，亦堪生食。一种蔓生者，功用相似。 \n时珍曰∶薄荷，人多栽莳。二月宿根生苗，清明前后分之。方茎赤色，其叶对生，初时 \n形长而头圆，及长则尖。吴、越、川、湖人多以代茶。苏州所莳者，茎小而气芳，江西者， \n稍粗，川蜀者更粗，入药以苏产为胜。《物类相感志》云∶凡收薄荷，须隔夜以粪水浇之， \n雨后乃可刈收，则性凉，不尔不凉也。野生者，茎叶气味都相似。 \n\\x茎叶\\x \n【气味】辛，温，无毒。 \n思邈曰∶苦、辛，平。元素曰∶辛、凉。 曰∶茎性燥。 \n甄权曰∶同薤作齑食，相宜。新病瘥人勿食之，令人虚汗不止。瘦弱人久食之，动消渴 \n病。 \n【主治】贼风伤寒发汗，恶气心腹胀满，霍乱，宿食不消，下气，煮汁服之，发汗，大 \n解劳乏，亦堪生食（《唐本》）。作菜久食，却肾气，辟邪毒，除劳气，令人口气香洁。煎汤 \n洗漆疮（思邈）。通利关节，发毒汗，去愤气，破血止痢（甄权）。疗阴阳毒，伤寒头痛，四 \n季宜食（士良）。治中风失音吐痰（《日华》）。主伤风头脑风，通关格，及小儿风涎，为要药 \n（苏颂）。杵汁服，去心脏风热（孟诜）。清头目，除风热（李杲）。利咽喉口齿诸病，治瘰 \n疮疥，风瘙瘾疹。捣汁含漱，去舌 \n苔语涩。 叶塞鼻 \n【发明】元素曰∶薄荷辛凉，气味俱薄，浮而升，阳也。故能去高巅及皮肤风热。 \n士良曰∶薄荷能引诸药入营卫，故能发散风寒。 \n宗 曰∶小儿惊狂壮热，须此引药。又治骨蒸热劳，用其汁与众药熬为膏。猫食薄荷则 \n醉，物相感尔。 \n好古曰∶薄荷，手、足厥阴气分药也。能搜肝气，又主肺盛有余肩背痛，及风寒汗出。 \n时珍曰∶薄荷入手太阴、足厥阴，辛能发散，凉能清利，专于消风散热，故头痛头风眼 \n目咽喉口齿诸病，小儿惊热及瘰 疮疥，为要药。戴原礼氏治猫咬，取其汁涂之有效，盖取 \n其相制也。 \n陆农师曰∶薄荷，猫之酒也。犬，虎之酒也。桑椹，鸠之酒也。 草，鱼之酒也。昝殷 \n《食医心镜 \n【附方】旧二，新八。 \n清上化痰∶利咽膈，治风热。以薄荷末，炼蜜丸芡子大。每噙一丸。白砂糖和之亦可。 \n（《简便单方》） \n风气瘙痒∶用大薄荷、蝉蜕等分，为末。每温酒调服一钱。（《永类钤 \n舌苔语蹇∶薄荷自然汁，和白蜜、姜汁擦之。（《医学集成》） \n眼弦赤烂∶薄荷，以生姜汁浸一宿，晒干为末。每用一钱，沸汤炮洗。（《明目经验方》） \n瘰结核，或破未破。以新薄荷二斤（取汁），皂荚一挺（水浸去皮，捣取汁）。同于银石器 \n内熬膏。入连翘末半两，连白青皮、陈皮，黑牵牛（半生半炒）各一两，皂荚仁一两半，同 \n捣和丸梧子大。每服三十丸，煎连翘汤下。（《济生方》） \n衄血不止∶薄荷汁滴之。或以干者水煮，绵裹塞鼻。（许学士《本事方》） \n血痢不止∶薄荷叶煎汤常服。（《普济》） \n水入耳中∶薄荷汁滴入立效。（《经验方》） \n蜂虿螫伤∶薄荷叶 贴之。（《外台秘要》） \n火毒生疮∶冬间向火，火气入内，两股生疮，汁水淋漓者。用薄荷煎汁频涂，立愈。（张 \n杲《医说》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>积雪草\n\n内容：（《本经》中品） \n【释名】胡薄荷（《天宝方》）、地钱草（《唐本》）、连钱草（《药图》）、海苏。 \n弘景曰∶积雪草方药不用，想此草以寒凉得名耳。 \n恭曰∶此草叶圆如钱，荆楚人谓为地钱草，徐议《药草图》名连钱草，余见下。 \n【集解】《别录》曰∶积雪草，生荆州川谷。 \n恭曰∶此草叶圆大如钱，茎细而劲，蔓生溪涧侧，生处亦稀。 \n颂曰∶今处处有之，八九月采苗叶，阴干用。段成式《酉阳杂俎》云∶地钱叶圆茎细， \n有蔓延地，一曰积雪草，一曰连钱草。谨按∶《天宝单行方》云∶连钱草生咸阳下湿地，亦 \n生临淄郡、济阳郡池泽中，甚香。俗间或云圆叶似薄荷，江东吴越丹阳郡极多，彼人常充生 \n菜食之。河北柳城郡尽呼为海苏，好近水生，经冬不死，咸阳、洛阳亦有之。或名胡薄荷， \n所在皆有。单服疗女子小腹疼。 \n宗 曰∶积雪草南方多有，生阴湿地，不必荆楚。形如水荇而小，面亦光洁，微尖为异。 \n叶叶各生。今人谓之连钱草，盖取象也。 \n时珍曰∶按苏恭注薄荷云∶一种蔓生，功用相似。苏颂《图经》云∶胡薄荷与薄荷相类， \n但味少甘，生江浙间，彼人多以作茶饮，俗呼为新罗薄荷，《天宝方》所用连钱草是也。据 \n二说，则积雪草即胡薄荷，乃薄荷之蔓生者尔。又《 仙庚辛玉册》云∶地钱，阴草也。生 \n荆、楚、江、淮、闽、浙间，多在宫院寺庙砖砌间，叶圆似钱，引蔓铺地，香如细辛，不见 \n开花也。 \n\\x茎叶\\x \n【气味】苦，寒，无毒。大明曰∶苦，辛。颂曰∶甘，平，无毒。 \n时珍曰∶取汁结草砂，伏硫黄。 \n【主治】大热，恶疮痈疽，浸淫赤 ，皮肤赤，身热（《本经》）。捣敷热肿丹毒（苏恭）。 \n主暴热，小儿寒热，腹内热结，捣汁服之（藏器）。单用治瘰 鼠漏，寒热时节来往（甄权）。 \n以盐 贴肿毒，并风疹疥癣（《日华》）。胡菝 ∶主风气壅并攻胸膈，作汤饮之立效（士良）。 \n研汁，点暴赤眼，良（时 \n【附方】旧二，新二 \n热毒痈肿∶秋后收连钱草。阴干为末。水调敷之。生捣亦可。（寇氏《衍义》） \n女子少腹痛∶颂曰∶《天宝单行方》云∶女子忽得小腹中痛，月经初来，便觉腰中切痛 \n连脊间，如刀锥所刺，不可忍者。众医不别，谓是鬼疰，妄服诸药，终无所益，其疾转增。 \n审察前状相当，即用此药。其药夏五月正放花时，即采曝干，捣筛为散。每服二方寸匕，和 \n好醋二小合，搅匀，平旦空腹顿服之。每旦一服，以知为度。如女子阴冷者，即取前药五两， \n加桃仁二百枚（去皮尖），熬捣为散，以蜜为丸如梧子大。每旦空腹米饮及酒下三十丸，日 \n再服，以愈为度。忌麻子、荞麦。（《图经本草》方）。 \n男女血病∶九仙驱红散∶治呕吐诸血及便血、妇人崩中神效。用积雪草五钱，当归（酒 \n洗）、栀子仁（酒炒）、蒲黄（炒）、黄连（炒）、条黄芩（酒炒）、生地黄（酒洗）、陈槐花（炒） \n各一钱。上部加藕节一钱五分，下部加地榆一钱五分，水二钟，煎一钟服，神效。此方得之 \n甚秘，此草与本草主治不同，不可晓也。（董炳《集验方》） \n牙痛塞耳∶用连钱草（即积雪草），和水沟污泥同捣烂，随左右塞耳内。（《摘玄方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>苏\n\n内容：（《别录》中品） \n【校正】自菜部移入此。 \n【释名】紫苏（《食疗》）、赤苏（《肘后方》）、桂荏时珍曰∶苏从酥，音酥，舒畅也。 \n苏性舒畅，行气和血，故谓之苏。曰紫苏者，以别白苏也。苏乃荏类，而味更辛如桂，故《尔 \n雅》谓之桂荏。 \n【集解】弘景曰∶苏叶下紫色而气甚香。其无紫色不香似荏者，名野苏，不堪用。 \n颂曰∶苏，紫苏也。处处有之，以背面皆紫者佳。夏采茎叶，秋采子。有数种，水苏、 \n鱼苏、山鱼苏皆是荏类，各有别条。 \n时珍曰∶紫苏、白苏，皆以二、三月下种，或宿子在地自生。其茎方，其叶团而有尖， \n四围有锯齿，肥地者面背皆紫，瘠地者面青背紫，其面背皆白者即白苏，乃荏也。紫苏嫩时 \n采叶，和蔬茹之，或盐及梅卤作俎食甚香，夏月作熟汤饮之。五、六月连根采收，以火煨其 \n根，阴干则经久叶不落。八月开细紫花，成穗作房，如荆芥穗。九月半枯时收子，子细如芥 \n子而色黄赤，亦可取油如荏油。《务本新书》云∶凡地畔近道可种苏，以遮六畜。收子打油 \n燃灯甚明，或熬之以油器物。《丹房镜源》云∶苏子油，能柔五金八石。《沙州记》云∶乞弗 \n虏之地，不种五谷，惟食苏子。故王祯云∶苏有遮护之功，又有灯油之用，不可阙也。今有 \n一种花紫苏，其叶细齿密纽，如剪成之状，香色茎子并无异者，人称回回苏云。 \n曰∶薄荷根茎真似紫苏，但叶不同尔。薄荷茎燥，紫苏茎和。入药须以刀刮去青薄皮 \n锉之。 \n\\x茎叶\\x \n【气味】辛，温，无毒。 \n李廷飞曰∶不可同鲤鱼食，生毒疮。 \n【主治】下气，除寒中，其子尤良（《别录》）。除寒热，治一切冷气 \n，治心腹胀满，止霍乱转筋，开胃下食，止香港脚，通大小肠（《日华》）。通心经，益脾胃， \n煮饮尤胜，与橘皮相宜（苏颂）。解肌发表，散风寒，行气宽中，消痰利肺，和血温中止痛 \n，定喘安胎，解鱼蟹毒，治蛇犬伤（时珍）。以叶生食作羹，杀一切鱼肉毒（甄权）。 \n【发明】颂曰∶若宣通风毒，则单用茎，去节尤良。 \n时珍曰∶紫苏，近世要药也。其味辛，入气分；其色紫，入血分。故同橘皮，砂仁，则 \n行气安胎；同藿香、乌药，则温中止痛；同香附、麻黄，则发汗解肌；同芎 、当归则和血 \n散血；同木瓜、浓朴，则散湿解暑，治霍乱、香港脚；同桔梗、枳壳，则利膈宽肠；同杏仁、 \n莱菔子，则消痰定喘也。 \n久则泄人真气焉。 \n宗 曰∶紫苏其气香，其味微辛甘能散。今人朝暮饮紫苏汤，甚无益。医家谓芳草致豪 \n贵之疾者，此有一焉。若脾胃寒人，多致滑泄，往往不觉。 \n【正误】颂曰∶苏主鸡瘕，《本经》不着。南齐褚澄治李道念食白沦鸡子成瘕，以苏煮 \n服，吐出鸡雏而愈也。 \n时珍曰∶按《南齐书》，褚澄所用者蒜也，非苏也。盖二字相似，誉录误耳，苏氏欠考 \n矣。详见蒜下。 \n【附方】旧二，新一十三。 \n感寒上气∶苏叶三两，橘皮四两，酒四升，煮一升半，分再服。（《肘后方》） \n伤寒气喘不止∶用赤苏一把，水三升，煮一升，稍稍饮之。（《肘后》）劳复食复欲死者。 \n苏叶煮汁二升，饮之。亦可入生姜、豆豉同煮饮。（《肘后》）卒 不止 香苏浓煮，顿服三 \n升，良。（《千金》）霍乱胀满，未得吐下。用生苏捣汁饮之，佳。干苏煮汁亦可。（《肘后 \n方》） \n诸失血病∶紫苏不限多少，入大锅内，水煎令干，去滓熬膏，以炒熟赤豆为末，和丸梧 \n子大。每酒下三、五十丸，常服之。（《斗门方》）金疮出血不止。以嫩紫苏叶、桑叶同捣贴 \n之。（《永类钤方》） \n颠扑伤损∶紫苏捣敷之。疮口自合。（《谈野翁试验方》）伤损血出不止。以陈紫苏叶蘸 \n所出血， 烂敷之。血不作脓，且愈后无瘢，甚妙也。（《永 \n疯狗咬伤∶紫苏叶嚼敷之。（《千金方》） \n蛇虺伤人∶紫苏叶捣饮之。（《千金方》） \n食蟹中毒∶紫苏煮汁饮二升。（《金匮要略》）飞丝入目，令人舌上生泡。用紫苏叶嚼烂， \n白汤咽之。（危氏《得效方》） \n乳痈肿痛∶紫苏煎汤频服，并捣封之。（《海上仙方》） \n咳逆短气∶紫苏茎叶二钱，人参一钱。水一钟，煎服。（《普济》） \n\\x子\\x \n【气味】辛，温，无毒。 \n【主治】下气，除寒温中（《别录》）。治上气咳逆，冷气及腰脚中湿风结气。研汁煮粥 \n长食，令人肥白身香（甄权）。调中，益五脏，止霍乱呕吐反胃，补虚劳，肥健人，利大小 \n便，破症结，消五膈，消痰止嗽，润心肺（《日华》）。治肺气喘急（宗 ）。治风顺气，利膈 \n宽肠，解鱼蟹毒 \n【发明】弘景曰∶苏子下气，与橘皮相宜。 \n时珍曰∶苏子与叶同功。发散风气宜用叶，清利上下则宜用子也。 \n【附方】旧三，新六。 \n顺气利肠∶紫苏子、麻子仁等分，研烂，水滤取汁，同米煮粥食之。（《济生方》） \n治风顺气，利肠宽中。用紫苏子一升，微炒杵，以生绢袋盛，于三斗清酒中浸三宿，少少饮 \n之。（《圣惠》） \n一切冷气∶紫苏子、高良姜、橘皮等分，蜜丸梧子大。每服十丸，空心酒下。（《药性 \n论》） \n风湿香港脚∶方同上。风寒湿痹，四肢挛急，脚肿不可践地。用紫苏子二两，杵碎。以水 \n三升，研取汁，煮粳米二合，作粥，和葱、椒、姜、豉食之。（《圣惠方》）消渴变水，服此 \n令水从小便出。用紫苏子（炒）三两，萝卜子（炒）三两，为末。每服二钱，桑根白皮煎汤 \n服，日三次。（《圣济总录》） \n梦中失精∶苏子一升。熬杵研末，酒服方寸匕，日再服。（《外台秘要》） \n食蟹中毒∶紫苏子煮汁饮之。（《金匮要略》） \n上气咳逆∶紫苏子入水研滤汁，同粳米煮粥食。（《简便方》）荏（别录上品） \n【校正】自菜部移入此。 \n【释名】KT （音鱼。） （弘景）白苏（图经弘景曰∶荏状如苏，东人呼为KT ， \n以其 \n似苏字，但除禾边故也。颂曰∶苏有数种∶有水苏、白苏、鱼苏、山鱼苏。皆是荏类。） \n【集解】别录曰∶荏叶，九月采，阴干。弘景曰∶荏状如苏，高硕白色，不甚香。其子 \n研之，杂米作糜，甚肥美，下气补益。笮其子作油，日煎之，即今油帛及和漆所用者，服食 \n断谷亦用之，名为重油。恭曰∶荏叶人常生食，其子故不及苏也。藏器曰∶江东以荏子为油， \n北土以大麻为油，此二油俱堪油物。若其和漆，荏者为强尔。炳曰∶又有大荏，形似野荏， \n高硕。叶大小荏一倍，不堪食。人收其子，以充油绢帛，与大麻子同。其小荏子欲熟，人采 \n其角食之，甚香美。大荏叶不堪食。颂曰∶白苏，方茎圆叶，不紫，亦甚香，实亦入药。鱼 \n苏，似茵陈，大叶而香，吴人以煮鱼者，一名鱼 。生山石间者名山鱼苏，主休息痢，大小 \n溲频数。干末，米饮调服之，效。诜曰∶可蒸令熟，烈日干之，当口开，舂取米食之，亦可 \n休粮。 \n\\x叶\\x \n【气味】辛，温，无毒。 \n【主治】调中，去臭气。（别录）捣敷虫咬及男子阴肿。（藏器）调气，润心肺，长肌肤， \n益颜色，消宿食，止上气咳嗽，去狐臭，敷虫咬。（日华） \n【附方】（旧二）男女阴肿（男子∶荏叶生捣，和醋封之。女人∶绵裹内，三四易。孟 \n诜食疗。） 蛇虺中人（以荏叶烂杵，猪脂和，薄敷上。梅师方。） \n\\x子\\x \n【气味】辛，温，无毒。（诜曰∶亦少破气。多食，发心闷。） \n【主治】咳逆，下气，温中补体。（别录）生食，止渴润肺。（蒸熟晒干，舂取米食，补 \n中益气，通血脉，填精髓）。（孟诜）止嗽。（日华）。 \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>水苏\n\n内容：（《本经》中品） \n【校正】自菜部移入此。 \n【释名】鸡苏（《吴普》）、香苏（《肘后》）、龙脑薄荷（《日用》）、芥 （音祖）、芥苴 \n（并《别录》）。 \n时珍曰∶此草似苏而好生水旁，故名水苏。其叶辛香，可以煮鸡，故有龙脑、香苏、鸡 \n苏诸名。芥 、芥苴当作芥苏，乃是一名而误录尔，亦因味辛如芥，故名。宋《惠民和剂局 \n方》，有龙脑薄荷丸，专治血病。元吴瑞《日用本草》，谓即水苏，必有所据也。周定王《救 \n荒本草》，言薄荷即鸡苏，以生东平龙脑冈者为良，故名；陈嘉谟《本草蒙筌》，以薄荷种于 \n苏州府学地名龙脑者，得名俱不同，何哉？ \n【集解】《别录》曰∶水苏生九真池泽。七月采。 \n弘景曰∶方药不用，莫能识；九真辽远，亦无能访之。 \n恭曰∶此苏生下泽水侧，苗似旋复，两叶相当，大香馥。青、齐、河间人名为水苏，江 \n左名为荠 ，吴会谓之鸡苏，而陶氏更于菜部出鸡苏，误矣。 \n保升曰∶叶似白薇，两叶相当，花生节间，紫白色，味辛而香，六月采茎叶，晒干。 \n颂曰∶水苏处处有之，多生水岸旁。南人多以作菜。江北甚多，而人不取食。又江左人 \n谓鸡苏、水苏是两种。陈藏器谓荠 自是一物，非水苏。水苏叶有雁齿，气香而辛，荠 叶 \n上有毛，稍长，气臭也。又茵陈注云∶江南所用茵陈，茎叶都似家茵陈而大，高三、四尺， \n气极芬香，味甘辛，俗名龙脑薄荷。 \n宗 曰∶水苏气味与紫苏不同。辛而不和，然状一如苏，但面不紫，及周遭槎牙如雁齿 \n耳。 \n瑞曰∶水苏即鸡苏，俗呼为龙脑薄荷。 \n时珍曰∶水苏、荠 一类二种尔。水苏气香，荠 气臭为异。水苏三月生苗，方茎中虚， \n叶似苏叶而微长。密齿，面皱色青，对节生，气甚辛烈，六七月开花成穗，如苏穗，水红色。 \n穗中有细子，状如荆芥子，可种易生，宿根亦自生。沃地者苗高四五尺。 \n\\x茎叶\\x \n【气味】辛，微温，无毒。 \n【主治】下气杀谷，除饮食。辟口臭，去邪毒，辟恶气。久服通神明，轻身耐老（《本 \n经》）。主吐血衄血血崩（《别录》）。治肺痿血痢，崩中带下（《日华》）。主诸气疾及脚肿（苏 \n颂）。酿酒渍酒及酒煮汁常服，治头昏目眩，及产后中风。恶血不止，服之弥妙（孟诜）。作 \n生菜食，除胃间酸水（藏器）。 \n【发明】时珍曰∶鸡苏之功，专于理血下气，清肺辟恶消谷，故《太平和剂局方》治吐 \n血衄血、唾血咳血、下血血淋、口臭口苦、口甜喉腥、邪热诸病，有龙脑薄荷丸方，药多不 \n录。用治血病，果有殊效也。 \n【附方】旧六，新九。 \n漏血欲死∶鸡苏煮汁一升，服之。（《梅师方》） \n吐血下血∶鸡苏茎叶，煎汁饮之。（《梅师方》） \n吐血咳嗽∶龙脑薄荷焙研末。米饮服一钱，取效。 \n衄血不止∶《梅师方》∶用鸡苏五合，香豉二合，同捣，搓如枣核大，纳鼻孔中，即止。 \n《 \n用龙脑薄荷、生地黄等分，为末，冷水服。脑热鼻渊，肺壅多涕。鸡苏叶、麦门冬、川芎 、 \n桑白皮（炒）、黄 （炙）、甘草（炙）、生地黄（焙）等分，为末，炼蜜丸梧子大。每服四 \n十丸，人参汤下。（《圣济总录》） \n风热头痛∶热结上焦，致生风气、痰厥头痛。用水苏叶五两，皂荚（炙去皮子）三两， \n芫花（醋炒焦）一两，为末，炼蜜丸梧子大。每服二十丸，食后荆芥汤下。（《圣惠方》） \n耳猝聋闭∶鸡苏叶生捣，绵裹塞之。（孟诜《食疗》） \n沐发令香∶鸡苏煮汁，或烧灰淋汁，沐之。（《食疗》） \n头生白屑∶方同上。暑月目昏，多眵泪生。龙脑薄荷叶捣烂，生绢绞汁，点之。（《圣 \n济总录》） \n中诸鱼毒∶香苏浓煮汁饮之，良。（《肘后方》） \n蛇虺螫伤∶龙脑薄荷叶研末，酒服，并涂之。（《易简方》） \n\n\n\n<目录>草部卷十四\\草之三\n\n<篇名>荠\n\n内容：（《拾遗》） \n【释名】臭苏（《日华》）、青白苏。 \n时珍曰∶《日华子》释水苏云∶一名臭苏，一名青白苏，正此草也，误作水苏尔。其形 \n似水苏而臭，似白苏而青，故有二名。 \n【集解】藏器曰∶按∶苏恭言∶江左名水苏为荠 。按∶水苏叶有雁齿，气香而辛。荠 \n叶稍长，其上有毛，气臭，亦可为生菜。 \n时珍曰∶荠 处处平地有之。叶似野苏而稍长，有毛气臭。山人茹之，叶不甚佳。 \n\\x茎叶\\x \n【气味】辛，温，无毒。 \n【主治】冷气泄痢。生食，除胃间酸水。 \n【附录】石荠 藏器曰∶味辛，温，无毒。主风冷气，疮疥瘙痒，痔 下血，煮汁服 \n之。生山石间，细叶紫花，高一、二尺，山人用之。 \n\n\n\n<目录>草部第十五卷\n\n<篇名>草之四\n\n内容：\\x隰草类上五十三种\\x \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>菊\n\n内容：（《本经》上品） \n【释名】节华（《本经》）、 女节（《别录》）、 女华（《别录》）、 女茎（《别录》）、 \n日精（《别录》）、 更生（《别录》）、 傅延年（《别录》）、 治蔷（《尔雅》）、 金蕊（《纲 \n目》）、阴成（《别录》）、 周盈（《别录》）。 \n时珍曰∶按陆佃《埤雅》云∶菊本作 ，从鞠。鞠，穷也。《月令》∶九月，菊有黄华。 \n华事至此而穷尽，故谓之 。节华之名，亦取其应节候也。崔实《月令》云∶女节、女华 \n，菊华之名也。治蔷、日精，菊根之名也。《抱朴子》云∶仙方所谓日精、更生、周盈，皆 \n一菊而根、茎、花、实之名异也。颂曰∶唐《天宝单方图》载白菊云∶原生南阳山谷及田野 \n中。 川人呼为回蜂菊，汝南 \n【集解】《别录》曰∶菊花生雍州川泽及田野。正月采根，三月采叶，五月采茎，九月 \n采花，十一月采实，皆阴干。弘景曰∶菊有两种∶一种茎紫气香而味甘，叶可作羹食者， \n为真菊；一种青茎而大，作蒿艾气，味苦不堪食者，名苦薏，非真菊也。华正相似，惟以甘 \n苦别之。南阳郦县最多，今近道处处有之，取种便得。又有白菊，茎叶都相似，惟花白，五 \n月取之。仙经以菊为妙用，但难多得，宜常服之。藏器曰∶白菊生平泽，五月花，紫白色。 \n颂曰∶处处有之，以南阳菊潭者为佳。初春布地生细苗，夏茂，秋花，冬实。然种类颇 \n多。惟紫茎气香，叶浓至柔者，嫩时可食，花微小，味甚甘者，为真；其茎青而大，叶细气 \n烈似蒿艾，花大味苦者，名苦薏，非真也。南阳菊亦有两种∶白菊叶大如艾叶，茎青根细， \n花白蕊黄；其黄菊叶似茼蒿，花蕊都黄。今服饵家多用白者。又有一种开小花，花瓣下如小 \n珠子，谓之珠子菊，云入药亦佳。 \n宗 曰∶菊花近世有二十余种。惟单叶花小而黄，绿叶色深小而薄，九月应候而开者是 \n也。邓州白菊单叶者，亦入药。余皆医经不用。 \n瑞曰∶花大而香者，为甘菊；花小而黄者，为黄菊；花小而气恶者，为野菊。 \n时珍曰∶菊之品凡百种，宿根自生，茎叶花色，品品不同。宋人刘蒙泉、范致能、史正 \n志皆有《菊谱》，亦不能尽收也。其茎有株、蔓、紫、赤、青、绿之殊，其叶有大、小、浓 \n、薄、尖、秃之异，其花有千叶单叶、有心无心、有子无子、黄白红紫、间色深浅、大小之 \n别，其味有甘苦辛之辨，又有夏菊秋菊冬菊之分。大抵惟以单叶味甘者入药，《菊谱》所载 \n甘菊、邓州黄、邓州白者是矣。甘菊始生于山野，今则人皆栽植之。其花细碎，品不甚高。 \n蕊如蜂窠，中有细子，亦可捺种。嫩叶及花皆可炸食。白菊花稍大，味不甚甘，亦秋月采之。 \n菊之无子者，谓之牡菊。烧灰撒地中，能死蛙黾。说出《周礼》。 \n\\x花（叶、根、茎、实并同）\\x \n【气味】苦，平，无毒。《别录》曰∶甘。 \n损之曰∶甘者入药，苦者不入药。 \n杲曰∶苦、甘，寒，可升可降，阴中微阳也。 \n时珍曰∶《本经》言菊花味苦，《别录》言菊花味甘。诸家以甘者为菊，苦者为苦薏， \n惟取甘者入药。谨按∶张华《博物志》，言菊有两种，苗花如一，惟味小异，苦者不中食。 \n范致能《谱》序，言惟甘菊一种可食，仍入药饵。其余黄白二花，皆味苦，虽不可饵，皆 \n可入药。其治头风，则白者尤良。据此二说则是菊类自有甘苦二种，食品须用甘菊，入 \n药则诸菊皆可，但不得用野菊名苦薏者尔。故景焕《牧竖闲谈》云∶真菊延龄，野菊泄人。 \n正如黄精益寿、钩吻杀人之意。之才曰∶术及枸杞根、桑根白皮、青葙叶为之使。 \n【主治】诸风头眩肿痛，目欲脱，泪出，皮肤死肌，恶风湿痹。久服利血气，轻身耐老 \n延年（《本经》）。疗腰痛去来陶陶，除胸中烦热，安肠胃，利五脉，调四肢（《别录》。陶 \n陶，纵缓貌）。治头目风热，风旋倒地，脑骨疼痛，身上一切游风令消散，利血脉，并无所 \n忌（甄权）。作枕明目，叶亦明目，生熟并可食（大明）。养目血，去翳膜（元素）。主肝气 \n不足 \n【气味】苦、辛，平，无毒。 \n【主治】风眩，能令头不白（弘景）。染髭发令黑。和巨胜、茯苓蜜丸服之，去风眩， \n变白不老，益颜色（藏器）。 \n【发明】震亨曰∶黄菊花属土与金，有水与火，能补阴血，故养目。 \n时珍曰∶菊春生夏茂，秋花冬实，备受四气，饱经露霜，叶枯不落，花槁不零，味兼甘 \n苦，性禀平和。昔人谓其能除风热，益肝补阴，盖不知其得金水之精英尤多，能益金水二脏 \n也。补水所以制火，益金所以平木，木平则风息，火降则热除，用治诸风头目，其旨深微。 \n黄者入金水阴分；白者，入金水阳分；红者，行妇人血分。皆可入药，神而明之，存乎其人。 \n其苗可蔬，叶可啜，花可饵，根实可药，囊之可枕，酿之可饮，自本至末，罔不有功。宜乎 \n前贤比之君子，神农列之上品，隐士采入酒 ，骚人餐其落英。费长房言∶九日饮菊酒，可 \n以辟不祥。《神仙传》言∶康风子、朱孺子皆以服菊花成仙。《荆州记》言∶胡广久病风羸， \n饮菊潭水多寿。菊之贵重如此，是岂群芳可伍哉？钟会《菊有五美赞》云∶圆花高悬，准天 \n极也。纯黄不杂，后土色也。早植晚发，君子德也；冒霜吐颖，象贞质也；杯中体轻，神仙 \n食也。《西京杂记》言∶采菊花茎叶，杂秫米酿酒，至次年九月始熟，用之。 \n【附方】旧五，新六。 \n服食甘菊∶《玉函方》云∶王子乔变白增年方∶用甘菊，三月上寅日采苗，名曰玉英； \n六月上寅日采叶，名曰容成；九月上寅日采花，名曰金精；十二月上寅日采根茎，名曰长生。 \n四味并阴干，百日取等分，以成日合捣千杵为末，每酒服一钱匕。或以蜜丸梧子大。酒服 \n七丸，一日三服。百日，身轻润泽；一年，发白变黑；服之二年，齿落再生；五年，八十岁 \n老翁，变为儿童也。孟诜云∶正月采叶，五月五日采茎，九月九日采花。服食白菊∶《太清 \n灵宝方》引∶九月九日白菊花二斤，茯苓一斤。并捣罗为末。每服二钱，温酒调下，日三服。 \n或以炼过松脂和丸鸡子大，每服一丸。主头眩，久服令人好颜色不老。藏器曰∶《抱朴子》 \n言刘生丹法，用白菊汁、莲花汁、地血汁、樗汁，和丹蒸服也。白菊花酒∶《天宝单方》∶治 \n丈夫、妇人久患头风眩闷，头发干落，胸中痰壅，每发即头旋眼昏，不觉欲倒者，是其候也。 \n先灸两风池各二七壮，并服此酒及散，永瘥。其法∶春末夏初，收白菊软苗，阴干捣末，空 \n腹取一方寸匕和无灰酒服之，日再服，渐加三方寸匕。若不饮酒者，但和羹粥汁服，亦得。 \n秋八月合花收曝干，切取三大斤，以生绢袋盛，贮三大斗酒中，经七日服之，日三次，常令 \n酒气相续为佳。（苏颂《图经》）风热头痛∶菊花、石膏、川芎各三钱，为末。每服一钱半， \n茶调下。（《简便方》） \n痘入目生翳障∶用白菊花、谷精草、绿豆皮等分，为末。每用一钱，以干柿饼一枚， \n粟米泔一盏，同煮候泔尽，食柿，日食三枚。浅者五七日，远者半月，见效。（《仁斋直指 \n方》）病后生翳∶白菊花、蝉蜕等分，为散。每用二三钱，入蜜少许，水煎服。大人小儿皆 \n宜，屡验。（《救急方》）疔肿垂死∶菊花一握，捣汁一升，入口即活，此神验方也。冬月采 \n根。（《肘后方》）女人阴肿∶甘菊苗捣烂煎汤，先熏后洗。（危氏《得效方》）酒醉不醒∶九 \n月九日真菊花为末，饮服方寸匕。（《外台秘要》）眼目昏花∶双美丸∶用甘菊花一斤，红椒 \n（去目）六两，为末，用新地黄汁和丸梧子大。每 \n\\x花上水\\x"}, {"n": 15, "text": "卷十五\n\n【主治】益色壮阳，治一切风（大明）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>野菊\n\n内容：（《拾遗》） \n【释名】苦薏。时珍曰∶薏乃莲子之心，此物味苦似之，故与之同名。 \n【集解】藏器曰∶苦薏生泽畔，茎如马兰，花如菊。菊甘而薏苦，语曰苦如薏是也。 \n时珍曰∶苦薏处处原野极多，与菊无异，但叶薄小而多尖，花小而蕊多，如蜂窠状，气 \n味苦辛惨烈。 \n\\x根、叶、茎、花\\x \n【气味】苦、辛，温，有小毒。 \n【主治】调中止泄，破血，妇人腹内宿血宜之（藏器）。治痈肿疔毒，瘰 眼息（时珍）。 \n【附方】新四。痈疽疔肿∶一切无名肿毒。《孙氏集效方》∶用野菊花连茎捣烂，酒煎热 \n服取汗，以渣敷之即愈。《卫生易简方》∶用野菊花茎叶、苍耳草各一握，共捣，入酒一碗， \n绞汁服，以渣敷之，取汗即愈。或六月六日采苍耳叶，九月九日采野菊花，为末。每酒服三 \n钱，亦可。天泡湿疮∶野菊花根、枣木，煎汤洗之。（《医学集成》）瘰 未破∶野菊花根捣 \n烂，煎酒服，以渣敷之。自消，不消亦自破也。（《瑞竹堂经验方 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>庵\n\n内容：（音淹闾《本经》上品） \n【释名】覆闾。 \n时珍曰∶庵，草屋也。闾，里门也。此草乃蒿属，老茎可以盖覆庵闾，故以名之。《贞 \n元广利方》谓之庵 蒿云。又史注云∶庵庐，军行宿室也。则闾似当作庐。 \n【集解】《别录》曰∶庵 子生雍州川谷，亦生上党及道边，十月采实阴干。弘景曰∶ \n状如蒿艾之类，近道处处有之，仙经亦时用之，人家种此辟蛇也。颂曰∶今江淮亦有之。春 \n生苗，叶如艾蒿，高二、三尺。七月开花，八月结实，九月采实。时珍曰∶庵 叶不似艾， \n似菊叶而薄，多细丫，面背皆青。高者四、五尺，其茎白色，如艾茎而粗。八、九月开细花， \n淡黄色。结细实如艾实，中有细子，极易繁衍。艺花者以之接菊。 \n\\x子\\x \n【气味】苦，微寒，无毒。《别录》曰∶微温。普曰∶神农、雷公、桐君、岐伯∶ \n苦，小温，无毒。李当之∶温。权曰∶辛，苦。 \n之才曰∶荆实、薏苡为之使。 \n【主治】五脏瘀血，腹中水气，胪胀留热，风寒湿痹，身体诸痛。久服轻身延年不老（ \n《本经》）。疗心下坚，隔中寒热，周痹，妇人月水不通，消食明目。 食之神仙（《别录 \n》）。益气，主男子阴痿不起，治心腹胀满（甄权）。腰脚重痛，膀胱痛，及骨节烦痛，不下 \n食（大明）。擂酒饮，治闪挫腰痛，及妇人产后血气痛（时珍）。 \n【发明】颂曰∶《本经》言久服轻身不老，而古方少有服食者，惟入诸杂治药中，如胡 \n洽治惊邪狸骨丸之类，大方中用之。孙思邈《千金翼》、《韦宙独行方》，主 折瘀血，并 \n单用庵 煮汁服，亦可末服。今人治打扑多用此法，或饮或散，其效最速。 \n时珍曰∶《吴普本草》及《名医别录》，并言 食庵 神仙，此亦谓其多寿尔。 \n乃兽名，似骡而小，前足长，后足短，不能自食，每负蹶鼠为之啮食。 \n【附方】旧一，新二。 \n月水不通，妇人宿有风冷，留血积聚，月水不通∶庵 子一升，桃仁二升（酒浸去皮尖）。 \n研匀入瓶内，以酒二斗浸，封五日后，每饮三合，日三服。（《圣惠方》） \n产后血痛∶庵 子一两。水一升，童子小便二杯，煎饮。（《频湖集简方》） \n【附录】对庐 《别录》有名未用曰∶味苦，寒，无毒。主疥疮久不瘳，生死肌，除大 \n热，煮汁洗之。似庵 。八月采。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>蓍\n\n内容：（音尸。《本经》上品） \n【释名】时珍曰∶按班固《白虎通》载孔子云∶蓍之为言 也。老人历年多，更事久， \n事能尽知也。陆佃《埤雅》云∶草之多寿者，故字从 。《博物志》言∶蓍千岁而三百茎， \n其本已老，故知吉凶。 \n【集解】《别录》曰∶蓍实生少室山谷，八月、九月采实，日干。 \n恭曰∶此草所在有之，其茎可为筮。陶氏误以楮实为之。楮实味甘，此味苦，今正之。 \n颂曰∶今蔡州上蔡县白龟祠旁，其生如蒿作丛，高五六尺，一本一、二十茎，至多者 \n五十茎，生便条直，所以异于众蒿也。秋后有花，出于枝端，红紫色，形如菊花，结实如艾 \n实。《史记·龟策传》云∶龟千岁乃游于莲叶之上。蓍百茎共一根。所生之处，兽无虎野狼， \n虫无毒螫。徐广注云∶刘向言龟千岁而灵，蓍百年而一本生百茎也。褚先生云∶蓍满百茎， \n其下必有神龟守之，其上常有青云覆之。《传》云∶天下和平，王道得而蓍茎长丈，其丛生 \n满百茎。方今取蓍者，八十茎以上，长八尺者，即已难得。但得满六十茎以上，长六尺者， \n即可用矣。今蔡州所上，皆不言如此。则此类亦神物，故不常有也。 \n时珍曰∶蓍乃蒿属，神草也。故《易》曰∶蓍之德，圆而神。天子蓍长九尺，诸侯七尺 \n，大夫五尺，士三尺。张华《博物志》言∶以末大于本者为主，次蒿，次荆，皆以月望浴之 \n。然则无蓍揲卦，亦可以荆、蒿代之矣。 \n\\x实\\x \n【气味】苦、酸，平，无毒。 \n【主治】益气充肌肤，明目聪慧先知。久服不饥不老轻身（《本经》）。 \n\\x叶\\x \n【主治】痞疾（时珍）。 \n【附方】新一。 \n腹中痞块∶蓍叶、独蒜、穿山甲（末）、食盐。同以好醋捣成饼，量痞大小贴之，两炷 \n香为度。其痞化为脓血，从大便出。（刘松石《保寿堂方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>艾\n\n内容：（《别录》中品） \n【释名】冰台（《尔雅》）、医草（《别录》）、黄草（《埤雅》）、艾蒿。 \n时珍曰∶王安石《字说》云∶艾可 疾，久而弥善，故字从 。陆佃《埤雅》云∶《博 \n物志》言削冰令圆，举而向日，以艾承其影则得火。则艾名冰台，其以此乎？医家用灸百病， \n故曰灸草。一灼谓之一壮，以壮人为法也。 \n【集解】《别录》曰∶艾叶生田野，三月三日采，曝干。 \n颂曰∶处处有之，以复道及四明者为佳，云此种灸百病尤胜。初春布地生苗，茎类蒿， \n叶背白，以苗短者为良。三月三日，五月五日，采叶曝干。陈久方可用。 \n时珍曰∶艾叶本草不着土产，但云生田野。宋时以汤阴复道者为佳，四明者图形。近代 \n惟汤阴者谓之北艾；四明者谓之海艾。自成化以来，则以蕲州者为胜，用充方物，天下 \n重之，谓之蕲艾。相传他处艾灸酒坛不能透，蕲艾一灸则直透彻，为异也。此草多生山原。 \n二月宿根生苗成丛，其茎直生，白色，高四五尺。其叶四布，状如蒿，分为五尖，丫上复 \n有小尖，面青背白，有茸而柔浓。七、八月，叶间出穗如车前穗，细花，结实累累盈枝，中 \n有细子，霜后始枯。皆以五月五日连茎刈取，曝干收叶。先君月池子讳言闻，尝着《蕲艾传》 \n一卷。有赞云∶产于山阳，采以端午。治病灸疾，功非小补。又宗懔《荆楚岁时记》云∶五 \n月五日鸡未鸣时，采艾似人形者揽而取之，收以灸病，甚验。是日采艾为人，悬于户上，可 \n禳毒瓦斯。其茎干之，染麻油引火点灸炷，滋润灸疮，至愈不疼。亦可代蓍策，及作烛心。 \n\\x叶\\x \n【修治】宗 曰∶艾叶干捣，去青滓，取白，入石硫黄末少许，谓之硫黄艾，灸家用之。 \n得米粉少许，可捣为末，入服食药用。 \n时珍曰∶凡用艾叶，须用陈久者，治令细软，谓之熟艾。若生艾灸火，则伤人肌脉。故 \n《孟子》云∶七年之病，求三年之艾。拣取净叶，扬去尘屑，入石臼内木杵捣熟，罗去渣滓 \n，取白者再捣，至柔烂如绵为度。用时焙燥，则灸火得力。入妇人丸散，须以熟艾，用醋煮 \n干，捣成饼子，烘干再捣为末用。或以糯糊和作饼，及酒炒者，皆不佳。洪氏《容斋随笔》 \n云∶艾难着力，若入白茯苓三、五片同碾，即时可作细末，亦一异也。 \n【气味】苦，微温，无毒。恭曰∶生寒；熟热。元素曰∶苦温，阴中之阳。时珍曰∶苦 \n而辛，生温熟热，可升可降，阳也。入足太阴、厥阴、少阴之经。苦酒、 \n【主治】灸百病。可作煎，止吐血下痢，下部 疮，妇人漏血，利阴气，生肌肉，辟风 \n寒，使人有子。作煎勿令见风（《别录》）。捣汁服，止伤血，杀蛔虫（弘景）。主衄血、下血 \n，脓血痢，水煮及丸散任用（苏恭）。止崩血、肠痔血，拓金疮，止腹痛，安胎。苦酒作煎， \n治癣甚良。捣汁饮，治心腹一切冷气、鬼气（甄权）。治带下，止霍乱转筋，痢后寒热（大 \n明）。 \n治带脉为病，腹胀满，腰溶溶如坐水中（好古）。温中、逐冷、除湿（时珍）。 \n【发明】诜曰∶春月采嫩艾作菜食，或和面作馄饨如弹子，吞三、五枚，以饭压之，治 \n一切鬼恶气，长服止冷痢。又以嫩艾作干饼子，用生姜煎服，止泻痢及产后泻血，甚妙。 \n颂曰∶近世有单服艾者，或用蒸木瓜和丸，或作汤空腹饮，甚补虚羸。然亦有毒发则热气冲 \n上，狂躁不能禁，至攻眼有疮出血者，诚不可妄服也。 \n震亨曰∶妇人无子，多由血少不能摄精，俗医谓子宫虚冷，投以辛热，或服艾叶。不知 \n艾性至热，入火灸则气下行；入药服，则气上行。本草止言其温，不言其热。世人喜温， \n率多服之，久久毒发，何尝归咎于艾哉！予考苏颂《图经》而因默有感焉。 \n时珍曰∶艾叶生则微苦太辛，熟则微辛太苦，生温熟热，纯阳也。可以取太阳真火，可 \n以回垂绝元阳。服之则走三阴，而逐一切寒湿，转肃杀之气为融和。灸之则透诸经，而治百 \n种病邪，起沉 之人为康泰，其功亦大矣。苏恭言其生寒，苏颂言其有毒。一则见其能止诸 \n血，一则见其热气上冲，遂谓其性寒有毒，误矣。盖不知血随气而行，气行则血散，热因久 \n服致火上冲之故尔。夫药以治病，中病则止。若素有虚寒痼冷，妇人湿郁带漏之人，以艾和 \n归、附诸药治其病，夫何不可？而乃妄意求嗣，服艾不辍，助以辛热，药性久偏，致使火躁 \n，是谁之咎欤，于艾何尤？艾附丸治心腹、少腹诸痛，调女人诸病，颇有深功。胶艾汤治虚 \n痢，及妊娠产后下血，尤着奇效。老人丹田气弱，脐腹畏冷者，以熟艾入布袋兜其脐腹，妙 \n不可言。寒湿香港脚，亦宜以此夹入袜内。 \n【附方】旧二十三，新二十九。 \n伤寒时气，温病头痛，壮热脉盛。以干艾叶三升。水一斗，煮一升，顿服取汗。（《肘 \n后方》）妊娠伤寒壮热，赤斑变为黑斑，溺血∶用艾叶如鸡子大，酒三升，煮二升半，分为 \n二服。（《伤寒类要》）妊娠风寒卒中，不省人事，状如中风∶用熟艾三两，米醋炒极热，以 \n绢包熨脐下，良久即苏。（《妇人良方》）中风口 ∶以苇筒长五寸，一头刺入耳内，四面以 \n面密封，不透风，一头以艾灸之七壮。患右灸左，患左灸右。（《胜金方》）中风口噤∶熟艾 \n灸承浆一穴，颊车二穴，各五壮。（《千金方》）中风掣痛，不仁不随∶并以干艾斛许，揉团 \n纳瓦甑中，并下塞诸孔，独留一目，以痛处着 \n舌缩口噤∶以生艾捣敷之。干艾浸湿亦可。（《圣济录》）咽喉肿痛∶《医方大成》∶同嫩艾捣 \n汁，细咽之。《经验方》∶用青艾和茎叶一握，同醋捣烂，敷于喉上。冬月取干艾亦得。李亚 \n所传方也。癫痫诸风∶熟艾于阴囊下谷道正门当中间，随年岁灸之。（《斗门方》）鬼击中恶， \n卒然着人，如刀刺状，胸胁腹内 刺切痛不可按，或即吐血、鼻中出血、下血，一名鬼排∶ \n以熟艾如鸡子大三枚，水五升，煎二升，顿服。（《肘后方》）小儿脐风撮口∶艾叶烧灰填脐 \n中，以帛缚定效。或隔蒜灸之，候口中有艾气立愈。（《简便方》）狐惑虫 病患齿无色， \n舌上白，或喜睡不知痛痒处，或下痢，宜急治下部。不晓此者，但攻其上，而下部生虫，食 \n其肛，烂见五脏，便死也。烧艾于管中，熏下部令烟入，或少加雄黄更妙。罂中烧烟亦可。 \n（《肘后方》）头风久痛∶蕲艾揉为丸，时时嗅之，以黄水出为度。（《青囊杂纂》）头风面疮， \n痒出黄水∶艾叶二两，醋一斤，砂锅煎取汁，每薄纸上贴之。一日一、两上。（ \n心腹恶气∶艾叶捣汁饮之。（《药性论》）脾胃冷痛∶白艾末，沸汤服二钱。（《卫生易简方》） \n蛔虫心痛如刺，口吐清水∶白熟艾一升。水三升，煮一升服，吐虫出。或取生艾捣汁， \n五更食香脯一片，乃饮一升，当下虫出。（《肘后方》） \n口吐清水∶干蕲艾煎汤啜之。（《怪证奇方》）。 \n霍乱洞下不止∶以艾一把。水三升，煮一升，顿服。（《外台秘要》） \n老小白痢∶艾姜丸∶用陈北艾四两，干姜（炮）三两，为末，醋煮仓米糊丸梧子大。每 \n服七 \n诸痢久下∶艾叶、陈皮等分，煎汤服之。亦可为末，酒煮烂饭和丸，每盐汤下二、三十 \n丸 \n暴泄不止∶陈艾一把，生姜一块，水煎热服。（《生生编》） \n粪后下血∶艾叶、生姜煎浓汁，服三合。（《千金方》） \n野鸡痔病∶先以槐柳汤洗过，以艾灸上七壮，取效。郎中王及乘骡入西川，数日病痔大 \n作 \n五壮，忽觉一道热气入肠中，因大转泻，血秽并出，泻后遂失胡瓜所在矣。（《经验方》） \n妊娠下血∶张仲景曰∶妇人有漏下者，有半产后下血不绝者，有妊娠下血者，并宜胶艾 \n汤 \n清酒三升，煮取三升，乃纳胶令消尽，每温服一升，日三服。（《金匮要略》） \n妊娠胎动或腰痛，或抢心，或下血不止，或倒产子死腹中∶艾叶一鸡子大，酒四升，煮 \n二升，分二服。（《肘后方》） \n胎动迫心作痛∶艾叶鸡子大。以头醋四升，煎二升，分温服。（《子母秘录》） \n妇人崩中连日不止∶熟艾鸡子大，阿胶（炒为末）半两，干姜一钱。水五盏，先煮艾姜 \n至 \n二盏半，倾出，入胶烊化，分三服，一日服尽。（初虞世《古今录验》） \n产后泻血不止∶干艾叶半两，炙熟老生姜半两，浓煎汤，一服止，妙。（孟诜《食疗本 \n草》）产后腹痛欲死，因感寒起者∶陈蕲艾二斤。焙干，捣铺脐上，以绢覆住，熨斗熨之， \n待口中艾气出，则痛自止矣。（《杨诚经验方》）忽然吐血一二口，或心衄，或内崩∶熟艾三 \n团，水五升，煮二升服。一方∶烧灰水服 \n鼻血不止∶艾灰吹之。亦可以艾叶煎服。（《圣惠方》） \n盗汗不止∶熟艾二钱，白茯神三钱，乌梅三个，水一钟，煎八分，临卧温服。（《通妙 \n真人方》） \n火眼肿痛∶以艾烧烟起，用碗覆之，候烟尽，碗上刮煤下，以温水调化洗眼，即瘥。更 \n入 \n面上 ∶艾灰、桑灰各三升，以水淋汁，再淋至三遍，以五色布纳于中，同煎，令可 \n丸 \n妇人面疮，名粉花疮∶以定粉五钱，菜子油调泥碗内，用艾一、二团，烧烟熏之，候烟 \n尽 \n身面疣目∶艾火灸三壮即除。（《圣惠方》） \n鹅掌风病∶蕲艾（真者）四、五两，水四五碗，煮五、六滚，入大口瓶内盛之，用麻布 \n二层缚之，将手心放瓶上熏之，如冷再热，如神。（陆氏《积德堂方》） \n疮疥熏法∶熟蕲艾一两，木鳖子三钱，雄黄二钱，硫黄一钱。为末，揉入艾中，分作四 \n条。每以一条安阴阳瓦中，置被里烘熏，后服通圣散。（《医方摘要》） \n小儿疳疮∶艾叶一两，水一升，煮取四合，分三服。（《备急方》） \n小儿烂疮∶艾叶烧灰，敷之，良。（《子母秘录》） \n疮口冷不合∶熟艾烧烟熏之。（《经验方》） \n白癞风疮∶干艾随多少，以浸曲酿酒如常法，日饮之，觉痹即瘥。（《肘后方》） \n疔疮肿毒∶艾蒿一担烧灰，于竹筒中淋取汁，以一、二合，和锻石如糊。先以针刺疮至 \n痛，乃点药三遍，其根自拔。玉山韩光以此治人神验。贞观初，衢州徐使君访得此方。予用 \n治三十余人，得效。（孙真人《千金方》） \n发背初起未成，及诸热肿∶以湿纸拓上，先干处是头，着艾灸之。不论壮数，痛者灸至 \n不痛；不痛者灸至痛乃止。其毒即散，不散亦免内攻，神方也。（李绛《兵部手集》） \n痈疽不合，疮口冷滞∶以北艾煎汤洗后，白胶熏之。（《直指方》） \n咽喉骨哽∶用生艾蒿数升，水、酒共一斗，煮四升，细细饮之，当下。（《外台秘要》） \n误吞铜钱∶艾蒿一把，水五升，煎一升，顿服便下。（钱相公《箧中方》） \n诸虫蛇伤∶艾灸数壮甚良。（《集简方》） \n风虫牙痛∶化蜡少许，摊纸上，铺艾，以箸卷成筒，烧烟，随左右熏鼻，吸烟令满口， \n呵 \n\\x实\\x \n【气味】苦、辛，暖，无毒。 \n【主治】明目，疗一切鬼气（甄权）。壮阳，助水脏腰膝，及暖子宫（大明）。 \n【发明】诜曰∶艾子和干姜等分，为末，蜜丸梧子大。空心每服三十丸，以饭三、五匙 \n压之，日再服。治百恶气，其鬼神速走出。田野之人，与此甚相宜也。 \n【附录】夏台 《别录》有名未用曰∶味甘，主百疾，济绝气。 \n弘景曰∶此药神奇乃尔，不复识用，可恨也。 \n时珍曰∶艾名冰台，此名夏台，艾灸百病能回绝气，此主百病济绝气，恐是一物重出也， \n故附于艾后。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>千年艾\n\n内容：（《纲目》） \n【集解】时珍曰∶千年艾出武当太和山中。小茎高尺许。其根如蓬蒿。其叶长寸余，无 \n尖丫，面青背白。秋开黄花，如野菊而小，结实如青珠丹颗之状。三伏日采叶曝干。叶不似 \n艾，而作艾香，搓之即碎，不似艾叶成茸也。羽流以充方物。 \n\\x叶\\x \n【气味】辛、微苦，温，无毒。 \n【主治】男子虚寒，妇人血气诸痛，水煎服之（时珍）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>茵陈蒿\n\n内容：（《本经》上品） \n【释名】藏器曰∶此虽蒿类，经冬不死，更因旧苗而生，故名茵陈，后加蒿字耳。 \n时珍曰∶按∶张揖《广雅》及《吴普本草》并作因尘，不知何义？ \n【集解】《别录》曰∶茵陈生太山及丘陵坡岸上，五月及立秋采，阴干。 \n弘景曰∶今处处有之，似蓬蒿而叶紧细。秋后茎枯，经冬不死，至春又生。 \n韩保升曰∶叶似青蒿而背白。 \n大明曰∶茵陈出和州及南山岭上，一名石茵陈。 \n颂曰∶近道皆有之，不及太山者佳。春初生苗，高三、五寸，似蓬蒿而叶紧细，无花实， \n五月、七月采茎叶阴干，今谓之山茵陈。江宁府一种茵陈，叶大根粗，黄白色，至夏有 \n阶州一种白蒿，亦似青蒿而背白，本土皆以为茵陈入药。今南方医人用山茵陈，乃有 \n数种。或着其说云∶山茵陈，汴京及北地用者，如艾蒿，叶细而背白，其气亦如艾，味苦， \n干则色黑。江南所用者，茎叶都似家茵陈而大，高三、四尺，气极芬香，味甘辛，俗又名龙 \n脑薄荷。吴中所用，乃石香 也，叶至细，色黄味辛，甚香烈，性温。若误作解脾药服，大 \n茵陈是也。大体世方用山茵陈疗脑痛，解伤寒发汗，行肢节滞气，化痰利膈，治劳倦最要 \n详本草正经，惟疗黄胆、利小便，与世方都不应。今试取汴京所用山茵陈为解肌发汗药， \n然少效；江南山茵陈疗伤寒脑痛绝胜。比见诸医议论，谓家茵陈亦能解肌下隔，去胸中烦。 \n方家少用，但可研作饮服之。本草所无，自出俗方。茵陈蒿当别是一物，主疗自异，不得为 \n山茵陈也。此说亦未可据。但以功较之，则江南者为胜；以经言之，则非本草所出。医方所 \n用，更当考论尔。 \n曰∶凡使须用叶有八角者，阴干，去根细锉，勿令犯火。 \n时珍曰∶茵陈昔人多莳为蔬，故入药用山茵陈，所以别家茵陈也。《洪舜俞老圃赋》云∶ \n酣糟紫姜之掌，沐醯青陈之丝，是也。今淮扬人，二月二日犹采野茵陈苗，和粉面作茵陈饼 \n食之。后人各据方士所传，遂致淆乱。今山茵陈二月生苗，其茎如艾。其叶如淡色青蒿而背 \n白，叶歧紧细而扁整。九月开细花黄色，结实大如艾子，花实并与庵 花实相似，亦有无花 \n实者。 \n\\x茎叶\\x \n【气味】苦，平、微寒，无毒。普曰∶神农、岐伯、雷公∶苦，无毒；黄帝∶辛，无毒。 \n权曰∶苦、辛，有小毒。 \n大明曰∶石茵陈∶苦，凉，无毒。伏 砂。 \n张元素曰∶苦、甘，阴中微阳。入足太阳经。 \n【主治】风湿寒热邪气，热结黄胆。久服轻身益气耐老。面白悦长年。白兔食之仙（《 \n本经》）。治通身发黄，小便不利，除头热，去伏瘕（《别录》）。通关节，去滞热，伤寒用 \n之（藏器）。 \n石茵陈∶治天行时疾热狂，头痛头旋，风眼疼，瘴疟。女人症瘕，并闪损乏绝（大明）。 \n【发明】弘景曰∶《仙经》云∶白蒿，白兔食之仙。而今茵陈乃云此，恐是误耳。 \n宗 曰∶张仲景治伤寒热甚发黄，身面悉黄者，用之极效。一僧因伤寒后发汗不彻，有 \n留热，面 \n分之一，十日减三分之二，二十日病悉去。方用山茵陈、山栀子各三分，秦艽、升麻各四钱， \n为散。每用三钱，水四合，煎二合，去滓，食后温服，以知为度。此药以山茵陈为本，故书 \n之。 \n王好古曰∶张仲景茵陈栀子大黄汤，治湿热也。栀子柏皮汤，治燥热也。如苗涝则湿黄， \n苗旱则燥黄。湿则泻之，燥则润之可也。此二药治阳黄也。韩只和、李思训治阴黄，用茵陈 \n附子汤。大抵以茵陈为君主，而佐以大黄、附子，各随其寒热也。 \n【附方】旧二，新六。 \n茵陈羹∶除大热黄胆，伤寒头痛，风热瘴疟，利小便。以茵陈细切，煮羹食之。生食亦 \n宜。（《食医心镜》） \n遍身风痒生疮疥∶用茵陈煮浓汁洗之，立瘥。（《千金方》） \n疡风病∶茵陈蒿两握，水一斗五升，煮取七升。先以皂荚汤洗，次以此汤洗之，冷更 \n作。隔日一洗，不然恐痛也。（崔行功《纂要》） \n风疾挛急∶茵陈蒿一斤，秫米一石，曲三斤，和匀，如常法酿酒服之。（《圣济总录》） \n痫黄如金，好眠吐涎∶茵陈蒿、白藓皮等分，水二钟，煎服，日二服。（《三十六黄方》） \n遍身黄胆∶茵陈蒿一把，同生姜一块，捣烂，于胸前四肢，日日擦之。 \n男子酒疸∶用茵陈蒿四根，栀子七个，大田螺一个（连壳捣烂）。以百沸白酒一大盏， \n冲汁饮之，秘方也。 \n眼热赤肿∶山茵陈、车前子等分。煎汤调（茶调散），服数服。（《直指方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>青蒿\n\n内容：（《本经》下品） \n【释名】草蒿（《本经》）、 方溃（《本经》）、 （音牵去声）、 蒿 （《蜀本》）、 \n香蒿（《衍义》）。 \n保升曰∶草蒿，江东人呼为 蒿，为其气臭似 也。北人呼为青蒿。《尔雅》云∶蒿， \n也。孙炎注云∶荆楚之间，谓蒿为 。郭璞注云∶今人呼青蒿香中炙啖者为 ，是也。 \n时珍曰∶《晏子》云∶蒿，草之高者也。按《尔雅》诸蒿，独 得单称为蒿，岂以诸蒿 \n叶背皆白，而此蒿独青，异于诸蒿故耶？ \n【集解】《别录》曰∶青蒿生华阴川泽。 \n弘景曰∶处处有之，即今青蒿，人亦取杂香菜食之。 \n保升曰∶嫩时醋淹为菹，自然香。叶似茵陈蒿而背不白，高四尺许。四月、五月采，日 \n干入药。《诗》云∶呦呦鹿鸣，食野之蒿。即此蒿也。 \n颂曰∶青蒿春生苗，叶极细，可食。至夏高四、五尺。秋后开细淡黄花，花下便结子， \n如粟米大，八、九月采子，阴干。根、茎、子、叶并入药用，干者炙作饮香尤佳。 \n宗 曰∶青蒿得春最早，人剔以为蔬，根赤叶香。沈括《梦溪笔谈》云∶青蒿一类，自 \n有二种∶一种黄色，一种青色。本草谓之青蒿，亦有所别也。陕西银绥之间，蒿丛中时有一 \n两窠，迥然青色者，土人谓之香蒿。茎叶与常蒿一同，但常蒿色淡青，此蒿深青，如松桧之 \n色。至深秋余蒿并黄，此蒿犹青，其气芬芳。恐古人所用，以深青者为胜。不然，诸蒿何尝 \n不青？ \n时珍曰∶青蒿，二月生苗，茎粗如指而肥软，茎叶色并深青。其叶微似茵陈，而面背俱 \n青。其根白硬。七八月开细黄花颇香。结实大如麻子，中有细子。 \n【修治】 曰∶凡使，惟中为妙，到膝即仰，到腰即俯。使子勿使叶，使根勿使茎，四 \n件若同使，翻然成痼疾。采得叶，用七岁儿七个溺，浸七日七夜，漉出晒干。 \n\\x叶、茎、根、子\\x \n【气味】苦，寒，无毒。 \n时珍曰∶伏硫黄。 \n【主治】疥瘙痂痒恶疮，杀虱，治留热在骨节间，明目（《本经》）。鬼气尸疰伏连，妇 \n人血气，腹内满，及冷热久痢。秋冬用子，春夏用苗，并捣汁服。亦曝干为末，小便入酒和 \n服（藏器）。补中益气，轻身补劳，驻颜色，长毛发，令黑不老，兼去蒜发，杀风毒。心痛 \n热 \n黄，生捣汁服，并贴之（大明）。治疟疾寒热（时珍）。生捣敷金疮，止血止疼良（苏恭）。 \n烧灰 \n隔纸淋汁，和锻石煎，治恶疮息肉 瘢（孟诜）。 \n【发明】颂曰∶青蒿治骨蒸热劳为最，古方单用之。 \n时珍曰∶青蒿得春木少阳之气最早，故所主之证，皆少阳、厥阴血分之病也。按《月令 \n通纂》，言伏内庚日，采青蒿悬于门庭内，可辟邪气。阴干为末，冬至、元旦各服二钱亦良 \n。观此，则青蒿之治鬼疰伏尸，盖亦有所伏也。 \n【附方】旧四，新十四。 \n男妇劳瘦∶青蒿细锉，水三升，童子小便五升，同煎取二升半。去滓入器中煎成膏，丸 \n如梧子大。每空心及卧时，温酒吞下二十丸。（《斗门方》） \n虚劳寒热，肢体倦疼，不拘男妇∶八、九月青蒿成实时采之，去枝梗，以童子小便浸三 \n日，晒干为末。每服二钱，乌梅一个，煎汤服。（《灵苑方》） \n骨蒸鬼气∶童子小便五大斗（澄清），青蒿五斗（八、九月拣带子者最好，细锉）。相和， \n纳大 \n釜中，以猛火煎取三大斗，去滓，溉釜令净，再以微火煎可二大斗，入猪胆一枚，同煎一大 \n斗半，去火待冷，以瓷器盛之。每欲服时，取甘草二、三两，炙熟为末，以煎和捣千杵为丸。 \n空腹粥饮下二十丸，渐增至三十丸止。（崔元亮《海上方》） \n骨蒸烦热∶青蒿一握，猪胆汁一枚，杏仁四十个（去皮尖，炒）。以童子小便一大盏， \n煎五分，空心温服。（《十便良方》） \n虚劳盗汗，烦热口干∶用青蒿一斤（取汁熬膏），入人参末、麦门冬末各一两，熬至可 \n丸，丸如梧子大，每食后米饮服二十丸，名青蒿丸。（《圣方总录》） \n疟疾寒热∶《肘后方》∶用青蒿一握，水二升，捣汁服之。《仁存方》∶用五月五日天未明 \n时采 \n青蒿（阴干）四两，桂心一两。为末。未发前，酒服二钱。《经验方》∶用端午日采青蒿叶（阴 \n干），桂心等分。为末。每服一钱，先寒用热酒；先热用冷酒，发日五更服之。切忌发物。 \n温疟痰甚，但热不寒∶用青蒿二两（童子小便浸焙），黄丹半两，为末。每服二钱，白汤调 \n下。（《仁存方》） \n赤白痢下∶五月五日采青蒿、艾叶等分，同豆豉捣作饼，日干，名蒿豉丹。每用一饼， \n以水一盏半煎服。（《圣济总录》） \n鼻中衄血∶青蒿捣汁服之，并塞鼻中，极验。（《卫生易简方》） \n酒痔便血∶青蒿（用叶不用茎，用茎不用叶），为末。粪前冷水，粪后水酒调服。（《永 \n类钤方》） \n金疮扑损∶《肘后方》∶用青蒿捣封之，血止则愈。一方∶用青蒿、麻叶、锻石等分，五 \n月五日捣和晒干。临时为末，搽之。 \n牙齿肿痛∶青蒿一握，煎水漱之。（《济急方》） \n毒蜂螫人∶嚼青蒿封之即安。（《肘后方》） \n耳出浓汁∶青蒿末，绵裹纳耳中。（《圣惠方》） \n鼻中息肉∶青蒿灰、锻石等分，淋汁熬膏点之。（《圣济总录》） \n\\x子\\x \n【气味】甘，冷，无毒。 \n【主治】明目开胃，炒用。治劳瘦，壮健人小便浸用之。治恶疮疥癣风疹，煎水洗之（ \n大明）。治鬼气，为末酒服方寸匕（孟诜）。功同叶（时珍）。 \n【附方】新一。 \n积热眼涩∶三月三日或五月五日，采青蒿花或子，阴干为末，每井华水空心服二钱。久 \n服明目，可夜看书，名青蒿散。（《十便良方》） \n节间虫∶见虫部。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>黄花蒿\n\n内容：（《纲目》） \n【释名】臭蒿 \n【集解】大明曰∶臭蒿一名草蒿。 \n时珍曰∶香蒿臭蒿通可名草蒿。此蒿与青蒿相似，但此蒿色绿带淡黄，气辛臭不可 \n人家采以罨酱黄酒曲者是也。 \n\\x叶\\x \n【气味】辛、苦，凉，无毒。 \n【主治】小儿风寒惊热（时珍）。 \n\\x子\\x \n【气味】辛，凉，无毒。 \n【主治】治劳，下气开胃，止盗汗及邪气鬼毒（大明）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>白蒿\n\n内容：（《本经》上品） \n【释名】蘩（《尔雅》）、由胡（《尔雅》）、蒌蒿（《食疗》）、 （音商）。 \n时珍曰∶白蒿有水陆二种，《尔雅》通谓之蘩，以其易蘩衍也。曰∶蘩，皤蒿。即今陆 \n生艾蒿也，辛熏不美。曰∶蘩，由胡。即今水生蒌蒿也，辛香而美。曰∶蘩之丑，秋为蒿。 \n则通指水陆二种而言，谓其春时各有种名，至秋老则皆呼为蒿矣。曰赖，曰萧，曰 ，皆老 \n蒿之通名，象秋气肃赖之气。 \n【集解】《别录》曰∶白蒿生中山川泽，二月采。 \n弘景曰∶蒿类甚多，而俗中不闻呼白蒿者。方药家既不用，皆无复识之。 \n恭曰∶《尔雅》∶蘩，皤蒿，即白蒿也，所在有之。叶颇似细艾，上有白毛错涩，粗于青 \n蒿 \n禹锡曰∶蓬蒿可以为菹。故《诗笺》云∶以豆荐蘩菹也。陆玑《诗疏》云∶凡艾白色为 \n皤蒿。今白蒿先诸草发生，香美可食，生蒸皆宜。 \n颂曰∶此草古人以为菹。今人但食蒌蒿，不复食此。或疑白蒿即蒌蒿，而孟诜《食疗》 \n又别着蒌蒿条，所说不同，明是二物，乃知古今食品之异也。又今阶州以白蒿为茵陈，其苗 \n叶亦相似，然以入药，恐不可用也。 \n时珍曰∶白蒿处处有之，有水、陆二种。本草所用，盖取水生者，故曰生中山川泽，不 \n曰山谷平地也。二种形状相似，但陆生辛熏，不及水生者香美尔。《诗》云∶呦呦鹿鸣，食 \n野之苹。苹，即陆生皤蒿，俗呼艾蒿是矣。鹿食九种解毒之草，白蒿其一也。《诗》云∶于 \n以采蘩，于沼于 。《左传》云∶苹蘩蕴藻之菜，可以荐于鬼神，羞于王公。并指水生白 \n蒿而言，则本草白蒿之为蒌蒿无疑矣。郑樵《通志》谓苹为蒌蒿，非矣。鹿乃山兽，蒌乃水 \n蒿。陆玑《诗疏》谓苹为牛尾蒿，亦非矣。牛尾蒿色青不白，细叶直上，状如牛尾也。蒌蒿 \n生陂泽中，二月发苗，叶似嫩艾而歧细，面青背白。其茎或赤或白，其根白脆。采其根茎， \n生熟菹曝皆可食，盖嘉蔬也。《景差大招》云∶吴酸蒿蒌不沾薄。谓吴人善调酸，瀹蒌蒿为 \n齑，不沾不薄而甘美，此正指水生者也。 \n\\x苗根\\x \n【气味】甘，平，无毒。思邈曰∶辛、平。 \n时珍曰∶发疮疥。 \n【主治】五脏邪气，风寒湿痹，补中益气，长毛发令黑，疗心悬，少食常饥。久服轻身 \n，耳目聪明不老（《本经》）。生 ，醋淹为菹食，甚益人；捣汁服，去热黄及心痛；曝为末 \n，米饮空心服一匙，治夏月暴水痢；烧灰淋汁煎，治淋沥疾（孟诜）。利膈开胃，杀河豚鱼 \n毒 \n【发明】弘景曰∶服食家七禽散云∶白兔食白蒿仙，与庵 同法耳。 \n时珍曰∶《本经》列白蒿于上品，有功无毒，而古今方家不知用，岂不得服之之诀欤？ \n【附方】旧一。 \n恶疮癞疾，但是恶疾遍体，面目有疮者，皆可服之∶用白艾蒿十束如升大，煮取汁，以 \n曲及 \n米一如酿酒法，候熟稍服之。（《深师方》） \n\\x子\\x \n【气味】缺 \n【主治】鬼气。为末，酒服之，良（孟诜）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>角蒿\n\n内容：（《唐本草》） \n【集解】恭曰∶角蒿叶似白蒿，花如瞿麦，红赤可爱，子似王不留行，黑色作角。七月、 \n八月采。 \n保升曰∶叶似蛇床、青蒿，子角似蔓荆，实黑而细，秋熟。所在皆有之。 \n宗 曰∶茎叶如青蒿，开淡红紫花，大约径三、四分。花罢结角，长二寸许，微弯。 \n曰∶凡使，勿用红蒿并邪蒿，二味真似角蒿，只是此香而角短尔。采得，于槐砧上细 \n锉用之。 \n【气味】辛、苦，平，有小毒。 \n【主治】干湿 ，诸恶疮有虫者（《唐本》）。治口齿疮，绝胜（宗 ）。 \n【附方】旧二，新一。 \n齿龈宣露，多是疳也。角蒿烧灰，夜涂上。切忌油腻、沙糖、干枣。（《外台秘要》） \n口疮不瘥，入胸中并生者。不拘大人、小儿，以角蒿灰涂之，有汁吐去，一宿效。（《千金 \n方》）月蚀耳疮用蒿灰掺之，良。（《集简方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>KT蒿\n\n内容：（《拾遗》） \n【释名】莪蒿（《尔雅》）、萝蒿（同上）、抱娘蒿。 \n时珍曰∶陆农师云∶KT 之为言高也。莪，亦峨也，莪科高也。可以覆蚕，故谓之萝。 \n抱根丛生，故曰抱娘。 \n【集解】时珍曰∶KT 蒿生高岗，似小蓟，宿根先于百草。《尔雅》云∶莪，萝是也。 \n《诗·小雅》云∶菁菁者，莪。陆玑注云∶即莪蒿也。生泽国渐洳处。叶似斜蒿而细科， \n三 \n月生。茎、叶可生食，又可蒸食，香美颇似蒌蒿。但味带麻，不似蒌蒿甘香。 \n【气味】辛，温，无毒。 \n【主治】破血下气，煮食之（藏器）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>马先蒿\n\n内容：（《本经》中品） \n【释名】马新蒿（《唐本》）、马矢蒿（《本经》）、练石草（《别录》）、烂石草（同上）、 \n虎麻。 \n时珍曰∶蒿气如马矢，故名。马先，乃马矢字讹也。马新，又马先之讹也。 \n弘景曰∶练石草，一名烂石草，即马矢蒿。今方药不复用之。 \n【集解】《别录》曰∶马先蒿、练石草，并生南阳川泽。 \n恭曰∶叶大如茺蔚，花红白色。二月、八月采茎叶，阴干用。八月、九月实熟，俗谓之 \n虎麻是也。一名马新蒿，所在有之。茺蔚苗短小，其子夏中熟。二物初生，极相似也。 \n禹锡曰∶按《尔雅》云∶蔚，牡 。注云，即蒿之无子者。《诗》云∶匪莪伊芳蔚。陆玑 \n云∶牡蒿也。三月始生，七月开花，似胡麻花而紫赤。八月生角，似小豆角，锐而长。一名 \n马新蒿，是也。 \n颂曰∶郭璞以牡 为无子，而陆玑云有子，二说小异。今当用有子者为正。 \n时珍曰∶《别录》牡蒿、马先蒿，原是二条。陆玑所谓有子者，乃马先蒿，而复引无子 \n之牡蒿释之，误矣。牡蒿详见本条。 \n【气味】苦，平，无毒。《别录》曰∶练石草∶寒。 \n【主治】寒热鬼疰，中风湿痹，女子带下病，无子（《本经》）。练石草∶治五癃，破石 \n淋，膀胱中结气，利水道小便（《别录》）。恶疮（弘景）。 \n【附方】旧一。 \n大疯癞疾，骨肉疽败，眉须堕落，身体痒痛∶以马先蒿（一名马矢蒿，一名烂石草）， \n炒捣末。每服方寸匕，食前温酒下，一日三服，一年都瘥。（《肘后方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>阴地厥\n\n内容：（宋《图经》） \n【集解】颂曰∶生邓州顺阳县内乡山谷。叶似青蒿，茎青紫色，花作小穗，微黄，根似 \n细辛。七月采根苗用。 \n时珍曰∶江浙亦有之。外家采制丹砂、硫黄。 \n\\x根苗\\x \n【气味】甘、苦，微寒，无毒。 \n【主治】肿毒风热（苏颂）。 \n【附方】新一。 \n男妇吐血后，胸膈虚热∶阴地厥、紫河车、贯众、甘草各半两。每服三钱，水煎服。（《圣 \n济总录》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>牡蒿\n\n内容：（《别录》下品） \n【释名】齐头蒿。 \n时珍曰∶《尔雅》∶蔚，牡 ，蒿之无子者。则牡之名以此也。诸蒿叶皆尖，此蒿叶独 \n而秃，故有齐头之名。 \n【集解】《别录》曰∶牡蒿，生田野。五月、八月采。 \n弘景曰∶方药不复用。 \n恭曰∶齐头蒿也，所在有之。叶似防风，细薄而无光泽。 \n生苗，其叶扁而本狭，末 有秃歧。嫩时可茹。鹿食九草， \n其一也。秋开细黄花，结实大如车前实，而内子微细不可见，故人以为无子也。 \n\\x苗\\x \n【气味】苦、微甘，温，无毒。 \n【主治】充肌肤，益气，令人暴肥。不可久服，血脉满盛（《别录》）。擂汁服，治阴肿 \n（时珍）。 \n【附方】新一。 \n疟疾寒热∶齐头蒿根、滴滴金根各一把。擂生酒一钟，未发前服。以滓敷寸口，男左女 \n右 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>九牛草\n\n内容：（宋《图经》） \n【集解】颂曰∶生筠州山冈上。二月生苗，独茎，高一尺。叶似艾叶，圆而长，背有白 \n毛，面青。五月采苗用。 \n时珍曰∶陈嘉谟《本草蒙筌》以此为蕲艾，谬矣。 \n\\x苗\\x \n【气味】微苦，有小毒。 \n【主治】解风劳，治身体痛。与甘草同煎服，不入众药用（苏颂）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>茺蔚\n\n内容：（《本经》上品） \n【释名】益母（《本经》）、益明（《本经》）、贞蔚（《别录》）、 （《尔雅》。音推）、 \n野天麻（《会编》）、猪麻（《纲目》）、火 （《本经》）、郁臭草（《图经》）、苦低草（《图 \n经》）、夏枯草（《外台》）、土质汗（《外台》）。 \n时珍曰∶此草及子皆充盛密蔚，故名茺蔚。其功宜于妇人及明目益精，故有益母、益明 \n之称。其茎方类麻，故谓之野天麻。俗呼为猪麻，猪喜食之也。夏至后即枯，故亦有夏枯之 \n名。《近效方》谓之土质汗。林亿云∶质汗出西番，乃热血合诸药煎成，治金疮折伤。益母 \n亦可作煎，治折伤，故名为土质汗也。 \n禹锡曰∶《尔雅》∶萑， 。注云∶今茺蔚也。又名益母。刘歆云∶ ，臭秽也。臭秽， \n即茺蔚也。陆玑云∶ ，益母也。故曾子见之感思。 \n【集解】《别录》曰∶茺蔚生海滨池泽，五月采。 \n弘景曰∶今处处有之。叶如荏，方茎，子形细长，有三棱。方用亦稀。 \n颂曰∶今园圃及田野极多。郭璞注《尔雅》云∶叶似荏，方茎白华，华生节间。节节生 \n花，实似鸡冠子，黑色，茎作四方棱，五月采。又云九月采实，医方稀有用实者。 \n宗 曰∶茺蔚初春生时，亦可浸洗，淘去苦水，煮作菜食。凌冬不凋悴也。 \n时珍曰∶茺蔚近水湿处甚繁。春初生苗如嫩蒿，入夏长三、四尺，茎方如黄麻茎。其叶 \n如艾叶而背青，一梗三叶，叶有尖歧。寸许一节，节节生穗，丛簇抱茎。四、五月间，穗内 \n开小花，红紫色，亦有微白色者。每萼内有细子四粒，粒大如同蒿子，有三棱，褐色，药肆 \n往往以作巨胜子货之。其草生时有臭气，夏至后即枯，其根白色。苏颂《图经》谓其叶似荏 \n，其子黑色，似鸡冠子，九月采实，寇宗 《衍义》谓其凌冬不凋者，皆误传也。此草有白 \n花、紫花二种，茎、叶、子、穗皆一样。但白者能入气分，红者能入血分，别而用之可也。 \n按《闺阁事宜》云∶白花者为益母；紫花者为野天麻。《返魂丹注》云∶紫花者为益母， \n花者不是。陈藏器《本草》云∶茺蔚生田野间，人呼为郁臭草。天麻生平泽，似马鞭草，节 \n节生紫花，花中有子，如青葙子。孙思邈《千金方》云∶天麻草，茎如火麻，冬生苗，夏着 \n赤花，如鼠尾花。此皆似以茺蔚、天麻为二物，盖不知其是一物二种。凡物花皆有赤白，如 \n牡丹、芍药、菊花之类是矣。又按∶郭璞《尔雅注》云∶ ，音推，即茺蔚，又名益母。叶 \n似荏，白华，华生节间。又云∶KT ，音推，方茎，叶长而锐，有穗，穗间有花紫缥色， \n可以为饮，江东呼为牛 。据此则是 、KT 名本相同，但以花色分别之，其为一物无疑 \n矣。宋人重修本草，以天麻草误注天麻，尤为谬失。陈藏器《本草》又有錾菜，云生江南阴 \n地，似益母，方茎对节白花，主产后血病。此即茺蔚之白花者，故其功主血病亦相同。 \n\\x子\\x \n【修治】时珍曰∶凡用，微炒香，亦或蒸熟，烈日曝燥，舂簸去壳，取仁用。 \n【气味】辛、甘，微温，无毒。《别录》曰∶甘，微寒。 \n时珍曰∶甘、辛，温。灰制硫黄。 \n【主治】明目益精，除水气，久服轻身（《本经》）。疗血逆大热，头痛心烦（《别录》） \n。产后血胀（大明）。舂仁生食，补中益气，通血脉，填精髓，止渴润肺（吴瑞）。治风解 \n热 \n，顺气活血，养肝益心，安魂定魄，调女人经脉，崩中带下，产后胎前诸病。久服令人有子 \n（时珍）。 \n【发明】震亨曰∶茺蔚子活血行气，有补阴之功，故名益母。凡胎前产后所恃者，血气 \n也。胎前无滞，产后无虚，以其行中有补也。 \n时珍曰∶茺蔚子味甘、微辛，气温，阴中之阳，手、足厥阴经药也。白花者入气分；紫 \n花者入血分。治妇女经脉不调，胎产一切血气诸病，妙品也，而医方鲜知用。时珍常以之同 \n四物、香附诸药治人，获效甚多。盖包络生血，肝藏血。此物能活血补阴，故能明目、益 \n精、调经，治女人诸病也。东垣李氏言瞳子散大者，禁用茺蔚子，为其辛温主散，能助火也 \n。当归虽辛温，而兼苦甘，能和血，故不禁之。愚谓目得血而能视，茺蔚行血甚捷，瞳子散 \n大，血不足也，故禁之，非助火也。血滞病目则宜之，故曰明目。 \n\\x茎\\x \n大明曰∶苗、叶、根同功。 \n【气味】藏器曰∶寒。时珍曰∶茎、叶∶味辛、微苦。花∶味微苦、甘。根∶味甘。并 \n无毒。 \n镜源曰∶制硫黄、雌黄、砒石。 \n【主治】瘾疹痒，可作浴汤（《本经》）。捣汁服，主浮肿，下水，消恶毒疔肿、乳痈丹 \n游等毒，并敷之。又服汁，主子死腹中，及产后血胀闷。滴汁入耳中，主 耳。捣敷蛇虺毒 \n（ \n下 \n，血晕、血风、血痛，崩中漏下，尿血、泻血，疳痢、痔疾，打扑内损瘀血，大便、小便不 \n通（时珍）。 \n【发明】时珍曰∶益母草之根、茎、花、叶、实，并皆入药，可同用。若治手、足厥阴 \n血分风热，明目益精，调女人经脉，则单用茺蔚子为良。若治肿毒疮疡，消水行血，妇人胎 \n产诸病，则宜并用为良。盖其根、茎、花、叶专于行，而子则行中有补故也。 \n【附方】旧十三，新十。 \n济阴返魂丹∶昝殷《产宝》曰∶此方，乃吉安文江高师禹，备礼求于名医所得者，其效 \n神妙，活人甚多，能治妇人胎前、产后诸疾危证。用野天麻，又名益母，又名火 ，又名负 \n担，即茺蔚子也。叶似艾叶，茎类火麻，方梗凹面，四、五、六月节节开花，红紫色如蓼花， \n南北随处皆有，白花者不是。于端午、小暑，或六月六日，花正开时，连根收采阴干，用叶 \n及花子。忌铁器，以石器碾为细末，炼蜜丸如弹子大随证嚼服用汤使。其根烧存性为末，酒 \n服，功与黑神散不相上下。其药不限丸数，以病愈为度。或丸如梧子大，每服五、七十 \n丸。又可捣汁滤净，熬膏服之。胎前脐腹痛，或作声者，米饮下；胎前产后，脐腹刺痛，胎 \n动不安，下血不止，当归汤下；产后，以童子小便化下一丸，能安魂定魄，血气自然调顺， \n诸病不生。又能破血痛，养脉息，调经络，并温酒下。胎衣不下，及横生不顺，死胎不下， \n经日胀满，心闷心痛，并用炒盐汤下。产后血晕，眼黑血热，口渴烦闷，如见鬼神，狂言不 \n省人事，以童子小便和酒化下；产后结成血块，脐腹奔痛，时发寒热，有冷汗，或面垢颜赤 \n，五心烦热，并用童子小便、酒下，或薄荷自然汁下。产后恶露不尽，结滞刺痛，上冲心胸 \n满闷，童子小便、酒下。产后泻血水，以枣汤下。产后痢疾，米汤下。产后血崩漏下，糯米 \n汤下。产后赤白带下，煎胶艾汤下；月水不调，温酒下。产后中风，牙关紧急，半身不遂， \n失音不语，童便、酒下；产后气喘咳嗽，胸膈不利，恶心吐酸水，面目浮肿，两胁疼痛，举 \n动失力，温酒下。产后月内咳嗽，自汗发热，久则变为骨蒸，童便、酒下；产后鼻衄，舌黑 \n口干，童便酒下。产后两太阳穴痛，呵欠心忪，气短羸瘦，不思饮食，血风身热，手足顽麻 \n，百节疼痛，并米饮化下。产后大小便不通，烦躁口苦者，薄荷汤下。妇人久无子息，温酒 \n下。 \n益母膏∶《近效方》∶治产妇诸疾，及折伤内损有瘀血，每天阴则痛，神方也。三月采益 \n母草一名负担，一名夏枯草，连根叶茎花洗择令净，于箔上摊曝水干，以竹刀切长五寸，勿 \n用铁刀，置于大锅中，以水浸过二、三寸，煎煮，候草烂水减三之二，漉去草，取汁约五 \n、六斗，入盆中澄半日，以绵滤去浊滓，以清汁入釜中，慢火煎取一斗，如稀饧状，瓷瓶封 \n收。每取梨大，暖酒和服，日再服。或和羹粥亦可。如远行，即更炼至可丸收之。服至七日， \n则疼渐平复也。产妇恶露不尽及血晕，一二服便瘥。其药无忌。又能治风，益心力。（《外 \n台秘要》） \n女人难产∶益母草捣汁七大合，煎减半，顿服立止。无新者，以干者一大握，水七合， \n煎服。（韦宙《独行方》） \n胎死腹中∶益母草捣熟，以暖水少许，和绞取汁，顿服之。（韦宙《独行方》）。 \n产后血晕，心气欲绝∶益母草研汁，服一盏，绝妙。（《子母秘录》） \n产后血闭不下者∶益母草汁一小盏，入酒一合，温服。（《圣惠方》） \n带下赤白∶益母草花开时采，捣为末。每服二钱，食前温汤下。（《集验方》） \n小便尿血∶益母草捣汁，服一升立瘥。此苏澄方也。（《外台秘要》） \n赤白杂痢困重者∶益母草（日干）、陈盐梅（烧存性），等分为末。每服三钱，白痢干姜 \n汤、赤痢甘草汤下。名二灵散。（《卫生家宝方》） \n小儿疳痢垂死者∶益母草嫩叶，同米煮粥食之，取足，以瘥为度，甚佳。饮汁亦可。（《广 \n济方》） \n痔疾下血∶益母草叶，捣汁饮之。（《食医心镜》） \n一切痈疮∶妇人妒乳乳痈，小儿头疮，及浸淫黄烂热疮，疥疽阴蚀∶并用天麻草（切） \n五升 \n急慢疔疮∶《圣惠方》∶用益母草捣封之，仍绞五合服，即消。《医方大成》∶用益母草四 \n月连花采之，烧存性。先以小尖刀十字划开疔根，令血出。次绕根开破，捻出血，拭干。 \n以稻草心蘸药捻入疮口，令到底。良久当有紫血出，捻令血净，再捻药入，见红血乃止。 \n一日夜捻药三、五度。重者二日根烂出，轻者一日出。有疮根胀起，即是根出，以针挑之。 \n出后仍敷药生肌易愈。忌风寒、房室、酒肉、一切毒物。疖毒己破∶益母草捣敷，甚妙。（《 \n斗门方》）勒乳成痈∶益母为末。水调涂乳上，一宿自瘥。生捣亦得。（《圣惠方》） \n喉闭肿痛∶益母草捣烂，新汲水一碗，绞浓汁顿饮，随吐愈。冬月用根。（《卫生易简方》） \n粉刺黑斑∶《闺阁事宜》云∶五月五日收带根天麻紫花者，晒干烧灰。以商陆根捣自然 \n汁，加酸醋和搜灰作饼，炭火 过收之。半年方用，入面药，甚能润肌。苏颂曰∶唐天后炼 \n益母草泽面法∶五月五日采根苗具者，勿令着土，曝干捣罗，以面水和成团，如鸡子大，再 \n曝干。 \n仍作一炉，四旁开窍，上下置火，安药中央。大火烧一炊久，即去大火，留小火养之， \n勿令火绝。经一复时出之，瓷器中研治，筛再研，三日收用，如澡豆法，日用。一方∶每十 \n两加滑石一两，胭脂一钱。 \n马咬成疮∶苦低草，切细，和醋炒涂之。（《孙真人方》） \n新生小儿∶益母草五两，煎水浴之，不生疮疥。（《简要济众》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>錾菜\n\n内容：（音惭。《拾遗》） \n【集解】藏器曰∶錾菜生江南阴地，似益母，方茎对节，白花。 \n时珍曰∶此即益母之白花者，乃《尔雅》所谓 是也。其紫花者，《尔雅》所谓KT 是 \n也。 、KT 皆同一音，乃一物二种。故此条亦主血病，与益母功同。郭璞独指白花者为 \n益母，昝殷谓白花者非益母，皆欠详审。嫩苗可食，故谓之菜。寇宗 言茺蔚嫩苗可煮食， \n正合此也。 \n\\x苗\\x \n【气味】辛，平，无毒。 \n【主治】破血，产后腹痛，煮汁服（藏器）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>薇衔\n\n内容：（薇，音眉。《本经》上品） \n【释名】糜衔（《本经》）、鹿衔（《唐本》）、吴风草（《唐本》）、无心（《吴普》）、无 \n颠（《吴普》）、承膏（《别录》）、承肌（《吴普》）。 \n恭曰∶南人谓之吴风草。一名鹿衔草，言鹿有疾，衔此草即瘥也。 \n时珍曰∶据苏说，则薇衔、糜衔当作麋衔也。鹿、麋一类也。按郦道元《水经注》云∶ \n魏兴锡山多生薇衔草，有风不偃，无风独摇。则吴风亦当作无风，乃通。 \n藏器曰∶一名无心草，非草之无心者，方药少用。 \n【集解】《别录》曰∶薇衔生汉中川泽及冤句、邯郸。七月采茎叶，阴干。 \n恭曰∶此草丛生，似茺蔚及白头翁，其叶有毛，赤茎。又有大、小二种∶楚人谓大者为 \n大吴风草，小者为小吴风草。 \n保升曰∶叶似茺蔚，丛生有毛，其花黄色，其根赤黑色。 \n\\x茎叶\\x \n【气味】苦，平，无毒。《别录》曰∶微寒。 \n之才曰∶得秦皮良。 \n【主治】风湿痹，历节痛，惊痫吐舌，悸气贼风，鼠 痈肿（《本经》）。暴症，逐水， \n疗痿蹶。久服轻身明目（《别录》）。妇人服之，绝产无子（藏器）。煎水，洗瘭疽、甲疽、恶 \n疮（时珍，出《外科精义》）。 \n【发明】时珍曰∶麋衔乃《素问》所用治风病自汗药，而后世不知用之，诚缺略也。《素 \n问》∶黄帝曰∶有病身热懈惰，汗出如浴，恶风少气，此为何病？岐伯曰∶病名酒风。治之 \n以 \n泽泻、术各三、五分，麋衔五分，合以三指撮为后饭。后饭者，先服药也。 \n【附方】新二。 \n年深恶疮∶无心草根、钓苓根、野狼毒、白丁香各五钱，麝香一字，为末掺之。又方∶无 \n心 \n小儿破伤风病，拘急口噤∶没心草半两，白附子（炮）二钱半，为末。每服一字，薄荷 \n酒灌下。（《圣济录》） \n【附录】无心草（宋《图经》） 颂曰∶生秦州及商州，凤翔各县皆出之。三月开花， \n五 \n月结实，六、七月采根苗，阴干用。性温，无毒。主积血，逐气块，益筋节，补虚损，润颜 \n色，疗 泄腹痛。 \n时珍曰∶麋衔一名无心草，此草功用与之相近，其图形亦相近，恐即一物也，故附之俟 \n访考焉。鼠耳草，亦名无心，与此不同。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>夏枯草\n\n内容：（《本经》下品） \n【释名】夕句（《本经》）、乃东（《本经》）、燕面（《别录》）、铁色草。 \n震亨曰∶此草夏至后即枯。盖禀纯阳之气，得阴气则枯，故有是名。 \n【集解】《别录》曰∶夏枯草生蜀郡川谷，四月采。 \n恭曰∶处处有之，生平泽。 \n颂曰∶冬至后生，叶似旋复。三月、四月开花，作穗紫白色，似丹参花，结子亦作穗。 \n五月便枯，四月采之。 \n时珍曰∶原野间甚多，苗高一、二尺许，其茎微方。叶对节生，似旋复叶而长大，有细 \n齿，背白多纹。茎端作穗，长一、二寸，穗中开淡紫小花，一穗有细子四粒。丹溪云无子， \n亦欠察矣。嫩苗瀹过，浸去苦味，油盐拌之可食。 \n【正误】宗 曰∶今谓之郁臭。自秋便生，经冬不悴，春开白花，夏结子。 \n震亨曰∶郁臭草有臭味，即茺蔚是也；夏枯草无臭味，明是两物。俱生于春，夏枯先枯 \n而无子；郁臭，后枯而结子。 \n\\x茎叶\\x \n【气味】苦、辛，寒，无毒。 \n之才曰∶土瓜为之使。伏汞砂。 \n【主治】寒热瘰 鼠 头疮，破症，散瘿结气，脚肿湿痹，轻身（《本经》）。 \n【发明】震亨曰∶本草言夏枯草大治瘰 ，散结气。有补养厥阴血脉之功，而不言及。 \n观其退寒热，虚者可使，若实者以行散之药佐之，外以艾灸，亦渐取效。 \n时珍曰∶黎居土《易简方》∶夏枯草治目疼，用沙糖水浸一夜用，取其能解内热、缓肝 \n火也。楼全善云∶夏枯草治目珠疼，至夜则甚者，神效。或用苦寒药点之反甚者，亦神效。 \n盖目珠连目本，即系也，属厥阴之经。夜甚及点苦寒药反甚者，夜与寒亦阴故也。夏枯禀纯 \n阳之气，补厥阴血脉，故治此如神，以阳治阴也。一男子至夜目珠疼，连眉棱骨，及头半边 \n肿痛。用黄连膏点之反甚，诸药不效。灸厥阴、少阳，疼随止，半日又作，月余。以夏枯 \n草二两，香附二两，甘草四钱，为末。每服一钱半，清茶调服。下咽则疼减半，至四、五服 \n良愈矣。 \n【附方】旧一，新六。 \n明目补肝，肝虚目睛痛，冷泪不止，筋脉痛，羞明怕日∶夏枯草半两，香附子一两。为 \n末 \n赤白带下∶夏枯草（花开时采，阴干）为末。每服二钱，米饮下，食前。（《徐氏家传方》） \n血崩不止∶夏枯草为末，每服方寸匕，米饮调下。（《圣惠方》） \n产后血晕，心气欲绝者。夏枯草捣绞汁服一盏，大妙。（《徐氏家传方》） \n扑伤金疮∶夏枯草（口嚼烂）， 上即愈。（《卫生易简》） \n汗斑白点∶夏枯草煎浓汁，日日洗之。（《乾坤生意》） \n瘰 马刀，不问已溃、未溃，或日久成漏∶用夏枯草六两，水二钟，煎七分，食远温服。 \n虚甚者，则煎汁熬膏服，并涂患处，兼以十全大补汤加香附、贝母、远志尤善。此物生血， \n乃治瘰 之圣药也。其草易得，其功甚多。（薛己《外科经验方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>刘寄奴草\n\n内容：（《唐本草》） \n【释名】金寄奴（大明）、乌藤菜（《纲目》）。 \n时珍曰∶按李延寿《南史》云∶宋高祖刘裕，小字寄奴。微时伐荻新洲，遇一大蛇，射 \n之。明日往，闻杵臼声。寻之，见童子数人皆青衣，于榛林中捣药。问其故。答曰∶我主为 \n刘寄奴所射，今合药敷之。裕曰∶神何不杀之？曰∶寄奴王者，不可杀也。裕叱之，童子皆 \n散，乃收药而反。每遇金疮敷之即愈。人因称此草为刘寄奴草。郑樵《通志》云∶江南人因 \n汉时谓刘为卯金刀，乃呼刘为金。是以又有金寄奴之名。江东人谓之乌藤菜云。 \n【集解】恭曰∶刘寄奴草生江南。茎似艾蒿，长三、四尺，叶似山兰草而尖长，一茎直 \n上有穗，叶互生，其子似稗而细。 \n保升曰∶今出越州，蒿之类也。高四、五尺，叶似菊，其花白色，其实黄白色作穗，夏 \n月收苗日干之。 \n颂曰∶今河中府、孟州、汉中、滁州亦有之。春生苗，茎似艾蒿，上有四棱，高二、三 \n尺以来。叶青似柳，四月开碎小黄白花，如瓦松，七月结实似黍而细，根淡紫色似莴苣。六 \n月、七月采苗及花子通用。 \n时珍曰∶刘寄奴一茎直上。叶似苍术，尖长糙涩，面深背淡。九月茎端分开数枝，一枝 \n攒簇十朵小花，白瓣黄蕊，如小菊花状。花罢有白絮，如苦 花之絮。其子细长，亦如苦 \n子。所云实如黍稗者，似与此不同，其叶亦非蒿类。 \n\\x子（苗同）\\x \n【修治】 曰∶凡采得，去茎叶，只用实。以布拭去薄壳令净，拌酒蒸，从巳至申，曝 \n干用。 \n时珍曰∶茎、叶、花、子皆可用。 \n【气味】苦，温，无毒。 \n【主治】破血下胀。多服令人下痢（苏恭）。下血止痛，治产后余疾，止金疮血，极效 \n（《别 \n录》）。心腹痛，下气，水胀血气，通妇人经脉症结，止霍乱水泻（大明）。小儿尿血，新者 \n研末服（时珍）。 \n【附方】旧一，新七。 \n大小便血∶刘寄奴为末，茶调空心服二钱，即止。（《集简方》） \n折伤瘀血在腹内者∶刘寄奴、骨碎补、延胡索各一两。水二升，煎七合，入酒及童子小 \n便各一合，顿温服之。（《千金方》） \n血气胀满∶刘寄奴穗实为末。每服三钱，酒煎服。不可过多，令人吐利。此破血之仙 \n药也。（《卫生易简方》） \n霍乱成痢∶刘寄奴草煎汁饮。（《圣济总录》） \n汤火伤灼∶刘寄奴捣末。先以糯米浆鸡翎扫上，后乃掺末。并不痛，亦无痕，大验 \n之方。凡汤火伤，先以盐末掺之，护肉不坏，后乃掺药为妙。（《经验方》） \n风入疮口肿痛∶刘寄奴为末。掺之即止。（《圣惠方》） \n小儿夜啼∶刘寄奴半两，地龙（炒）一分，甘草一寸。水煎，灌少许。（《圣济总录》） \n赤白下痢，阴阳交带，不问赤白∶刘寄奴、乌梅、白姜等分。水煎服。赤加梅，白加姜。（《艾 \n元英如宜方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>曲节草\n\n内容：（宋《图经》） \n【释名】六月凌（音令。《图经》）、六月霜（《纲目》）、绿豆青（《图经》）、蛇蓝。 \n时珍曰∶此草性寒，故有凌、霜、绿豆之名。 \n【集解】颂曰∶曲节草生筠州。四月生苗，茎方色青有节，叶似刘寄奴而青软，七、八 \n月着花似薄荷，结子无用。五月、六月采茎叶，阴干。 \n\\x茎叶\\x \n【气味】甘，平，无毒。 \n【主治】发背疮，消痈肿，拔毒。同甘草作末，米汁调服 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>丽春草\n\n内容：（宋《图经》） \n【释名】仙女蒿（《图经》）、定参草。 \n颂曰∶丽春草，生檀 山川谷，檀 山在 \n高密界。河南淮阳郡、 川及谯郡、汝南郡等，并呼为龙芊草。河北近山、邺郡、汲郡，并 \n名丛兰艾。上党紫团山亦有，名定参草，又名仙女蒿。今所在有之。甚疗 黄，人莫能知。 \n时珍曰∶此草有殊功，而不着其形状。今罂粟亦名丽春草，九仙子亦名仙女娇，与此同 \n名，恐非一物也。当俟博访。 \n\\x花及根\\x \n【气味】甘，微温，无毒。 \n【主治】 黄黄胆（苏颂）。 \n【发明】颂曰∶唐天宝中， 川郡杨正进方，名医皆用有效。其方云∶丽春草疗因时患 \n伤热，变成 黄，遍身壮热，小便黄赤，眼如金色，面又青黑，心头气痛，绕心如刺，头旋 \n欲倒，兼胁下有瘕气，及黄胆等，经用有验。其药春三月采花，阴干一升，捣散。每平明空 \n腹取三方寸匕，和生麻油一盏顿服，日一服，隔五日再进，以知为度。其根疗黄胆，捣汁一 \n盏，空腹顿服，须臾即利三两行，其疾立已。一剂不能全愈，隔七日更一剂，永瘥。忌酒、 \n面、猪、鱼、蒜、粉、酪等。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>旋复花\n\n内容：（《本经》下品） \n【释名】金沸草（《本经》）、金钱花（《纲目》）、滴滴金（《纲目》）、盗庚（《尔雅》）、 \n夏菊（《纲目》）、戴椹（《别录》）。 \n宗 曰∶花绿繁茂，圆而覆下，故曰旋复。 \n时珍曰∶诸名皆因花状而命也。《尔雅》云∶ ，盗庚也。盖庚者，金也，谓其夏开黄 \n花，盗窃金气也。《酉阳杂俎》云∶金钱花，一名毗尸沙，自梁武帝时始进入中国。 \n【集解】《别录》曰∶旋复生平泽川谷。五月采花，日干，二十日成。 \n弘景曰∶出近道下湿地，似菊花而大。别有旋 根，出河南，北国亦有，形似芎 ，惟 \n合旋 膏用之，余无所用，非此旋复花根也。 \n保升曰∶叶似水苏，花黄如菊，六月至九月采花。 \n颂曰∶今所在皆有。二月以后生苗，多近水旁，大似红蓝而无刺，长一、二尺以来，叶 \n似柳，茎细。六月开花如菊花，小铜钱大，深黄色。上党田野人呼为金钱花，七八月采花。 \n今近道人家园圃所莳金钱花，花叶并同，极易繁盛，恐即旋复也。 \n宗 曰∶旋复叶如大菊，又如艾蒿。秋开花大如梧桐子，花淡黄色，其香过于菊。别有 \n旋花，乃鼓子花，非此花也。见本条。 \n时珍曰∶花状如金钱菊。水泽边生者，花小瓣单；人家栽者，花大蕊簇，盖壤瘠使然。 \n其根细白。俗传露水滴下即生，故易繁，盖亦不然。 \n\\x花\\x \n【修治】 曰∶采得花，去蕊并壳皮及蒂子，蒸之，从巳至午，晒干用。 \n【气味】咸，温，有小毒。《别录》曰∶甘，微温，冷利。 \n权曰∶甘，无毒。大明曰∶无毒。宗 曰∶苦、甘、辛。 \n【主治】结气胁下满，惊悸，除水，去五脏间寒热，补中下气（《本经》）。 \n消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮，风气湿痹，皮间死肉，目中眵 ，利大 \n肠，通血脉，益色泽（《别录》）。主水肿，逐大腹，开胃，止呕逆不下食（甄权）。行痰水， \n去头目风（宗 ）。消坚软痞，治噫气 \n【发明】颂曰∶张仲景治伤寒汗下后，心下痞坚，噫气不除，有七物旋复代赭汤；杂治 \n妇人，有三物旋复汤。胡洽居士治痰饮在两胁胀满，有旋复花丸，用之尤多。成无己曰∶硬 \n则气坚，旋复之咸，以软痞坚也。 \n震亨曰∶寇宗 言其行痰水去头目风，亦走散之药。病患涉虚者，不宜多服，冷利大肠 \n，宜戒之。 \n时珍曰∶旋复乃手太阴肺、手阳明大肠药也。所治诸病，其功只在行水、下气、通血脉 \n尔。李卫公言∶嗅其花能损目。唐慎微《本草》误以旋花根方收附此下，今改正之。 \n【附方】旧一，新三。 \n中风壅滞∶旋复花，洗净焙研，炼蜜丸梧子大。夜卧以茶汤下五丸至七丸、十丸。（《经 \n验后方》）半产漏下，虚寒相抟，其脉弦芤∶旋复花汤∶用旋复花三两，葱十四茎，新绛少 \n许。水三升，煮一升，顿服。（《金匮要略》） \n月蚀耳疮∶旋复花烧研，羊脂和涂之。（《集简方》） \n小儿眉癣，小儿眉毛眼睫，因癣退不生∶用野油花（即旋复花）、赤箭（即天麻苗）、防 \n风等分，为末。洗净，以油调涂之。（《总微论》） \n\\x叶\\x \n【主治】敷金疮，止血（大明）。治疔疮肿毒（时珍）。 \n\\x根\\x \n【主治】风湿（《别录》）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>青葙\n\n内容：（《本经》下品） \n【释名】草蒿（《本经》）、萋蒿（《本经》）、昆仑草（《唐本》）、野鸡冠（《纲目》）、 \n鸡冠苋（《纲目》）、子名草决明（《 \n时珍曰∶青葙名义未详。胡麻叶亦名青 ，此草又多生于胡麻地中，与之同名，岂以其 \n相似而然耶？青蒿，亦名草蒿，其功相似，而名亦相同，何哉？其子明目，与决明子同功， \n故 \n有草决明之名。其花、叶似鸡冠，嫩苗似苋，故谓之鸡冠苋。郑樵《通志》言俗名牛尾蒿者， \n误矣。 \n【集解】《别录》曰∶青葙生平谷道旁。三月采茎叶，阴干。五月、六月采子。 \n弘景曰∶处处有之。似麦闸极花，其子甚细。别有草蒿，或作草 ，主疗殊相类，形名又 \n相似可疑，而实两种也。 \n恭曰∶此草苗高尺余，叶细软，花紫白色，实作角，子黑而扁光，似 \n苋实而大，生下湿地，四月、五月采，荆襄人名为昆仑草。 \n颂曰∶今江淮州郡近道亦有之。二月生青苗，长三、四尺。叶阔似柳而软。茎似蒿，青 \n红色。六月、七月内生花，上红下白。子黑光而扁，似莨菪。根亦似蒿根而白，直下独茎生 \n根。六月、八月采子。 \n时珍曰∶青葙生田野间，嫩苗似苋可食，长则高三四尺。苗、叶、花、实与鸡冠花一样 \n无别。但鸡冠花穗或有大而扁、或团者。此则梢间出花穗，尖长四、五寸，状如兔尾，水红 \n色，亦有黄白色者。子在穗中，与鸡冠子及苋子一样难辨。苏恭言其结角，误矣。萧炳言黄 \n花者名陶朱术，与陈藏器所说不同。又有天灵草，亦此类也，并附于下。 \n\\x茎叶\\x \n【修治】 曰∶凡用先烧铁杵臼，乃捣用之。 \n【气味】苦，微寒，无毒。 \n【主治】邪气，皮肤中热，风瘙身痒，杀三虫（《本经》）。恶疮疥虱痔蚀，下部 疮（《别 \n录》）。捣汁服，大疗温疠（苏恭）。止金疮血（大明）。 \n\\x子\\x \n【气味】苦，微寒，无毒。权曰∶苦，平。 \n【主治】唇口青（《本经》）。治五脏邪气，益脑髓，镇肝，明耳目，坚筋骨，去风寒湿 \n痹（大明）。治肝脏热毒冲眼，赤障青盲翳肿，恶 \n【发明】炳曰∶理眼，有青葙子丸。 \n宗 曰∶青葙子，《经》中不言治眼，惟《药性论》、《日华子》始言治肝明目。今人多 \n用治眼，殊与《经》意不相当。 \n时珍曰∶青葙子治眼，与决明子、苋实同功。《本经》虽不言治眼，而云一名草决明， \n主唇口青，则其明目之功可知矣。目者肝之窍，唇口青者足厥阴经之证，古方除热亦多用之， \n青葙子之为厥阴药，又可知矣。况用之治目，往往有验，尤可征。据《魏略》云∶初平中有 \n青牛先生，常服青葙子丸，年百余岁，如五、六十者。 \n【附方】旧一。 \n鼻衄不止，眩冒欲死∶青葙子汁三合，灌入鼻中。（《贞元广利方》） \n【附录】桃朱术 \n炳曰∶青箱，一种花黄者，名陶朱术，苗相似。 \n藏器曰∶桃朱术生园中，细如芹，花紫，子作角。以镜向旁敲之，则子自发。五月五日 \n乃收子，带之令妇人为夫所爱。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>雁来红\n\n内容：时珍曰∶茎、叶、穗、子并与鸡冠同。其叶九月鲜红，望之如花，故名，吴人呼为老少 \n年。一种六月叶红者，名十样锦。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>天灵草\n\n内容：时珍曰∶按《土宿真君本草》云∶状如鸡冠花，叶亦如之，折之有液如乳，生江、湖、 \n荆南陂池间。五月取汁，可制雄、硫，煮雌炼砂。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>思子\n\n内容：曰∶思莫子、鼠细子，二件真似青葙子，只是味不同。思 子味粗，煎之有涎。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>鸡冠\n\n内容：（宋《嘉 》） \n【释名】时珍曰∶以花状命名。 \n【集解】时珍曰∶鸡冠处处有之。三月生苗，入夏高者五、六尺；矬者，才数寸。其叶 \n青柔，颇似白苋菜而窄，梢有赤脉。其茎赤色，或圆、或扁，有筋起。六、七月梢间开花， \n有红、白、黄三色。其穗圆长而尖者，俨如青葙之穗；扁卷而平者，俨如雄鸡之冠。花大有 \n围一、二尺者，层层卷出可爱。子在穗中，黑细光滑，与苋实一样。其穗如秕麦状。花最耐 \n久，霜后始蔫。 \n\\x苗\\x \n【气味】甘，凉，无毒。 \n【主治】疮痔及血病（时珍）。 \n\\x子\\x \n【气味】甘，凉，无毒。 \n【主治】止肠风泻血，赤白痢（藏器）。崩中带下，入药炒用 \n\\x花\\x \n【气味】同上。 \n【主治】痔漏下血，赤白下痢，崩中赤白带下，分赤白用（时珍）。 \n【附方】新十一。 \n吐血不止∶白鸡冠花，醋浸煮七次，为末。每服二钱，热酒下。（《经验方》） \n结阴便血∶鸡冠花、椿根白皮等分，为末，炼蜜丸梧子大。每服三十丸，黄 汤下，日 \n二服。（《圣济总录》）粪后下血∶白鸡冠花并子（炒），煎服。（《圣惠方》） \n五痔肛肿久不愈，变成 疮∶用鸡冠花、凤眼草各一两。水二碗，煎汤频洗。（《卫生宝 \n鉴》） \n下血脱肛∶白鸡冠花、防风等分，为末，糊丸梧子大，空心米饮每服七十丸。一方∶白 \n鸡冠花（炒）、棕榈灰、羌活一两。为末。每服二钱，米饮下。（《永类钤方》） \n经水不止∶红鸡冠花一味，晒干为末。每服二钱，空心酒调下。忌鱼腥、猪肉。（孙氏 \n《集效方》）产后血痛∶白鸡冠花，酒煎服之。（《李楼奇方》） \n妇人白带∶白鸡冠花晒干，为末。每旦空心酒服三钱。赤带，用红者。（孙氏《集效方》） \n白带沙淋∶白鸡冠花、苦壶卢等分，烧存性，空心火酒服之。（《摘玄》） \n赤白下痢∶鸡冠花，煎酒服。赤，用红；白，用白。（《集简方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>红蓝花\n\n内容：（宋《开宝》） \n【释名】红花（《开宝》）、黄蓝颂曰∶其花红色，叶颇似蓝，故有蓝名。 \n【集解】志曰∶红蓝花，即红花也，生梁汉及西域。《博物志》云∶张骞得种于西域。 \n今魏地亦种之。 \n花下作 多刺，花出 \n大。其花曝干，以染真红，又作胭脂。 \n时珍曰∶红花，二月、八月、十二月皆可以下种，雨后布子，如种麻法。初生嫩叶、苗， \n亦可食。其叶如小蓟叶。至五月开花，如大蓟花而红色。侵晨采花捣熟，以水淘，布袋绞去 \n黄汁又捣，以酸粟米泔清又淘，又绞袋去汁，以青蒿覆一宿，晒干。或捏成薄饼，阴干收之。 \n入药搓碎用。其子五月收采，淘净捣碎煎汁，入醋，拌蔬食，极肥美。又可为车脂及烛。 \n\\x花\\x \n【气味】辛，温，无毒。 \n元素曰∶入心养血，谓其苦温，阴中之阳，故入心。佐当归，生新血。 \n好古曰∶辛而甘苦温，肝经血分药也。入酒，良。 \n【主治】产后血晕口噤，腹内恶血不尽绞痛，胎死腹中，并酒煮服。亦主蛊毒（《开宝》）。 \n多用破留血，少用养血（震亨）。活血润燥，止痛散肿，通经（时 \n【发明】时珍曰∶血生于心包，藏于肝，属于冲任。红花汁与之同类，故能行男子血脉， \n通女子经水。多则行血，少则养血。按《养 漫笔》云∶新昌徐氏妇，病产晕已死，但胸膈 \n微热。有名医陆氏曰∶血闷也。得红花数十斤，乃可活。遂亟购得，以大锅煮汤，盛三桶于 \n窗格之下，舁妇寝其上熏之，汤冷再加。有顷指动，半日乃苏。按此亦得唐许胤宗，以黄 \n汤熏柳太后风病之法也。 \n【附方】旧四，新四。 \n六十二种风，张仲景治六十二种风，兼腹内血气刺痛∶用红花 \n一大两，分为四分。以酒一大升，煎钟半，顿服之。不止再服。（《图经本草》） \n一切肿疾∶红花，熟，捣，取汁，服。不过三服，便瘥。（《外台秘要》） \n喉痹壅塞不通者∶红蓝花捣，绞取汁一小升服之，以瘥为度。如冬月无生花，以干者浸 \n湿绞汁，煎 \n热病胎死∶红花，酒煮汁，饮二、三盏。（《熊氏补遗》） \n胎衣不下∶方同上。（《杨氏产乳》） \n产后血晕，心闷气绝∶红花一两，为末，分作二服，酒二盏，煎一盏，连服。如口噤， \n斡开灌之，或入小便尤妙。（《子母秘录》） \n耳出水 红蓝花三钱半，枯矾五钱。为 \n方去矾。（《圣惠方》） \n噎膈拒食∶端午采头次红花（无灰酒拌，焙干）、血竭（瓜子样者）等分为末。无灰酒 \n一盏，隔汤顿热，徐咽。初服二分；次日，四分；三日，五分。（杨起《简便方》） \n\\x子\\x \n【主治】天行疮痘，水吞数颗（《开宝》）。 \n功与花同（苏颂）。 \n【附方】旧二，新一。 \n血气刺痛∶红蓝子一升。捣碎，以无灰酒一大升拌子，曝干，重捣筛，蜜丸梧子大，空 \n心酒下四十丸。（张仲景方） \n疮疽不出∶红花子、紫草茸各半两，蝉蜕二钱半，水酒钟半，煎减半，量大小加减服。 \n（庞安常《伤寒论》） \n女子中风，血热烦渴∶以红蓝子五合。熬捣，旦日取半大匙，以水一升 \n渣，细细咽之。（《贞元广利方》） \n\\x苗\\x \n【主治】生捣，涂游肿（《开宝》）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>番红花\n\n内容：（《纲目》） \n【释名】洎夫蓝（《纲目》）、撒法郎。 \n【集解】时珍曰∶番红花，出西番回回地面及天方国，即彼地红蓝花也。 \n元时，以入食馔用。按∶张华《博物志》言∶张骞得红蓝花种于西域，则此即一种，或方 \n域地气稍有异耳。 \n【气味】甘，平，无毒。 \n【主治】心忧郁积，气闷不散，活血。久服令人心喜。又治惊悸（时珍）。 \n【附方】新一。 \n人所传。（王玺《医 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>燕脂\n\n内容：（《纲目》） \n【释名】 赦。 \n时珍曰∶按伏候《中华古今注》云∶燕脂起自纣，以红蓝花汁凝作之。调脂饰女面，产 \n于燕地，故曰燕脂。或作 赦。匈奴人名妻为阏氏，音同燕脂，谓其颜色可爱如燕脂也。俗 \n作胭肢、胭支者，并谬也。 \n【集解】时珍曰∶燕脂有四种∶一种以红蓝花汁染胡粉而成，乃《苏鹗演义》所谓 \n燕脂叶似蓟，花似蒲，出西方，中国谓之红蓝，以染粉为妇人面色者也。一种以山燕脂花汁 \n染粉而成，乃《段公路北户录》所谓端州山间有花丛生，叶类蓝，正月开花似蓼，土人采含 \n苞者为燕脂粉，亦可染帛，如红蓝者也。一种以山榴花汁作成者，郑虔《胡本草》中载之。 \n一种以紫矿染绵而成者，谓之胡燕脂，李 《南海药 \n紫梗是也。大抵皆可入血病药用。又落葵子亦可取汁和粉饰面，亦谓之胡燕脂，见菜部。 \n【气味】甘，平，无毒。 \n【主治】小儿 耳，浸汁滴之（《开宝》）。活血，解痘毒（时珍）。 \n【附方】新五。 \n婴孩鹅口，白浓如纸∶用坯子燕脂，以乳汁调涂之，一宿效。男用女乳，女用男乳。（《集 \n简方》） \n漏疮肿痛∶猪胆七个，绵燕脂十个洗水，和匀，搽七次即可。（《救急方》） \n防痘入目∶燕脂嚼汁点之。（《集简方》） \n痘疮倒陷∶干燕脂三钱，胡桃（烧存性）一个，研末，用胡荽煎酒服一钱，再服取效。 \n（《救急方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>大蓟、小蓟\n\n内容：（《别录》中品） \n【释名】虎蓟（弘景）、马蓟（《范 \n华》）、鸡项草（《图经》）、 \n小蓟是猫蓟，叶并多刺，相似。田野甚多，方药少用。 \n虎、曰猫，因其苗状狰狞也。曰马者，大也。牛蒡，因其根似牛蒡根也。鸡项，因其茎似鸡 \n之项也。千针、红花，皆其花状也。郑樵《通志》谓《尔雅》之KT ，曰狗毒者即此，未 \n知是否？ \n【集解】《别录》曰∶大小蓟，五月采。 \n恭曰∶大小蓟，叶虽相似，功力有殊。大蓟生山谷，根疗痈肿；小蓟生平泽，不能消肿， \n而俱能破血。 \n颂曰∶小蓟处处有之，俗名青刺蓟。二月生苗，二、三寸时，并根作菜，茹食甚美。四 \n月高尺余，多刺，心中出花，头如红蓝花而青紫色，北人呼为千针草。四月采苗，九月采根， \n并阴干用。大蓟苗根与此相似，但肥大尔。 \n宗 曰∶大、小蓟皆相似，花如髻。但大蓟高三四尺，叶皱；小蓟高一尺许，叶不皱， \n以此为异。作菜虽有微芒，不害人。 \n\\x大蓟根叶\\x（同） \n【气味】甘，温，无毒。弘景曰∶有毒。权曰∶苦，平。 \n大明曰∶叶凉。 \n【主治】女子赤白沃，安胎，止吐血鼻衄，令人肥健（《别录》）。 \n捣根绞汁服半升，主崩中血下立瘥（甄权）。叶∶治肠痈，腹脏瘀血， \n作晕扑损，生研，酒并小便任服。又恶疮疥癣，同盐研 之（大明）。 \n小蓟根（苗同） \n【气味】甘，温，无毒。大明 \n曰∶凉。 \n【主治】养精保血（《别录》）。破宿血，生新血，暴下血血崩，金疮出血，呕血等，绞 \n取汁温服。作煎和糖，合金疮，及蜘蛛蛇蝎毒，服之亦佳（藏器）。治热毒风，并胸膈烦闷， \n苗∶去烦热，生研汁服（并大明）。作菜食，除风热。夏月热烦 \n瘥（孟诜）。 \n【发明】大明曰∶小蓟力微，只可退热，不似大蓟能健养下气也。 \n恭曰∶大小蓟皆能破血。但大蓟兼疗痈肿，而小蓟专主血，不能消肿也。 \n【附方】旧六，新九。 \n心热吐血口干∶用刺蓟叶及根，捣绞取汁，每顿服二小盏。（《圣惠方》） \n舌硬出血不止∶刺蓟捣汁，和酒服。干者为末，冷水服。（《普济方》） \n九窍出血∶方同上。（《简要济众》） \n卒泻鲜血∶小蓟叶捣汁，温服一升。（《梅师方》） \n崩中下血∶大、小蓟根一升，酒一斗，渍五宿，任饮。亦可酒煎服，或生捣汁。温服。 \n又方∶小蓟茎叶洗切，研汁一盏，入生地黄汁一盏，白术半两，煎减半，温服。（《千金方》） \n堕胎下血∶小蓟根叶、益母草五两。水二大碗，煮汁一碗，再煎至一盏，分二服，一日 \n服尽。（《圣济总录》） \n金疮出血不止∶小蓟苗捣烂涂之。（孟诜《食疗本草》） \n小便热淋∶马蓟根，捣汁服。（《圣惠方》） \n鼻塞不通∶小蓟一把，水二升，煮取一升，分服。（《外台秘要》方） \n小儿浸淫，疮痛不可忍，发寒热者∶刺蓟叶新水调敷疮上，干即易之。（《简要济众方》） \n癣疮作痒∶刺蓟叶，捣汁服之。（《千金方》） \n妇人阴痒∶小蓟煮汤，日洗三次。（《普济方》） \n诸 不合∶虎蓟根、猫蓟根、酸枣根、枳根、杜衡各一把，斑蝥三分。炒为末，蜜丸枣 \n大。 \n疔疮恶肿∶千针草四两，乳香一两，明矾五钱，为末。酒服二钱，出汗为度。（《普济 \n方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>续断\n\n内容：（《本经》上品） \n【释名】属折（《本经》）、接骨（《别录》）、龙豆（《本经》）、南草（《别录》）。 \n时珍曰∶续断、属折、接骨，皆 \n以功命名也。 \n【集解】《别录》曰∶续断生常山山谷，七月、八月采，阴干。 \n日采。 \n弘景曰∶按《桐君药录》云∶续断生蔓延，叶细茎如荏，大根本，黄白有汁，七月、八 \n月采根。今皆用茎叶节节断，皮黄皱，状如鸡脚者，又呼为桑上寄生。时人又有接骨树，高 \n丈余许，叶似蒴 ，皮主金疮。广州又有续断藤，一名诺藤，断其茎，以器承取汁饮，疗虚 \n损绝伤，用沐头，长发，折枝插地即生。恐皆非真。李当之云是虎蓟，与此大乖，但虎蓟亦 \n疗血。 \n恭曰∶所在山谷皆有。今俗用者，叶似苎而茎方，根如大蓟，黄白色。陶说非也。 \n颂曰∶今陕西、河中、兴元、 \n舒、越、晋、绛诸州亦有之。三月以后生苗，干四棱，似 \n苎麻，叶两两相对而生。四月开花，红白色，似益母花。根如大蓟，赤黄色。谨按∶《范汪 \n方》云∶续断即是马蓟，与小蓟叶相似，但大于小蓟尔。叶似旁翁菜而小浓，两边有刺，刺 \n人，其花紫色，与今越州所图者相类。而市之货者，亦有数种，少能辨其粗良。医人但以节 \n节断、皮黄皱者为真。 \n曰∶凡使勿用草茅根，缘真相似，若误服令人筋软。 \n时珍曰∶续断之说不一。桐君言是蔓生，叶似荏。李当之、范汪并言是虎蓟。《日华子》 \n言是大蓟，一名山牛 \n蓟条，颇难依据。但自汉以来，皆以大蓟为续断，相承久矣。究其实，则二苏所云，似与桐 \n君相符，当以为正。今人所用，以川中来，色赤而瘦，折之有烟尘起者为良焉。郑樵《通志》 \n谓范汪所说者乃南续断，不知何据？盖以别川续断耳。 \n\\x根\\x \n【修治】 曰∶凡采得根，横切锉之，又去向里硬筋，以酒浸一伏时，焙干，入药用。 \n【气味】苦，微温，无毒。《别录》曰∶辛。普曰∶神农、雷公、 \n李当之∶苦，无毒；扁鹊∶辛，无毒。 \n之才曰∶地黄为之使，恶雷丸。 \n【主治】伤寒，补不足，金疮痈疡折跌，续筋骨，妇人乳难。久服益气力 \n妇人崩中漏血，金疮血内漏，止痛生肌肉，及 伤恶血腰痛 \n毒，通宣血脉（甄权）。助气，补五劳七伤，破症结瘀 \n妇 \n人产前后一切病，胎漏，子宫冷，面黄虚肿，缩小便，止泄精尿血（大明）。 \n【发明】时珍曰∶宋张叔潜秘书，知剑州时，其阁下病血痢。一医用平胃散一两，入川 \n续断末二钱半。每服二钱，水煎服即愈。绍兴壬子，会稽时行痢疾。叔潜之子以方传人，往 \n往有验。小儿痢服之效。 \n【附方】旧二，新二。 \n小便淋沥∶生续断捣绞汁服。即马蓟根也。（《古今录验》）妊娠胎动，两、三月堕，预 \n宜服此∶川续断（酒浸）、杜仲（姜汁炒去丝）各二两。为末，枣肉煮烂杵和丸梧子大。每 \n服三 \n十丸，米饮下。产后诸疾血晕，心闷烦热，厌厌气欲绝，心头硬，乍寒乍热∶续断皮一握。 \n水三升，煎二升，分三服。如人行一里，再服，无所忌。此药救产后垂死。（《子母秘录》） \n打扑伤损，闪肭骨节∶用接骨草叶捣烂罨之，立效。（《卫生易简方 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>苦\n\n内容：（音袄。《别录》下品） \n【释名】钩、 （《尔雅》）、苦板。 \n时珍曰∶凡物稚曰 ，此物嫩时可食，故以名之。 \n【集解】弘景曰∶苦 \n处处有之，伧人取茎生食之。 \n保升曰∶所在下湿 \n地有之，茎圆无刺，可生啖，子若猫蓟。五月五日采苗，曝干。 \n恭曰∶今人以为漏芦，非也。 \n时珍曰∶《尔雅》钩、 。即此苦 也。 大 \n如拇指，中空，茎头有苔似蓟，初生可食。许慎《说文》言∶江南人食之下气。今浙东人清 \n明节采其嫩苗食之，云一年不生疮疖。亦捣汁和米为食，其色清，久留不败。《造化指南》 \n云∶苦板大者名苦藉，叶如地 \n其无花实者，名地胆草，汁苦如胆也。处处湿地有之。入炉火家用。 \n\\x苗\\x \n【气味】苦，微寒，无毒。 \n【主治】面目通身漆疮。烧灰敷之，亦可生食（《别录》）。烧灰疗金 \n治丹毒（大明）。煎汤洗痔， \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>漏芦\n\n内容：（《本经》上品） \n【释名】野兰（《本经》）、荚蒿（苏恭）、 \n时珍曰∶屋之西北黑处谓之漏；凡物黑色谓之芦。此草秋后即黑，异于众草，故有漏芦 \n之称。《唐韵》作KT ，其荚如麻，故俗呼为鬼油麻云。 \n【集解】《别录》曰∶漏芦生乔山山谷。八月采根，阴干。 \n弘景曰∶乔山应是黄帝所葬处，乃在上郡。今出近道。市人取苗用之。俗中取根名鹿骊 \n根，苦酒摩以疗疮疥。 \n恭曰∶此药俗名荚蒿，茎叶似白蒿，花黄，生荚，长似细麻之荚，大如箸许，有四五瓣， \n七、八月后皆黑，异于众草，蒿之类也。常用其茎叶及子，未见用根。其鹿骊，山南谓之木 \n藜芦，有毒，非漏芦也。今人以马蓟似苦 者为漏芦，亦非也。 \n志曰∶别本注言漏芦茎大如箸，高四五尺，子房似油麻房而小。江东人取其苗用，胜于 \n根。江宁及上党者佳。陶云鹿骊，苏云木藜芦，皆非也。漏芦自别。 \n藏器曰∶南人用苗，北土用根，乃树生，如茱萸树，高二三尺，有毒杀蛊，山人以洗疮 \n疥。 \n保升曰∶叶似角蒿，今曹、兖州下湿处最多。六月、七月采茎，日干，黑于众草。 \n大明曰∶花苗并可用。形并气味似干牛蒡，头上有白花子。 \n颂曰∶今汴东州郡及秦、海州皆有之。旧说茎叶似白蒿，花黄有荚，茎若箸大，房类油 \n麻而小。今诸郡所图上，惟单州者差相类；沂州者花叶颇似牡丹；秦州者花似单叶寒菊，紫 \n色，五、七枝同一干；海州者，花紫碧，如单叶莲花，花萼下及根旁有白茸裹之，根如蔓荆 \n而细，又类葱本，黑色，淮甸人呼为老翁花。三州所生花虽别，而叶颇相类，但秦、海州者 \n叶更作锯齿状。一物而殊类如此，医家何所适从？当依旧说，以单州出者为胜。又本草飞廉 \n一名漏芦，云与苦 相类，其根生则肉白皮黑，干则黑如玄参。七、八月采花，阴干用。 \n所说与秦州、海州所图漏芦花、叶及根颇相近，然彼人但名漏芦，不曰飞廉也。 \n曰∶一种真似漏芦，只是味苦、酸，误服令人吐不止。 \n时珍曰∶按沈存中《笔谈》云∶今方家所用漏芦乃飞廉也。飞廉一名漏芦，苗似 \n苦，根如牛蒡绵头者是也。采时用根。今闽中所谓漏芦，茎如油麻，高六七寸，秋深枯黑 \n如漆，采时用苗，乃真漏芦也。余见飞廉下。 \n\\x根苗\\x \n【修治】 曰∶凡采得漏芦，细锉，以生甘草相对拌蒸之，从巳至申，拣出晒干用。 \n【气味】苦、咸，寒，无毒。《别录》曰∶大寒。藏器曰∶有毒。 \n杲曰∶无毒。足阳明本经药也。 \n大明曰∶连翘为之使。 \n【主治】皮肤热毒，恶疮疽痔，湿痹，下乳汁。久服轻身益气，耳目聪明，不老延 \n年（《本经》）。止遗溺，热气疮痒如麻豆，可作浴汤（《别 \n风赤眼，小儿壮热，扑损，续筋骨，乳痈、瘰 、金疮，止血排脓，补血长肉，通经脉（大 \n明 \n【发明】弘景曰∶此药久服甚益人，而服食方罕见用之。近道出者，惟疗 疥耳，市人 \n皆取苗用。 \n为手足阳明药，而古方治痈疽发背，以漏芦汤为首称也。庞安常《伤寒论》治痈疽及预解时 \n行痘疹热，用漏芦叶，云无则以山栀子代之。亦取其寒能解热，盖不知其能入阳明之故也。 \n【附方】旧二，新六。 \n腹中蛔虫∶漏芦为末，以饼 和方寸匕，服之。（《外台秘要》） \n时泄痢，冷热不调∶以漏芦一两，杵为散。每服一钱，以猪肝一两，入盐少许，以水同 \n煮熟，空心顿食之。（《圣惠方》） \n入药末一半，同熬成膏，入后末和丸梧子大，每温水下三十丸。（《圣济总录》） \n产后带下∶方同上。 \n乳汁不下，乃气脉壅塞也，又治经络凝滞，乳内胀痛，邪畜成痈，服之自然内消∶漏 \n二两半，蛇蜕十条（炙焦），栝蒌十个（烧存性）。为末。每服二钱，温酒调下，良久以热羹 \n汤投之，以通为度。（《和剂方》）历节风痛，筋脉拘挛∶古圣散∶用漏芦（麸炒）半两，地 \n龙（去土炒）半两，为末。生姜二两取汁，入蜜三两，同煎三五沸，入好酒五合，盛之。每 \n以三杯，调末一钱，温服。（《圣济总录》） \n一切痈疽发背，初发二日，但有热证，便宜服漏芦汤，退毒下脓，乃是宣热拔毒之剂， \n热退 \n半两，大黄（微炒）一两，为细末。每服二钱，姜枣汤调下。（李迅《痈疽集验方》） \n白秃头疮∶五月收漏芦草，烧灰，猪膏和涂之。（《圣济总录》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>飞廉\n\n内容：（《本经》上品） \n【释名】漏芦（《别录》）、木禾（《别录》）、 \n（《别录》）、伏猪（同）、天荠（同）。 \n尾， \n有角，能致风气。此草附茎有皮如箭羽，复疗风邪，故有飞廉、飞雉、飞轻诸名。 \n【集解】《别录》曰∶飞廉生河内川泽，正月采根，七月、八月采花，阴干。 \n弘景曰∶处处有之。极似苦 ，惟叶多刻缺，叶下附茎，轻有皮起似箭羽，其花紫色。 \n俗方殆无用，而道家服其枝茎，可得长生，又入神枕方。今既别有漏芦，则此漏芦乃别名尔。 \n恭曰∶此有两种∶一种生平泽中，是陶氏所说者。一种生山冈上者，叶颇相似，而无刻 \n缺，且多毛，其茎亦无羽，其根直下，更无旁枝，生则肉白皮黑，中有黑脉，日干则黑如玄 \n参。用茎叶及根，疗疳蚀杀虫，与平泽者俱有验。今俗以马蓟似苦 者为漏芦，并非是也。 \n保升曰∶叶似苦 ，茎似软羽，花紫色，子色白。所在平泽皆有， \n曰∶凡使，勿用赤脂蔓，与飞廉形状相似，只赤脂蔓见酒则色便如血，以此可表识之 \n颂曰∶今秦州所图漏芦，花似单叶寒菊，紫色，五、七枝同一干。海州所图漏芦，花紫 \n碧色，如单叶莲花，花萼下及根旁有白茸裹之，根黑色，如蔓荆而细，又类葱本，与陶苏所 \n说飞廉相近，然彼但谓之漏芦。今医家罕有用飞廉者，不能的识。 \n时珍曰∶飞廉，亦蒿类也。苏颂《图经》疑海州所图之漏芦是飞廉。沈存中《笔谈》亦 \n言飞廉根如牛蒡而绵头。古方漏芦散下云，用有白茸者则是有白茸者，乃飞廉无疑矣。今考 \n二物气、味、功、用俱不相远，似可通用，岂或一类有数种，而古今名称各处不同乎？ \n\\x根及花\\x \n【修治】 曰∶凡用根，先刮去粗皮，杵细，以苦酒拌一夜，漉出，日干细杵用。 \n【气味】苦，平，无毒。权曰∶苦、咸，有毒。 \n【主治】骨节热，胫重酸疼。久服令人身轻（《本经》）。 \n螫针刺，鱼子细起，热疮痈疽痔，湿痹，止风邪咳嗽，下乳汁。久服益气明目不老，可煮可 \n干用（《别录》）。主留血（《甄权》）。疗疳蚀，杀虫（苏恭）。 \n小儿疳痢，为散，浆水服，大效（萧炳）。治头风旋晕（时珍）。 \n【发明】时珍曰∶葛洪《抱朴子》书，言飞廉单服可轻身延寿。又言服飞廉煎，可远涉 \n疾行，力数倍于常。《本经》、《别录》所列亦是良药，而后人不知用，何哉？ \n【附方】旧一。 \n若不痛，非疳也。下部虫如马尾大，相缠出无数。十日瘥，二十日平复。（《千金翼方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>苎麻\n\n内容：（《别录》下品）。 \n【释名】时珍曰∶苎麻作 ，可以绩 ，故谓之 。凡麻丝之细者，为 ；粗者为 。 \n陶弘景云∶苎即今绩苎麻是也。麻字从广，从林（音派），象屋下林麻之形。广音掩。 \n【集解】颂曰∶苎麻旧不着所出州土，今闽、蜀、江、浙多有之。剥其皮可以绩布。苗 \n高七八尺。叶如楮叶而无叉，面青背白，有短毛。夏秋间着细穗青花。其 \n月、八月采。按陆玑《草木疏》云∶苎一科数十茎，宿根在土中，至春自生，不须栽种。荆 \n扬间岁三刈，诸园种之岁再刈，便剥取其皮，以竹刮其表，浓处自脱，得里如筋者煮之，用 \n缉布。今江、浙、闽中尚复如此。 \n数十穗，青白色。 \n时珍曰∶苎，家苎也。又有山苎，野苎也。有紫苎，叶面紫；白苎，叶面青，其背皆白。 \n可刮洗煮食救荒，味甘美。其子茶褐色，九月收之，二月可种。宿根亦自生。 \n\\x根\\x \n【气味】甘，寒，无毒。权曰∶甘，平。大明曰∶甘、滑，冷，无毒。 \n【主治】安胎，贴热丹毒（《别录》）。治心膈热，漏胎下血，产前后心烦，天行热疾， \n大渴大狂，服金石药人心热， 毒箭蛇虫咬（大明）。沤苎汁 \n【发明】震亨曰∶苎根大能补阴而行滞血，方药或恶其贱，似未曾用也。 \n藏器曰∶苎性破血，将苎麻 \n与产妇枕之，止血晕。产后腹痛，以苎安腹上即止也。又蚕咬人毒入肉，取苎汁饮之。今人 \n以苎近蚕种，则蚕不生是矣。 \n【附方】旧四，新八。 \n痰哮咳嗽∶苎根（ 存性），为末，生豆腐蘸三五钱，食即效。未全，可以肥猪肉二、 \n三片蘸食，甚妙。（《医学正传》） \n小便不通∶《圣惠方》∶用麻根、蛤粉各半两，为末。每服二钱，空心新汲水下。《摘玄 \n方》∶用苎根洗研，摊绢上，贴少腹连阴际，须臾即通。 \n妙。亦治诸淋。（《圣惠方》） \n五种淋疾∶苎麻根两茎，打碎。以水一碗半，煎半碗，顿服即通，大妙。（《斗门方》） \n妊娠胎动，忽下黄汁如胶，或如小豆汁，腹痛不可忍者∶苎根（去黑皮，切）二升，银一 \n斤，水九升，煎四升。每服以水一升，入酒半升，煎一升，分作二服。一方∶不用银。（《梅 \n师方》） \n肛门肿痛∶生苎根捣烂，坐之良。（《濒湖集简方》） \n脱肛不收∶苎根捣烂，煎汤熏洗之。（《圣惠方》） \n痈疽发背，初起未成者。苎根（熟）捣敷上，日夜数易，肿消则瘥。（《图经本草》） \n五色丹毒∶苎根煮浓汁，日三浴之。（《外台秘要》） \n鸡鱼骨哽∶《谈野翁试验方》∶用苎麻根捣汁，以匙挑灌之，立效。《医方大成》∶用野苎 \n麻根捣碎，丸如龙眼大，鱼骨鱼汤 \n\\x叶\\x \n【气味】同根。 \n【主治】金疮伤折血出，瘀血（时珍）。 \n【发明】时珍曰∶苎麻叶甚散血，五月五日收取，和锻石捣作团，晒干收贮。遇有金疮 \n折损者，研末敷之，即时 \n六月收野苎叶、苏叶， \n生猪血试之，可验也。秋冬用干叶亦可。 \n【附方】新三。 \n五日采麻叶，阴干为末。每服二钱，冷水调下。勿吃热物，令人闷倒。只吃冷物。小 \n儿半钱。（《杨子建护命方》） \n冷痢白冻∶方同上。 \n蛇虺咬伤∶青麻嫩头捣汁，和酒等分，服三盏。以渣敷之，毒从窍中出 \n，以渣弃水中即不发。看伤处 \n有窍是雄蛇，无窍是雌蛇，以针挑破伤处成窍，敷药。（《摘玄方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>麻\n\n内容：（ ，音顷。《唐本草》） \n【释名】白麻。 \n时珍曰∶ 一作KT ，又作KT ，种必连顷，故谓之KT 也。 \n【集解】恭曰∶ ，即KT 麻也。今人取皮作布及索者。实似大麻子，九月、十月采， \n阴干。 \n颂曰∶处处有之。北人种以绩布，及打绳索。苗高四、五尺，或六、七尺，叶似苎而薄， \n花黄，实壳如蜀葵，其中子黑色。 \n时珍曰∶ 麻今之白麻也。多生卑湿处，人亦种之。叶大似桐叶，团而有尖。六七月开 \n黄花。结实如半磨形，有齿，嫩青老黑。中子扁黑，状如黄葵子。其茎轻虚洁白。北人取皮 \n作麻。以茎蘸硫黄作淬灯，引火甚速。其嫩子，小 \n\\x实\\x \n【气味】苦，平，无毒。 \n【主治】赤白冷热痢，炒研为末，每蜜汤服一钱。痈肿无头者，吞一枚（苏恭）。 \n生眼翳瘀肉，起倒睫拳毛（时珍）。 \n\\x根\\x \n【主治】亦治痢，古方用之（苏颂）。 \n【附方】新三。 \n一切眼疾∶ 麻子一升。为末。以 猪肝批片，蘸末炙 \n服一字，陈米饮下 \n，磨去壳，马尾筛取黄肉去焦壳，每十两可得四两 \n药慢炙熟，为末，醋和丸梧子大。每服三十丸，白汤下。一方∶以KT 实内袋中蒸熟，暴 \n为末，蜜丸。温水下。（《圣济总录》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>大青\n\n内容：（《别录》中品） \n【释名】时珍曰∶其茎叶皆深青，故名。 \n【集解】《别录》曰∶大青三四月采茎，阴干。 \n弘景曰∶今出东境及近道，紫茎长尺许，茎、叶皆用。 \n颂曰∶今江东州郡及荆南、眉、蜀、濠、淄诸州皆有之。春生青紫茎，似石竹苗叶，花 \n红紫色，似马蓼，亦似芫花，根黄，三月、四月采茎叶，阴干用。 \n时珍曰∶处处有之。高二、三尺，茎圆。叶长三、四寸，面青背淡，对节而生。八月开 \n小花，红色成簇。结青实大如椒颗。九月色赤。 \n\\x茎叶\\x \n【气味】苦，大寒，无毒。权曰∶甘。时珍曰∶甘、微咸，不苦。 \n【主治】时气头痛，大热口疮（《别录》）。除时行热毒 \n权）。治热毒风，心 \n主热毒痢，黄胆、喉痹、丹毒（时珍）。 \n【发明】颂曰∶古方治伤寒黄汗、黄胆等，有大青汤。又治伤寒头身强、腰脊痛，葛根 \n汤内亦用大青。大抵时疾多用之。 \n寒也。朱肱《活人书》治伤寒发赤斑烦痛，有犀角大青汤、大青四物汤。故李象先《指掌赋》 \n云∶阳毒则狂斑烦乱，以大青、升麻，可回困笃。 \n【附方】新六。喉风喉痹∶大青叶捣汁灌之，取效止。（《卫生易简方》）小儿口疮∶大 \n青十八铢，黄连十二铢。水三升，煮一升服。一日二服，以瘥为度。（《千金方》）热病下痢 \n困笃者∶大青汤∶用大青四两，甘草、赤石脂三两，胶二两，豉八合。水一斗，煮三升，分 \n三服，不过二剂瘥。（《肘后方》） \n热病发斑，赤色烦痛∶大青四物汤∶用大青一两，阿胶、甘草各二钱半，豉二合，分三 \n服。每用水一盏半，煎一盏，入胶烊化服。又犀角大青汤∶用大青七钱半，犀角二钱半，栀 \n子十枚，豉二撮，分二服。每服水一盏半，煎八分，温服。（《南阳活人书》） \n肚皮青黑，小儿卒然肚皮青黑，乃血气失养，风寒乘之，危恶之候也∶大青为末，纳口 \n中，以酒送下。（《保幼大全方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>小青\n\n内容：（宋《图经》） \n【集解】颂曰∶小青生福州，三月生花，彼土人当月采叶用之。 \n\\x叶\\x \n【气味】温，无毒。 \n【主治】生捣，敷痈肿疮疖甚效（苏颂）。治血痢腹痛，研汁服，解 \n【附方】新三。 \n蛇虺螫伤∶《卫生易简方》∶用小青一握（细研），入香白芷半两。酒调服。手 患处， \n候 \n黄水出为效。《摘玄方》∶用小青、大青、牛膝叶同捣汁，和酒服，以渣敷之。 \n中暑发昏∶小青叶（井水浸去泥），控干，入沙糖擂汁，急灌之。（《寿域方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>葫芦巴\n\n内容：（宋《嘉 》） \n【释名】苦豆。 \n【集解】禹锡曰∶葫芦巴出广州并黔州。春生苗，夏结子，子作细荚，至秋采。今人 \n多用岭南者。或云是番萝卜子，未审的否？ \n颂曰∶今出广州。或云种出海南诸番，盖其地芦菔子也。舶客将种莳于岭外亦生，然不 \n及番中来者真好。今医家治元脏虚冷为要药，而唐已前方不见用，本草不着，盖是近出。 \n【修治】时珍曰∶凡入药，淘净，以酒浸一宿，晒干，蒸熟或炒过用。 \n【气味】苦，大温，无毒。杲曰∶纯阳。 \n【主治】元脏虚冷气。得附子、硫黄，治肾虚冷，腹胁胀满，面色青黑。得 香子、桃 \n仁，治膀胱气甚效（嘉 ）。治冷气疝瘕，寒湿香港脚，益右肾，暖丹田（时珍）。 \n【发明】宗 曰∶膀胱气，用此合桃仁（麸炒）等分。为末，半为散，半以酒糊和丸梧 \n子大。每服五、七十丸，空心盐酒下；其散，以热米饮下，与丸子相间，空心服，日各一、 \n二服。时珍曰∶葫芦巴，右肾命门药也。元阳不足，冷气潜伏，不能归元者，宜之。宋 \n《惠民和剂局方》，有葫芦巴丸，治大人、小儿，小肠奔豚偏坠，及小腹有形如卵，上下走 \n痛，不可忍者。用葫芦巴八钱，茴香六钱，巴戟（去心）、川乌头（炮去皮）各二钱，楝实 \n（去 \n核）四钱，吴茱萸五钱。并炒为末，酒糊丸梧子大。每服十五丸，小儿五丸，盐酒下。太医 \n薛已云∶一人 \n有人病目不睹，思食苦豆，即葫芦巴，频频不缺。不周岁而目中微痛，如虫行入 ，渐明而 \n愈。按∶此亦因其益命门之功，所谓益火之原，以消阴翳是也。 \n【附方】新六。 \n小肠气痛∶葫芦巴（炒）研末，每服二钱，茴香酒下。（《直指方》） \n肾脏虚冷，腹胁胀满∶葫芦巴（炒）二两，熟附子、硫黄各七钱五分。为末，酒煮曲糊 \n丸梧桐子大，每盐汤下三、四十丸。（《圣济总录》）冷气疝瘕∶葫芦巴（酒浸晒干）、荞麦（炒， \n研面）各四两，小茴香一两。为末，酒糊丸梧子大。每服五十丸，空心盐汤或盐酒下。服至 \n两月，大便出白脓，则除根。（方广《心法附余》） \n阴 肿痛偏坠，或小肠疝气，下元虚冷，久不愈者，沉香内消丸主之∶沉香、木香各半 \n两，葫芦巴（酒浸炒）、小茴香（炒）各二两。为末，酒糊丸梧子大。每服五、七十丸，盐 \n酒下。 \n气攻头痛∶葫芦巴（炒）、三棱（酒浸焙）各半两，干姜（炮）二钱半，为末，姜汤或 \n温酒每服二钱。（《济生方》） \n寒湿香港脚，腿膝疼痛，行步无力∶胡芦巴（酒浸一宿，焙）、破故纸（炒 \n香）各四两。为末。以木瓜切顶去瓤，安药在内令满，用顶合住签定，烂蒸，捣丸梧子 \n大。每服七十丸，空心温酒下。（《杨氏家藏方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>蠡实\n\n内容：（《本经》中品） \n【释名】荔实（《别录》）、马蔺子（《唐本》） \n马帚（《尔雅》）、铁扫帚（《救荒》）、剧草（《本经》 \n三坚。 \n恭曰∶此即马蔺子也。《月令》∶仲冬荔挺出。郑玄注云∶荔，马薤也。《通俗文》云 \n∶一名马蔺。本草谓之荔实。 \n高诱云∶荔挺出，荔草挺出也。讲礼者不识，呼为荔挺，又作马苋，并误矣。马苋亦名豚耳， \n即马齿也。 \n河南北人呼为铁扫帚，是矣。 \n【集解】《别录》曰∶蠡实生河东川谷，五月采实，阴干。 \n诸郡及鼎、澧州亦有之，近汴尤多。叶似薤而长浓，三月开紫碧花，五月结实作角子，如麻 \n大而赤色有棱，根细长，通黄色，人取以为刷。三月开花，五月采实，并阴干用。许慎《说 \n文》云∶荔似蒲而小，根可为刷。高诱云∶河北平泽率生之。江东颇多，种于阶庭，但呼为 \n旱蒲，不知即马薤也。 \n时珍曰∶蠡草生荒野中，就地丛生，一本二、三十茎，苗高三、四尺，叶中抽茎，开花 \n结实。 \n【正误】宗 曰∶蠡实，陶隐居言方药不用，俗无识者。本草诸家所注不相应。若果是 \n马蔺，则《日华子本草》不当更言可为菜蔬。盖马蔺叶出土已硬，又无味，马牛皆不食，岂 \n堪人食？今不敢以蠡实为马蔺，更俟博识。 \n荔字之讹也。张揖《广雅》云∶荔又名马蔺，其说已明。又按∶周定王《救荒本草》言∶其 \n嫩苗味苦，炸熟换水浸去苦味，油盐调食，则马蔺亦可作菜矣。寇氏但据陶说疑之，欠考矣。 \n陶氏不识药多矣。今正其误。 \n\\x实\\x \n【修治】时珍曰∶凡入药炒过用，治疝则以醋拌炒之。 \n【气味】甘，平，无毒。保升曰∶寒。 \n颂曰∶山人服之，云大温，甚有奇效。 \n【主治】皮肤寒热，胃中热气，风寒湿痹，坚筋骨，令人嗜食。久服轻身（《本经 \n》）。止心烦满，利大小便，长肌肤肥大（《别录》）。疗 \n金疮血内流，痈肿，有效（苏恭）。妇人血气烦闷，产后血晕，并经脉 \n不止，崩中带下，消一切疮疖，止鼻衄吐血，通小肠，消酒毒，治黄病，杀蕈毒，敷蛇虫咬 \n（大明）。治小腹疝痛，腹内冷积，水痢诸病（时珍）。 \n【附方】旧二，新六。 \n诸冷极病，医所不治者∶马蔺子九升洗净，空腹服一合，酒下，日三服 \n寒疝诸疾，寒疝不能食，及腹内一切诸疾，消食肥肌。马蔺子一升，每日取一把，以面拌煮 \n吞之，服尽愈。（姚僧坦《集验方》） \n喉痹肿痛∶《卫生易简方》∶用蠡实一合，升麻五分，水一升，煎三合，入少蜜搅匀，细 \n呷，大验。《圣惠方》∶用马蔺子二升，升麻一两。为末，蜜丸。水服一钱。又方∶马蔺子八 \n钱，牛蒡子六钱。为末，空心温水服方寸匕。水痢百病∶张文仲《备急方》∶用马蔺子，以 \n六月六日面熬，各等分，为末，空心米饮服方寸匕。如无六月六日面，常面亦可，牛骨灰亦 \n可。又方∶马蔺子、干姜、黄连各等分，为散，熟汤服二方寸匕，入腹即断也。冷、热皆治， \n常用神效，不得轻之。忌猪肉、冷水。肠风下血，有疙瘩疮，破者不治∶马蔺子一斤（研破 \n酒浸，夏三、冬七日，晒干），何首乌半斤，雄黄、雌黄各四两，为末，以浸药酒打糊丸梧 \n子大。每服三十丸，温酒下，日三服，见效。（《普济方》） \n\\x花、茎及根、叶\\x \n【主治】去白虫（《本经》）。疗喉痹 \n【发明】颂曰∶蠡草、花、实，皆入药。《列仙传》云∶寇先生宋人，好种荔，食其葩 \n实，是矣。 \n时珍曰∶按《叶水东日记》云∶北方田野人患胸腹饱胀者，取马楝花擂凉水服，即泄数 \n行而愈。 \n据此则多服令人泄之说有验，而蠡实之为马蔺更无疑矣。 \n【附方】旧三，新七。 \n睡死不寤∶蠡实根一握，杵烂，以水绞汁，稍稍灌之。（《外台秘要》） \n喉痹口噤∶马蔺花二两，蔓荆子一两，为末，温水服一钱。 \n喉痹肿痛，喘息欲死者∶《外台秘要》∶用马蔺根、叶二两，水一升半，煮一盏，细饮 \n之，立瘥。《圣惠方》∶用根捣汁三合，蜜一合，慢火熬成，徐徐点之，日五七度。一方∶单 \n汁饮之，口噤者灌下。无生者，以刷煎汁。 \n沙石热淋∶马蔺花七枚（烧），故笔头二七枚（烧），粟米一合（炒）。为末。每服三钱， \n酒下，日二服。名通神散。 \n小便不通∶马蔺花（炒）、茴香（炒）、葶苈（炒），为末，每酒服二钱。（《十便良方》） \n一切痈疽，发背恶疮∶用铁扫帚，同松毛、牛膝，以水煎服。（《乾坤生意》） \n面上瘢 ∶取铁扫帚，地上自落叶，并子，煎汤频洗，数次自消。（《寿域神方》） \n面 鼻渣∶马蔺子花，杵敷之佳。（《肘后方》） \n【附录】必似勒（《拾遗》） 藏器曰∶辛，温，无毒。主冷气，胃闭不消食，心腹胀满。 \n生昆仑，状似马蔺子。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>恶实\n\n内容：（《别录》中品） \n【释名】鼠粘（《别录》）、牛蒡（《别录》）、大力子（《纲目》）、蒡翁菜（《纲目》）、便牵 \n牛（《纲目》）、蝙蝠刺。 \n时珍曰∶其实状恶而多刺钩，故名 \n也。俚人谓之便牵牛。河南人呼为夜叉头。 \n颂曰∶实壳多刺，鼠过之则缀惹不可脱，故谓之鼠粘子，亦如羊负来之比。 \n【集解】《别录》曰∶恶实生鲁山平泽。恭曰∶鲁山在邓州东北。此草叶大 \n如芋，子壳似栗状，实细长如茺蔚子。 \n颂曰∶恶实即牛蒡子也，处处有之。叶大如芋叶而长。实似葡萄核而褐色，外壳似栗 ， \n而小如指 \n时珍曰∶牛蒡古人种子，以肥壤栽之。剪苗 淘为蔬，取根煮曝为脯，云甚益人，今人 \n亦罕食之。三月生苗，起茎高者三、四尺。四月开花成丛，淡紫色。结实如枫 而小，萼 \n细刺百十攒簇之，一 有子数十颗。其根大者如臂，长者近尺，其色灰黪。七月采子，十月 \n采根。 \n\\x子\\x \n【修治】 曰∶凡用拣净，以酒拌蒸，待有白霜重出，以布拭去，焙干，捣粉用。 \n【气味】辛，平，无毒。藏器曰∶苦。 \n元素曰∶辛，温，阳中之阴，升也。 \n杲曰∶辛，平，阳也，降也。 \n【主治】明目补中，除风伤（《别录》）。风毒肿，诸 （藏器）。研末浸酒，每日服三、 \n二盏，除诸风，去 \n吞 \n一枚，出痈疽头（苏恭）。炒研煎饮，通利小便（孟诜）。润肺散气，利咽膈，去皮肤风，通 \n十 \n二经（元素）。消斑疹毒（时珍）。 \n【发明】杲曰∶鼠粘子其用有四∶治风湿瘾疹，咽喉风热，散诸肿疮疡之毒，利凝滞腰 \n膝之气，是也。 \n【附方】旧四，新十二。 \n风水身肿欲裂∶鼠粘子二两，炒研为末。每温水服二钱，日三服。（ \n风热浮肿，咽喉闭塞∶牛蒡子一合（半生半熟），为末。热酒服一寸匕 \n痰厥头痛∶牛蒡子（炒）、旋复花等分，为末。腊茶清服一钱，日二服 \n头痛连睛∶鼠粘子、石膏等分，为末，茶清调服。（《医方摘要》） \n咽膈不利，疏风壅，涎唾多∶牛蒡子（微炒）、荆芥穗各一两，炙甘草半两，为末。食 \n后汤服二钱，当缓缓取效。（寇氏《本草衍义》） \n悬痈喉痛，风热上抟也。恶实（炒）、甘草（生）等分，水煎含咽，名启关 \n方》） \n喉痹肿痛∶牛蒡子六分，马蔺子八分，为散。每空心温水服方寸匕，日再服。仍以牛蒡 \n子三两，盐二两，研匀，炒热包熨喉外。（《广济方》） \n咽喉痘疹∶牛蒡子二钱，桔梗一钱半，粉甘草节七分，水煎服。（《痘 \n风热瘾疹∶牛蒡子（炒）、浮萍等分，以薄荷汤服二钱，日二服。（初虞世《古今录验》） \n风龋牙痛∶鼠粘子（炒），煎水含，冷吐之。（《延年方》） \n小儿痘疮，时出不快，壮热狂躁，咽膈壅塞，大便秘涩，小儿咽喉肿，胸膈不利∶若大 \n便利者，勿服。牛蒡子（炒）一钱二分，荆芥穗二分，甘草节四分。水一盏，同煎至七分， \n温服。已出亦可服。名必胜散。（《和剂局方》） \n妇人吹乳∶鼠粘二钱，麝香少许，温酒细吞下。（《袖珍方》） \n便痈肿痛∶鼠粘子二钱，炒研末，入蜜一匙，朴硝一匙，空心温酒服。（《袖珍方》） \n蛇蝎蛊毒∶大力子，煮汁服。（《卫生易简方》） \n水蛊腹大∶恶实（微炒）一两，为末，面糊丸梧子大，每米饮下十丸。（张文仲方） \n历节肿痛，风热攻手指，赤肿麻木，甚则攻肩背两膝，遇暑热则大 \n便秘∶牛蒡子三两，新豆豉（炒）、羌活各一两，为末。每服二钱，白汤下。（《本事方》） \n\\x根、茎\\x \n【气味】苦，寒，无毒。权曰∶甘、平。 \n藏器曰∶根须蒸熟曝干用。不尔，令人欲吐。 \n【主治】伤寒寒热汗出，中风面肿，消渴热中，逐水。久服轻身耐老（《别录》）。根∶ \n主牙齿痛，劳疟诸风，脚缓弱风毒，痈疽，咳嗽伤肺，肺壅疝瘕，冷气积血（苏恭）。根∶ \n浸 \n酒服，去风及恶疮。和叶捣碎，敷杖疮金疮，永不畏风（藏器）。主面目烦闷，四肢不健， \n通 \n十二经脉，洗五脏恶气。可常作菜食，令人身轻（甄权）。切根如豆，拌面作饭食，消胀壅。 \n茎叶煮汁作浴汤，去皮间习习如虫行。又入盐花生捣，拓一切肿毒（孟诜）。 \n【发明】颂曰∶根作脯食甚良。茎叶宜煮汁酿酒服。冬月采根，蒸曝入药。刘禹锡《传 \n信方》∶疗暴中风，用紧细牛蒡根，取时避风，以竹刀或荆刀刮去土，生布拭了，捣绞取汁 \n一大升，和好蜜四大合，温分两服，得汗出便瘥。此方得之岳鄂郑中丞。郑因食热肉一顿， \n便中暴风。外甥卢氏为 阳令，有此方。服，当时便瘥。 \n【附方】旧五，新一十六。 \n时气余热不退，烦躁发渴，四肢无力，不能饮食∶用牛蒡根捣汁，服一小盏，效。（《圣 \n惠方》） \n天行时疾∶生牛蒡根，捣汁五合，空腹分为二服。服讫，取桑叶一把，炙黄，以水一升， \n煮取五合，顿服取汗，无叶用枝。（孙真人《食忌》） \n热攻心烦恍惚∶以牛蒡根（捣汁）一升，食后分为二服。（《食医心镜》） \n伤寒搐搦，汗后覆盖不密，致腰背手足搐搦者，牛蒡根散主之∶牛蒡根十条，麻黄、牛 \n膝、天南星各六钱锉，于盆内研细，好酒一升同研，以新布绞取汁。以炭火半秤烧一地坑令 \n赤，扫净，倾药汁入坑内，再烧令黑色，取出于乳钵内细研。每服一钱，温酒下，日三服。 \n（朱肱《活人书》） \n一切风疾十年、二十年者∶牛蒡根一升，生地黄、枸杞子、牛膝各三升，用袋盛药，浸 \n无灰酒三升内，每任意饮之。（《外台秘要》方） \n老人中风，口目 动，烦闷不安。牛蒡根（切）一升（去皮晒干，杵为面），白米四合 \n（淘净）。和作 ，豉汁中煮，加葱、椒五味，空心食之。恒服极效。（《寿亲养老书》） \n老人风湿久痹，筋挛骨痛。服此壮肾，润皮毛，益气力∶牛蒡根一升（切），生地黄一 \n升（切），大豆二升（炒），以绢袋盛，浸一斗酒中，五六日，任性空心温服二、三盏，日二 \n服。（《集验方》） \n头面忽肿，热毒风气内攻，或连手足赤肿，触着痛者∶牛蒡子根（一名蝙蝠刺），洗净 \n研烂，酒煎成膏，绢摊贴肿处。仍以热酒服一、二匙，肿消痛减。（《斗 \n不 \n可禁者，摩膏主之∶取牛蒡茎叶，捣取浓汁二升，无灰酒一升，盐花一匙头， 火煎稠成膏， \n以摩痛处，风毒自散。摩时须极力令热，乃效。冬月用根。（《箧中方》） \n头风白屑∶牛蒡叶捣汁，熬稠涂之。至明，皂荚水洗去。（《圣惠方》） \n喉中热肿∶鼠粘根一升，水五升，煎一升，分三服。（《延年方》） \n小儿咽肿∶牛蒡根捣汁，细咽之。（《普济方》） \n热毒牙痛，热毒风攻头面，齿龈肿痛不可忍∶牛蒡根一斤（捣汁），入盐花一钱。银器 \n中熬成膏。每用涂齿龈上，重者不过三度，瘥。（《圣惠方》） \n项下瘿疾∶鼠粘子根一升。水三升，煮取一升半，分三服。或为末，蜜丸常服之。（《救 \n急方》） \n小便不通，脐腹急痛∶牛蒡叶汁、生地黄汁二合，和匀，入蜜二合。每服一合，入水半 \n盏，煎三五沸，调滑石末一钱服。（《圣济总录》） \n疖子肿毒∶鼠粘子叶贴之。（《千金方》） \n石 出脓，坚实寒热∶鼠粘子叶为末，和鸡子白封之。（《外台秘要》） \n诸疮肿毒∶牛蒡根三茎（洗）。煮烂捣汁，入米煮粥，食一碗，甚良。（《普济方》） \n积年恶疮，反花疮、漏疮不瘥者。牛蒡根捣，和腊月猪脂，日日封之。（《千金方》） \n月水不通，结成症块，腹肋胀大，欲死∶牛蒡根二斤（锉）。蒸三遍，以生绢袋盛之， \n以酒二斗浸五日，每食前温服一盏。（《普济方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>耳\n\n内容：（《本经》中品） \n【释名】胡 （《本经》）、常思（弘景）、苍耳（《尔雅》）、卷耳（《诗经》）、爵耳（《诗 \n疏》）、猪耳（《纲目》）、耳 （《诗疏》）、地葵（《本经》）、 （音施）、羊负来（弘 \n景）、道人头（《图经》）、进贤菜（《记事珠》）、喝起草（《纲目》）、野茄（《纲目》）、缣 \n丝草。 \n颂曰∶诗人谓之卷耳，《尔雅》谓之苍耳，《广雅》谓之 耳，皆以实得名也。陆玑《诗 \n疏》云∶其实正如妇人耳 ，今或谓之耳 草。郑康成谓是白胡荽，幽州人呼为爵耳。《博 \n物志》云∶洛中有人驱羊入蜀，胡 子多刺，粘缀羊毛，遂至中土，故名羊负来。俗呼 \n人头。 \n弘景曰∶伧人皆食之，谓之常思菜。以叶覆麦作黄衣者，方用甚稀。 \n时珍曰∶其叶形如 麻，又如茄，故有 耳及野茄诸名。其味滑如葵，故名地葵，与地 \n肤同名。诗人思夫赋卷耳之章，故名常思菜。张揖《广 \n【集解】《别录》曰∶ 耳生安陆川谷及六安田野，实熟时采。 \n氏《诗疏》云∶其叶青白似胡荽，白华细茎，蔓生，可煮为茹，滑而少味。四月中生 \n子，正如妇人耳 。郭璞云∶形如鼠耳，丛生如盘。今之所有皆类此，但不作蔓生。 \n时珍曰∶按∶周定王《救荒本草》云∶苍耳叶青白，类粘糊菜叶。秋间结实，比桑椹短 \n小而多刺。嫩苗炸熟，水浸淘拌食，可救饥。其子炒去皮，研为面，可作烧饼食，亦可熬油 \n点灯。 \n\\x实\\x \n【修治】大明曰∶入药炒熟，捣去刺用，或酒拌蒸过用。 \n【气味】甘，温，有小毒。《别录》曰∶苦。权曰∶甘，无毒。 \n米泔，害人。 \n【主治】风头寒痛，风湿周痹，四肢拘挛痛，恶肉死肌，膝痛。久服益气，耳目聪明， \n强志轻身（《本经》）。治肝热，明目（甄权）。治一切风气， \n（大明）。炒香浸酒服，去风补 \n【附方】旧三，新四。 \n酒服三十丸，日二服。生者捣汁服亦可。（《朱氏集验方》） \n葶苈（末）等分。每服二钱，水下，日二服。（《千金方》） \n两 \n（炒）。为末，以水一升半，煎取七合，去滓呷之。（《食医心镜》） \n水一斗，煮取五升，热含之。冷即吐去，吐后 \n（孙真人《千金翼》） \n钱。（《证治要诀》） \n嗜酒不已∶毡中苍耳子七枚，烧灰投酒中饮之，即不嗜。（陈藏器《 \n【修治】 曰∶凡采得去心，取黄精，以竹刀细切拌之， \n干用。 \n【气味】苦、辛，微寒，有小毒。 \n【主治】溪毒（《别录》）。中风伤寒头痛（孟 \n膝风毒。夏月采曝为末，水服一、二匕，冬月酒服。或为丸，每服二、三十丸，日三服。满 \n百日，病出如 疥，或痒，汁出，或斑驳甲错皮起，皮落则肌如凝脂。令人省睡 \n，除诸 \n出涎，去目黄好睡。烧灰和腊猪脂，封疔肿出根；煮酒服，主狂犬咬毒（藏器）。 \n【发明】时珍曰∶苍耳叶久服去风热有效，最忌猪肉及风邪，犯之则遍身发出赤丹也。 \n按《苏沈良方》云∶ 耳根、苗、叶、实，皆洗濯阴干 \n二灶炼之。灰汁耗，即旋取傍釜中热灰汤益之。一日夜不绝火，乃旋得霜，干瓷瓶收之。每 \n日早晚酒服二钱，补暖去风驻颜，尤治皮肤风，令人肤革清净。每澡沐入少许尤佳。宜州 \n文学昌从KT ，服此十余年，至七、八十，红润轻健，皆此药力 \n也。《斗门方》云∶妇人血风攻脑，头旋闷绝，忽死倒地，不知人事者。用喝起草嫩心阴 \n干为末，以酒服一大钱，其功甚效。此物善通顶门连脑，盖即苍耳也。 \n【附方】旧十二，新十七。 \n疮杖疮，牙疼喉痹∶五月五日采苍耳根叶数担，洗净晒萎细锉，以大锅五口，入水煮烂， \n以筛滤去粗滓，布绢再滤。复入净锅，武火煎滚，文火煎稠，搅成膏，以新罐贮封。每以敷 \n贴，即愈。牙疼即敷牙上，喉痹敷舌上或噙化，二、三次即效。每日用酒服一匙，极有效。 \n（《集简方》） \n五日午时附地刈取 耳叶，洗暴燥，捣下筛，每服方寸匕，酒或浆水下，日二、夜三。若觉 \n吐逆，则以蜜丸服，准计方寸匕数也。风轻者，日二服。若身体作粟或麻豆出，此为风毒出 \n也。可以针刺溃去黄汁，乃止。七月七、九月九，亦可采用。（《千金方》） \n一切风气∶苍耳嫩叶一石（切），和麦 五升作块，于蒿艾中 二十日成曲。取米一斗， \n炊作饭，看冷暖，入曲三升酿之，封二七日 \n得令密，密则溢出。忌马肉、猪肉。（孟诜《食疗本草》） \n每服一钱，酒调下，日三服。若吐，则以蜜丸梧子大，每服二十丸。十日全好矣。（《杨氏 \n经验方》） \n血风脑晕∶方见发明下。 \n毒攻手足，肿痛欲断∶苍耳捣汁渍之，并以滓敷之，立效。春，用心；冬，用子。（《千 \n金翼》）卒中水毒，初觉头目微痛，恶寒，骨节强急，日醒暮剧，手足逆冷，三日则虫蚀下 \n部；六、七日脓溃，食至五脏，杀人也。捣常思草，绞汁服一、二升，并以绵染，导其下部。 \n（《肘后方》）毒蛇溪毒，沙虱、射工等所伤，口噤眼黑，手足强直，毒攻腹内成块，逡巡不 \n救∶苍耳嫩苗一握。取汁，和酒温灌之，以滓浓敷伤处。（《胜金方》） \n疫病不染∶五月五日午时多采苍耳嫩叶，阴干收之。临时为末，冷水服二钱，或水煎举 \n家皆服，能辟邪恶。（《千金方》） \n风瘙瘾疹，身痒不止∶用苍耳茎、叶、子等分，为末。每服二钱，豆淋酒调下。（《圣 \n惠方》） \n面上黑斑∶苍耳叶焙为末，食后米饮调服一钱，一月愈。（《摘玄方》） \n赤白汗斑∶苍耳嫩叶尖，和青盐擂烂，五、六月间擦之，五、七次效。（《摘玄方》） \n大风疠疾∶《袖珍方》∶用嫩苍耳、荷叶等分，为末。每服二钱，温酒下，日二服。《干 \n坤生意》∶用苍耳叶为末，以大枫子油和丸梧子大。每服三、四十丸，以茶汤下，日二服。 \n又方∶五月五日或六月六日，五更带露采苍耳草，捣取汁，熬作锭子。取半斤鳢鱼一尾，剖 \n开不去肚肠，入药一锭，线缝，以酒二碗，慢火煮熟令吃，不过三五个鱼即愈也。忌盐一百 \n日。 \n卒得恶疮∶苍耳、桃皮作屑，纳疮中。（《百一方》） \n反花恶疮，有肉如饭粒，破之血出，随生反出∶用苍耳叶捣汁，服三合，并涂之，日二 \n上。（《圣济总录》） \n日三服，拔根甚验。《养生方》∶用苍耳根、苗烧灰，和醋淀涂之，干再上。不十次，即拔根 \n出。 \n齿风动痛∶苍耳一握，以浆水煮，入盐含漱。（《外台秘要》） \n缠喉风病∶苍耳根一把，老姜一块。研汁，入酒服。（《圣济总录》） \n赤目生疮作痛∶道人头末二两，乳香一钱，每用一钱，烧烟搐鼻。（《圣济总录》） \n鼻衄不止∶苍耳茎叶捣汁一小盏服。（《圣惠方》） \n五痔下血∶五月五日采苍耳茎、叶为末。水服方寸匕，甚效。（《千金翼》） \n赤白下痢∶苍耳草（不拘多少）洗净，用水煮烂去滓，入蜜用武火熬成膏。每服一、二 \n匙， \n产后诸痢∶苍耳叶捣绞汁，温服半中盏，日三、四服。（《圣惠方》） \n误吞铜钱∶苍耳头一把，以水一升，浸水中十余度，饮水愈。（《肘后方》） \n花蜘蛛毒咬人，与毒蛇无异∶用野缣丝（即道人头）。捣汁一盏服，仍以渣敷之。（《摘 \n玄方 \n\\x花\\x \n【主治】白癞顽痒（时珍）。 \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>天名精\n\n内容：（《本经》上品） \n【校正】时珍曰∶据苏、沈二说，并入《唐本》鹤虱，《开宝》地菘，《别录》有名未用 \n松。 \n【释名】天蔓荆（《别录》）、天门精（《别录》）、 \n与地同、玉门精（《别录》）、麦句姜（《本经》）、蟾蜍兰（《别录》）、蛤蟆蓝（《本经》）、蚵 \n草（《纲目》）、豕首（《本经》）、彘颅（《别录》）、活鹿草（《异苑》）、刘 草（ 音，胡革反）、 \n皱面草（《纲目》）、母猪芥（《纲目》），实名鹤虱，根名杜牛膝。 \n恭曰∶天名精，即活鹿草也。《别录》一名天蔓荆，南人名为地菘，叶与蔓荆、菘菜相 \n类，故有此名。其味甘辛，故有姜称。状如蓝，而蛤蟆好居其下，故名蛤蟆蓝。香气似兰， \n故又名蟾蜍兰。 \n时珍曰∶天名精乃天蔓荆之讹也。其气如豕彘，故有豕首、彘颅之名。昔人谓之活鹿草， \n俗人因其气臊，讹为狐狸臊者，是也。《尔雅》云∶ ，豕首也。郭璞注云∶江东呼为 \n首，可以炒蚕蛹食。藏器曰∶郭璞注《尔雅》蘧麦，云即麦句姜者，非也。陶公注钓樟条云∶ \n有一草似野狼牙，气辛臭，名为地菘，人呼为刘 草，主金疮。按《异苑》云∶宋元嘉中，青 \n州刘 射一獐，剖五脏以此草塞之，蹶然而起。 怪而拔草，便倒，如此三度。 因密录此 \n草种之， \n定非二物。 \n【正误】弘景曰∶天名精即今之 ，亦名 首。夏月杵汁服之，除热病。味至苦而云 \n甘，或非是也。 \n恭曰∶ 首苦而臭，名精辛而香，全不相类也。 \n禹锡曰∶苏恭云∶天名精南人名地菘。陈藏器《本草解纷》，亦言天名精为地菘。《开宝 \n本草》不当重出地菘条，例宜刊削。 \n时珍曰∶按沈括《笔谈》云∶世人既不识天名精，又妄认地菘为火 ，本草又出鹤虱 \n一条，都成纷乱。不知地菘即天名精，其叶似菘，又似蔓荆，故有二名，鹤虱即其实也。又 \n《别录》有名未用 松，即此地菘，亦系误出，今并正之，合而为一。 \n【集解】《别录》曰∶天名精生平原川泽，五月采。 \n荆，又名天芜菁。叶似山南菘菜，夏秋抽条，颇似薄荷，花紫白色，味辛而香。 \n志曰∶地菘所在皆有，生人家及路旁阴处，高二、三寸，叶似菘叶而小。又曰∶鹤虱， \n出波斯者为胜。今上党亦有，力势薄于波斯者。 \n恭曰∶鹤虱生西戎，子似蓬蒿子而细，合茎叶用之。 \n颂曰∶天名精，江湖间皆有之，状如韩保升所说。又曰∶鹤虱，江、淮、衡、湘皆有之 \n。春生苗，叶皱似紫苏，大而尖长，不光。茎高二尺许。七月生黄白花，似菊。八月结实， \n子极尖细，干即黄黑色。南人呼其叶为火 。按火 即 ，虽花实相类，而别是一物，不 \n可杂用。 \n时珍曰∶天名精嫩苗绿色，似皱叶菘芥，微有狐气。淘净炸之，亦可食。长则起茎，开 \n小黄花，如小野菊花。结实如茼蒿，子亦相似，最黏人衣，狐气尤甚。炒熟则香，故诸家皆 \n云辛而香，亦巴人食负 ，南人食山柰之意尔。 \n其根白色，如短牛膝。此物最贱，而《唐本草》言鹤虱出西戎，宋本草言出波斯者，何 \n哉？盖当时人不知用之，惟四戎、波斯始知入药，且土产所宜故尔。亦苜蓿云出西域，而不 \n知中土饲马者即是也。详见 下。 \n\\x叶\\x（根同） \n【气味】甘，寒，无毒。《别录 \n生汁吐人。 \n【主治】瘀血血瘕欲死，下血止血，利小便，久服轻身耐老（《本 \n虫，去痹，除胸中结热，止烦渴，逐水，大吐下（《别录》）。破血 \n除诸毒肿，疔疮 痔，金疮内射，身痒瘾疹不止者，揩之立已 \n止血，解恶虫蛇螫毒， \n松∶主眩痹（《别录》有名未用）。 \n【发明】时珍曰∶天名精，并根苗而言也。地菘、 松，皆 \n也。其功大抵只是吐痰止血杀虫解毒，故擂汁服之能止痰疟 \n治猪瘟病也。按∶孙天仁《集效方》云∶凡男、妇乳蛾，喉咙肿痛，及小儿急慢惊风，牙关 \n紧急，不省人事者。以鹤虱草（一名皱面草，一名母猪芥，一名杜牛膝），取根洗净捣烂， \n入 \n好酒绞汁灌之，良久即苏。仍以渣敷项下，或醋调，搽亦妙。朱端章《集验方》云∶余被檄 \n任淮西幕府时，牙疼大作。一刀镊人以草药一捻，汤泡少时，以手蘸汤挹痛处即定。因求其 \n方，用之治人多效，乃皱面地菘草也，俗人讹为地葱。沈存中《笔谈》专辩地菘，其子名鹤 \n虱，正此物也。钱季诚方∶用鹤虱一枚，擢置齿中。高监方∶以鹤虱煎米醋 \n漱口，或用防风、鹤虱煎水噙漱，仍研草塞痛处，皆有效也。 \n【附方】旧二，新九。 \n男女吐血∶皱面草（即地菘），晒干为末。每服一、二钱，以茅花泡汤调服，日二次。（《卫 \n生易简》） \n根、叶捣汁，鹅翎扫入，去痰最妙。《圣济总录》∶用杜牛膝、鼓锤草，同捣汁灌之。不得下 \n者，灌鼻得吐为妙。又方∶杜牛膝（春夏用茎，秋冬用根）一把，青矾半两，同研，点患处， \n令吐脓血痰沫，即愈。 \n二丸，即愈。干者为末，蜜丸亦可。名救生丸。（《经效济世方》） \n诸骨哽咽∶地菘、马鞭草各一握（去根），白梅肉一个，白矾一钱，捣作弹丸，绵裹含 \n咽， \n其骨自软而下也。（《普济方》） \n疔疮肿毒∶鹤虱草叶，浮酒糟，同捣敷之，立效。（孙氏《集效方》） \n发背初起∶地菘杵汁一升，日再服，瘥乃止。（《伤寒类要》） \n恶疮肿毒∶地菘捣汁，日服三、四次。（《外台秘要》） \n恶蛇咬伤∶地菘捣敷之。（《易简方》） \n\n\n\n<目录>草部第十五卷\\草之四\n\n<篇名>鹤虱\n\n内容：（《唐本草》） \n【气味】苦，平，有小毒。 \n大明曰∶凉，无毒。 \n【主治】蛔、蛲虫。为散，以肥肉 汁服方寸匕，亦入丸散用（《唐本》）。虫心痛。以 \n淡醋和半匕服，立瘥 \n【发明】颂曰∶鹤虱，杀虫方中为最要药。《古今录验方》∶疗蛔咬心痛，取鹤虱十两。 \n捣筛，蜜丸梧子大。以蜜汤空腹吞四、五十丸。忌酒肉。韦云患心痛十年不瘥，于杂方内见， \n合服之便愈。李 \n汁下之。五岁，一服二分，虫出即止也。 \n【附方】新一。 \n大肠虫出不断，断之复生，行坐不得∶鹤虱末，水调半两服，自愈。（《怪疾奇方》） \n\n\n\n<目录>草部第十五卷\n\n<篇名>草之四\n\n内容：（音喜 。 \n【校正】并入《唐本》猪膏莓。 \n【释名】希仙（《纲目》）、火 草（《唐本》）、猪膏莓（《唐本》）、 \n虎膏（《唐本》）、狗膏（《唐本》）、粘糊菜（《救荒》）。 \n呼草之气味辛毒为 。此草气臭如猪而味 螫，故谓之 。猪膏、虎膏、狗膏，皆因其气， \n以及治虎、狗伤也。火 当作虎 ，俗音讹尔，近人复讹 \n为希仙矣。《救荒本草》言∶其嫩苗炸熟，浸去苦味，油盐调食，故俗谓之粘糊菜。 \n【集解】恭曰∶ ，田野皆识之。一名火 。叶似酸浆而狭长，花黄白色。三月、四 \n月采苗叶曝干。又曰∶猪膏莓，生平泽下湿地，所在皆有。一名虎膏，一名狗膏。叶似苍耳， \n茎圆有毛。 \n颂曰∶ 处处有之。春生苗，叶似芥叶而狭长，文粗。茎高二、三尺。秋初有花如菊。 \n秋末结实，颇似鹤虱。夏采叶。曝干用。 \n藏器曰∶猪膏草，叶似荏有毛。 \n保升曰∶猪膏叶似苍耳，两枝相对，茎叶俱有毛，黄白色。五月、六月采苗，日干。 \n时珍曰∶按∶苏恭《唐本草》谓 似酸浆，猪膏莓似苍耳，列为二种。而成纳《进 \n丸表》，言此药与本草所述相异，多生沃壤，高三尺许，节叶相对 \n此草金棱银线，素茎紫 ，对节而生，蜀号火 \n人妄认地菘为火 。有单 \n人不识，重复出条也。按此数说各异，而今人风痹多用 丸，将何适从耶？时珍尝聚诸草 \n订视，则猪膏草素茎有直棱，兼有斑点，叶似苍耳而微长，似地菘而稍薄，对节而生，茎叶 \n皆有细毛。肥壤一株分枝数十。八、九月开小花，深黄色，中有长子如茼蒿子，外萼有细刺 \n黏人。地菘则青茎，圆而无棱，无斑无毛，叶皱似菘芥，亦不对节。观此则似与成张二氏所 \n说相合。今河南陈州采 充方物，其状亦是猪膏草，则沈氏谓 即猪膏 \n矣。苏恭所谓似酸浆者，乃龙葵，非 ，盖误认尔。但沈氏言世间单服火 ，乃是地菘， \n不当用猪膏莓，似与成张之说相反。今按 、猪膏莓条，并无治风之说。惟《本经》地菘 \n条，有去痹除热，久服轻身耐老之语，则治风似当用地菘。然成、张进御之方，必无虚谬之 \n理。或者二草皆有治风之功乎？而今服猪膏莓之 者，复往往有效。其地菘不见有服之者。 \n则 之为猪膏，尤不必疑矣。 \n\\x \\x \n【气味】苦，寒，有小毒。又曰∶猪膏莓∶辛、苦，平，无毒。 \n藏器曰∶有小毒。苏恭曰∶猪膏无毒，误矣。 \n【主治】 ∶治热 烦满不能食。生捣汁三合服，多则令人吐。又曰∶猪膏 \n莓∶主金疮止痛，断血生肉，除诸恶疮，消浮肿。捣封之，汤渍散敷并良（苏恭）。 \n主久疟痰阴，捣汁服取吐。捣敷虎伤、狗咬、蜘蛛咬、蚕咬、蠼 溺疮（藏器）。治肝 \n肾风气，四肢麻痹，骨痛膝弱，风湿诸疮（时珍）。 \n【发明】颂曰∶蜀人单服 法∶五月五日、六月六日、九月九日， \n采叶，去根茎花实，净洗曝干。入甑中，层层洒酒与蜜蒸之，又曝。如此九过，则气 \n味极香美。熬捣筛末，蜜丸服之。云甚益元气，治肝肾风气，四肢麻痹，骨间疼，腰膝无力 \n者，亦能行大肠气。诸州所说，皆云性寒有小毒，与唐本同。惟文州及高邮军云∶性热无毒。 \n服之补益，安五脏，生毛发，兼主风湿疮，肌肉顽痹，妇人久冷尤宜用。须去粗茎，留枝叶 \n花实蒸曝。两说不同。岂单用叶，则寒而有毒，并枝、花、实，则热而无毒乎？抑土地所产 \n不同而然欤？ \n时珍曰∶生捣汁服则令人吐，故云有小毒；九蒸九曝，则补人去痹，故云无毒。生则性 \n寒，熟则性温，云热者，非也。 \n慎微曰∶按江陵府节度使成讷《进 丸方表》略云∶臣有弟欣，年三十一 \n中风伏枕五年，百医不瘥。有道人钟针因睹此患，曰∶可饵 丸必愈。其草多生沃壤 \n，高三尺许，节叶相对。当夏五月以来收之，每去地五寸剪刈，以温水洗去泥土，摘叶及枝 \n头。凡九蒸九曝，不必太燥，但以取足为度。仍熬捣为末，炼蜜丸如梧子大，空心温酒或米 \n饮下二三十丸。服至二千丸，所患忽加，不得忧虑，是药攻之力；服至四千丸，必得复故； \n至五千丸，当复丁壮。臣依法修合，令欣服之，果如其言。服后须吃饭三 \n日采者佳。奉敕宣付医院详录。又知益州张咏《进 丸表》略云∶切以餐石饮水，可作充 \n肠之馔；饵松含柏，亦成救病之功。是以疗 \n济时之药，辄陈鄙物之形。不耻管窥，辄干 \n并药方二件。依方差人访问采觅，其草颇 \n茎叶颇同苍耳。不费登高 \n谁知至贱之中，乃有殊常之效。臣自吃至百服，眼目清明；即至千服，髭须乌黑，筋力轻健， \n效验多端。臣本州有都押衙罗守一，曾因中风坠马，失音不语。臣与十服，其病立瘥。又和 \n尚智严，年七十，忽患偏风，口眼 斜，时时吐涎。臣与十服，亦便得痊。今合 \n职员史元奏进。 \n【附方】新五。 \n风寒泄泻∶火 丸∶治风气行于肠胃，泄泻。火 草为末，醋糊丸梧子大。每服三十丸， \n白汤下。（《圣济总录》）痈疽肿毒，一切恶疮。 草（端午采者）一两，乳香一两，白矾 \n（烧）"}]);
